/**
 * Headless test suite for Honeycomb Catacombs.
 *
 * Not part of the game. Nothing in scripts/ runs this or knows it exists.
 *
 * The combat engine touches no DOM and reads no clock, which is exactly what makes it testable
 * outside a browser. This loads the honeycomb files into a `vm` context with a minimal window /
 * localStorage / document shim, then drives the engine directly.
 *
 * What it proves, and why each matters:
 *   determinism   the same seed reproduces a fight exactly -- trace, outcome and rewards
 *   divergence    a different seed does not, so the seed is actually doing something
 *   save/resume   a mid-combat save reloaded into a FRESH ENGINE continues to an identical result
 *   identity      allies are not duplicated across the save boundary (the bug this design avoids)
 *   map           map generation is reproducible and structurally sound
 *   content       every content table cross-reference resolves
 *   forecasts     a dry run leaves the world byte-identical, says what will actually happen, and
 *                 cannot change the fight it describes
 *
 * Usage:  node "!designDocs/honeycomb/tools/test-honeycomb.js"
 * Exits non-zero if anything fails.
 */
const fs = require("fs");
const vm = require("vm");
const path = require("path");

const ROOT = path.resolve(__dirname, "..", "..", "..", "scripts", "misc");

// Load order matters and mirrors index.html. Scene and UI files are omitted: they need a real DOM,
// and everything they call is already covered here.
const FILES = [
	"honeycomb.js",
	"honeycomb/honeycomb-tuning.js",
	"honeycomb/honeycomb-state.js",
	"honeycomb/honeycomb-effects.js",
	"honeycomb/honeycomb-entities.js",
	"honeycomb/honeycomb-tags.js",
	"honeycomb/honeycomb-content-statuses.js",
	"honeycomb/honeycomb-content-cards.js",
	"honeycomb/honeycomb-content-characters.js",
	"honeycomb/honeycomb-content-abilities.js",
	"honeycomb/honeycomb-abilities.js",
	"honeycomb/honeycomb-content-enemies.js",
	"honeycomb/honeycomb-content-map.js",
	"honeycomb/honeycomb-content-lust-events.js",
	"honeycomb/honeycomb-progression.js",
	"honeycomb/honeycomb-combat.js",
	"honeycomb/honeycomb-text-tooltips.js",
	"honeycomb/honeycomb-tooltip.js",
	"honeycomb/honeycomb-choices.js",
	"honeycomb/honeycomb-forecast.js",
	"honeycomb/honeycomb-map.js",
	"honeycomb/honeycomb-overlays-map.js",
	"honeycomb/honeycomb-lust-events.js",
	"honeycomb/honeycomb-gallery.js",
	// Plays nothing headlessly: its elements and its clock are two seams block [123] replaces.
	"honeycomb/honeycomb-music.js",
	"honeycomb/honeycomb-art.js",
	// The cut-ins register overlays and do nothing at all without a screen, so they load headlessly
	// and their content -- which layers exist, what art each names -- can be held to the same
	// cross-reference checks as everything else.
	"honeycomb/honeycomb-overlays-broken.js",
	"honeycomb/honeycomb-font-metrics.js",
	"honeycomb/honeycomb-sprite-metrics.js",
	"honeycomb/honeycomb-warnings.js",
];

/** A fresh, fully isolated engine. Each call gets its own globals and its own storage. */
// Set around a test that provokes an engine error on purpose. See the console shim below.
let expectErrors = false;

function newEngine() {
	const store = {};
	const sandbox = {
		// Errors are surfaced, because an engine error during a test is the test failing in a way the
		// assertions may not notice. `expectErrors` mutes them for the handful of cases that provoke
		// one deliberately, so a passing run stays free of alarming stack traces.
		console: {
			log() {}, warn() {}, debug() {}, info() {},
			error(...argumentArray) { if (!expectErrors) console.error(...argumentArray); },
		},
		localStorage: {
			getItem: (key) => (key in store ? store[key] : null),
			setItem: (key, value) => { store[key] = String(value); },
			removeItem: (key) => { delete store[key]; },
		},
		Date, Math, JSON, encodeURI, encodeURIComponent, decodeURIComponent,
		Object, Array, String, Number, Infinity, parseInt, parseFloat, setTimeout, clearTimeout,
		document: {
			getElementById: () => null,
			createElement: () => ({ style: { setProperty() {} }, appendChild() {}, classList: { add() {}, remove() {} } }),
			body: null,
		},
	};
	sandbox.window = sandbox;
	vm.createContext(sandbox);
	for (const file of FILES) {
		vm.runInContext(fs.readFileSync(path.join(ROOT, file), "utf8"), sandbox, { filename: file });
	}
	installLegacyOutfitFixtures(sandbox.honeycomb);
	installLegacyCardFixtures(sandbox.honeycomb);
	installRetiredLustFixtures(sandbox.honeycomb);
	return sandbox.honeycomb;
}

