// The two rows that pointed at them. Appended AFTER the shipped queue, so the real content stays at the
// head of it and every ordering assertion still reads the game's own running order first.
const RETIRED_LUST_QUEUE_FIXTURES = [
	// A row that does NOT opt in, so the opt-in rule still has something to be proved against. Every
	// shipped row opts in now, which is correct for shipped content and leaves this untestable.
	{ index: "retiredNoTile", character: "nettle", tag: "venom", rank: 1, event: "lustEventFirstStirring" },
	// A genuinely MULTI-PART scene: ONE scene split across two rows. That is what `partArray` is for,
	// and the shipped content has no example of it any more -- Nettle's three ranks are three scenes,
	// not one scene in three pieces, which is the bug this pair was written to stop coming back.
	{
		index: "retiredPartOne", character: "severine", tag: "charm", rank: 1, event: "lustEventFirstStirring",
		gallery: { name: "Part one", partArray: ["retiredPartTwo"] },
	},
	{
		index: "retiredPartTwo", character: "severine", tag: "charm", rank: 2, event: "lustEventTrial",
		requirementArray: [{ index: "lustEventDone", entry: "retiredPartOne" }],
	},
	{ index: "anyUndone", character: "any", tag: "charm", rank: 3, event: "lustEventUndone", gallery: true },
	{
		index: "afterThree", character: "severine", tag: "charm", event: "lustEventFirstStirring",
		requirementArray: [{ index: "lustEventCount", atLeast: 3 }],
		gallery: { name: "Three deep", characterArray: ["brienne"] },
	},
];

function installRetiredLustFixtures(honeycomb) {
	for (const definition of RETIRED_LUST_EVENT_FIXTURES) {
		if (honeycomb.findDefinition(honeycomb.eventArray, definition.index) == null) {
			honeycomb.eventArray.push(definition);
		}
	}
	for (const row of RETIRED_LUST_QUEUE_FIXTURES) {
		if (honeycomb.findDefinition(honeycomb.lustEventQueueArray, row.index) == null) {
			honeycomb.lustEventQueueArray.push(row);
		}
	}
}


