	const base = hc.memberCardEntryArray({ characterIndex: "brienne", outfitIndex: "default", equipmentArray: [] });
	const swapped = hc.memberCardEntryArray({ characterIndex: "brienne", outfitIndex: "bloodied", equipmentArray: [] });
	const equipped = hc.memberCardEntryArray({ characterIndex: "brienne", outfitIndex: "default", equipmentArray: ["thiefGloves"] });

	const total = (entryArray) => entryArray.reduce((sum, e) => sum + e.count, 0);
