console.log("\n[9] Character art -- tiers, poses, states and the fallback chain");
{
	const hc = newEngine();
	// chainTag is the only part of the art module that reads the UI layer, and it is not used here.
	hc.ui = hc.ui || { missingPathArray: {} };
	startRun(hc, 606060);
	const combat = hc.combat.begin("loneSporeling");
	const ally = hc.state.run.partyArray[0];
	const foe = combat.enemyArray[0];

	// Health tiers pick the drawn set, and a missing hurt set falls back to the healthy one.
	ally.health = ally.maxHealth;
	check("a healthy fighter is tier 1", hc.art.tierFor(ally) === 1);
	ally.health = Math.max(1, Math.floor(ally.maxHealth * 0.3));
	check("a wounded fighter is tier 2", hc.art.tierFor(ally) === 2);
	const hurtChain = hc.art.spriteChain(ally, "basic");
	check("a tier-2 request asks for tier 2 first", hurtChain[0].includes("/2-basic"));
	check("a tier-2 request falls back to tier 1", hurtChain.some(p => p.includes("/1-basic")));
	ally.health = ally.maxHealth;

	// Poses come from card and intent type, so a Support card does not swing a sword.
	check("damage cards use the offense pose", hc.art.poseForCardType("damage") === "offense");
	check("support cards use the passive pose", hc.art.poseForCardType("support") === "passive");
	check("passive cards use the passive pose", hc.art.poseForCardType("passive") === "passive");
	const offense = hc.art.spriteChain(ally, "offense");
	check("an offense request falls back to basic",
		offense[0].includes("-offense") && offense.some(p => p.includes("-basic")));

	// State priority. Death must outrank everything, or a corpse renders as merely poisoned.
	ally.temporaryHealth = 0; ally.statusArray = []; ally.downed = false;
	check("a clean fighter has no state", hc.art.activeState(ally) === null);
	hc.applyStatus(ally, "poison", 3, hc.newEffectContext({ combat }));
	check("poison becomes the active state", hc.art.activeState(ally).index === "poisoned");
	ally.downed = true;
	check("death outranks poison", hc.art.activeState(ally).index === "death");
	ally.downed = false;
	hc.removeStatus(ally, "poison", null, hc.newEffectContext({ combat }));

	// THE SCOPE-CONTROL PROPERTY: a filter state must never demand an image.
	ally.temporaryHealth = 5;
	const shieldedChain = hc.art.spriteChain(ally, "basic");
	check("a filter state contributes no art paths", shieldedChain.every(p => !p.includes("/shielded/")));
	check("a filter state does supply a CSS filter", hc.art.stateFilter(ally) !== "none");
	ally.temporaryHealth = 0;

	// Full and half states, exercised with temporary definitions so content stays untouched.
	hc.art.stateArray.push({ index: "zzTestFull", name: "T", type: "full", priority: 9999,
		test: e => e.instanceId === ally.instanceId });
	const fullChain = hc.art.spriteChain(ally, "offense");
	check("a full state is tried before the plain outfit art", fullChain[0].includes("/zzTestFull/"));
	check("a full state still falls back out to the outfit", fullChain.some(p => !p.includes("/zzTestFull/")));
	hc.art.stateArray.pop();

	ally.health = 1;
	hc.art.stateArray.push({ index: "zzTestHalf", name: "T", type: "half", priority: 9999,
		test: e => e.instanceId === ally.instanceId });
	const halfChain = hc.art.spriteChain(ally, "basic").filter(p => p.includes("/zzTestHalf/"));
	check("a half state never asks for a tier-2 file",
		halfChain.length > 0 && halfChain.every(p => p.includes("/1-")));
	hc.art.stateArray.pop();
	ally.health = ally.maxHealth;

	// Enemies resolve through the same code path.
	const enemyChain = hc.art.spriteChain(foe, "damaged");
	check("enemies resolve through the same resolver",
		enemyChain.length > 0 && enemyChain[0].startsWith("enemies/"));

	// Every chain must terminate in something, for every character, outfit and pose.
	const brokenArray = [];
	for (const character of hc.characterArray) {
		for (const outfit of character.outfitArray) {
			const probe = { side: "ally", characterIndex: character.index, outfitIndex: outfit.index,
				health: 1, maxHealth: 1, temporaryHealth: 0, statusArray: [], downed: false };
			for (const pose of ["basic", "damaged", "offense", "passive"]) {
				if (hc.art.spriteChain(probe, pose).length === 0) {
					brokenArray.push(`${character.index}/${outfit.index}/${pose}`);
				}
			}
			if (hc.art.portraitChain(character.index, outfit.index).length === 0) {
				brokenArray.push(`${character.index}/${outfit.index}/portrait`);
			}
		}
	}
	check("every character, outfit and pose yields a non-empty chain",
		brokenArray.length === 0, brokenArray.join(", "));
}

