console.log("\n[10] Card pools -- rebuilt, coalesced, and honest about where a card came from");
{
	const hc = newEngine();
	hc.state = hc.newProfile();

	// The reported bug: the Duelist's Blade rewrites Sword Strike to Riposte, and Brienne already has
	// a Riposte. The rewritten row must MERGE with it rather than sit beside it. (Session 9 took Riposte
	// out of her starting deck, so this engine puts one back to keep testing the merge.)
	hc.findDefinition(hc.characterArray, "brienne").startingCardArray.push({ index: "brienneRiposte", count: 1 });
	const baseCleave = hc.findDefinition(hc.characterArray, "brienne").startingCardArray
		.filter((entry) => entry.index === "brienneCleave").reduce((sum, entry) => sum + entry.count, 0);
	const withBlade = hc.memberCardEntryArray({
		characterIndex: "brienne", outfitIndex: "default", equipmentArray: ["duelistBlade"],
	});
	const indexArray = withBlade.map((entry) => entry.index);
	check("a replacement merges into an existing row rather than duplicating it",
		new Set(indexArray).size === indexArray.length, indexArray.join(", "));

	const riposte = withBlade.find((entry) => entry.index === "brienneRiposte");
	check("the merged row carries the combined count", riposte && riposte.count === 1 + baseCleave,
		riposte ? String(riposte.count) : "missing");
	check("the merged row names every source that put it there",
		riposte && riposte.sourceArray.some((source) => source.kind === "equipment"));

	// The pool is derived, never patched: two calls in a row must agree.
	const first = JSON.stringify(hc.memberCardEntryArray({ characterIndex: "nettle", outfitIndex: "grovekeeper" }));
	const second = JSON.stringify(hc.memberCardEntryArray({ characterIndex: "nettle", outfitIndex: "grovekeeper" }));
	check("resolving a pool twice gives the same answer", first === second);

	// A replacement with a count leaves the remainder behind.
	const partialArray = hc.applyPoolModifier(
		[hc.newPoolEntry("brienneCleave", 3, null)],
		{ cardReplacementArray: [{ from: "brienneCleave", to: "brienneRiposte", count: 1 }] },
		null,
		hc.findDefinition(hc.poolKindArray, "card"));
	check("a partial replacement leaves the remainder in place",
		partialArray.length === 2 &&
		partialArray.find((entry) => entry.index === "brienneCleave").count === 2 &&
		partialArray.find((entry) => entry.index === "brienneRiposte").count === 1);

	// Sorting is a registry, and it must not reorder the caller's array.
	const source = hc.memberCardEntryArray({ characterIndex: "brienne", outfitIndex: "default" });
	const before = source.map((entry) => entry.index).join(",");
	hc.sortCardEntryArray(source, "name");
	check("sorting returns a copy", source.map((entry) => entry.index).join(",") === before);
}

