console.log("\n[11] Card ownership and the owner-down policy");
{
	const hc = newEngine();
	const run = startRun(hc, 4242, [
		{ characterIndex: "brienne", outfitIndex: "default" },
		{ characterIndex: "severine", outfitIndex: "default" },
	]);
	const combat = hc.combat.begin("loneSporeling", {});
	const severine = run.partyArray.find((member) => member.characterIndex === "severine");
	const brienne = run.partyArray.find((member) => member.characterIndex === "brienne");

	// THE REPORTED BUG. A Blood Pact gained during the run used to arrive ownerless, so its
	// self-damage found nobody and the card paid out for free.
	const gained = hc.addCardToRunDeck("severineBloodPact", null);
	check("a gained card is owned by the character it names", gained.ownerInstanceId === severine.instanceId);

	severine.health = 1;
	// Her heirloom gold is cleared first: Blood Pact ignores Temporary HP, so gold left standing would
	// still be counted against her lust and she would (correctly) not break at 0 health.
	severine.temporaryHealth = 0;
	combat.handArray.push(gained.instanceId);
	const result = hc.combat.playCard(gained.instanceId, null);
	// Session 5: a player character at no health is BROKEN, never downed -- lust 0 >= health 0 is
	// already true, so the break test catches it and death never fires for anyone who uses lust.
	check("Blood Pact at 1 HP breaks its owner rather than killing her",
		result.played === true && severine.broken === true && severine.downed === false,
		"hp " + severine.health + " broken " + severine.broken + " downed " + severine.downed);

	// A card created mid-fight follows the same rule.
	const created = hc.addCardToPile("severineBloodPact", "hand", hc.newEffectContext({ combat }));
	check("a card created mid-fight is owned too", created.ownerInstanceId === severine.instanceId);

	// A neutral card has no owner, and falls back rather than resolving to nobody.
	const neutral = hc.addCardToRunDeck("neutralFocus", null);
	check("a neutral card stays ownerless", neutral.ownerInstanceId === null);
	check("an ownerless card still finds an acting entity",
		hc.cardActingEntity(hc.resolveCard(neutral), combat) !== null);

	// The ownerless fallback must never draw randomness: the hand renders through this path.
	const streamBefore = JSON.stringify(hc.state.rng);
	hc.cardActingEntity(hc.resolveCard(neutral), combat);
	hc.cardActingEntity(hc.resolveCard(neutral), combat);
	check("resolving an ownerless card draws no RNG", JSON.stringify(hc.state.rng) === streamBefore);

	// Owner-down policy.
	brienne.downed = true;
	const guard = hc.resolveCard(run.deckArray.find((card) => card.cardIndex === "brienneGrit"));
	check("the default policy makes a downed owner's card unplayable",
		hc.cardPlayability(guard, combat).playable === false);

	hc.tuning.combat.defaultOwnerDownPolicy = "cycle";
	check("the cycle policy makes it playable", hc.cardPlayability(guard, combat).playable === true);
	check("the cycle policy rewrites what the card does",
		hc.cardEffectArray(guard, combat)[0].index === "drawCards");
	check("the acting entity is still nobody under cycle", hc.cardActingEntity(guard, combat) === null);

	hc.tuning.combat.defaultOwnerDownPolicy = "haunt";
	check("the haunt policy lets a downed owner keep acting",
		hc.cardActingEntity(guard, combat) === brienne);
	hc.tuning.combat.defaultOwnerDownPolicy = "unplayable";
}

