console.log("\n[13] Abilities -- character spells, not potions");
{
	const hc = newEngine();
	check("the potion resource is gone", hc.findDefinition(hc.resourceArray, "potionSlots") === null);

	hc.state = hc.newProfile();
	// A1 is a progression unlock now (the mandatory Ability 1 node), so the tests open it the way a
	// player would. `unlock` walks the shortest legal route to the node.
	const unlock = (characterIndex, nodeIndex) => {
		const loadout = { characterIndex: characterIndex, outfitIndex: "default", equipmentArray: [] };
		hc.setResource("experience", 100000);
		for (let guard = 0; guard < 120; guard++) {
			if (hc.progression.refuseReason(loadout, nodeIndex) === null) { hc.progression.select(loadout, nodeIndex); return; }
			const route = hc.progression.pathTo(loadout, nodeIndex);
			if (route == null) return;
			let progressed = false;
			for (const step of route.nodeIndexArray) {
				if (hc.progression.refuseReason(loadout, step) === null) { hc.progression.select(loadout, step); progressed = true; break; }
			}
			if (!progressed) return;
		}
	};
	// Which abilities a member has is DERIVED, on the same seam the card pool uses.
	check("an outfit can grant an ability",
		hc.abilities.indexArray({ characterIndex: "brienne", outfitIndex: "warden" }).indexOf("brienneAegis") >= 0);
	check("an outfit can replace an ability",
		hc.abilities.indexArray({ characterIndex: "nettle", outfitIndex: "grovekeeper" }).join(",") === "nettleGraveward");
	check("equipment can grant an ability",
		hc.abilities.indexArray({ characterIndex: "severine", outfitIndex: "default", equipmentArray: ["thiefGloves"] })
			.indexOf("neutralSecondWind") >= 0);

	const run = startRun(hc, 8080, [
		{ characterIndex: "brienne", outfitIndex: "default" },
		{ characterIndex: "severine", outfitIndex: "default" },
		{ characterIndex: "nettle", outfitIndex: "default" },
	]);
	unlock("brienne", "briAbility1");
	unlock("severine", "severineAbility1");
	unlock("nettle", "netAbility1");
	const combat = hc.combat.begin("loneSporeling", {});
	const brienne = run.partyArray[0];
	const severine = run.partyArray[1];
	const nettle = run.partyArray[2];

	check("charges are dealt at combat start", hc.abilities.charges(brienne, "brienneBrace") === 1);
	check("charges are per character, not a shared pool",
		hc.abilities.charges(severine, "brienneBrace") === 0 && hc.abilities.charges(severine, "severineBloodTap") === 3);

	const blockBefore = brienne.temporaryHealth;
	check("an untargeted ability resolves",
		hc.abilities.use(brienne.instanceId, "brienneBrace", null).played === true &&
		brienne.temporaryHealth > blockBefore);
	check("using an ability spends a charge", hc.abilities.charges(brienne, "brienneBrace") === 0);
	check("a spent ability is refused",
		hc.abilities.use(brienne.instanceId, "brienneBrace", null).reason === "noCharges");

	const enemy = combat.enemyArray[0];
	// Blight is gated on having at least one Soul, so it is refused until Nettle has harvested.
	check("an ability whose requirement is unmet is refused",
		hc.abilities.use(nettle.instanceId, "nettleBlight", enemy.instanceId).reason === "requirementNotMet");
	hc.addMechanic(nettle, "harvest", 1, hc.newEffectContext({ combat: combat }));
	check("and allowed once they are met", hc.abilities.usability(nettle, "nettleBlight", combat).usable === true);

	check("a targeted ability needs a target",
		hc.abilities.use(nettle.instanceId, "nettleBlight", null).reason === "needsTarget");
	check("a targeted ability resolves against its pick",
		hc.abilities.use(nettle.instanceId, "nettleBlight", enemy.instanceId).played === true &&
		hc.statusStacks(enemy, "poison") > 0);

	// Blood Tap pays life for Strength, three times a fight.
	const severineHealth = severine.health;
	check("Blood Tap costs life and grants Strength",
		hc.abilities.use(severine.instanceId, "severineBloodTap", null).played === true &&
		severine.health < severineHealth && hc.statusStacks(severine, "strength") > 0);

	// Charges survive a save, and an outfit change reconciles rather than refilling.
	const revived = JSON.parse(JSON.stringify(hc.state));
	check("charges survive serialisation",
		revived.run.partyArray[0].abilityChargeArray[0].charges === 0);

	brienne.outfitIndex = "warden";
	hc.abilities.reconcile(brienne);
	check("an outfit change does not refill a spent ability",
		hc.abilities.charges(brienne, "brienneBrace") === 0);
	check("an ability arriving from an outfit starts full",
		hc.abilities.charges(brienne, "brienneAegis") === 1);

	// A downed character's abilities are unavailable, on the same rule their cards follow.
	brienne.downed = true;
	check("a downed character cannot use abilities",
		hc.abilities.usability(brienne, "brienneAegis", combat).reason === "ownerDown");
}

