console.log("\n[20] Two questions in one effect list are asked in order");
{
	const hc = newEngine();
	const run = startRun(hc, 2468, [{ characterIndex: "brienne", outfitIndex: "default" }]);
	const combat = hc.combat.begin("loneSporeling", {});

	hc.cardArray.push({
		index: "zzTwoQuestions", name: "Two Questions", characterIndex: "neutral",
		type: "support", rarity: "special", costArray: { energy: 0 }, targetMode: "owner",
		layout: "horizontal", artPath: "cards/art/neutral-focus",
		effectArray: [
			{ index: "chooseOption", prompt: "First?", optionArray: [
				{ index: "one", name: "One", effectArray: [{ index: "temporaryHealth", amount: 1 }] }] },
			//A question inside a nesting effect shares the same conversation, which is what stops the
			//numbering restarting and pairing answers with the wrong questions.
			{ index: "repeat", times: 1, effectArray: [
				{ index: "chooseOption", prompt: "Second?", optionArray: [
					{ index: "two", name: "Two", effectArray: [{ index: "temporaryHealth", amount: 2 }] }] }] },
		],
	});

	const instance = hc.addCardToRunDeck("zzTwoQuestions", run.partyArray[0].instanceId);
	for (const pile of ["drawPileArray", "discardPileArray", "handArray"]) {
		const at = combat[pile].indexOf(instance.instanceId);
		if (at >= 0) combat[pile].splice(at, 1);
	}
	combat.handArray.push(instance.instanceId);

	const blockBefore = run.partyArray[0].temporaryHealth;
	const promptArray = [];
	let answerArray = [];
	let result = hc.combat.playCard(instance.instanceId, null, answerArray);
	let guard = 0;
	while (result.reason === "needsChoice" && guard++ < 6) {
		promptArray.push(result.choice.prompt);
		answerArray = result.answerArray.concat([{ chosenArray: [result.choice.optionArray[0].index] }]);
		result = hc.combat.playCard(instance.instanceId, null, answerArray);
	}

	check("both questions were asked, in order", promptArray.join(",") === "First?,Second?");
	check("the card completed after the last answer", result.played === true);
	check("both branches resolved", hc.state.run.partyArray[0].temporaryHealth - blockBefore === 3);
	hc.cardArray.pop();
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[21] Global experience -- a shared pool that survives runs");
{
	const hc = newEngine();
	hc.state = hc.newProfile();

	// PROFILE scope, so it is readable and writable with no run in progress at all -- the title
	// screen shows it.
	check("a profile resource reads with no run", hc.getResource("experience") === 0);
	hc.addResource("experience", 5);
	check("a profile resource writes with no run", hc.getResource("experience") === 5);
	hc.setResource("experience", 0);

	// Run-scope resources still refuse to exist outside a run, which is the property that keeps the
	// two lifetimes apart.
	check("a run resource is zero with no run", hc.getResource("gold") === 0);

	const run = startRun(hc, 909, [
		{ characterIndex: "brienne", outfitIndex: "default" },
		{ characterIndex: "severine", outfitIndex: "default" },
	]);
	const relicExperience = hc.getResource("experience");
	check("granting a starting relic already paid", relicExperience > 0);

	function winFight(encounterIndex) {
		const combat = hc.combat.begin(encounterIndex, {});
		for (const enemy of combat.enemyArray) { enemy.downed = true; enemy.health = 0; }
		return hc.discovery.awardCombat(combat, null);
	}

	const first = winFight("loneSporeling");
	check("a first win pays", first.awarded > 0);
	check("a first win names what was new",
		first.lineArray.some((line) => line.newNameArray.length > 0));

	// Round 02: a repeat pays PERSONAL experience (split among the party) and nothing global -- the
	// global pool is for finding things.
	const repeat = winFight("loneSporeling");
	check("a repeat still pays something", repeat.personal > 0);
	check("a repeat adds nothing to the global pool", repeat.awarded === 0);
	// THE PROPERTY THE WHOLE SYSTEM IS FOR: seeing something new is worth more than grinding.
	check("a repeat pays less than a first time",
		repeat.awarded + repeat.personal < first.awarded + first.personal);
	check("a repeat names nothing as new",
		repeat.lineArray.every((line) => line.newNameArray.length === 0));

	const freshEnemy = winFight("bruteAndSpore");
	check("a fight with a new enemy pays more than a pure repeat",
		freshEnemy.awarded + freshEnemy.personal > repeat.awarded + repeat.personal);

	// A discovery is recorded once, ever.
	check("the ledger holds each discovery once",
		hc.discovery.count("enemy") === new Set(hc.state.profile.discoveryArray.enemy).size);
	check("the ledger knows what it has seen", hc.discovery.isKnown("enemy", "sporeling") === true);
	check("the ledger knows what it has not", hc.discovery.isKnown("enemy", "matriarch") === false);

	// Gained cards and relics pay; a card from a character's own pool does not come through the
	// gaining path at all, so a starting deck cannot pay for itself.
	const beforeCard = hc.getResource("experience");
	hc.addCardToRunDeck("neutralHedge", null);
	check("acquiring a new card pays", hc.getResource("experience") > beforeCard);
	const afterFirstCard = hc.getResource("experience");
	hc.addCardToRunDeck("neutralHedge", null);
	check("acquiring the same card again pays nothing", hc.getResource("experience") === afterFirstCard);

	// THE POINT: it survives a run ending, however that run ended.
	const banked = hc.getResource("experience");
	hc.state.run = null;
	check("experience survives the run ending", hc.getResource("experience") === banked);
	check("the ledger survives the run ending", hc.discovery.count("enemy") > 0);

	// And a save round trip.
	const revived = JSON.parse(JSON.stringify(hc.state));
	check("experience survives serialisation", revived.profile.resourceArray.experience === banked);
	check("the ledger survives serialisation", revived.profile.discoveryArray.enemy.length > 0);

	// Content can gate on lifetime progress without the effect layer knowing about progression.
	const context = hc.newEffectContext({});
	check("content can ask what has been discovered",
		hc.testCondition({ index: "hasDiscovered", kind: "enemy", discovery: "sporeling" }, context) === true);
	check("content can count discoveries",
		hc.resolveValue({ index: "discoveryCount", kind: "enemy" }, context) === hc.discovery.count("enemy"));

	// Every kind names itself readably, so a reward screen never prints a raw index.
	const unnamedArray = [];
	for (const kind of hc.discoveryKindArray) {
		const ledger = { enemy: hc.enemyArray, encounter: hc.encounterArray, event: hc.eventArray,
			relic: hc.relicArray, card: hc.cardArray, region: hc.regionArray }[kind.index] || [];
		for (const entry of ledger) {
			if (kind.nameFor(entry.index) === entry.index) unnamedArray.push(kind.index + "/" + entry.index);
		}
	}
	check("every discoverable thing has a printable name", unnamedArray.length === 0, unnamedArray.join(", "));
}

