console.log("\n[27] Forecasts -- the real action, dry-run and rolled back");
{
	const hc = newEngine();
	startRun(hc, 4242);
	hc.combat.begin("sporePair");

	// --- Nothing survives a dry run ---
	// The strongest property this design has: a forecast must be invisible afterwards. RNG counters
	// are part of that, and they are the half that would go wrong silently -- a forecast that advanced
	// a stream would change the fight it was describing.
	{
		const before = hc.snapshotState();
		const cardId = hc.state.run.combat.handArray[0];
		const enemyId = hc.livingEntityArray("enemy", hc.state.run.combat)[0].instanceId;
		hc.forecast.forCard(cardId, enemyId);
		check("a forecast leaves the world byte-identical", hc.snapshotState() === before);

		const rngBefore = JSON.stringify(hc.state.rng);
		hc.forecast.invalidate();
		hc.forecast.incoming();
		check("a whole dry turn leaves the world byte-identical", hc.snapshotState() === before);
		check("no RNG stream advanced", JSON.stringify(hc.state.rng) === rngBefore);
		check("the sandbox flag is not left set", hc.forecast.active === false);
	}

	// --- The forecast agrees with what happens ---
	// The point of running the real action rather than a parallel calculation. If these ever disagree
	// the design has failed, not the arithmetic.
	{
		hc.forecast.invalidate();
		const combat = hc.state.run.combat;
		// Minted rather than looked for in the opening hand: what is drawn depends on the seed, and a
		// test whose subject is decided by a shuffle stops proving the thing it was written for.
		const cardId = hc.addCardToPile("brienneCleave", "hand",
			hc.newEffectContext({ combat: combat })).instanceId;
		// Aimed at the healthiest enemy, so an overkill does not hide a wrong number under a floor.
		const enemyArray = hc.livingEntityArray("enemy", combat).slice()
			.sort((left, right) => right.health - left.health);
		const enemyId = enemyArray[0].instanceId;

		{
			const reading = hc.forecast.forCard(cardId, enemyId);
			const predicted = reading.byEntity[enemyId];
			check("the forecast names the target", predicted != null);

			const result = hc.combat.playCard(cardId, enemyId);
			check("the card actually played", result.played === true);
			// Re-read: playCard resolves through the choice runner, which may replace honeycomb.state.
			const after = hc.findEntity(enemyId, hc.state.run.combat);
			check("forecast health matches what happened",
				predicted.healthAfter === after.health,
				"forecast " + predicted.healthAfter + " vs actual " + after.health);
			check("forecast damage matches what happened",
				predicted.damage === predicted.health - after.health,
				"forecast " + predicted.damage + " vs actual " + (predicted.health - after.health));
		}
	}

	// --- Lethality is called correctly, both ways ---
	{
		hc.forecast.invalidate();
		const cardId = hc.addCardToPile("brienneCleave", "hand",
			hc.newEffectContext({ combat: hc.state.run.combat })).instanceId;
		// The ID is held, never the entity. A forecast REPLACES honeycomb.state exactly as a choice
		// rewind does, so an entity read before one is an abandoned copy and writes to it vanish --
		// which is precisely how this test failed when it was first written.
		const enemyId = hc.livingEntityArray("enemy", hc.state.run.combat)[0].instanceId;
		{
			const healthy = hc.forecast.markFrom(
				hc.forecast.forCard(cardId, enemyId).byEntity[enemyId], "outgoing");
			check("a survivable hit is not called lethal", healthy != null && healthy.lethal === false);

			// The same card against one point of health. Re-read after the forecast above.
			const live = hc.findEntity(enemyId, hc.state.run.combat);
			live.health = 1;
			live.temporaryHealth = 0;
			hc.forecast.invalidate();

			const doomed = hc.forecast.markFrom(
				hc.forecast.forCard(cardId, enemyId).byEntity[enemyId], "outgoing");
			check("a finishing hit is called lethal", doomed != null && doomed.lethal === true);
			check("and the forecast did not actually kill anything",
				hc.findEntity(enemyId, hc.state.run.combat).downed !== true);
			check("nor did it heal them back up",
				hc.findEntity(enemyId, hc.state.run.combat).health === 1);
		}
	}
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[28] The incoming forecast -- what ending the turn now would cost");
{
	const hc = newEngine();
	startRun(hc, 909090);
	hc.combat.begin("deepSwarm");

	const before = hc.snapshotState();
	const reading = hc.forecast.incoming();
	check("the incoming forecast reports something", reading != null);
	check("it left the world alone", hc.snapshotState() === before);
	// Since round 04 (item 26) it reports BOTH sides: poison the party applied ticks on the enemy's own
	// turn, and filtering enemies out hid it. Nothing an enemy does to another enemy is in here.
	// (The poison case gets its own engine below -- a forecast REPLACES honeycomb.state, so poisoning
	// somebody here and unpoisoning them afterwards would leave the poison on a live copy.)
	check("it reports the party", reading.entityArray.some((summary) => summary.side === "ally"));

	// The claim being tested: this is strictly more truthful than adding up the intent numbers,
	// because it IS the turn. Ending the turn for real must land on the numbers it named.
	const predictedArray = reading.entityArray.map((summary) => ({
		entityId: summary.entityId, healthAfter: summary.healthAfter,
	}));

	hc.combat.endPlayerTurn();
	hc.combat.runEnemyTurn();

	const wrongArray = [];
	for (const predicted of predictedArray) {
		const actual = hc.findEntity(predicted.entityId, hc.state.run.combat);
		if (actual == null || actual.health !== predicted.healthAfter) {
			wrongArray.push(predicted.entityId + ": said " + predicted.healthAfter +
				", got " + (actual == null ? "gone" : actual.health));
		}
	}
	check("every ally ends the turn on the health it was told", wrongArray.length === 0,
		wrongArray.join("; "));

	// Item 26: poison on an ENEMY is the payoff of playing Nettle, and it belongs on that enemy's bar.
	{
		const poisonEngine = newEngine();
		startRun(poisonEngine, 2611);
		poisonEngine.combat.begin("loneSporeling");
		const target = poisonEngine.state.run.combat.enemyArray[0];
		const targetId = target.instanceId;
		const healthBefore = target.health;
		poisonEngine.applyStatus(target, "poison", 6, poisonEngine.newEffectContext({ combat: poisonEngine.state.run.combat }));
		poisonEngine.forecast.invalidate();
		const poisonReading = poisonEngine.forecast.incoming();
		const summary = poisonReading == null ? null : poisonReading.byEntity[targetId];
		check("an enemy's poison is forecast on the enemy's own bar", summary != null && summary.damage >= 6,
			summary == null ? "no summary at all" : "damage " + summary.damage);
		check("and it says where that leaves them", summary != null && summary.healthAfter === healthBefore - 6,
			summary == null ? "-" : healthBefore + " -> " + summary.healthAfter);
		//The reading must still be a forecast: the real enemy is untouched until the turn ends.
		check("the forecast left the poison where it was",
			poisonEngine.statusStacks(poisonEngine.state.run.combat.enemyArray[0], "poison") === 6);
	}
	check("at least one ally was actually reported on", predictedArray.length > 0);
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[29] Forecast safety rails");
{
	const hc = newEngine();
	startRun(hc, 31337);
	hc.combat.begin("sporePair");

	// A forecast must never write a save: it would put a future that is about to be discarded over
	// the present. Guarded at save.write, the only function that reaches storage.
	{
		let sawWrite = false;
		hc.forecast.active = true;
		sawWrite = hc.save.write(hc.tuning.save.autosaveSlot);
		hc.forecast.active = false;
		check("a save inside a dry run is refused", sawWrite === false);
		check("and is allowed again once it ends",
			hc.save.write(hc.tuning.save.autosaveSlot) === true);
	}

	// Nesting would restore an inner snapshot over an outer one and strand the caller in the sandbox.
	{
		let inner = "not attempted";
		hc.forecast.dryRun(function () {
			inner = hc.forecast.dryRun(function () { return null; });
			return null;
		});
		check("a nested dry run is refused rather than attempted", inner === null);
		check("the outer one still cleared its flag", hc.forecast.active === false);
	}

	// An action that throws must not take the game down with it, and must still put the world back.
	{
		const before = hc.snapshotState();
		expectErrors = true;
		const reading = hc.forecast.dryRun(function () { throw new Error("deliberate"); });
		expectErrors = false;
		check("a failed forecast returns an empty reading rather than throwing",
			reading != null && reading.entityArray.length === 0);
		check("a failed forecast still restores the world", hc.snapshotState() === before);
	}

	// The aimed forecast answers the question being asked; the standing one answers a different
	// question and must not overwrite it.
	{
		const allyId = hc.livingEntityArray("ally", hc.state.run.combat)[0].instanceId;
		// Summaries are built the way readLog builds them, so the fields a mark reads are all present.
		function summaryWith(damage, heal) {
			const summary = hc.forecast.newSummary(allyId);
			summary.damage = damage; summary.certainDamage = damage;
			summary.heal = heal; summary.certainHeal = heal;
			return hc.forecast.finishSummary(summary);
		}
		hc.forecast.invalidate();
		hc.forecast.standing = { byEntity: {}, entityArray: [], log: [] };
		hc.forecast.standing.byEntity[allyId] = summaryWith(5, 0);
		check("the standing forecast marks an ally",
			hc.forecast.markFor(allyId).kind === "incoming");

		// A held reading's PLAY part is what an entity it touches shows.
		const play = { byEntity: {}, entityArray: [], log: [] };
		play.byEntity[allyId] = summaryWith(0, 4);
		hc.forecast.aiming = { play: play, combined: null };
		check("an aimed forecast wins over it", hc.forecast.markFor(allyId).kind === "outgoing");
		check("and reports the aimed numbers", hc.forecast.markFor(allyId).healthDelta === 4);

		// A play that moves nothing draws nothing, rather than an empty mark.
		check("a forecast that changes nothing produces no mark",
			hc.forecast.markFrom(summaryWith(0, 0), "outgoing") === null);

		hc.forecast.invalidate();
		check("invalidate clears both", hc.forecast.markFor(allyId) === null);
	}

	// Switched off means off, not "computed and hidden".
	{
		hc.tuning.forecast.aimEnabled = false;
		check("the aim forecast can be switched off",
			hc.forecast.forCard(hc.state.run.combat.handArray[0], null) === null);
		hc.tuning.forecast.aimEnabled = true;

		hc.tuning.forecast.incomingEnabled = false;
		hc.forecast.invalidate();
		check("the incoming forecast can be switched off", hc.forecast.incoming() === null);
		hc.tuning.forecast.incomingEnabled = true;
	}
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[30] The named animation vocabulary");
{
	const hc = newEngine();

	// The vocabulary lives in the combat SCENE, which this harness deliberately does not load -- its
	// entries need a real DOM to play into. The names are still worth checking from here, because a
	// card asking for an animation that does not exist fails silently and at runtime. Read out of the
	// file rather than duplicated into a second table that could drift from the first.
	const sceneSource = fs.readFileSync(
		path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
	const vocabularyBlock = sceneSource.split("honeycomb.combatScene.namedAnimationArray = [")[1];
	check("the animation vocabulary was found", vocabularyBlock != null);

	const knownArray = [];
	if (vocabularyBlock != null) {
		const upToEnd = vocabularyBlock.split("\n];")[0];
		for (const match of upToEnd.matchAll(/index:\s*"([^"]+)"/g)) knownArray.push(match[1]);
	}
	check("it holds several animations", knownArray.length >= 5, knownArray.join(", "));

	// Every animation any content asks for must be one of them. Walks nested effect lists, because a
	// flourish is usually inside a repeat or a branch rather than at the top level.
	const problemArray = [];
	function walkEffectArray(effectArray, where) {
		for (const entry of effectArray || []) {
			if (entry == null) continue;
			if (entry.index === "playAnimation" && knownArray.indexOf(entry.animation) < 0) {
				problemArray.push(where + ": unknown animation " + entry.animation);
			}
			if (entry.effectArray) walkEffectArray(entry.effectArray, where);
			if (entry.thenArray) walkEffectArray(entry.thenArray, where);
			if (entry.elseArray) walkEffectArray(entry.elseArray, where);
		}
	}

	for (const card of hc.cardArray) walkEffectArray(card.effectArray, "card " + card.index);
	for (const ability of hc.abilityArray) walkEffectArray(ability.effectArray, "ability " + ability.index);
	for (const enemy of hc.enemyArray) {
		for (const intent of enemy.intentArray || []) {
			walkEffectArray(intent.effectArray, "enemy " + enemy.index + "/" + intent.index);
		}
	}
	for (const event of hc.eventArray) {
		for (const choice of event.choiceArray || []) {
			walkEffectArray(choice.effectArray, "event " + event.index + "/" + choice.text);
		}
	}
	check("every animation content asks for exists", problemArray.length === 0, problemArray.join("; "));

	// The effect carries presentation parameters through untouched, so one animation serves several
	// cards without each needing an entry of its own.
	{
		const context = hc.newEffectContext({});
		hc.resolveEffectArray(
			[{ index: "playAnimation", animation: "burst", color: "#63d2a3", strength: 2 }], context);
		const logged = context.log.find((entry) => entry.type === "animation");
		check("playAnimation logs a beat", logged != null);
		check("and passes its colour through", logged != null && logged.color === "#63d2a3");
		check("and its strength", logged != null && logged.strength === 2);
	}

	// A flourish is presentation, so it must never print itself into a card's rules text.
	{
		const text = hc.describeEffectArray([{ index: "playAnimation", animation: "burst" }]);
		check("a flourish prints nothing in rules text", text === "");
	}
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[31] A forecast cannot change the fight it describes");
{
	// THE PROPERTY THAT MATTERS MOST about this design. A forecast runs the real action -- it draws
	// from the same RNG streams, fires the same hooks, moves the same cards -- and then rolls the
	// world back. If the rollback were imperfect in any way, the game would quietly diverge from
	// itself whenever the player hovered a target, and the symptom would be unreproducible fights.
	//
	// Proven by playing the same fight twice with the same seed: once plainly, once with a forecast
	// answered before every single decision. The traces must be identical, byte for byte.
	function fight(seed, withForecasts) {
		const hc = newEngine();
		startRun(hc, seed);
		hc.combat.begin("deepSwarm");
		const traceArray = [];
		let guard = 0;

		while (guard++ < 200) {
			const combat = hc.state.run.combat;
			if (combat.phase !== "playerTurn") break;

			let played = true;
			while (played && hc.state.run.combat.phase === "playerTurn") {
				played = false;
				for (const instanceId of hc.state.run.combat.handArray.slice()) {
					const enemyArray = hc.livingEntityArray("enemy", hc.state.run.combat);
					if (enemyArray.length === 0) break;
					// The weakest living enemy, by id so nothing is held across a forecast.
					const targetId = enemyArray.slice()
						.sort((left, right) => left.health - right.health)[0].instanceId;

					if (withForecasts) {
						// Exactly what the interface does while a card is dragged over a target: a
						// forecast per candidate, and one for the turn handover on top.
						hc.forecast.invalidate();
						hc.forecast.forCard(instanceId, targetId);
						for (const enemy of hc.livingEntityArray("enemy", hc.state.run.combat)) {
							hc.forecast.forCard(instanceId, enemy.instanceId);
						}
						hc.forecast.incoming();
					}

					const result = hc.combat.playCard(instanceId, targetId);
					if (result.played) {
						played = true;
						traceArray.push("play " + instanceId + " -> " + targetId);
						for (const entity of hc.entityArray(hc.state.run.combat)) {
							traceArray.push("  " + entity.instanceId + " " + entity.health + "/" + entity.temporaryHealth);
						}
					}
				}
			}

			if (withForecasts) { hc.forecast.invalidate(); hc.forecast.incoming(); }
			traceArray.push("endTurn " + hc.state.run.combat.turnNumber);
			hc.combat.endPlayerTurn();
			if (hc.state.run.combat.phase !== "playerTurn" &&
				hc.state.run.combat.phase !== "enemyTurn") break;
			hc.combat.runEnemyTurn();
			if (hc.state.run.combat.phase !== "enemyTurn" &&
				hc.state.run.combat.phase !== "playerTurn") break;
			if (hc.state.run.combat.phase === "victory" || hc.state.run.combat.phase === "defeat") break;
			hc.combat.startPlayerTurn(hc.newEffectContext({ combat: hc.state.run.combat }));
		}

		return {
			trace: traceArray.join("\n"),
			phase: hc.state.run.combat.phase,
			turns: hc.state.run.combat.turnNumber,
			rng: JSON.stringify(hc.state.rng),
		};
	}

	const plain = fight(20260910, false);
	const forecast = fight(20260910, true);

	check("the fight actually ran", plain.trace.length > 0);
	check("forecasts do not change the trace", plain.trace === forecast.trace,
		"first difference at character " +
			(function () {
				for (let index = 0; index < Math.max(plain.trace.length, forecast.trace.length); index++) {
					if (plain.trace[index] !== forecast.trace[index]) return index;
				}
				return -1;
			})());
	check("forecasts do not change the outcome", plain.phase === forecast.phase);
	check("forecasts do not change how long it takes", plain.turns === forecast.turns);
	check("forecasts do not advance a single RNG stream", plain.rng === forecast.rng,
		plain.rng + " vs " + forecast.rng);
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[32] Forecasting an ability spends nothing");
{
	// An ability costs a CHARGE, and charges are run state rather than combat state -- they outlive
	// the fight. A forecast that spent one would quietly drain a character's spells every time the
	// pointer crossed a legal target.
	const hc = newEngine();
	startRun(hc, 5150);
	// A1 is a progression unlock now; open it so there is an ability to forecast.
	hc.setResource("experience", 100000);
	const briLoadout = { characterIndex: "brienne", outfitIndex: "default", equipmentArray: [] };
	hc.progression.select(briLoadout, "briStart");
	hc.progression.select(briLoadout, "briAbility1");
	hc.combat.begin("sporePair");

	const memberId = hc.livingEntityArray("ally", hc.state.run.combat)[0].instanceId;
	const abilityArray = hc.abilities.memberAbilityArray(hc.findEntity(memberId, hc.state.run.combat));
	check("the first ally has an ability to forecast", abilityArray.length > 0);

	if (abilityArray.length > 0) {
		const abilityIndex = abilityArray[0].index;
		const chargesBefore = abilityArray[0].charges;
		check("and a charge to spend", chargesBefore > 0);

		const before = hc.snapshotState();
		const targetId = hc.livingEntityArray("enemy", hc.state.run.combat)[0].instanceId;
		const reading = hc.forecast.forAbility(memberId, abilityIndex, targetId);

		check("forecasting an ability reports something", reading != null);
		check("and leaves the world byte-identical", hc.snapshotState() === before);

		// Read again from live state rather than trusting the array captured above.
		const after = hc.abilities.memberAbilityArray(hc.findEntity(memberId, hc.state.run.combat))
			.find((entry) => entry.index === abilityIndex);
		check("the charge was not spent", after.charges === chargesBefore);

		// Using it for real then costs the charge and matches what was forecast.
		const summaryArray = reading.entityArray.slice();
		const result = hc.abilities.use(memberId, abilityIndex, targetId);
		check("the ability actually used", result.played === true);

		const wrongArray = [];
		for (const summary of summaryArray) {
			const entity = hc.findEntity(summary.entityId, hc.state.run.combat);
			if (entity == null) continue;
			if (entity.health !== summary.healthAfter) {
				wrongArray.push(summary.entityId + ": said " + summary.healthAfter + ", got " + entity.health);
			}
		}
		check("the forecast matched what the ability did", wrongArray.length === 0, wrongArray.join("; "));

		const spent = hc.abilities.memberAbilityArray(hc.findEntity(memberId, hc.state.run.combat))
			.find((entry) => entry.index === abilityIndex);
		check("using it for real does spend the charge", spent.charges === chargesBefore - 1);
	}
}

