console.log("\n[33] Card types, keywords and self-describing targets");
{
	const hc = newEngine();
	// Round 04: types are DERIVED from effects, and a card may have several.
	const unknownArray = hc.cardArray.filter((card) => hc.cardTypeIndexArray(card).some((typeIndex) =>
		hc.findDefinition(hc.cardTypeArray, typeIndex) == null)).map((card) => card.index);
	check("every card's types are registered types", unknownArray.length === 0, unknownArray.join(", "));
	check("every card has at least one type", hc.cardArray.every((card) => hc.cardTypeIndexArray(card).length > 0));

	check("Damage steps its owner to the front by default", hc.cardType("damage").partyShift === "front");
	check("Support moves nobody by default", hc.cardType("support").partyShift === "none");
	check("a Passive card stays in play once played", hc.cardType("passive").afterPlay === "inPlay");
	check("the old names still resolve", hc.cardType("offense").index === "damage" && hc.cardType("power").index === "passive");
	check("the Wisp is a Curse (round 06 folded Status into Curse)", hc.cardTypeIndexArray(hc.findDefinition(hc.cardArray, "curseWisp")).join() === "curse");
	check("weakening an enemy is Negative, not Support", hc.cardTypeIndexArray(hc.findDefinition(hc.cardArray, "nettleWasting")).join() === "negative");
	check("damage plus healing is Damage and Support", hc.cardTypeIndexArray(hc.findDefinition(hc.cardArray, "severineQuaff")).join() === "damage,support");
	check("the primary type is the first", hc.cardType(hc.findDefinition(hc.cardArray, "severineQuaff")).index === "damage");
	check("a cost is not a type (Blood Pact hurts its owner)", hc.cardHasType(hc.findDefinition(hc.cardArray, "severineBloodPact"), "damage") === false);
	check("a declared Passive stays Passive alone", hc.cardTypeIndexArray(hc.findDefinition(hc.cardArray, "brienneHoldTheLine")).join() === "passive");
	check("typeArray overrides the derivation", hc.cardTypeIndexArray({ typeArray: ["negative", "offense"], effectArray: [] }).join() === "negative,damage");

	const resolve = (index) => hc.resolveCard({ instanceId: null, cardIndex: index, ownerInstanceId: null, upgradeLevel: 0 });
	check("Temporary HP is a keyword", hc.findDefinition(hc.keywordArray, "temporaryHealth") != null);
	check("Lust and Broken are keywords too",
		hc.findDefinition(hc.keywordArray, "lust") != null && hc.findDefinition(hc.keywordArray, "broken") != null);
	check("shields are gone from the keyword table", hc.findDefinition(hc.keywordArray, "shield") == null);
	check("a card granting Temporary HP carries the keyword", hc.cardKeywordArray(resolve("brienneGrit")).indexOf("temporaryHealth") >= 0);
	check("a status a card applies is a keyword for free", hc.cardKeywordArray(resolve("nettleVenomTouch")).indexOf("poison") >= 0);
	check("a card flag is a keyword", hc.cardKeywordArray(resolve("nettleSoulHarvest")).indexOf("exhaust") >= 0);
	check("a keyword hidden inside a choice is still found", hc.cardKeywordArray(resolve("neutralHedge")).indexOf("temporaryHealth") >= 0);

	// SHIELDS ARE GONE. Nothing the player reads may say Block or Shield, and nothing in the engine may
	// carry the old stat -- this is the guard on the whole strip-out.
	const shieldTextArray = hc.cardArray.filter((card) => /\b(Block|Shield)\b/.test(hc.cardText(resolve(card.index)))).map((card) => card.index);
	check("no printed card text says Block or Shield", shieldTextArray.length === 0, shieldTextArray.join(", "));
	check("no effect is called block", hc.findDefinition(hc.effectArray, "block") == null);
	check("temporary health replaced it", hc.findDefinition(hc.effectArray, "temporaryHealth") != null);
	check("the keyword is highlighted in the card text",
		hc.cardTextMarkup(resolve("brienneGrit")).indexOf('class="hcKeyword"') >= 0);

	// A card that hits every enemy says so; the drain still reads as a drain.
	check("an all-enemies card says ALL enemies", hc.cardText(resolve("nettleMiasma")).indexOf("ALL enemies") >= 0,
		hc.cardText(resolve("nettleMiasma")));
	//Session 33: Crimson Arc became a drain, so the plain all-hitter is Beacon Flame's opening line.
	check("the plain all-hitter reads right", hc.cardText(resolve("cinderBeaconFlame")).indexOf("Deal 10 damage to ALL enemies.") === 0,
		hc.cardText(resolve("cinderBeaconFlame")));
	check("an override keeps its own phrasing", hc.cardText(resolve("severineQuaff")) === "Deal 4 damage. Heal for the damage dealt.",
		hc.cardText(resolve("severineQuaff")));
	check("an ally-targeted grant names the ally", hc.cardText(resolve("brienneLendSteel")).indexOf("An ally gains 7 Temporary HP.") === 0,
		hc.cardText(resolve("brienneLendSteel")));
	check("a status put on oneself is gained", hc.cardText(resolve("brienneIronRetort")) === "Gain 5 Temporary HP. Gain 2 Retort.",
		hc.cardText(resolve("brienneIronRetort")));
	check("Severine starts with the all-hitter",
		hc.findDefinition(hc.characterArray, "severine").startingCardArray.some((entry) => entry.index === "severineRend"));
	check("a starter card targets an ally", resolve("clemenceGrant").targetMode === "ally");

	// Presentation resolves card-first, type-second.
	const offense = hc.art.cardPresentation(resolve("severineStrike"));
	check("a Damage card swings by default", offense.pose === "offense" && offense.animationArray.length > 0);
	const custom = hc.art.cardPresentation(Object.assign({}, resolve("severineStrike"), { pose: "passive", animationArray: [{ animation: "burst" }] }));
	check("a card's own presentation wins", custom.pose === "passive" && custom.animationArray[0].animation === "burst");
	check("an ability gestures by default", hc.art.abilityPresentationFor({}).pose === "passive");
}

console.log("\n[34] Party order: who moves, and who gets hit");
{
	const hc = newEngine();
	const run = startRun(hc, 8080);
	// Creeping Rot is the node that moves Nettle now, so open it the way a player would.
	hc.setResource("experience", 100000);
	const netShiftLoadout = { characterIndex: "nettle", outfitIndex: "default", equipmentArray: [] };
	hc.progression.select(netShiftLoadout, "netStart");
	hc.progression.select(netShiftLoadout, "netAbility1");
	hc.progression.select(netShiftLoadout, "netCex1");
	const combat = hc.combat.begin("loneSporeling", {});
	const idOf = (characterIndex) => run.partyArray.find((member) => member.characterIndex === characterIndex).instanceId;
	const order = () => hc.state.run.partyArray.filter((m) => !m.downed).map((m) => m.characterIndex).join(",");
	const give = (cardIndex, characterIndex) => {
		const instance = hc.addCardToPile(cardIndex, "hand", hc.newEffectContext({ combat: hc.state.run.combat }));
		instance.ownerInstanceId = idOf(characterIndex);
		return instance.instanceId;
	};
	hc.setResource("energy", 99);
	const enemyId = () => hc.livingEntityArray("enemy", hc.state.run.combat)[0].instanceId;

	check("the party starts in selection order", order() === "brienne,nettle,severine", order());
	check("Nettle's Damage card is read as moving her back",
		hc.cardPartyShift(hc.combat.resolveById(give("nettleStrike", "nettle")), hc.findEntity(idOf("nettle"), hc.state.run.combat)) === "back");

	hc.combat.playCard(hc.state.run.combat.handArray[hc.state.run.combat.handArray.length - 1], enemyId());
	check("playing it sends her to the back", order() === "brienne,severine,nettle", order());

	hc.combat.playCard(give("severineStrike", "severine"), enemyId());
	check("Severine's Damage card brings her to the front (the type default)", order() === "severine,brienne,nettle", order());

	const witherId = give("nettleVenomTouch", "nettle");
	check("with Creeping Rot, a Negative card also moves her back",
		hc.cardPartyShift(hc.combat.resolveById(witherId), hc.findEntity(idOf("nettle"), hc.state.run.combat)) === "back");
	hc.combat.playCard(witherId, enemyId());
	check("playing it leaves her at the back", order() === "severine,brienne,nettle", order());

	hc.combat.playCard(give("brienneBulwark", "brienne"), null);
	check("Brienne's Support cards bring her forward", order() === "brienne,severine,nettle", order());

	// The preview and the move are one answer.
	const nettle = hc.findEntity(idOf("nettle"), hc.state.run.combat);
	const preview = hc.previewShift(nettle, "front", hc.state.run.combat);
	check("a preview says where they would end up", preview != null && preview.toRank === 0 && preview.fromRank === 2);
	check("and moves nobody", order() === "brienne,severine,nettle");
	const context = hc.newEffectContext({ combat: hc.state.run.combat });
	hc.shiftEntity(nettle, "front", context);
	check("the real move lands where the preview said", order() === "nettle,brienne,severine", order());
	check("the move is logged with the new order", context.log.some((e) => e.type === "partyOrder" && e.orderIdArray[0] === nettle.instanceId));

	// A downed member holds no rank and keeps their place. Since session 5 a player character is never
	// downed by damage -- they break -- so the flag is set directly here to exercise the ranking rule
	// itself, which still has to hold for anything that does die (a summoned ally, an enemy).
	const severine = hc.findEntity(idOf("severine"), hc.state.run.combat);
	severine.health = 0; severine.downed = true;
	check("a downed member drops out of the ranks", hc.entityRank(severine, hc.state.run.combat) === -1);
	hc.shiftEntity(hc.findEntity(idOf("nettle"), hc.state.run.combat), "back", context);
	check("the living still reorder around them", order() === "brienne,nettle", order());
	severine.downed = false; severine.health = 10; severine.broken = false; severine.lust = 0;

	// Most enemy attacks land on whoever stands in front.
	const sporeling = hc.findDefinition(hc.enemyArray, "sporeling");
	// Round 04: targets are relative to the user, so an enemy aims at the front of ITS enemies -- the party.
	check("the Sporeling spits at the front", hc.findDefinition(hc.cardArray, "sporelingSpit").targetMode === "frontEnemy");
	check("the Hollow Knight pierces to the back",
		hc.findDefinition(hc.cardArray, "hollowKnightPierce").targetMode === "backEnemy");

	// Off freezes the order.
	hc.tuning.combat.partyShiftEnabled = false;
	const frozen = order();
	hc.combat.playCard(give("severineStrike", "severine"), enemyId());
	check("with shifting switched off nobody moves", order() === frozen, order());
	hc.tuning.combat.partyShiftEnabled = true;

	// A Power leaves the cycle once played.
	const powerId = give("brienneHoldTheLine", "brienne");
	hc.combat.playCard(powerId, null);
	check("a played Power goes into play, not the discard", hc.combat.pileHolding(powerId) === "inPlayPileArray");
}

console.log("\n[35] Forecasts: resting, held, and what is left to chance");
{
	const hc = newEngine();
	const run = startRun(hc, 9191, [
		{ characterIndex: "nettle", outfitIndex: "default" },
		{ characterIndex: "brienne", outfitIndex: "default" },
	]);
	// Nettle only steps back once Creeping Rot is bought; open it so the held forecast sees the shift.
	hc.setResource("experience", 100000);
	const netShiftLoadout = { characterIndex: "nettle", outfitIndex: "default", equipmentArray: [] };
	hc.progression.select(netShiftLoadout, "netStart");
	hc.progression.select(netShiftLoadout, "netAbility1");
	hc.progression.select(netShiftLoadout, "netCex1");
	hc.combat.begin("loneSporeling", {});
	const combat = () => hc.state.run.combat;
	const sporeling = () => hc.livingEntityArray("enemy", combat())[0];
	const nettleId = run.partyArray[0].instanceId;
	const brienneId = run.partyArray[1].instanceId;
	sporeling().intentCardIndex = "sporelingSpit";
	hc.setResource("energy", 99);

	hc.forecast.invalidate();
	let standing = hc.forecast.incoming();
	// Iron Sigil puts Shield on everyone at the start of a fight, so the spit is damage plus what Shield took.
	const spitTaken = (summary) => summary == null ? 0 : summary.certainDamage + summary.certainAbsorbed;
	check("at rest, the front ally takes the spit", spitTaken(standing.byEntity[nettleId]) === 7);
	check("and nobody else does", spitTaken(standing.byEntity[brienneId]) === 0);

	// Poison ticking at the start of the next turn is counted.
	sporeling().intentCardIndex = "sporelingHarden";
	hc.applyStatus(hc.findEntity(brienneId, combat()), "poison", 3, hc.newEffectContext({ combat: combat() }));
	hc.forecast.invalidate();
	standing = hc.forecast.incoming();
	check("poison at the start of the next turn is in the forecast",
		standing.byEntity[brienneId] && standing.byEntity[brienneId].certainDamage === 3);
	hc.removeStatus(hc.findEntity(brienneId, combat()), "poison", null, hc.newEffectContext({ combat: combat() }));
	sporeling().intentCardIndex = "sporelingSpit";

	// Holding a card that moves its owner re-answers who gets hit.
	const give = (cardIndex, ownerId) => {
		const instance = hc.addCardToPile(cardIndex, "hand", hc.newEffectContext({ combat: combat() }));
		instance.ownerInstanceId = ownerId;
		return instance.instanceId;
	};
	const graveTouch = give("nettleStrike", nettleId);
	const before = hc.snapshotState();
	hc.forecast.invalidate();
	const held = hc.forecast.forHeldCard(graveTouch, null);
	check("holding a card forecasts something", held != null && held.combined != null);
	check("and leaves the world byte-identical", hc.snapshotState() === before);
	check("with Nettle about to step back, Brienne takes the spit", spitTaken(held.combined.byEntity[brienneId]) === 7);
	check("and Nettle does not", spitTaken(held.combined.byEntity[nettleId]) === 0);

	// Held over a target it would kill, the enemy turn never comes.
	sporeling().health = 3;
	hc.forecast.invalidate();
	const lethal = hc.forecast.forHeldCard(graveTouch, sporeling().instanceId);
	check("the play part says the target falls", lethal.play.byEntity[sporeling().instanceId].downed === true);
	check("so nothing is incoming", lethal.combined.entityArray.every((summary) => summary.certainDamage === 0));
	hc.forecast.aiming = lethal;
	check("an enemy's mark is the outgoing one", hc.forecast.markFor(sporeling().instanceId).kind === "outgoing");
	hc.forecast.invalidate();
	sporeling().health = sporeling().maxHealth;

	// A random attack is a MIGHT on everyone it could hit, not a promise to the one it picked.
	hc.combat.clear();
	hc.combat.begin("wispCluster", {});
	for (const wisp of hc.livingEntityArray("enemy", combat())) wisp.intentCardIndex = "gloomWispFlicker";
	hc.forecast.invalidate();
	const random = hc.forecast.incoming();
	const nettleSummary = random.byEntity[nettleId];
	const brienneSummary = random.byEntity[brienneId];
	check("a random hit is logged as chance", random.log.some((entry) => entry.type === "damage" && entry.chance === true));
	check("nobody's certain damage includes it", nettleSummary.certainDamage === 0 && brienneSummary.certainDamage === 0);
	check("everyone it could reach might take it", nettleSummary.potentialDamage > 0 && brienneSummary.potentialDamage > 0);
	check("the exact outcome is still recorded", nettleSummary.damage + brienneSummary.damage > 0);

	hc.tuning.forecast.randomTargets = "exact";
	const exactMoss = hc.forecast.markFrom(nettleSummary, "incoming", null);
	const exactBrienne = hc.forecast.markFrom(brienneSummary, "incoming", null);
	check("exact mode names who it lands on", (exactMoss && exactMoss.healthDelta < 0) || (exactBrienne && exactBrienne.healthDelta < 0));
	hc.tuning.forecast.randomTargets = "potential";
	const potentialMark = hc.forecast.markFrom(nettleSummary, "incoming", null);
	check("potential mode shows a might and no certain loss", potentialMark.healthDelta === 0 && potentialMark.potentialDamage > 0);
}

console.log("\n[36] Rewards are dealt across the party");
{
	const offersFor = (party, seed, setup) => {
		const hc = newEngine();
		if (setup) setup(hc);
		startRun(hc, seed, party);
		const combat = hc.combat.begin("loneSporeling", {});
		const offerArray = hc.combat.rollCardReward(hc.findDefinition(hc.encounterArray, "loneSporeling"), combat);
		const owners = offerArray.map((offer) => {
			const member = hc.state.run.partyArray.find((m) => m.instanceId === offer.ownerInstanceId);
			return member ? member.characterIndex : "neutral";
		});
		const characters = offerArray.map((offer) => hc.findDefinition(hc.cardArray, offer.cardIndex).characterIndex);
		return { hc, offerArray, owners, characters };
	};
	const solo = offersFor([{ characterIndex: "nettle", outfitIndex: "default" }], 1);
	check("one character: every offer is theirs", solo.offerArray.length === 3 && solo.owners.every((o) => o === "nettle"), solo.owners.join());
	check("and every card is from their pool", solo.characters.every((c) => c === "nettle"));

	let pairOk = true;
	for (let seed = 1; seed <= 20; seed++) {
		const pair = offersFor([{ characterIndex: "nettle", outfitIndex: "default" }, { characterIndex: "severine", outfitIndex: "default" }], seed);
		if (pair.offerArray.length !== 3 || pair.owners.indexOf("nettle") < 0 || pair.owners.indexOf("severine") < 0) pairOk = false;
	}
	check("two characters: both are always offered for, across twenty seeds", pairOk);

	let trioOk = true;
	for (let seed = 1; seed <= 20; seed++) {
		const trio = offersFor(DEFAULT_PARTY, seed);
		if (trio.owners.slice().sort().join() !== "brienne,nettle,severine") trioOk = false;
	}
	check("three characters: one each, across twenty seeds", trioOk);

	// Four or more: still three offers, three different characters, chosen by chance.
	const addTester = (hc) => {
		hc.characterArray.push({ index: "zzTester", name: "Tester", className: "Test", baseHealth: 10, artFolder: "knight",
			defaultOutfit: "default", outfitArray: [{ index: "default", name: "Default", unlockedFromStart: true }],
			startingCardArray: [{ index: "zzTesterCard", count: 1 }], tagArray: [] });
		hc.cardArray.push({ index: "zzTesterCard", name: "Tester Card", characterIndex: "zzTester", type: "offense",
			rarity: "common", costArray: { energy: 1 }, targetMode: "enemy", layout: "horizontal", artPath: "x",
			effectArray: [{ index: "damage", amount: 1 }] });
	};
	const four = offersFor(DEFAULT_PARTY.concat([{ characterIndex: "zzTester", outfitIndex: "default" }]), 5, addTester);
	check("four characters: still three offers", four.offerArray.length === 3);
	check("for three different characters", new Set(four.owners).size === 3, four.owners.join());

	// A character who cannot gain cards never takes a slot.
	const barred = offersFor(DEFAULT_PARTY, 7, (hc) => { hc.findDefinition(hc.characterArray, "severine").canGainCards = false; });
	check("a character who cannot gain cards is never offered for", barred.owners.indexOf("severine") < 0, barred.owners.join());

	// A bonus card takes a slot of its own, neutral or not.
	const bonus = (() => {
		const hc = newEngine();
		startRun(hc, 3, DEFAULT_PARTY);
		const combat = hc.combat.begin("loneSporeling", {});
		hc.resolveEffectArray([{ index: "addRewardCard", card: "neutralWarcry" }], hc.newEffectContext({ combat }));
		return hc.combat.rollCardReward(hc.findDefinition(hc.encounterArray, "loneSporeling"), combat);
	})();
	check("a fight's bonus card is on the screen", bonus.some((offer) => offer.cardIndex === "neutralWarcry"));
	check("and the screen is still three wide", bonus.length === 3);

	// Requirements: a card can be gated, favoured, or guaranteed by what the member is wearing.
	const guaranteed = offersFor(DEFAULT_PARTY, 11, (hc) => {
		hc.findDefinition(hc.cardArray, "brienneRally").offerGuarantee =
			{ index: "wearsOutfit", outfit: "bloodied", character: "brienne" };
		hc.findDefinition(hc.cardArray, "brienneRally").offerCondition = null;
	});
	check("an unmet guarantee does nothing special",
		guaranteed.offerArray.filter((offer) => offer.cardIndex === "brienneRally").length <= 1);
	const worn = offersFor([{ characterIndex: "brienne", outfitIndex: "bloodied" }, { characterIndex: "nettle", outfitIndex: "default" }], 11, (hc) => {
		hc.findDefinition(hc.cardArray, "brienneRally").offerGuarantee =
			{ index: "wearsOutfit", outfit: "bloodied", character: "brienne" };
	});
	check("a guarantee met by the costume puts the card on the screen", worn.offerArray.some((offer) => offer.cardIndex === "brienneRally"));

	const gated = offersFor([{ characterIndex: "brienne", outfitIndex: "default" }], 13, (hc) => {
		for (const card of hc.cardArray) if (card.characterIndex === "brienne") card.offerCondition = { index: "wearsOutfit", outfit: "nothingLikeThis" };
	});
	check("a card whose condition fails is never offered", gated.offerArray.every((offer) => offer.cardIndex.indexOf("brienne") !== 0));

	const weighted = offersFor([{ characterIndex: "brienne", outfitIndex: "bloodied" }], 17, (hc) => {
		hc.findDefinition(hc.cardArray, "brienneRiposte").offerWeightArray =
			[{ condition: { index: "wearsOutfit", outfit: "bloodied" }, multiplier: 5 }];
	});
	const member = weighted.hc.state.run.partyArray[0];
	const pool = weighted.hc.combat.rewardPoolFor(member, weighted.hc.state.run.combat, []);
	const riposte = pool.find((entry) => entry.index === "brienneRiposte");
	//Session 8: Riposte is an Armament card and Bloodied Plate also leans on Armament, so both multipliers fold in.
	check("a costume multiplies a card's weight", riposte && riposte.weight === weighted.hc.tuning.reward.rarityWeightArray.common * 5 *
		weighted.hc.archetypeWeightFor(member, weighted.hc.findDefinition(weighted.hc.cardArray, "brienneRiposte")));

	// Same seed, same screen.
	const firstRoll = offersFor(DEFAULT_PARTY, 99).offerArray.map((o) => o.cardIndex).join();
	const secondRoll = offersFor(DEFAULT_PARTY, 99).offerArray.map((o) => o.cardIndex).join();
	check("the reward screen is deterministic", firstRoll === secondRoll);
}

console.log("\n[37] What counts as a discovery");
