console.log("\n[40] Numbers that tell the truth: live card text, the drain, and costs");
{
	const hc = newEngine();
	const run = startRun(hc, 7373, DEFAULT_PARTY);
	const combat = hc.combat.begin("loneSporeling", {});
	const severine = run.partyArray.find((member) => member.characterIndex === "severine");
	const sporeling = combat.enemyArray[0];
	const resolve = (index) => hc.resolveCard({ instanceId: null, cardIndex: index, ownerInstanceId: severine.instanceId, upgradeLevel: 0 });
	const context = hc.newEffectContext({ combat });

	// Live numbers: the owner's Strength, then the target's Sundered.
	hc.applyStatus(severine, "strength", 2, context);
	check("Strength raises the printed damage", hc.cardText(resolve("severineStrike"), { source: severine, target: null, combat }) === "Deal 9 damage.");
	hc.applyStatus(sporeling, "sundered", 1, context);
	// 9 with Strength, x1.25 for one Sundered = 11.25, rounded UP to 12 (Noodle).
	check("a Sundered target raises it again", hc.cardText(resolve("severineStrike"), { source: severine, target: sporeling, combat }) === "Deal 12 damage.");
	check("with no live context the printed number stands", hc.cardText(resolve("severineStrike")) === "Deal 7 damage.");
	check("a changed number is marked up in the card markup",
		hc.cardTextMarkup(resolve("severineStrike"), { source: severine, target: null, combat }).indexOf("hcAmount-up") >= 0);
	hc.removeStatus(severine, "strength", null, context);
	hc.removeStatus(sporeling, "sundered", null, context);

	// The drain heals for what the hit actually did.
	severine.health = severine.maxHealth - 20;
	sporeling.temporaryHealth = 3;
	const drain = hc.addCardToPile("severineQuaff", "hand", context);
	drain.ownerInstanceId = severine.instanceId;
	hc.setResource("energy", 9);
	const before = severine.health;
	hc.combat.playCard(drain.instanceId, sporeling.instanceId);
	check("a drain heals for the damage dealt, after Shield", hc.findEntity(severine.instanceId, hc.state.run.combat).health === before + 1);

	// A discounted card prints its discounted cost -- the engine always charged it; the face now says so.
	const edge = hc.addCardToPile("neutralWhettedEdge", "hand", hc.newEffectContext({ combat: hc.state.run.combat }));
	const target = hc.addCardToPile("severineStrike", "hand", hc.newEffectContext({ combat: hc.state.run.combat }));
	target.ownerInstanceId = severine.instanceId;
	hc.combat.playCard(edge.instanceId, target.instanceId);
	const liveContext = hc.newEffectContext({ combat: hc.state.run.combat });
	check("Whetted Edge discounts the card it lands on", hc.cardCost(hc.combat.resolveById(target.instanceId), "energy", liveContext) === 0);

	// Shield eaten by the enemy turn shows up in the forecast, even when no health moves.
	const live = hc.state.run.combat;
	const front = hc.frontAlly(live);
	front.temporaryHealth = 20;
	for (const enemy of hc.livingEntityArray("enemy", live)) enemy.intentCardIndex = "sporelingSpit";
	hc.forecast.invalidate();
	const mark = hc.forecast.markFrom(hc.forecast.incoming().byEntity[front.instanceId], "incoming", null);
	check("a hit Shield fully absorbs still marks the bar", mark != null && mark.healthDelta === 0);
	check("and says how much Shield will be left", mark != null && mark.temporaryAfter === 13, mark && mark.temporaryAfter);
}

