console.log("\n[43] Events reach the party outside a fight, and forecast what they will do");
{
	const hc = newEngine();
	startRun(hc, 9595, DEFAULT_PARTY);
	const run = hc.state.run;
	for (const member of run.partyArray) member.health = 10;
	// The bug this guards: with no fight in progress "all allies" used to be nobody.
	hc.resolveEffectArray([{ index: "heal", amount: 5, targetOverride: "allAllies" }], hc.newEffectContext({}));
	check("an event heal on all allies lands outside combat", run.partyArray.every((member) => member.health === 15));

	const well = hc.findDefinition(hc.eventArray, "wellOfWaxLight");
	const before = hc.snapshotState();
	// Expectations are taken BEFORE the forecast: a forecast replaces honeycomb.state, and `run` above
	// then points at the abandoned copy the dry run was played out on. See CATCH-UP's traps.
	const expectedArray = run.partyArray.map((member) => ({ id: member.instanceId, after: Math.max(0, member.health - 8) }));
	const reading = hc.forecast.forEventChoice(well.choiceArray[0]);
	check("an event choice forecasts its damage to every member", reading != null &&
		expectedArray.every((expected) => reading.byEntity[expected.id] != null && reading.byEntity[expected.id].healthAfter === expected.after));
	check("and leaves the world as it was", hc.snapshotState() === before);
}

console.log("\n[39] A reload never strands the party on the map (round 02, item 42)");
{
	const hc = newEngine();
	startRun(hc, 6262, DEFAULT_PARTY);
	hc.map.generateRegion();
	// The screens a node opens need a real DOM; here they are recorded instead of drawn.
	const openedArray = [];
	hc.overlay.open = (index, params) => { openedArray.push({ index, params }); };
	hc.scene.go = (index) => { openedArray.push({ index: "scene:" + index }); };

	// Standing on an unfinished event node, which is exactly what a save taken on entering one holds.
	const map = hc.state.run.map;
	const eventNode = map.rowArray.flat().find((node) => node.typeIndex === "event") ||
		Object.assign(map.rowArray[1][0], { typeIndex: "event", eventIndex: "wellOfWaxLight" });
	map.currentNodeId = eventNode.id;
	eventNode.visited = false;
	check("an unfinished node offers no moves on its own", hc.map.availableNodeIdArray().length === 0);
	check("resuming re-opens its screen", hc.map.resumeUnfinishedNode() === true &&
		openedArray.some((entry) => entry.index === "event"));

	// A node that no longer exists steps back rather than trapping anyone.
	openedArray.length = 0;
	map.currentNodeId = "noSuchNode";
	hc.map.resumeUnfinishedNode();
	check("a missing node steps back to somewhere with moves", hc.map.availableNodeIdArray().length > 0);

	// A finished node needs nothing.
	eventNode.visited = true;
	map.currentNodeId = eventNode.id;
	check("a finished node is left alone", hc.map.resumeUnfinishedNode() === false);
}

