console.log("\n[44] Progression: ranks, exclusive choices, the way to a node, two experience pools");
{
	const loadout = { characterIndex: "brienne", outfitIndex: "default", equipmentArray: [] };
	const hc = newEngine();
	startRun(hc, 5151, DEFAULT_PARTY);

	// --- Two pools ---
	// SESSION 55 took the prices out of this block. Brienne's Vigour used to cost a flat 25 a rank and
	// these numbers were written against that; it costs 4 now (Noodle: "since brienne has 6 ranks, it
	// should cost 4 exp"), so the block reads the node's own cost and stocks the pool from it. The rule
	// being checked is unchanged: a rank is paid from the character's own experience first, and the
	// global pool covers whatever is left.
	const vigourNode = hc.findDefinition(hc.characterArray, "brienne").progressionTree.nodeArray
		.find((entry) => entry.index === "briStart");
	const rankCost = vigourNode.cost;
	check("Vigour's per-rank price is its whole cost divided by its ranks",
		vigourNode.rankMaximum === 6 && rankCost === 4, "rank " + vigourNode.rankMaximum + " at " + rankCost);
	// One rank's worth and a single point over, so the SECOND rank has to reach the global pool.
	hc.setResource("experience", 100);
	hc.progression.addPersonalExperience("brienne", rankCost + 1);
	check("personal experience belongs to one character",
		hc.progression.personalExperience("brienne") === rankCost + 1 && hc.progression.personalExperience("nettle") === 0);
	check("a character may spend their own and the global pool", hc.progression.spendable("brienne") === 100 + rankCost + 1);
	check("but never another character's", hc.progression.spendable("nettle") === 100);

	hc.setResource("experience", 1000);
	const healthBefore = hc.previewMaximumHealth(loadout);
	const firstRank = hc.progression.select(loadout, "briStart");
	check("a rank is paid from the character's own experience first",
		firstRank.paid.personal === rankCost && firstRank.paid.global === 0,
		JSON.stringify(firstRank.paid));
	const secondRank = hc.progression.select(loadout, "briStart");
	check("the global pool covers the rest",
		secondRank.paid.personal === 1 && secondRank.paid.global === rankCost - 1,
		JSON.stringify(secondRank.paid));
	check("a node can be held at more than one rank", hc.progression.rankOf("brienne", "briStart") === 2);
	check("each rank's modifier stacks", hc.previewMaximumHealth(loadout) === healthBefore + 10);
	for (let rankIndex = 2; rankIndex < 6; rankIndex++) hc.progression.select(loadout, "briStart");
	check("a node stops at its highest rank", hc.progression.refuseReason(loadout, "briStart") === "maxed");

	// --- Giving ranks back, each to the pool that paid for it ---
	const personalBefore = hc.progression.personalExperience("brienne");
	const globalBefore = hc.getResource("experience");
	hc.progression.unselect(loadout, "briStart");
	hc.progression.unselect(loadout, "briStart");
	check("ranks come back one at a time", hc.progression.rankOf("brienne", "briStart") === 4);
	check("each rank returns to the pool that paid for it",
		hc.progression.personalExperience("brienne") === personalBefore &&
		hc.getResource("experience") === globalBefore + 2 * rankCost,
		hc.getResource("experience") + " vs " + (globalBefore + 2 * rankCost));

	hc.progression.select(loadout, "briAbility1");
	hc.progression.select(loadout, "briStart");
	hc.progression.unselect(loadout, "briStart");
	check("a rank given back keeps what hangs off the node", hc.progression.isSelected("brienne", "briAbility1"));
	for (let giveIndex = hc.progression.rankOf("brienne", "briStart"); giveIndex > 0; giveIndex--) hc.progression.unselect(loadout, "briStart");
	check("the last rank given back takes its dependants", hc.progression.isSelected("brienne", "briAbility1") === false);

	// --- A rank requirement ---
	hc.progression.reset(loadout);
	hc.findDefinition(hc.characterArray, "brienne").progressionTree.nodeArray.push(
		{ index: "testVeteran", name: "Veteran", description: "Test.", x: 20, y: 50, cost: 5, requiresArray: [{ index: "briStart", rank: 3 }] });
	hc.setResource("experience", 1000);
	hc.progression.select(loadout, "briStart");
	check("one rank does not meet a rank requirement", hc.progression.refuseReason(loadout, "testVeteran") === "unreachable");
	check("the way to it counts the missing ranks", hc.progression.pathTo(loadout, "testVeteran").stepCount === 3);
	hc.progression.select(loadout, "briStart");
	hc.progression.select(loadout, "briStart");
	check("the requirement opens at that rank", hc.progression.refuseReason(loadout, "testVeteran") === null);

	// --- The way to a locked node ---
	const fresh = newEngine();
	startRun(fresh, 5152, DEFAULT_PARTY);
	fresh.setResource("experience", 1000);
	const route = fresh.progression.pathTo(loadout, "briReplaceAttack");
	check("the way to a locked node starts at the root", route.stepCount === 4 &&
		["briStart", "briAbility1", "briExtraAttack", "briReplaceAttack"].every((index) => route.nodeIndexArray.indexOf(index) >= 0));
	check("the way lists the connections it walks",
		route.edgeArray.some((edge) => edge.from === "briExtraAttack" && edge.to === "briReplaceAttack"));
	fresh.progression.select(loadout, "briStart");
	fresh.progression.select(loadout, "briAbility1");
	fresh.progression.select(loadout, "briExtraAttack");
	check("the way ignores what is already held", fresh.progression.pathTo(loadout, "briReplaceAttack").stepCount === 1);
	fresh.progression.unselect(loadout, "briExtraAttack");
	fresh.progression.select(loadout, "briTrimAttack");
	check("no route is offered through a locked choice", fresh.progression.pathTo(loadout, "briReplaceAttack") === null);

	// --- A save from before the exclusive pair: the earlier choice stands, the later is refunded ---
	const legacy = newEngine();
	legacy.state = legacy.newProfile();
	legacy.state.profile.progressionArray.brienne = ["briStart", "briAbility1", "briExtraAttack", "briTrimAttack"];
	const legacyRefund = legacy.progression.onLoadoutChanged(loadout);
	check("the later of two exclusive choices gives way",
		legacy.progression.isSelected("brienne", "briExtraAttack") && !legacy.progression.isSelected("brienne", "briTrimAttack"));
	check("and is refunded at its listed price", legacyRefund === 75 && legacy.getResource("experience") === 75);

	// --- Tree-node hooks reach combat. They never did before round 02. ---
	const hooked = newEngine();
	startRun(hooked, 5153, DEFAULT_PARTY);
	hooked.setResource("experience", 1000);
	hooked.findDefinition(hooked.characterArray, "brienne").progressionTree.nodeArray.push({
		index: "testHook", name: "Test Hook", description: "+2 Temporary HP gained.", x: 0, y: 0, cost: 5, requiresArray: ["briStart"],
		temporaryBonus: 2,
		hooks: { modifyTemporaryHealthGained: function (amount, params) { return amount + params.definition.temporaryBonus; } },
	});
	for (const nodeIndex of ["briStart", "testHook"]) hooked.progression.select(loadout, nodeIndex);
	hooked.combat.begin("loneSporeling", {});
	const brienne = hooked.state.run.partyArray.find((member) => member.characterIndex === "brienne");
	check("a tree node is a hook source", hooked.hookSourceArray(brienne).some((source) => source.kind === "progression"));
	check("and its hook changes the numbers (+2 Temporary HP)",
		hooked.applyStatusHooks("modifyTemporaryHealthGained", 5, { entity: brienne }) === 7,
		"got " + hooked.applyStatusHooks("modifyTemporaryHealthGained", 5, { entity: brienne }));

	// --- A victory pays the party personally, split once ---
	// The SPLIT is what is under test, so the default outfit's +20% personal experience (OUTFITS-LIST) is
	// neutralised here; block [98] holds the +20% itself.
	const payer = newEngine();
	for (const character of payer.characterArray) {
		const plainOutfit = character.outfitArray.find((outfit) => outfit.index === "default");
		if (plainOutfit != null) plainOutfit.personalExperienceMultiplier = 1;
	}
	startRun(payer, 5154, DEFAULT_PARTY);
	const fight = payer.combat.begin("loneSporeling", {});
	for (const enemy of fight.enemyArray) { enemy.downed = true; enemy.health = 0; }
	const award = payer.discovery.awardCombat(fight, null);
	const shareArray = award.shareArray.map((share) => share.amount);
	check("a victory pays every member personally", award.personal > 0 && award.shareArray.length === 3);
	// SESSION 55: personal experience is TRIPLED on the way in (Noodle: "Triple personal EXP gained"),
	// so the shares add up to the multiplied total rather than the raw award. The multiplier is read from
	// tuning rather than written as 3, so retuning it does not break this.
	const personalMultiplier = payer.tuning.progression.personalExperienceMultiplier;
	check("the shares add up",
		shareArray.reduce((sum, amount) => sum + amount, 0) === Math.round(award.personal * personalMultiplier),
		shareArray.join("+") + " vs " + Math.round(award.personal * personalMultiplier));
	check("and they are three times what the award itself was worth", personalMultiplier === 3);
	check("the split is as even as whole numbers allow", Math.max(...shareArray) - Math.min(...shareArray) <= 1);
	check("the remainder goes to the front", shareArray[0] >= shareArray[shareArray.length - 1]);
	check("meeting pays nothing personal; only the win does",
		payer.progression.personalExperience("brienne") === shareArray[0]);
	const runShareArray = payer.progression.payRunVictory();
	check("winning a run pays the party personally",
		runShareArray.reduce((sum, share) => sum + share.amount, 0) ===
			Math.round(payer.tuning.progression.runVictoryExperience * personalMultiplier));

	// A GOLEM TAKES NO SHARE (session 55, Noodle: "divide it across -player characters- in the roster
	// (no golems)"). A summoned combatant is pushed into run.partyArray like anyone else, and one built
	// from an enemy definition has no characterIndex at all -- so the share it took was paid to nobody.
	const golem = payer.combat.newEnemy("infernalPawn", 0);
	golem.side = "ally";
	golem.summoned = true;
	golem.temporary = true;
	payer.state.run.partyArray.push(golem);
	const withGolemArray = payer.progression.payPersonal(30);
	check("a golem standing in the party takes no experience", withGolemArray.length === 3,
		withGolemArray.map((share) => share.characterIndex).join(","));
	check("and none of it is paid to nobody",
		withGolemArray.every((share) => share.characterIndex != null) &&
		withGolemArray.reduce((sum, share) => sum + share.amount, 0) === Math.round(30 * personalMultiplier),
		JSON.stringify(withGolemArray));
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[45] Equipment: one wearer, heirlooms, remembered loadouts, capacity");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	const party = [
		{ characterIndex: "brienne", outfitIndex: "default", equipmentArray: ["ironSigil", "whetstone"] },
		{ characterIndex: "nettle", outfitIndex: "default", equipmentArray: ["shadowLocket"] },
	];

	// --- Heirlooms: the starting relics, now worn ---
	check("an heirloom is its owner's alone",
		hc.equipment.canWear("brienne", "ironSigil") && !hc.equipment.canWear("nettle", "ironSigil"));
	check("shared gear fits anyone", hc.equipment.canWear("nettle", "whetstone"));
	check("a character starts in their heirloom", hc.equipment.startingArray("severine").join() === "crimsonFang");
	check("the starting relics are relics no more", hc.findDefinition(hc.relicArray, "ironSigil") == null);

	// --- One wearer ---
	check("whoever holds a piece is found", hc.equipment.wearerOf("whetstone", party, "nettle") === "brienne");
	check("taking a piece takes it off its holder",
		hc.equipment.takeFrom("whetstone", party, "nettle") === "brienne" && party[0].equipmentArray.indexOf("whetstone") < 0);

	// --- Remembered loadouts ---
	party[0].equipmentArray.push("whetstone");
	hc.equipment.remember(party[0]);
	party.splice(0, 1);
	check("a benched character still holds what they wore", hc.equipment.wearerOf("whetstone", party, null) === "brienne");
	check("rejoining gives it back", hc.equipment.loadoutForJoining("brienne", party).equipmentArray.join() === "ironSigil,whetstone");
	party[0].equipmentArray.push("whetstone");
	check("but not what a fielded member wears now",
		hc.equipment.loadoutForJoining("brienne", party).equipmentArray.join() === "ironSigil");
	party[0].equipmentArray.pop();
	check("a piece can be taken from a benched character's memory",
		hc.equipment.takeFrom("whetstone", party, "nettle") === "brienne" &&
		hc.equipment.rememberedLoadout("brienne").equipmentArray.join() === "ironSigil");
	check("a never-fielded character joins in their starting gear",
		hc.equipment.loadoutForJoining("severine", party).equipmentArray.join() === "crimsonFang");

	// --- Capacity (round 03, item 9): one each at three or more, one more per member short of three ---
	const maximum = hc.tuning.run.partySizeMaximum;
	const baseline = hc.tuning.equipment.capacityPartySize;
	check("the default party of three gets one piece each", baseline === 3 && hc.equipment.capacity(3) === 1);
	check("a party larger than three still gets the base capacity", hc.equipment.capacity(maximum) === hc.tuning.equipment.baseCapacity);
	check("every member short of three adds capacity", hc.equipment.capacity(baseline - 2) ===
		hc.tuning.equipment.baseCapacity + 2 * hc.tuning.equipment.capacityPerMissingMember);
	check("pieces past capacity do not count", hc.equipment.activeArray(["ironSigil", "whetstone"], maximum).join() === "ironSigil");

	// --- Kinds (round 03, item 5): generic or heirloom, no slots; rarity is independent ---
	check("equipment has no slots any more", hc.equipmentArray.every((piece) => piece.slot === undefined) && hc.equipmentSlotArray === undefined);
	check("a piece naming a character is an heirloom", hc.equipment.kindOf(hc.findDefinition(hc.equipmentArray, "ironSigil")).index === "heirloom");
	check("a piece naming nobody is generic", hc.equipment.kindOf(hc.findDefinition(hc.equipmentArray, "whetstone")).index === "generic");
	check("every rarity is a real one", hc.equipmentArray.every((piece) => hc.findDefinition(hc.equipmentRarityArray, piece.rarity) != null));
	check("the starting heirlooms are common", ["ironSigil", "shadowLocket", "crimsonFang"].every((index) =>
		hc.findDefinition(hc.equipmentArray, index).rarity === "common"));
	check("heirlooms come in more than one rarity", new Set(hc.equipmentArray.filter((piece) => piece.characterIndex != null)
		.map((piece) => piece.rarity)).size > 1);
	check("an heirloom's kind text says so", hc.equipment.kindText(hc.findDefinition(hc.equipmentArray, "duelistBlade")) === "Rare Heirloom");
	// --- The bio's tile counts that character's heirlooms only (item 6) ---
	const brienneHeirlooms = hc.equipment.progressFor("brienne", true);
	check("the heirloom count is the character's own", brienneHeirlooms.total === 2 && brienneHeirlooms.found === 1,
		JSON.stringify(brienneHeirlooms));
	check("the wearable count leaves out other characters' heirlooms",
		hc.equipment.progressFor("brienne", false).total === hc.equipmentArray.filter((piece) => piece.characterIndex == null || piece.characterIndex === "brienne").length);

	// --- A run carries only what counts, and remembers it ---
	const tight = newEngine();
	tight.state = tight.newProfile();
	tight.tuning.equipment.capacityPerMissingMember = 0;
	const run = tight.newRun([{ characterIndex: "brienne", outfitIndex: "default", equipmentArray: ["ironSigil", "whetstone"] }], 77);
	check("a run leaves greyed pieces behind", run.partyArray[0].equipmentArray.join() === "ironSigil");
	check("a run remembers what was worn in it",
		tight.equipment.recentPosition("brienne", "ironSigil") === 0 &&
		tight.equipment.recentPosition("brienne", "whetstone") === Infinity);
	check("a selection naming no equipment wears the heirloom",
		tight.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 78).partyArray[0].equipmentArray.join() === "crimsonFang");

	// --- A worn heirloom still acts for the whole party ---
	const fang = newEngine();
	startRun(fang, 6161, DEFAULT_PARTY);
	const fight = fang.combat.begin("loneSporeling", {});
	for (const member of fang.state.run.partyArray) member.health = member.maxHealth - 10;
	const healthBefore = fang.state.run.partyArray.map((member) => member.health);
	fang.fireRunHooks("onEnemyDowned", { entity: fight.enemyArray[0], context: fang.newEffectContext({ combat: fight }) });
	check("worn equipment hears a world event (the Crimson Fang heals every ally)",
		fang.state.run.partyArray.every((member, index) => member.health === healthBefore[index] + 3));

	// --- An old save: heirlooms go on their owners ---
	const old = newEngine();
	const oldState = old.newProfile();
	oldState.formatVersion = 1;
	oldState.profile.lastPartyArray = [{ characterIndex: "brienne", outfitIndex: "default", equipmentArray: [] }];
	oldState.run = {
		relicArray: [{ index: "crimsonFang", counter: 0 }, { index: "bonePendant", counter: 0 }],
		partyArray: [{ characterIndex: "severine", equipmentArray: [] }],
	};
	check("an old save migrates", old.save.migrate(oldState) === true && oldState.formatVersion === old.tuning.save.formatVersion);
	check("an old saved party is dressed in its heirlooms", oldState.profile.lastPartyArray[0].equipmentArray.join() === "ironSigil");
	check("an old run's starting relic moves onto its owner",
		oldState.run.partyArray[0].equipmentArray.join() === "crimsonFang" &&
		oldState.run.relicArray.map((relic) => relic.index).join() === "bonePendant");
}

