console.log("\n[46] The battle log keeps the fight's history");
{
	const hc = newEngine();
	startRun(hc, 7171, DEFAULT_PARTY);
	hc.combat.begin("loneSporeling", {});
	// A choice or a forecast REPLACES the state, so the fight is always re-read rather than held.
	const live = () => hc.state.run.combat;
	check("the fight's setup is recorded",
		live().historyArray.some((line) => line.type === "turnStart") &&
		live().historyArray.some((line) => line.type === "temporaryHealth"));

	// Puts a card from the run deck into the hand, wherever it was.
	function intoHand(cardIndex) {
		let instance = hc.state.run.deckArray.find((card) => card.cardIndex === cardIndex);
		if (!instance) instance = hc.addCardToRunDeck(cardIndex, null);
		for (const pile of ["drawPileArray", "discardPileArray", "handArray"]) {
			const at = live()[pile].indexOf(instance.instanceId);
			if (at >= 0) live()[pile].splice(at, 1);
		}
		live().handArray.push(instance.instanceId);
		return instance.instanceId;
	}
	hc.setResource("energy", 10);
	const strikeId = intoHand("brienneCleave");
	const enemyId = live().enemyArray[0].instanceId;

	const beforeForecast = live().historyArray.length;
	hc.forecast.forCard(strikeId, enemyId);
	check("a forecast writes nothing to the history", live().historyArray.length === beforeForecast);

	const edgeId = intoHand("neutralWhettedEdge");
	const beforeAsking = live().historyArray.length;
	check("a card that stops to ask is rewound", hc.combat.playCard(edgeId, null).reason === "needsChoice");
	check("and leaves nothing in the history", live().historyArray.length === beforeAsking);

	const beforePlay = live().historyArray.length;
	check("a card can be played", hc.combat.playCard(strikeId, enemyId).played === true);
	const playedArray = live().historyArray.slice(beforePlay);
	check("a played card is recorded by what it IS", playedArray.some((line) =>
		line.type === "cardPlayed" && line.card === "brienneCleave" && line.sourceId != null && line.targetId === enemyId));
	check("and so is what it did", playedArray.some((line) => line.type === "damage" && line.targetId === enemyId));

	hc.combat.endPlayerTurn();
	hc.combat.runEnemyTurn();
	check("the enemy's turn is recorded", live().historyArray.some((line) => line.type === "moveUsed"));
	check("every line knows its turn", live().historyArray.every((line) => typeof line.turn === "number"));
	check("what is not worth reading is left out (animation cues, pile moves)",
		live().historyArray.every((line) => line.type !== "animation" && line.type !== "cardToDiscard"));
	const revived = JSON.parse(JSON.stringify(hc.state));
	check("the history saves with the fight", revived.run.combat.historyArray.length === live().historyArray.length);

	const capped = newEngine();
	startRun(capped, 7172, DEFAULT_PARTY);
	capped.tuning.battleLog.maximumEntries = 5;
	capped.combat.begin("loneSporeling", {});
	check("a long fight's history is capped", capped.state.run.combat.historyArray.length === 5);
}

