console.log("\n[47] Enemy moves are cards, seen moves are remembered, play speed scales every duration");
{
	const hc = newEngine();
	startRun(hc, 8181, DEFAULT_PARTY);

	// --- A move IS a card (round 04) ---
	const spitDefinition = hc.findDefinition(hc.cardArray, "sporelingSpit");
	check("an enemy's move is an entry of the card table", spitDefinition != null && spitDefinition.enemyIndex === "sporeling");
	const combat = hc.combat.begin("loneSporeling", {});
	const sporeling = combat.enemyArray[0];
	const card = hc.moveCard(sporeling, "sporelingSpit");
	check("played by an enemy it is that card", card.name === "Spit" && card.isIntent === true && card.effectArray === spitDefinition.effectArray);
	check("printed as a real card type", hc.cardType(card).index === "damage");
	check("an enemy's card moves nobody", hc.cardPartyShift(card, null) === "none");
	check("and it words itself like any card", hc.cardText(card).indexOf("7") >= 0);
	check("aimed at the party, it says so from the player's side", hc.cardText(card) === "Deal 7 damage to the party member in front.", hc.cardText(card));
	check("Spores is Negative, not Offense", hc.cardType(hc.findDefinition(hc.cardArray, "sporelingSpores")).index === "negative");
	check("no reward pool offers an enemy's move",
		hc.tuning.reward.offerableRarityArray.indexOf("enemy") < 0 && spitDefinition.characterIndex === undefined);

	// --- Seen moves ---
	check("nothing is seen before it is shown", hc.discovery.hasSeenIntent("sporeling", "sporelingHarden") === false ||
		sporeling.intentCardIndex === "sporelingHarden");
	const shown = sporeling.intentCardIndex;
	check("a telegraphed move is seen", hc.discovery.hasSeenIntent("sporeling", shown) === true);
	const unshown = hc.moveIndexArray(sporeling).find((index) => index !== shown);
	check("a move not yet shown is not", hc.discovery.hasSeenIntent("sporeling", unshown) === false);
	check("seeing a move pays nothing", combat.discoveryArray.every((entry) => entry.kind !== "intent"));

	const quiet = newEngine();
	startRun(quiet, 8182, DEFAULT_PARTY);
	quiet.tuning.progression.experienceEnabled = false;
	const quietCombat = quiet.combat.begin("loneSporeling", {});
	check("moves are remembered even with experience switched off",
		quiet.discovery.hasSeenIntent("sporeling", quietCombat.enemyArray[0].intentCardIndex) === true);

	// --- Play speed ---
	const normal = hc.duration(1000);
	hc.state.profile.settingArray = { playSpeed: "fast" };
	const fast = hc.findDefinition(hc.tuning.animation.playSpeedArray, "fast");
	check("a faster play speed shortens every duration", hc.duration(1000) === normal / fast.multiplier);
	hc.state.profile.settingArray.playSpeed = "noSuchSpeed";
	check("an unknown play speed falls back to the default", hc.playSpeed() === hc.tuning.animation.defaultPlaySpeed);
}

