console.log("\n[48] Battle layouts are data");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	const layoutArray = hc.tuning.battleLayout.layoutArray;

	check("the default layout is scene (round 03, item 4)", hc.battleLayout().index === "scene");
	check("every layout has a name and a description",
		layoutArray.every((layout) => typeof layout.name === "string" && typeof layout.description === "string"));
	// Every number a layout names must be one the stylesheet reads; a typo would silently do nothing.
	const knownFieldArray = hc.battleLayoutPropertyArray.map((property) => property.field)
		.concat(hc.battleLayoutFlagArray.map((flag) => flag.field), ["index", "name", "description"]);
	const unknownArray = [];
	for (const layout of layoutArray) {
		for (const field of Object.keys(layout)) if (knownFieldArray.indexOf(field) < 0) unknownArray.push(layout.index + "." + field);
	}
	check("every field a layout sets is one the screen reads", unknownArray.length === 0, unknownArray.join(", "));

	// Writing a layout, onto a stand-in element.
	const written = {};
	const element = { style: {
		setProperty: (name, value) => { written[name] = value; },
		removeProperty: (name) => { delete written[name]; },
	} };
	hc.writeBattleLayoutProperties(element, hc.findDefinition(layoutArray, "stage"));
	check("a layout's numbers reach their CSS variables, with units", written["--hc-frame-height"] === "62%" && written["--hc-fighter-gap"] != null);
	hc.writeBattleLayoutProperties(element, hc.findDefinition(layoutArray, "jumbo"));
	check("a number a layout leaves out is cleared, not left over from the last one", written["--hc-fighter-gap"] === undefined);
	check("a flag becomes a class", hc.battleLayoutClassText(hc.findDefinition(layoutArray, "stage")).indexOf("hcUnframed") >= 0 &&
		hc.battleLayoutClassText(hc.findDefinition(layoutArray, "jumbo")).indexOf("hcUnframed") < 0);
	check("a flag that applies when TRUE adds its class only then",
		hc.battleLayoutClassText(hc.findDefinition(layoutArray, "scene")).indexOf("hcDepthFocus") >= 0 &&
		hc.battleLayoutClassText(hc.findDefinition(layoutArray, "jumbo")).indexOf("hcDepthFocus") < 0);

	// No switching (round 06, item 4): a choice left on an old profile is ignored, even in a debug build.
	const debugWas = hc.tuning.debug.enabled;
	hc.tuning.debug.enabled = true;
	if (hc.state.profile.settingArray == null) hc.state.profile.settingArray = {};
	hc.state.profile.settingArray.battleLayout = "jumbo";
	check("a layout remembered on the profile is ignored; scene is always shown", hc.battleLayout().index === "scene");
	check("there is no way to cycle layouts", hc.cycleBattleLayout === undefined && (hc.combatScene == null || hc.combatScene.onLayoutButton === undefined));
	hc.tuning.debug.enabled = debugWas;
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[49] Round 03: card moves say where from; the downed stay down");
{
	const hc = newEngine();
	startRun(hc, 4903);
	hc.combat.begin("wispCluster", {});
	const run = hc.state.run;
	const combat = run.combat;

	// The hand motion (item 1) flies a card from where it was, so the log has to say.
	const enemy = combat.enemyArray[0];
	const createContext = hc.newEffectContext({ source: enemy, combat: combat });
	hc.addCardToPile("curseWisp", "discardPile", createContext);
	const created = createContext.log.filter((entry) => entry.type === "cardCreated")[0];
	check("a created card names who made it", created != null && created.sourceId === enemy.instanceId);
	const moveContext = hc.newEffectContext({ combat: combat });
	hc.moveCardToPile(combat.handArray[0], "discardPile", moveContext);
	const moved = moveContext.log.filter((entry) => entry.type === "cardDiscarded")[0];
	check("a moved card names the pile it left", moved != null && moved.fromPileArray === "handArray");

	// Item 3: a maximum that grows (a tree node, an outfit, equipment) must not stand a downed member up.
	const definition = hc.findDefinition(hc.characterArray, "brienne");
	const brienne = run.partyArray.filter((member) => member.characterIndex === "brienne")[0];
	const severine = run.partyArray.filter((member) => member.characterIndex === "severine")[0];
	brienne.health = 0;
	brienne.downed = true;
	// `baseHealth` is now an OVERRIDE of the shared tuning.run.characterBaseHealth and no character
	// carries one, so this writes an absolute value rather than incrementing an absent field.
	definition.baseHealth = hc.characterBaseHealth(definition) + 6;
	hc.recalculateMemberStats(brienne);
	check("a downed member gaining max HP stays down at 0", brienne.downed === true && brienne.health === 0, "health " + brienne.health);
	const severineBefore = severine.health;
	const severineDefinition = hc.findDefinition(hc.characterArray, "severine");
	severineDefinition.baseHealth = hc.characterBaseHealth(severineDefinition) + 6;
	hc.recalculateMemberStats(severine);
	check("a standing member still gains the difference", severine.health === severineBefore + 6);

	// Item 7: a relic already carried pays experience instead of nothing; a random pick never repeats.
	run.combat = null;
	const eventContext = hc.newEffectContext({});
	hc.resolveEffectArray([{ index: "gainRelic", relic: "cracksealWax" }], eventContext);
	check("an event relic is granted the first time", hc.hasRelic("cracksealWax"));
	const experienceBefore = hc.getResource("experience");
	const duplicateContext = hc.newEffectContext({});
	hc.resolveEffectArray([{ index: "gainRelic", relic: "cracksealWax" }], duplicateContext);
	check("a duplicate pays experience instead", hc.getResource("experience") === experienceBefore + hc.tuning.progression.duplicateRelicExperience &&
		run.relicArray.filter((relic) => relic.index === "cracksealWax").length === 1);
	check("and says so in the log", duplicateContext.log.some((entry) => entry.type === "relicDuplicate" && entry.experience > 0));
	check("the preview warns before the choice is taken",
		hc.describeEffectArray([{ index: "gainRelic", relic: "cracksealWax" }]).indexOf("already carried") >= 0);
	for (let pick = 0; pick < hc.relicArray.length + 2; pick++) hc.resolveEffectArray([{ index: "gainRandomRelic" }], hc.newEffectContext({}));
	check("random relics never duplicate", new Set(run.relicArray.map((relic) => relic.index)).size === run.relicArray.length &&
		//Session 8: a sister mechanic's relic is only offered while its character is in the party.
		run.relicArray.length === hc.relicArray.filter((relic) => hc.relicOfferable(relic) || hc.hasRelic(relic.index)).length);
	check("an event-pool relic stays out of treasure", (function () {
		hc.relicArray.push({ index: "zzEventOnly", name: "Event Only", description: "", rarity: "common", pool: "event" });
		run.relicArray.length = 0;
		let seen = false;
		for (let roll = 0; roll < 40; roll++) { const offer = hc.rollRelicOffer(); if (offer && offer.index === "zzEventOnly") seen = true; }
		hc.relicArray.pop();
		return seen === false;
	})());

	// Item 8: deck edits log the actual card, so the event screen can show it; a removal naming no card
	// is random (the Cardsharp's trade used to remove nothing at all).
	const deckBefore = run.deckArray.length;
	const tradeContext = hc.newEffectContext({});
	hc.resolveEffectArray([{ index: "removeCardFromDeck", card: null }, { index: "addCardToDeck", card: "neutralWarcry", count: 1 }], tradeContext);
	const removedEntry = tradeContext.log.filter((entry) => entry.type === "deckCardRemoved")[0];
	const addedEntry = tradeContext.log.filter((entry) => entry.type === "deckCardAdded")[0];
	check("a trade takes a card away and adds one", run.deckArray.length === deckBefore && removedEntry != null && addedEntry != null);
	check("the removed card is named in the log", removedEntry != null && hc.findDefinition(hc.cardArray, removedEntry.card) != null);
	check("the added card's instance is named in the log", addedEntry != null && hc.combat.cardInstance(addedEntry.cardId) != null);
}

