console.log("\n[50] Round 04: shared deck services, poison vs Sundered, upgrade previews");
{
	const hc = newEngine();
	startRun(hc, 5004);
	const run = hc.state.run;

	// Item 3: removal is ONE service, and it offers starter cards (the shop's old picker hid them).
	const firstPass = hc.resolveWithChoices({
		buildContext: () => hc.newEffectContext({}),
		run: (context) => hc.resolveEffectArray([{ index: "deckService", service: "removeCard" }], context),
	});
	check("the removal service asks which card", firstPass.complete === false && firstPass.choice.index === "deckCard");
	const offered = hc.choiceKind(firstPass.choice).gather(firstPass.choice);
	const starter = offered.find((entry) => entry.card.rarity === "starter");
	check("starter cards can be removed", starter != null);
	const deckBefore = run.deckArray.length;
	const secondPass = hc.resolveWithChoices({
		answerArray: firstPass.answerArray.concat([{ chosenArray: [starter.instanceId] }]),
		buildContext: () => hc.newEffectContext({}),
		run: (context) => hc.resolveEffectArray([{ index: "deckService", service: "removeCard" }], context),
	});
	check("and the chosen card goes", secondPass.complete === true && hc.state.run.deckArray.length === deckBefore - 1 &&
		hc.state.run.deckArray.every((card) => card.instanceId !== starter.instanceId));
	check("the campfire uses the same services", hc.restOptionArray.filter((option) => option.base === true)
		.filter((choice) => choice.effectArray.some((entry) => entry.index === "deckService")).length === 2);
	check("the old starter-hiding picker is gone", hc.cardPicker === undefined);

	// Item 6: an upgrade question asks for a preview.
	const upgradePass = hc.resolveWithChoices({
		buildContext: () => hc.newEffectContext({}),
		run: (context) => hc.resolveEffectArray([{ index: "deckService", service: "upgradeCard" }], context),
	});
	check("an upgrade question previews the upgrade", upgradePass.complete === false && upgradePass.choice.previewUpgrade === true);
	check("a removal question does not", firstPass.choice.previewUpgrade === false);

	// Item 5: poison ignores Sundered, attacks do not.
	hc.state.run.combat = null;
	hc.combat.begin("loneSporeling", {});
	const combat = hc.state.run.combat;
	const enemy = combat.enemyArray[0];
	enemy.health = 100; enemy.maxHealth = 100; enemy.temporaryHealth = 0;
	const context = hc.newEffectContext({ combat: combat });
	hc.applyStatus(enemy, "sundered", 2, context);
	hc.dealDamage(null, enemy, 10, { ignoreTemporary: true, ignoresStrength: true, damageType: "poison" }, context);
	check("poison damage is not raised by Sundered", enemy.health === 90, "health " + enemy.health);
	hc.dealDamage(null, enemy, 10, {}, context);
	check("attack damage still is", enemy.health === 75, "health " + enemy.health);

	// Sundered is ADDITIVE per stack -- 4 stacks is exactly double -- and it stacks in INTENSITY, so a
	// second application raises the level rather than restarting a timer (Noodle, round 07).
	// SESSION 55 GAVE IT A DECAY (Noodle: "Sundered should reduce by 1 each turn"). It used to carry no
	// decayTiming at all, which is what this block asserted; one stack now comes off at the end of the
	// holder's turn, and the stack type is unchanged.
	const sunderedDefinition = hc.findDefinition(hc.statusArray, "sundered");
	check("Sundered stacks in intensity and loses one stack per holder turn",
		sunderedDefinition.stackType === "intensity" && sunderedDefinition.decayTiming === "ownerTurnEnd" &&
		(sunderedDefinition.decayAmount == null ? 1 : sunderedDefinition.decayAmount) === 1,
		"stackType " + sunderedDefinition.stackType + ", decayTiming " + sunderedDefinition.decayTiming);
	check("its description no longer promises that it does not fade",
		hc.statusDescription(sunderedDefinition).indexOf("Does not fade") < 0,
		hc.statusDescription(sunderedDefinition));
	hc.removeStatus(enemy, "sundered", null, context);
	hc.applyStatus(enemy, "sundered", 3, context);
	hc.tickStatuses(enemy, "ownerTurnEnd", context);
	check("three stacks tick down to two", hc.statusStacks(enemy, "sundered") === 2, "stacks " + hc.statusStacks(enemy, "sundered"));
	hc.tickStatuses(enemy, "ownerTurnEnd", context);
	hc.tickStatuses(enemy, "ownerTurnEnd", context);
	check("and are gone by the third tick", hc.statusStacks(enemy, "sundered") === 0, "stacks " + hc.statusStacks(enemy, "sundered"));
	hc.tickStatuses(enemy, "ownerTurnEnd", context);
	check("ticking an absent Sundered does nothing", hc.statusStacks(enemy, "sundered") === 0);
	hc.removeStatus(enemy, "sundered", null, context);
	hc.applyStatus(enemy, "sundered", 4, context);
	enemy.health = 100;
	hc.dealDamage(null, enemy, 10, {}, context);
	check("4 Sundered stacks double the damage", enemy.health === 80, "health " + enemy.health);

	// ROUNDS UP (Noodle): one stack on a 2-damage hit is 2.5, which lands as 3 rather than flooring back
	// to 2. Without this, Claw Flurry's 2x3 gains nothing from Sundered.
	hc.removeStatus(enemy, "sundered", null, context);
	hc.applyStatus(enemy, "sundered", 1, context);
	enemy.health = 100;
	hc.dealDamage(null, enemy, 2, {}, context);
	check("1 Sundered rounds a fraction up (2 becomes 3)", enemy.health === 97, "health " + enemy.health);
}

