console.log("\n[51] Round 04: teams, not kinds -- a Sporeling for the party, Severine against it");
{
	const hc = newEngine();
	startRun(hc, 5104);
	hc.combat.begin("loneSporeling", {});
	const live = () => hc.state.run.combat;
	const brienne = () => hc.state.run.partyArray.find((member) => member.characterIndex === "brienne");
	const enemySporeling = () => live().enemyArray.find((enemy) => enemy.summoned !== true);

	// --- An enemy fighting FOR the party ---
	const fromBrienne = hc.newEffectContext({ source: brienne(), combat: live() });
	hc.resolveEffectArray([{ index: "summon", enemy: "sporeling" }], fromBrienne);
	const friend = hc.state.run.partyArray.find((member) => member.enemyIndex === "sporeling");
	check("a summoned enemy can join the party's team", friend != null && friend.side === "ally" && friend.temporary === true);
	check("the AI plays it, and it telegraphs at once", hc.isAiControlled(friend) && friend.intentCardIndex != null);
	check("it is drawn and named as what it is", hc.art.baseFolder(friend).indexOf("enemies/") === 0 && hc.entityName(friend) === "Sporeling");
	friend.intentCardIndex = "sporelingSpit";
	check("its card is worded from the party's side", hc.cardText(hc.telegraphedCard(friend)) === "Deal 7 damage to the enemy in front.",
		hc.cardText(hc.telegraphedCard(friend)));
	const foeBefore = enemySporeling().health + enemySporeling().temporaryHealth;
	const brienneBefore = brienne().health;
	hc.combat.endPlayerTurn();
	check("as the party's turn ends it spits at the ENEMY", enemySporeling().health + enemySporeling().temporaryHealth < foeBefore);
	check("and not at the party", brienne().health === brienneBefore);

	// --- A party character fighting AGAINST the party ---
	hc.state.run.combat.phase = "playerTurn";
	const fromEnemy = hc.newEffectContext({ source: enemySporeling(), combat: live() });
	hc.resolveEffectArray([{ index: "summon", character: "severine" }], fromEnemy);
	const rival = live().enemyArray.find((enemy) => enemy.characterIndex === "severine");
	check("a character can join the enemy team", rival != null && rival.side === "enemy" && hc.isAiControlled(rival));
	check("she is still Severine", hc.art.baseFolder(rival).indexOf("characters/") === 0 && hc.entityName(rival) === "Severine");
	check("her moves are her own cards", hc.moveIndexArray(rival).indexOf("severineQuaff") >= 0);
	rival.intentCardIndex = "severineQuaff";
	check("her card played against the party says whom it hits", hc.telegraphedCard(rival).userSide === "enemy");
	const frontBefore = hc.frontOf("ally", live()).health + hc.frontOf("ally", live()).temporaryHealth;
	const front = hc.frontOf("ally", live());
	hc.combat.endPlayerTurn();
	hc.combat.runEnemyTurn();
	check("on the enemy turn she hits the party", front.health + front.temporaryHealth < frontBefore);
	check("no enemy was hurt by her", rival.health > 0 && live().enemyArray.every((enemy) => enemy.health > 0 || enemy.downed));
	// Her Drain's heal is `targetOverride: "owner"`. The owner search once looked only in the party, so
	// the heal fell through to the party's front member (browser check, round 04).
	hc.state.run.combat.phase = "playerTurn";
	rival.health = rival.maxHealth - 10;
	rival.intentCardIndex = "severineQuaff";
	const drainFront = hc.frontOf("ally", live());
	drainFront.temporaryHealth = 0;
	const drainFrontBefore = drainFront.health;
	const rivalBefore = rival.health;
	hc.combat.playMove(rival, hc.newEffectContext({ source: rival, combat: live() }));
	check("an enemy-side Drain heals the one who played it", rival.health > rivalBefore, rival.health + " vs " + rivalBefore);
	check("and never the party member it drained", drainFront.health < drainFrontBefore, drainFront.health + " vs " + drainFrontBefore);

	// --- Summons follow their summoner ---
	hc.state.run.combat.phase = "playerTurn";
	const partyBrood = hc.newEffectContext({ source: brienne(), combat: live() });
	const partyBefore = hc.state.run.partyArray.length;
	hc.resolveEffectArray([{ index: "summonEnemy", enemy: "sporeling", count: 1 }], partyBrood);
	check("summonEnemy calls to the SUMMONER's team", hc.state.run.partyArray.length === partyBefore + 1);
	check("opposing sends it the other way", (function () {
		const enemiesBefore = live().enemyArray.length;
		hc.resolveEffectArray([{ index: "summon", enemy: "sporeling", team: "opposing" }], hc.newEffectContext({ source: brienne(), combat: live() }));
		return live().enemyArray.length === enemiesBefore + 1;
	})());

	// --- Temporary friends leave with the fight ---
	hc.combat.dismissTemporaryAllies();
	check("temporary allies leave when the fight ends", hc.state.run.partyArray.every((member) => member.temporary !== true));

	// --- An old save's intents become cards ---
	const old = { formatVersion: 2, profile: { discoveryArray: { intent: ["sporeling/spit"] } },
		run: { combat: { enemyArray: [{ enemyIndex: "capBrute", currentIntentIndex: "windUp", lastIntentIndex: "slam", sameIntentCount: 1, intentPosition: 2 }] } } };
	hc.save.migrate(old);
	check("a saved telegraph becomes its card", old.run.combat.enemyArray[0].intentCardIndex === "capBruteWindUp" &&
		old.run.combat.enemyArray[0].movePosition === 2 && old.run.combat.enemyArray[0].currentIntentIndex === undefined);
	check("seen moves stay seen", old.profile.discoveryArray.intent[0] === "sporeling/sporelingSpit");
}

