console.log("\n[52] Round 04 second batch: Dread stays, events preview everything, carried statuses, block expiry, placement, reports");
{
	const hc = newEngine();
	startRun(hc, 5205);
	const run = hc.state.run;

	// --- Item 14: Dread cannot be removed by ordinary means ---
	const dread = hc.addCardToRunDeck("curseDread", null);
	const offerPass = hc.resolveWithChoices({
		buildContext: () => hc.newEffectContext({}),
		run: (context) => hc.resolveEffectArray([{ index: "deckService", service: "removeCard" }], context),
	});
	const offered = hc.choiceKind(offerPass.choice).gather(offerPass.choice);
	check("the removal service does not offer Dread", offered.every((entry) => entry.instanceId !== dread.instanceId) && offered.length > 0);
	let randomHitDread = false;
	for (let roll = 0; roll < 60; roll++) {
		const picked = hc.randomRunDeckCard();
		if (picked != null && picked.instanceId === dread.instanceId) randomHitDread = true;
	}
	check("a random removal never lands on Dread", randomHitDread === false);
	hc.resolveEffectArray([{ index: "removeCardFromDeck", card: "curseDread" }], hc.newEffectContext({}));
	check("an effect naming Dread outright still removes it", hc.state.run.deckArray.every((card) => card.instanceId !== dread.instanceId));

	// --- Item 13: every event choice can be previewed in full ---
	// Hurt the party first so heals show as changes, then dry-run every choice of every page. (The
	// pending question above rolled the world back, so the run is re-read: `run` is stale from here.)
	for (const member of hc.state.run.partyArray) member.health = Math.max(1, Math.floor(member.maxHealth / 2));
	hc.addResource("gold", 500);
	const unexplained = [];
	for (const event of hc.eventArray) {
		const pageArray = [event].concat(event.pageArray == null ? [] : event.pageArray);
		for (const page of pageArray) {
			for (const choice of page.choiceArray == null ? [] : page.choiceArray) {
				const reading = hc.forecast.forEventChoice(choice);
				if (reading == null) { unexplained.push(event.index + "/" + choice.text + ": no reading"); continue; }
				for (const line of reading.unexplainedArray) unexplained.push(event.index + " / " + choice.text + ": " + line);
			}
		}
	}
	check("no event choice changes anything its preview cannot show", unexplained.length === 0, unexplained.join(" | "));

	const garden = hc.findDefinition(hc.eventArray, "theSporeGarden");
	const harvest = hc.forecast.forEventChoice(garden.choiceArray.find((choice) => choice.index === "harvest"));
	check("the Spore Garden's harvest previews both Tonics", harvest.log.filter((entry) => entry.type === "deckCardAdded").length === 2);
	// A forecast REPLACES honeycomb.state (CATCH-UP trap): everything below re-reads the live run.
	check("and the preview left the deck alone", hc.state.run.deckArray.every((card) => card.cardIndex !== "neutralTonic"));

	const bench = hc.findDefinition(hc.eventArray, "theTollBench");
	const toll = hc.forecast.forEventChoice(bench.choiceArray.find((choice) => choice.index === "payToll"));
	const brienneId = hc.state.run.partyArray.find((member) => member.characterIndex === "brienne").instanceId;
	check("the Toll Bench previews the heal", toll.byEntity[brienneId] != null && toll.byEntity[brienneId].heal === 25);
	check("and the Regeneration", toll.byEntity[brienneId].statusArray.some((status) => status.index === "regeneration"));
	const sitFree = hc.forecast.forEventChoice(bench.choiceArray.find((choice) => choice.index === "sitFree"));
	check("and Dread before it is taken", sitFree.log.some((entry) => entry.type === "deckCardAdded"));

	const cardsharp = hc.findDefinition(hc.eventArray, "theCardsharp");
	const trade = hc.forecast.forEventChoice(cardsharp.choiceArray.find((choice) => choice.index === "tradeCard"));
	const removedEntry = trade.log.find((entry) => entry.type === "deckCardRemoved");
	check("a random removal is marked random, so the preview keeps the secret", removedEntry != null && removedEntry.random === true);
	const shrine = hc.findDefinition(hc.eventArray, "theQuietShrine");
	if (shrine != null) {
		const prayChoice = shrine.choiceArray.find((choice) => choice.effectArray.some((entry) => entry.index === "gainRandomRelic"));
		const pray = prayChoice == null ? null : hc.forecast.forEventChoice(prayChoice);
		const relicEntry = pray == null ? null : pray.log.find((entry) => entry.type === "relicGained" || entry.type === "relicDuplicate");
		check("a random relic is marked random too", relicEntry != null && relicEntry.random === true);
	}

	// --- Item 13: a status given outside a fight reaches the next one ---
	hc.resolveEffectArray([{ index: "applyStatus", status: "regeneration", stacks: 3, targetOverride: "allAllies" }], hc.newEffectContext({}));
	const brienne = hc.state.run.partyArray.find((member) => member.characterIndex === "brienne");
	check("the status is marked as carried", brienne.statusArray.some((status) => status.index === "regeneration" && status.carried === true));
	const healthBefore = brienne.health;
	hc.combat.begin("loneSporeling", {});
	// The opening turn starts inside begin(), so the first tick has already happened: 3 -> 2, and a heal.
	check("it survives the start of the fight and ticks on the opening turn", hc.statusStacks(brienne, "regeneration") === 2 && brienne.health > healthBefore,
		hc.statusStacks(brienne, "regeneration") + " stacks, " + healthBefore + " -> " + brienne.health);
	check("and is an ordinary combat status from then on", brienne.statusArray.find((status) => status.index === "regeneration").carried == null);

	// --- Item 16: Temporary HP halving is logged ---
	// Session 5: it HALVES rather than wearing off, so the entry says how much went, not all of it.
	const combat = hc.state.run.combat;
	combat.phase = "playerTurn";
	brienne.temporaryHealth = 6;
	const expiryContext = hc.newEffectContext({ combat: combat });
	hc.combat.startPlayerTurn(expiryContext);
	check("Temporary HP halving at turn start is a log entry",
		expiryContext.log.some((entry) => entry.type === "temporaryDecayed" && entry.targetId === brienne.instanceId && entry.amount === 3));
	check("and half of it is still standing", brienne.temporaryHealth === 3, "left " + brienne.temporaryHealth);

	// --- Item 15: how an enemy stands ---
	const matriarchDefinition = hc.findDefinition(hc.enemyArray, "matriarch");
	// Session 11: her scale is 1 (an anchored sprite is sized by the stage height), so the anchor is what she declares.
	check("the boss declares how it stands", matriarchDefinition.presentation != null && matriarchDefinition.presentation.anchor === "back");
	const placed = hc.combat.newEnemy("matriarch", 0, { offsetXPercent: -8 });
	check("an encounter's placement lays over the definition's", placed.placement.scale === matriarchDefinition.presentation.scale && placed.placement.offsetXPercent === -8);
	check("an enemy with nothing to say carries no placement", hc.combat.newEnemy("sporeling", 0, null).placement === null);
	const bossFight = hc.findDefinition(hc.encounterArray, "theMatriarch") || hc.encounterArray.find((encounter) => encounter.enemyIndexArray.indexOf("matriarch") >= 0);
	check("a placement is a plain object a save can hold", JSON.parse(JSON.stringify(placed.placement)).offsetXPercent === -8 && bossFight != null);

	// --- Item 17: a bug report loads like a save ---
	hc.noteError("test error");
	const report = JSON.parse(hc.save.toReportText());
	check("a report wraps the save with what a bug needs", report.kind === "honeycombReport" && report.state.run != null && report.errorArray.length === 1);
	const other = newEngine();
	check("a report loads in a fresh engine", other.save.fromText(JSON.stringify(report)) === true && other.state.run.seed === hc.state.run.seed);
	check("so does a bare save", other.save.fromText(hc.save.toText()) === true);
}

