console.log("\n[53] Round 04 item 8: a mechanic each, and abilities that ask for something");
{
	const hc = newEngine();
	const run = startRun(hc, 5308);
	// Mechanics run only once Ability 1 is bought; this block is about the mechanics, so open it.
	for (const member of hc.state.run.partyArray) unlockAbility1(hc, member.characterIndex);
	hc.combat.begin("sporePair", {});
	const live = () => hc.state.run.combat;
	const member = (characterIndex) => hc.state.run.partyArray.find((entry) => entry.characterIndex === characterIndex);

	// --- Every starting character has one, and the three cover the three widget kinds ---
	check("each of the trio owns a mechanic", ["brienne", "nettle", "severine"].every((index) => hc.mechanicFor(member(index)) != null));
	check("and between them they use all three kinds",
		["bar", "orb", "orbs"].every((kind) => hc.mechanicArray.some((mechanic) => mechanic.kind === kind)));
	check("a mechanic belongs to exactly one character", hc.mechanicArray.every((mechanic) =>
		hc.mechanicArray.filter((other) => other.characterIndex === mechanic.characterIndex).length === 1));

	// --- Brienne: a bar that fills as she is hit and as she shields ---
	const brienne = member("brienne");
	const resolve = hc.findDefinition(hc.mechanicArray, "resolve");
	// Session 5: the Iron Sigil grants its opening gold through honeycomb.grantTemporaryHealth rather
	// than writing the field, so Resolve HEARS it and Brienne opens a fight with a point or two already
	// in the bar. Everything below is therefore measured as a delta.
	const resolveAtStart = hc.mechanicValue(brienne, "resolve");
	//SESSION 33 (Noodle): Resolve is 1:1 on damage taken, never on Temporary HP gained -- so her heirloom's
	//opening gold puts nothing in the bar.
	check("Resolve opens empty: her heirloom's gold is not damage taken", resolveAtStart === 0, "resolve " + resolveAtStart);
	const wardContext = hc.newEffectContext({ combat: live(), source: brienne });
	hc.resolveEffectArray([{ index: "temporaryHealth", amount: 8, targetOverride: "owner" }], wardContext);
	check("Temporary HP gained does not fill it", hc.mechanicValue(brienne, "resolve") === resolveAtStart,
		"resolve " + hc.mechanicValue(brienne, "resolve"));
	brienne.temporaryHealth = 3;
	hc.dealDamage(live().enemyArray[0], brienne, 5, { ignoresStrength: true }, hc.newEffectContext({ combat: live() }));
	check("and a blow fills it 1:1, gold and health alike", hc.mechanicValue(brienne, "resolve") === resolveAtStart + 5 * resolve.pointsPerDamage,
		"resolve " + hc.mechanicValue(brienne, "resolve"));
	hc.addMechanic(brienne, "resolve", 999, null);
	check("it stops at its ceiling", hc.mechanicValue(brienne, "resolve") === resolve.maximum);

	// --- Severine: three orbs, tested rather than stored ---
	const severine = member("severine");
	severine.health = severine.maxHealth;
	severine.damageDealtThisTurn = 0;
	for (const enemy of live().enemyArray) enemy.health = enemy.maxHealth;
	check("no orb is lit with nothing done", hc.mechanicOrbsLit(severine, live()) === 0);
	severine.damageDealtThisTurn = 3;
	check("dealing damage lights one", hc.mechanicOrbsLit(severine, live()) === 1);
	severine.health = Math.floor(severine.maxHealth / 2) - 1;
	live().enemyArray[0].health = 1;
	check("being hurt and marking prey light the rest", hc.mechanicOrbsLit(severine, live()) === 3);
	check("the orbs store nothing", severine.meterArray == null || severine.meterArray.thirst == null);

	// --- Nettle: a counter with a face ---
	const nettle = member("nettle");
	check("Harvest starts empty", hc.mechanicValue(nettle, "harvest") === 0);
	const downContext = hc.newEffectContext({ combat: live() });
	const victim = live().enemyArray[0];
	victim.health = 0;
	hc.checkDeath(victim, downContext);
	check("an enemy falling is a soul", hc.mechanicValue(nettle, "harvest") === 1);
	const burnContext = hc.newEffectContext({ combat: live() });
	hc.combat.noteExhaust(live().handArray[0] || "card_1", "effect", burnContext, null);
	check("so is a card burned away", hc.mechanicValue(nettle, "harvest") === 2);

	// --- Requirements: reported one by one, and spent ---
	// Each state entry is asked directly, which needs no charges -- a requirement is about the world,
	// not about the ability's own bookkeeping.
	const graveState = hc.abilities.requirementStateArray(nettle, "nettleGraveward", live());
	check("a requirement says what it wants", graveState.length === 1 && graveState[0].text === "Needs 1 Soul.");
	check("and whether it is met", graveState[0].met === true && hc.mechanicValue(nettle, "harvest") === 2);
	hc.addMechanic(nettle, "harvest", -2, null);
	check("an empty meter reads as unmet", hc.abilities.requirementStateArray(nettle, "nettleGraveward", live())[0].met === false);

	// Shield Wall arrives with the warden outfit, so Brienne can actually use it.
	brienne.outfitIndex = "warden";
	hc.abilities.reconcile(brienne);
	hc.addMechanic(brienne, "resolve", -hc.mechanicValue(brienne, "resolve"), null);
	const shortUsability = hc.abilities.usability(brienne, "brienneAegis", live());
	check("the ability says which requirement is missing",
		shortUsability.reason === "requirementNotMet" && shortUsability.explanation === "Needs 1 Resolve.", shortUsability.explanation);
	check("and lists every requirement with its state", shortUsability.requirementArray.length === 1 &&
		shortUsability.requirementArray[0].met === false);

	hc.addMechanic(brienne, "resolve", 8, null);
	check("a met requirement lets it through", hc.abilities.usability(brienne, "brienneAegis", live()).usable === true);
	const resolveBefore = hc.mechanicValue(brienne, "resolve");
	check("using it spends the meter", hc.abilities.use(brienne.instanceId, "brienneAegis", null).played === true &&
		hc.mechanicValue(member("brienne"), "resolve") < resolveBefore - 4,
		"resolve " + resolveBefore + " -> " + hc.mechanicValue(member("brienne"), "resolve"));
	// Spent outright, then partly rebuilt by Brienne's own mechanic: the Temporary HP Aegis hands out
	// counts toward Resolve, so it comes back a little. Net spend.
	check("and the spend leaves it lower than it was", hc.mechanicValue(member("brienne"), "resolve") < resolveBefore,
		"resolve " + hc.mechanicValue(member("brienne"), "resolve") + " (before " + resolveBefore + ")");

	// --- A meter is per fight, and a save carries it ---
	const carried = JSON.parse(JSON.stringify(hc.state));
	check("a meter survives serialisation", hc.mechanicValue(carried.run.partyArray.find((entry) => entry.characterIndex === "nettle"), "harvest") === 0 ||
		carried.run.partyArray.find((entry) => entry.characterIndex === "brienne").meterArray != null);
	hc.state.run.combat = null;
	hc.addMechanic(member("brienne"), "resolve", 5, null);
	hc.combat.begin("loneSporeling", {});
	check("and a new fight resets it to its opening value",
		hc.mechanicValue(member("brienne"), "resolve") === resolveAtStart,
		"resolve " + hc.mechanicValue(member("brienne"), "resolve"));

	// --- Every requirement a content file writes must be a real condition ---
	check("every ability requirement is expressible", hc.abilityArray.every((ability) =>
		(ability.requirementArray == null ? [] : ability.requirementArray).every((requirement) =>
			hc.findDefinition(hc.conditionArray, requirement.condition.index) != null)));
	check("every spend names a real mechanic", hc.abilityArray.every((ability) =>
		(ability.spendArray == null ? [] : ability.spendArray).every((entry) =>
			hc.findDefinition(hc.mechanicArray, entry.mechanic) != null)));
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[54] Round 04 item 25: the charging bar keeps a boss's big moves for later");
{
	const hc = newEngine();
	startRun(hc, 5425);
	hc.combat.begin("matriarchLair", {});
	const boss = () => hc.state.run.combat.enemyArray.find((enemy) => enemy.enemyIndex === "matriarch");
	const chargedArray = hc.findDefinition(hc.enemyArray, "matriarch").moveArray.filter((move) => move.chargeCost != null);

	check("the boss has moves that must be charged up to", chargedArray.length >= 2);
	check("and it starts with no charge", hc.moveCharge(boss()) === 0);

	// --- Nothing charged can be chosen on the opening turn ---
	const openingArray = hc.eligibleMoveArray(boss(), hc.aiMoveArray(boss()));
	check("so none of them is eligible to open the fight",
		openingArray.every((move) => move.chargeCost == null) && openingArray.length > 0);

	// --- The bar fills on its owner's turns ---
	const perTurn = hc.chargePerTurn(boss());
	hc.gainMoveCharge(boss());
	check("a turn of charging counts", hc.moveCharge(boss()) === perTurn);
	for (let turn = 0; turn < 6; turn++) hc.gainMoveCharge(boss());
	check("and it stops at the ceiling", hc.moveCharge(boss()) === hc.tuning.ai.chargeMaximum);

	const charged = hc.eligibleMoveArray(boss(), hc.aiMoveArray(boss()));
	check("a full bar puts the big moves back on the table", charged.some((move) => move.chargeCost != null));

	// --- Choosing one spends it, which is what stops it repeating ---
	const target = boss();
	target.charge = hc.tuning.ai.chargeMaximum;
	const cost = chargedArray[0].chargeCost;
	target.intentCardIndex = null;
	// Force the choice by making that move the only eligible one.
	const onlyArray = [chargedArray[0]];
	const chosen = hc.moveStrategyArray.find((strategy) => strategy.index === "weighted").select(target, onlyArray);
	check("a charged move can be chosen once the bar allows it", chosen != null && chosen.card === chargedArray[0].card);
	// selectMove rolls over the whole list, so it is asked until a charged move comes up: whenever one
	// does, the bar must fall by exactly what that move costs.
	let spentCorrectly = null;
	for (let attempt = 0; attempt < 40 && spentCorrectly == null; attempt++) {
		target.charge = hc.tuning.ai.chargeMaximum;
		target.lastMoveCardIndex = null;
		target.sameMoveCount = 0;
		const pickedIndex = hc.selectMove(target);
		const picked = chargedArray.find((move) => move.card === pickedIndex);
		if (picked != null) spentCorrectly = hc.moveCharge(target) === hc.tuning.ai.chargeMaximum - picked.chargeCost;
	}
	check("choosing one spends exactly what it cost", spentCorrectly === true, "spent " + spentCorrectly);
	check("the cost is the one the content named", cost >= hc.tuning.ai.rareChargeCost);

	// --- A big move looks like one ---
	const bigCard = hc.moveCard(target, chargedArray[0].card);
	check("a charged move wears the rarer vertical frame", bigCard.isRareMove === true && bigCard.layout === "vertical");
	const smallIndex = hc.findDefinition(hc.enemyArray, "matriarch").moveArray.find((move) => move.chargeCost == null).card;
	const smallCard = hc.moveCard(target, smallIndex);
	check("an ordinary one does not", smallCard.isRareMove === false && smallCard.layout !== "vertical");
	check("rareChargeCost is what decides it", hc.tuning.ai.rareChargeCost <= chargedArray[0].chargeCost);

	// --- A whole fight never opens with one, and never repeats one ---
	{
		const fightEngine = newEngine();
		startRun(fightEngine, 777);
		const combat = fightEngine.combat.begin("matriarchLair", {});
		const chargedNameArray = chargedArray.map((move) => move.card);
		const playedArray = [];
		let guard = 0;
		while (combat.phase !== "victory" && combat.phase !== "defeat" && guard++ < 14) {
			const enemyContext = fightEngine.combat.endPlayerTurn() && null;
			const turnContext = fightEngine.combat.runEnemyTurn();
			if (turnContext != null) {
				for (const entry of turnContext.log.filter((line) => line.type === "moveUsed")) playedArray.push(entry.card);
			}
			if (combat.phase === "victory" || combat.phase === "defeat") break;
			fightEngine.combat.startPlayerTurn(fightEngine.newEffectContext({ combat: fightEngine.state.run.combat }));
		}
		check("a real fight never opens on a charged move",
			playedArray.length > 0 && chargedNameArray.indexOf(playedArray[0]) < 0, playedArray.join(","));
		let repeated = false;
		for (let scanIndex = 1; scanIndex < playedArray.length; scanIndex++) {
			if (playedArray[scanIndex] === playedArray[scanIndex - 1] && chargedNameArray.indexOf(playedArray[scanIndex]) >= 0) repeated = true;
		}
		check("and never plays one twice running", repeated === false, playedArray.join(","));
	}
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[55] Round 04 item 24: a card can upgrade more than one way");
{
	const hc = newEngine();
	startRun(hc, 5524);
	const run = hc.state.run;
	const pathed = hc.cardArray.filter((card) => card.upgradePathArray != null);
	check("at least one card offers several paths", pathed.length > 0 && pathed[0].upgradePathArray.length >= 2);

	const definition = pathed[0];
	const instance = hc.addCardToRunDeck(definition.index, null);
	check("a fresh copy has taken no path", instance.upgradePath == null && hc.cardAwaitsUpgradePath(instance) === true);
	check("and its ladder is the first path's until it does",
		hc.cardUpgradeArray(definition, null) === definition.upgradePathArray[0].upgradeArray);
	check("every path names its own ladder", definition.upgradePathArray.every((path) =>
		path.index != null && path.name != null && Array.isArray(path.upgradeArray) && path.upgradeArray.length > 0));

	// --- Upgrading asks which way, and remembers the answer ---
	const first = hc.resolveWithChoices({
		buildContext: () => hc.newEffectContext({}),
		run: (context) => {
			context.targetCardArray = [instance.instanceId];
			hc.resolveEffectArray([{ index: "upgradeTargetCard", levels: 1 }], context);
		},
	});
	check("upgrading it asks which way it should grow",
		first.complete === false && first.choice.index === "option" &&
		first.choice.optionArray.length === definition.upgradePathArray.length,
		first.complete ? "it did not ask" : first.choice.index);
	check("and each option previews what that path gives",
		first.choice.optionArray.every((option) => option.description != null && option.description !== ""));

	const secondPathIndex = definition.upgradePathArray[1].index;
	const second = hc.resolveWithChoices({
		answerArray: first.answerArray.concat([{ chosenArray: [secondPathIndex] }]),
		buildContext: () => hc.newEffectContext({}),
		run: (context) => {
			context.targetCardArray = [instance.instanceId];
			hc.resolveEffectArray([{ index: "upgradeTargetCard", levels: 1 }], context);
		},
	});
	const liveArray = hc.state.run.deckArray.filter((card) => card.cardIndex === definition.index);
	const upgraded = liveArray.find((card) => card.upgradeLevel > 0);
	check("the answer is taken", second.complete === true && upgraded != null && upgraded.upgradePath === secondPathIndex,
		upgraded == null ? "nothing upgraded" : upgraded.upgradePath);

	// --- The card it becomes is that path's card ---
	const resolved = hc.resolveCard(upgraded);
	const expected = hc.resolveCard({ instanceId: null, cardIndex: definition.index, ownerInstanceId: null,
		upgradeLevel: 1, upgradePath: secondPathIndex });
	check("and the card it becomes is that path's", resolved.text === expected.text &&
		JSON.stringify(resolved.costArray) === JSON.stringify(expected.costArray));
	const otherPath = hc.resolveCard({ instanceId: null, cardIndex: definition.index, ownerInstanceId: null,
		upgradeLevel: 1, upgradePath: definition.upgradePathArray[0].index });
	check("the two paths really differ", otherPath.text !== expected.text ||
		JSON.stringify(otherPath.costArray) !== JSON.stringify(expected.costArray));

	// --- A committed copy never asks again, and two copies may differ ---
	check("a committed copy no longer awaits a path", hc.cardAwaitsUpgradePath(upgraded) === false);
	check("it is finished once its ladder runs out", hc.cardUpgradesRemaining(upgraded) === 0);
	const secondCopy = hc.addCardToRunDeck(definition.index, null);
	hc.upgradeCardInstance(secondCopy.instanceId, 1, definition.upgradePathArray[0].index);
	const liveSecond = hc.state.run.deckArray.find((card) => card.instanceId === secondCopy.instanceId);
	check("two copies of one card can go different ways",
		liveSecond.upgradePath === definition.upgradePathArray[0].index &&
		hc.state.run.deckArray.find((card) => card.instanceId === upgraded.instanceId).upgradePath === secondPathIndex);

	// --- A card with no paths is untouched by any of this ---
	const plain = hc.cardArray.find((card) => card.upgradeArray != null && card.upgradePathArray == null && hc.cardIsUpgradable(card));
	check("an ordinary upgradeable card still has its own ladder",
		hc.cardUpgradeArray(plain, null) === plain.upgradeArray);
	const plainInstance = hc.addCardToRunDeck(plain.index, null);
	check("and it never asks which way", hc.cardAwaitsUpgradePath(plainInstance) === false);
	hc.upgradeCardInstance(plainInstance.instanceId, 1, null);
	check("it simply upgrades",
		hc.state.run.deckArray.find((card) => card.instanceId === plainInstance.instanceId).upgradeLevel === 1);
	check("and the save carries the path", JSON.parse(JSON.stringify(hc.state)).run.deckArray
		.find((card) => card.instanceId === upgraded.instanceId).upgradePath === secondPathIndex);
	check("the run is intact", run != null && hc.state.run.deckArray.length > 0);
}


