		startRun(hc, 5713, DEFAULT_PARTY);
		const combat = hc.combat.begin("hollowPatrol", {});
		const knight = combat.enemyArray.find((e) => e.enemyIndex === "hollowKnight");
		const wisp = combat.enemyArray.find((e) => e.enemyIndex === "gloomWisp");
		knight.intentCardIndex = "hollowKnightCleave";
		wisp.intentCardIndex = "gloomWispBeguile";
		hc.forecast.refreshStanding();
		const party = hc.state.run.partyArray;
		const markArray = party.map((m) => hc.forecast.markFor(m.instanceId)).filter((mark) => mark != null);
		check("an all-hitting enemy move reaches the health forecast",
			markArray.some((mark) => mark.healthDelta < 0),
			JSON.stringify(markArray.map((mark) => mark.healthDelta)));
		check("and a random Lust move reaches the lust forecast",
			markArray.some((mark) => mark.lustGained > 0 ||
				(mark.summary != null && mark.summary.lustGained > 0)),
			JSON.stringify(markArray.map((mark) => mark.lustGained)));

		// Beguile ALONE: every candidate must carry the might, not only the one the dry run picked.
		const alone = hc.combat.begin("hollowPatrol", {});
		alone.enemyArray.find((e) => e.enemyIndex === "hollowKnight").intentCardIndex = "hollowKnightBrace";
		alone.enemyArray.find((e) => e.enemyIndex === "gloomWisp").intentCardIndex = "gloomWispBeguile";
		hc.forecast.refreshStanding();
		const mightArray = hc.state.run.partyArray.map((m) => hc.forecast.markFor(m.instanceId));
		check("a random Lust move alone marks every candidate with the might",
			mightArray.every((mark) => mark != null && mark.lustMight > 0),
			JSON.stringify(mightArray.map((mark) => mark == null ? null : mark.lustMight)));
