console.log("\n[61] Round 06 item 10: lust on anyone -- enemies break into defeat, Severine's Enthrall, the Matriarch's cut-in");
{
	const hc = newEngine();
	const context = () => hc.newEffectContext({ combat: hc.state.run.combat });
	const begin = (encounterIndex, seed) => {
		startRun(hc, seed || 6101);
		hc.combat.begin(encounterIndex);
		hc.state.run.combat.phase = "playerTurn";
		return hc.state.run.combat;
	};
	const lust = (target, amount) => {
		const ctx = context();
		hc.gainLust(target, amount, { tagArray: [] }, ctx);
		return ctx;
	};

	// --- Who takes lust, and what breaking does to them ------------------------------------------------
	check("everyone takes lust unless their definition is immune", (() => {
		const combat = begin("sporePair");
		const sporeling = combat.enemyArray[0];
		const sporelingDefinition = hc.findDefinition(hc.enemyArray, "sporeling");
		const ordinary = hc.entityUsesLust(sporeling);
		sporelingDefinition.lustImmune = true;
		const immune = hc.entityUsesLust(sporeling) === false && hc.gainLust(sporeling, 50, { tagArray: [] }, context()) === 0;
		delete sporelingDefinition.lustImmune;
		return ordinary === true && immune;
	})());
	check("characters get the whole Broken state, enemies are defeated by it -- by kind, not team", (() => {
		return hc.entityBreakBehavior({ characterIndex: "severine", side: "enemy" }) === "state" &&
			hc.entityBreakBehavior({ enemyIndex: "sporeling", side: "ally" }) === "defeated" &&
			hc.findDefinition(hc.enemyArray, "matriarch").brokenBehavior == null;
	})());
	check("only the special few play the cut-in: Brienne, Nettle, Severine and the Matriarch", (() => {
		return ["brienne", "nettle", "severine"].every((index) => hc.entityHasBrokenCutIn({ characterIndex: index })) &&
			hc.entityHasBrokenCutIn({ enemyIndex: "matriarch" }) &&
			["sporeling", "capBrute", "gloomWisp", "hollowKnight"].every((index) => !hc.entityHasBrokenCutIn({ enemyIndex: index }));
	})());

	// --- An enemy that breaks is beaten on the spot ----------------------------------------------------
	check("a sporeling whose lust catches its health is out of the fight with no health", (() => {
		const combat = begin("sporePair");
		const sporeling = combat.enemyArray[0];
		const standing = sporeling.health;
		const ctx = lust(sporeling, standing);
		const broken = ctx.log.find((entry) => entry.type === "broken");
		const downed = ctx.log.find((entry) => entry.type === "downed");
		return sporeling.broken === true && sporeling.downed === true && sporeling.health === 0 &&
			broken != null && broken.behavior === "defeated" && broken.cutIn === false &&
			downed != null && downed.cause === "broken" && ctx.log.indexOf(broken) < ctx.log.indexOf(downed);
	})());
	check("short of its health it only builds", (() => {
		const combat = begin("sporePair");
		const sporeling = combat.enemyArray[0];
		lust(sporeling, sporeling.health - 1);
		return sporeling.broken !== true && sporeling.downed !== true && sporeling.lust > 0;
	})());
	check("a lethal hit on an enemy carrying lust is still a kill, not a break", (() => {
		const combat = begin("sporePair");
		const sporeling = combat.enemyArray[0];
		lust(sporeling, 3);
		const ctx = context();
		hc.dealDamage(null, sporeling, 999, {}, ctx);
		const downed = ctx.log.find((entry) => entry.type === "downed");
		return sporeling.downed === true && sporeling.broken !== true && downed != null && downed.cause === "health" &&
			!ctx.log.some((entry) => entry.type === "broken");
	})());
	check("every enemy broken wins, though their health bars were never emptied by damage", (() => {
		const combat = begin("sporePair");
		combat.enemyArray.forEach((enemy) => lust(enemy, enemy.health));
		return hc.combat.checkEnd(context()) === "victory";
	})());
	check("a Severine on the enemy team keeps the whole state: broken, standing", (() => {
		const combat = begin("sporePair");
		hc.resolveEffectArray([{ index: "summon", character: "severine" }], hc.newEffectContext({ source: combat.enemyArray[0], combat }));
		const rival = hc.state.run.combat.enemyArray.find((enemy) => enemy.characterIndex === "severine");
		const ctx = lust(rival, hc.standingAgainstLust(rival));
		const broken = ctx.log.find((entry) => entry.type === "broken");
		return rival.broken === true && rival.downed !== true && broken.behavior === "state" && broken.cutIn === true;
	})());
	check("a player character is still never downed", (() => {
		begin("sporePair");
		const brienne = hc.state.run.partyArray.find((member) => member.characterIndex === "brienne");
		hc.dealDamage(null, brienne, 999, {}, context());
		return brienne.broken === true && brienne.downed !== true;
	})());

	// --- The Matriarch ---------------------------------------------------------------------------------
	check("breaking the Matriarch plays her cut-in, beats her, and wins her lair", (() => {
		const combat = begin("matriarchLair");
		combat.enemyArray.push(hc.combat.newEnemy("sporeling", combat.enemyArray.length));
		const matriarch = combat.enemyArray.find((enemy) => enemy.enemyIndex === "matriarch");
		const ctx = lust(matriarch, matriarch.health);
		const broken = ctx.log.find((entry) => entry.type === "broken");
		return broken != null && broken.cutIn === true && broken.enemyIndex === "matriarch" && matriarch.downed === true &&
			hc.combat.checkEnd(context()) === "victory";
	})());
	check("her cut-in reads her own art from the enemies folder", (() => {
		const matriarch = hc.findDefinition(hc.enemyArray, "matriarch");
		const art = path.join(ROOT, "..", "..", "v13 spire images");
		return hc.brokenOverlay.characterFor({ enemyIndex: "matriarch" }) === matriarch &&
			hc.brokenOverlay.artPathFor(matriarch) === "enemies/matriarch/broken" &&
			fs.existsSync(path.join(art, "enemies", "matriarch", "broken.webp")) &&
			fs.existsSync(path.join(art, "enemies", "matriarch", "brokenBG.webp"));
	})());

	// --- Severine's Enthrall --------------------------------------------------------------------------------
	const severine = hc.findDefinition(hc.characterArray, "severine");
	//Session 25: the starting deck is the two basics (aggressive Rend, defensive Quaff); the old
	//Enthrall/Rake starters are retired from the opening hand.
	check("Severine starts with Rend and Quaff, not Enthrall or Rake", (() => {
		const starting = severine.startingCardArray;
		return starting.some((entry) => entry.index === "severineRend") &&
			starting.some((entry) => entry.index === "severineQuaff") &&
			!starting.some((entry) => entry.index === "severineEnthrall") &&
			!starting.some((entry) => entry.index === "severineStrike");
	})());
	check("it is a Lewd card carrying a lust tag", (() => {
		const resolved = hc.resolveCard({ cardIndex: "severineEnthrall" });
		return hc.cardTypeIndexArray(resolved).join() === "lewd" && resolved.tagArray.indexOf("charm") >= 0;
	})());
	check("played at a sporeling, it lands 7 lust", (() => {
		const combat = begin("sporePair");
		const sporeling = combat.enemyArray[0];
		const severineMember = hc.state.run.partyArray.find((member) => member.characterIndex === "severine");
		const instance = hc.newCardInstance("severineEnthrall", severineMember.instanceId);
		combat.temporaryCardArray = combat.temporaryCardArray || [];
		combat.temporaryCardArray.push(instance);
		combat.handArray.push(instance.instanceId);
		hc.setResource("energy", 3);
		const result = hc.combat.playCard(instance.instanceId, sporeling.instanceId);
		const live = hc.state.run.combat.enemyArray.find((enemy) => enemy.instanceId === sporeling.instanceId);
		return result.played === true && live.lust === 7;
	})());
}

