console.log("\n[62] Round 06 item 11: lust is not a status, lust-only cards are Lewd, Lewd's own frame and icon");
{
	const hc = newEngine();
	const art = path.join(ROOT, "..", "..", "v13 spire images");
	const typeOf = (card) => hc.cardTypeIndexArray(card).join();

	// --- Lust is not a status --------------------------------------------------------------------------
	check("lust has no entry in the status table", hc.findDefinition(hc.statusArray, "lust") == null);
	check("removing a status named lust leaves lust alone", (() => {
		startRun(hc, 6201);
		const member = hc.state.run.partyArray[0];
		member.lust = 5;
		hc.applyStatus(member, "sensitive", 2, hc.newEffectContext({}));
		hc.resolveEffectArray([{ index: "removeStatus", status: "lust" }, { index: "removeStatus", status: "sensitive" }],
			hc.newEffectContext({ source: member, targetArray: [member] }));
		const live = hc.state.run.partyArray.find((entry) => entry.instanceId === member.instanceId);
		return live.lust === 5 && hc.statusStacks(live, "sensitive") === 0;
	})());

	// --- Which cards are Lewd --------------------------------------------------------------------------
	check("a card that only inflicts lust is Lewd", typeOf({ index: "t", targetMode: "enemy", effectArray: [{ index: "lust", amount: 3 }] }) === "lewd");
	check("a card that only applies Sensitive to the other team is Lewd, not Negative",
		typeOf({ index: "t", targetMode: "enemy", effectArray: [{ index: "applyStatus", status: "sensitive", stacks: 1 }] }) === "lewd");
	check("an ordinary debuff is still Negative, and lust on the user's own team is still no type",
		typeOf({ index: "t", targetMode: "enemy", effectArray: [{ index: "applyStatus", status: "weak", stacks: 1 }] }) === "negative" &&
		typeOf({ index: "t", targetMode: "self", effectArray: [{ index: "lust", amount: 3 }, { index: "drawCards", amount: 1 }] }) === "support");
	check("a card that debuffs AND builds lust keeps Negative first (Spores)", typeOf(hc.resolveCard({ cardIndex: "sporelingSpores" })) === "negative,lewd");

	// --- Lewd's own frame and icon ---------------------------------------------------------------------
	const lewd = hc.findDefinition(hc.cardTypeArray, "lewd");
	check("Lewd names its own frame for both layouts, and the files exist", ["vertical", "horizontal"].every((layout) =>
		lewd.framePathByLayout[layout] != null && fs.existsSync(path.join(art, lewd.framePathByLayout[layout] + ".webp"))));
	check("Lewd's icon is its own file, shared with no other type or status", (() => {
		const used = hc.cardTypeArray.filter((type) => type !== lewd).map((type) => type.iconPath)
			.concat(hc.statusArray.map((status) => status.iconPath));
		return fs.existsSync(path.join(art, lewd.iconPath + ".webp")) && used.indexOf(lewd.iconPath) < 0;
	})());
	check("a Lewd card is drawn in the Lewd frame; a Damage card keeps the shared one, and ui.card asks the same function", (() => {
		const shared = hc.tuning.art.cardFrame.horizontal.framePath;
		const primary = (cardIndex) => hc.cardTypeDefinitionArray(hc.resolveCard({ cardIndex: cardIndex }))[0];
		const source = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-ui.js"), "utf8");
		return hc.cardTypeFramePath(primary("severineEnthrall"), "horizontal", shared) === "cards/frames/lewdHorizontal" &&
			hc.cardTypeFramePath(primary("severineStrike"), "horizontal", shared) === shared &&
			/honeycomb\.cardTypeFramePath\(type, layoutIndex, frame\.framePath\)/.test(source);
	})());

	// --- The warning rule ------------------------------------------------------------------------------
	const lustTagWarnings = () => hc.warnings.report().warningArray.filter((warning) => warning.rule === "lustCardTag");
	check("the six lust tags are flagged (round 07 added Penance)", hc.cardTagArray.filter((tag) => tag.lustTag === true).map((tag) => tag.index).join() ===
		"restraint,exposure,charm,venom,torment,penance");
	check("the shipped cards raise no lust-tag warnings", lustTagWarnings().length === 0, JSON.stringify(lustTagWarnings()));
	check("a lust card with no lust tag is reported; a school tag alone does not count", (() => {
		hc.cardArray.push({ index: "testUntaggedLust", name: "Untagged", characterIndex: "neutral", rarity: "special", costArray: { energy: 1 },
			targetMode: "enemy", tagArray: ["necromancy"], effectArray: [{ index: "lust", amount: 4 }] });
		const found = lustTagWarnings().some((warning) => /testUntaggedLust/.test(warning.message));
		hc.cardArray.pop();
		return found;
	})());
}

