console.log("\n[71] Round 06 items 16-24 (session 12)");
{
	// The map preview's foe count matches the actual line-up. Since session 21 there is NO count
	// scaling, so the count is the encounter's own at any party size.
	const hc = newEngine();
	const bigParty = [
		{ characterIndex: "brienne", outfitIndex: "default" },
		{ characterIndex: "nettle", outfitIndex: "default" },
		{ characterIndex: "severine", outfitIndex: "default" },
		{ characterIndex: "cinder", outfitIndex: "default" },
		{ characterIndex: "clemence", outfitIndex: "default" },
		{ characterIndex: "cassadora", outfitIndex: "default" },
	];
	startRun(hc, 7200, bigParty);
	const encounter = hc.findDefinition(hc.encounterArray, "loneSporeling");
	const predicted = hc.combat.scaledEnemyCount(encounter);
	const actual = hc.combat.scaledLineUpArray(encounter).length;
	check("the preview's foe count matches the line-up", predicted === actual, predicted + " vs " + actual);
	check("and no party size is shown facing extra foes",
		predicted === encounter.enemyIndexArray.length, String(predicted));
}
{
	// Item 20: costume rates and the obtainable-card list. Rates are for the outfit worn NOW.
	const hc = newEngine();
	startRun(hc, 7201, DEFAULT_PARTY);
	const loadout = (outfitIndex) => ({ characterIndex: "severine", outfitIndex: outfitIndex, equipmentArray: [] });
	const stateFor = (cardIndex, outfitIndex) => hc.cardOfferState("severine", hc.findDefinition(hc.cardArray, cardIndex), loadout(outfitIndex));
	check("a costume-only card is blocked in an outfit that cannot offer it",
		stateFor("severineHeartsToll", "default") === "blocked", stateFor("severineHeartsToll", "default"));
	check("and is offered (boosted) in the outfit it names",
		stateFor("severineHeartsToll", "crimsonCovenant") === "boosted", stateFor("severineHeartsToll", "crimsonCovenant"));
	hc.findDefinition(hc.cardArray, "severineBloodthirst").offerWeightArray =
		[{ condition: { index: "wearsOutfit", outfit: "bloodSaint", character: "severine" }, multiplier: 0.5 }];
	check("a reduced-rate card is reduced only in that outfit",
		stateFor("severineBloodthirst", "bloodSaint") === "reduced" && stateFor("severineBloodthirst", "default") === "normal");
	check("a boosted-rate card is boosted only in that outfit",
		stateFor("severineHamstring", "huntress") === "boosted" && stateFor("severineHamstring", "default") === "normal");
	// AUDIT-01: OUTFITS-LIST REDUCES the opposed sister rather than blocking it (Huntress reduces self-damage).
	check("an outfit reduces the sister mechanic it opposes, and leaves the rest alone",
		stateFor("severineLeechMark", "huntress") === "normal" && stateFor("severineBloodPrice", "huntress") === "reduced",
		stateFor("severineLeechMark", "huntress") + " / " + stateFor("severineBloodPrice", "huntress"));
	// The reasons NAME the outfit and multiplier, so a badge can explain itself.
	const heartsTollInfo = hc.cardOfferStateInfo("severine", hc.findDefinition(hc.cardArray, "severineHeartsToll"), loadout("default"));
	check("a blocked card names the outfit it needs",
		heartsTollInfo.state === "blocked" && heartsTollInfo.reasonArray.some((reason) => reason.toLowerCase().indexOf("default") >= 0),
		heartsTollInfo.reasonArray.join(" | "));
	check("a boosted card names the outfit and the multiplier",
		hc.cardOfferStateInfo("severine", hc.findDefinition(hc.cardArray, "severineHamstring"), loadout("huntress")).reasonArray.some((reason) => reason.indexOf("Huntress") >= 0 && reason.indexOf("×3") >= 0));
	const list = hc.obtainableCardArray("severine");
	check("the obtainable list is that character's cards", list.length > 0 && list.every((card) => card.characterIndex === "severine"));
	check("and it includes both a costume-only and a plain card",
		list.some((card) => card.index === "severineHeartsToll") && list.some((card) => card.index === "severineQuaff"));

	const run = hc.state.run;
	const severine = run.partyArray.find((member) => member.characterIndex === "severine");
	check("a costume-only card is not offerable without the outfit",
		hc.cardOfferableForParty(hc.findDefinition(hc.cardArray, "severineHeartsToll")) === false);
	severine.outfitIndex = "crimsonCovenant";
	check("and is offerable while the outfit is worn",
		hc.cardOfferableForParty(hc.findDefinition(hc.cardArray, "severineHeartsToll")) === true);
}
{
	// Item 17: the VFX blend is read from the file's suffix first, the corners as the backup.
	const hc = newEngine();
	check("the additive test effect has an additive rule",
		hc.tuning.vfx.suffixRuleArray.some((rule) => rule.suffix === "-additive" && rule.blend === "additive"));
	check("the green test effect keys green",
		hc.tuning.vfx.suffixRuleArray.some((rule) => rule.suffix === "-green" && rule.blend === "chroma" && rule.chromaColor[1] === 255));
	check("the magenta test effect keys magenta",
		hc.tuning.vfx.suffixRuleArray.some((rule) => rule.suffix === "-magenta" && rule.blend === "chroma" && rule.chromaColor[0] === 255));
	check("an attack may opt out of a VFX",
		hc.findDefinition(hc.cardArray, "severineRend").effectArray[0].effectArray[0].vfx === "none");
	check("an attack may name its own VFX",
		hc.findDefinition(hc.cardArray, "severineNightfall").effectArray[0].vfx === "vfx/test-magenta");
}

