console.log("\n[72] Session 15: the tooltip text table");
{
	const hc = newEngine();
	if (hc.ui.trimNumber == null) hc.ui.trimNumber = (value) => String(value);
	const indexArray = hc.tooltipTextArray.map((entry) => entry.index);
	check("the table has entries, each with an index and text",
		indexArray.length > 50 && hc.tooltipTextArray.every((entry) => typeof entry.index === "string" && typeof entry.text === "string"));
	check("no index is written twice in the shipped table", new Set(indexArray).size === indexArray.length);

	// Every key the game asks for, read from the source: text("..."), html("..."), countText("...").
	const sourceText = ["honeycomb-tooltip.js", "honeycomb-scene-teambuilding.js"]
		.map((name) => fs.readFileSync(path.join(ROOT, "honeycomb", name), "utf8")).join("\n");
	// Built from a prefix at run time: "weaknessReset.refusal." + the refusal reason.
	const dynamicPrefixArray = ["weaknessReset.refusal.", "banish."];
	const askedArray = [];
	const pattern = /tooltip\.(text|html|countText)\("([^"]+)"/g;
	let match;
	while ((match = pattern.exec(sourceText)) != null) {
		if (dynamicPrefixArray.indexOf(match[2]) >= 0) continue;
		askedArray.push(...(match[1] === "countText" ? [match[2] + ".one", match[2] + ".many"] : [match[2]]));
	}
	const missing = askedArray.filter((index) => indexArray.indexOf(index) < 0);
	check("every key the tooltips ask for is in the table", missing.length === 0, missing.join(", "));
	// USED means named anywhere in the source as a string, since some keys are chosen by a ternary first.
	const usedFlat = indexArray.filter((index) => sourceText.indexOf('"' + index + '"') >= 0 ||
		sourceText.indexOf('"' + index.replace(/\.(one|many)$/, "") + '"') >= 0);
	const unused = indexArray.filter((index) => usedFlat.indexOf(index) < 0 && dynamicPrefixArray.every((prefix) => index.indexOf(prefix) !== 0));
	check("every entry in the table is used", unused.length === 0, unused.join(", "));

	check("tokens are filled", hc.tooltip.text("weakness.toNextRank", { amount: 7 }) === "7 to next rank.");
	check("a count picks one or many",
		hc.tooltip.countText("ability.charges", 1) === "1 charge" && hc.tooltip.countText("ability.charges", 3) === "3 charges");
	check("a missing index prints itself in brackets", (() => {
		expectErrors = true;
		const shown = hc.tooltip.text("no.such.entry");
		expectErrors = false;
		return shown === "[no.such.entry]";
	})());
	check("a later entry replaces an earlier one (mods, translations)", (() => {
		hc.tooltipTextArray.push({ index: "health.heading", text: "Vigour" });
		hc.tooltip.textByIndex = null;
		const replaced = hc.tooltip.text("health.heading") === "Vigour";
		hc.tooltipTextArray.pop();
		hc.tooltip.textByIndex = null;
		return replaced && hc.tooltip.text("health.heading") === "Health";
	})());
	check("rendered panels read the table and leave no bracketed keys", (() => {
		const render = (kind, key, element) => hc.findDefinition(hc.tooltipKindArray, kind).render(key, element);
		const markupArray = [
			render("weaknessBench", "severine"),
			render("equipmentCapacity", "3"),
			render("status", "poison", { dataset: { hcstacks: "1" } }),
			render("weaknessRank", 2),
		];
		return markupArray.every((markup) => markup !== "" && markup.indexOf("[") < 0) &&
			markupArray[0].indexOf("Time on the bench") >= 0 && markupArray[2].indexOf("1 stack") >= 0;
	})());
}

