console.log("\n[73] Session 16: the second boss, the elite pool, and the rest of the roster");
{
	const hc = newEngine();
	// A run is needed before anything draws from the encounter stream.
	startRun(hc, 7301, DEFAULT_PARTY);

	// Every one of the newly drawn enemies is fielded by an encounter.
	const fielded = new Set();
	for (const encounter of hc.encounterArray) for (const enemy of encounter.enemyIndexArray) fielded.add(enemy);
	const newcomerArray = ["gardener", "sage", "alchemist", "shield", "scavenger", "juggernaut"];
	check("every newly drawn enemy is fielded by an encounter",
		newcomerArray.every((index) => fielded.has(index)),
		newcomerArray.filter((index) => !fielded.has(index)).join(", "));

	// The elite pool is separate from the ordinary one, so an elite stop is an opt-in fight.
	const elite = hc.rollEncounter("middle", { elite: true });
	const ordinary = hc.rollEncounter("middle", { elite: false });
	check("an elite node rolls an elite encounter", elite != null && elite.isElite === true, elite == null ? "null" : elite.index);
	check("a combat node rolls a non-elite encounter", ordinary != null && ordinary.isElite !== true, ordinary == null ? "null" : ordinary.index);
	check("the scavenger is the game's first elite",
		hc.findDefinition(hc.enemyArray, "scavenger").tagArray.indexOf("elite") >= 0);

	// Both bosses are met exactly once: a run clears two floors, and each floor names a different boss.
	const regionByIndex = (index) => hc.findDefinition(hc.regionArray, index);
	const upper = regionByIndex("upperCatacombs");
	const vault = regionByIndex("floodedVault");
	// LANE E7: a run's LENGTH is tuning.map.route.regionsPerRun now, not the size of regionArray --
	// that table holds sub-act alternatives a single run never all visits.
	check("a run has two floors naming two different bosses",
		hc.tuning.map.route.regionsPerRun === 2 && upper.bossEncounterIndex !== vault.bossEncounterIndex,
		upper.bossEncounterIndex + " / " + vault.bossEncounterIndex);
	const bossLineUp = (encounterIndex) => hc.findDefinition(hc.encounterArray, encounterIndex).enemyIndexArray;
	check("the first floor ends at the Matriarch", bossLineUp(upper.bossEncounterIndex).indexOf("matriarch") >= 0);
	check("the second floor ends at the Juggernaut", bossLineUp(vault.bossEncounterIndex).indexOf("juggernaut") >= 0);

	// A procedural map actually places elite nodes, holds them back to the middle stretch, and fields
	// only elite encounters on them.
	const earlyEliteArray = [];
	const mislabelledArray = [];
	let eliteSeen = 0;
	for (let seed = 7400; seed < 7440; seed++) {
		startRun(hc, seed, DEFAULT_PARTY);
		const map = hc.map.generateRegion("upperCatacombs");
		const depthTotal = map.rowArray.length - 1;
		for (let rowIndex = 0; rowIndex < map.rowArray.length; rowIndex++) {
			for (const node of map.rowArray[rowIndex]) {
				if (node.typeIndex !== "elite") continue;
				eliteSeen++;
				const fraction = depthTotal <= 0 ? 1 : rowIndex / depthTotal;
				if (fraction < hc.tuning.map.eliteEarliestDepthFraction) earlyEliteArray.push(seed + ":" + rowIndex);
				const encounter = hc.findDefinition(hc.encounterArray, node.encounterIndex);
				if (encounter == null || encounter.isElite !== true) mislabelledArray.push(seed + ":" + node.encounterIndex);
			}
		}
	}
	check("elite nodes appear on a procedural map", eliteSeen > 0, String(eliteSeen));
	check("no elite node appears before the elite depth gate", earlyEliteArray.length === 0, earlyEliteArray.join(", "));
	check("every elite node fields an elite encounter", mislabelledArray.length === 0, mislabelledArray.join(", "));

	// Mechanically distinct: he owns POSITION, she owns SUMMONS. Neither repeats the other's primitive.
	const cardFor = (move) => hc.findDefinition(hc.cardArray, move.card);
	const hasEffect = (cardArray, effectIndex) =>
		cardArray.some((card) => (card.effectArray || []).some((entry) => entry.index === effectIndex));
	const juggernautMoves = hc.findDefinition(hc.enemyArray, "juggernaut").moveArray.map(cardFor);
	const matriarchMoves = hc.findDefinition(hc.enemyArray, "matriarch").moveArray.map(cardFor);
	check("the Juggernaut disrupts party order", hasEffect(juggernautMoves, "shiftParty"));
	check("the Juggernaut reaches the back line", hasEffect(juggernautMoves, "shiftParty") && juggernautMoves.some((card) => card.targetMode === "backEnemy"));
	check("the Matriarch owns summons, not position",
		hasEffect(matriarchMoves, "summonEnemy") && !hasEffect(matriarchMoves, "shiftParty"));

	// His own rule overrides the bar (session 19): he ALWAYS opens with Avalanche, whatever it costs.
	const openingArray = [];
	for (let seed = 7300; seed < 7330; seed++) {
		startRun(hc, seed, DEFAULT_PARTY);
		const combat = hc.combat.begin("juggernautHollow", {});
		const boss = combat.enemyArray.find((enemy) => enemy.enemyIndex === "juggernaut");
		openingArray.push(boss.intentCardIndex);
	}
	check("the Juggernaut always opens with Avalanche",
		openingArray.length > 0 && openingArray.every((card) => card === "juggernautAvalanche"), openingArray.join(", "));
}

