console.log("\n[74] Session 17: elite prizes, generic relics, and longer floors");
{
	const hc = newEngine();
	const run = startRun(hc, 7401, DEFAULT_PARTY);
	const combat = hc.combat.begin("scavengerAlone", {});

	// --- An elite leans the card spread toward rares ---
	check("the elite rarity table favours rares",
		hc.tuning.reward.eliteRarityWeightArray.rare > hc.tuning.reward.rarityWeightArray.rare);
	const offerMember = run.partyArray.find((member) => member.characterIndex === "severine");
	const normalPool = hc.combat.rewardPoolFor(offerMember, combat, []);
	const elitePool = hc.combat.rewardPoolFor(offerMember, combat, [], null, hc.tuning.reward.eliteRarityWeightArray);
	const normalWeight = {};
	for (const entry of normalPool) normalWeight[entry.index] = entry.weight;
	const rareEntry = elitePool.find((entry) => {
		const card = hc.findDefinition(hc.cardArray, entry.index);
		return card != null && card.rarity === "rare";
	});
	check("an elite weights a rare card above the ordinary table",
		rareEntry != null && rareEntry.weight > normalWeight[rareEntry.index],
		rareEntry == null ? "no rare in the pool" : rareEntry.index + ": " + normalWeight[rareEntry.index] + " -> " + rareEntry.weight);

	// --- An elite and a boss always pay a relic ---
	check("an elite fight always pays a relic",
		hc.combat.rollRewardRelic(hc.findDefinition(hc.encounterArray, "scavengerAlone")) != null);
	check("a boss fight always pays a relic",
		hc.combat.rollRewardRelic(hc.findDefinition(hc.encounterArray, "juggernautHollow")) != null);
	// The roll reaches the reward object the victory screen reads.
	startRun(hc, 7402, DEFAULT_PARTY);
	hc.combat.begin("scavengerCache", {});
	const reward = hc.combat.finishVictory();
	check("an elite victory carries its relic into the reward",
		reward != null && reward.relicIndex != null, reward == null ? "no reward" : String(reward.relicIndex));

	// --- Three generic relics join the pool ---
	const genericArray = ["wardstone", "travelersLantern", "pilgrimsBell"];
	check("the three generic relics are in the relic table",
		genericArray.every((index) => hc.findDefinition(hc.relicArray, index) != null));
	check("they are generic: no offerCondition and no character",
		genericArray.every((index) => {
			const relic = hc.findDefinition(hc.relicArray, index);
			return relic.offerCondition == null && relic.characterIndex == null;
		}));
	startRun(hc, 7403, [{ characterIndex: "nettle", outfitIndex: "default" }]);
	check("a party can be offered a generic relic",
		hc.uncarriedRelicArray().some((relic) => genericArray.indexOf(relic.index) >= 0));

	// --- The floors are longer, and a longer floor is a wider one ---
	check("the procedural floor doubled its rows",
		hc.findDefinition(hc.regionArray, "upperCatacombs").rowCount >= 18);
	const vault = hc.findDefinition(hc.regionArray, "floodedVault");
	check("every anchored backdrop is a panorama with a doubled anchor set",
		vault.backdropArray.every((backdrop) => backdrop.aspect > 2.5 && backdrop.anchorArray.length >= 20),
		vault.backdropArray.map((backdrop) => backdrop.index + " " + backdrop.aspect.toFixed(2) + " / " + backdrop.anchorArray.length).join("; "));
	startRun(hc, 7404, DEFAULT_PARTY);
	hc.map.generateRegion("upperCatacombs");
	const upperView = hc.map.viewBox();
	check("a long procedural floor is proportionally wider than the base aspect",
		upperView.width / upperView.height > hc.tuning.map.frame.stageAspect * 1.5,
		(upperView.width / upperView.height).toFixed(2));
	startRun(hc, 7405, DEFAULT_PARTY);
	hc.map.generateRegion("floodedVault");
	const vaultView = hc.map.viewBox();
	check("an anchored floor takes its painting's panoramic aspect",
		vaultView.width / vaultView.height > 2.5,
		(vaultView.width / vaultView.height).toFixed(2));
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[75] Session 18: the Juggernaut's identity, cleanse, and thrown cards");
{
	const hc = newEngine();
	const run = startRun(hc, 8100, DEFAULT_PARTY);
	const combat = hc.combat.begin("scavengerAlone", {});
	const juggernaut = hc.findDefinition(hc.enemyArray, "juggernaut");

	// --- Identity: every attack but Log Sweep lays 3 Sundered, and the companion cleanses ---
	const moveCard = (index) => hc.findDefinition(hc.cardArray, index);
	const hasEffect = (card, effectIndex) => (card.effectArray || []).some((entry) => entry.index === effectIndex);
	const sunderedEntry = (card) => (card.effectArray || []).find((entry) => entry.index === "applyStatus" && entry.status === "sundered");
	const attackArray = juggernaut.moveArray.map((move) => moveCard(move.card)).filter((card) => hasEffect(card, "damage"));
	//Log Sweep Weakens instead; Overhead Smash is the payoff and lays nothing.
	const debuffArray = attackArray.filter((card) => card.index !== "juggernautSweep" && card.index !== "juggernautOverhead");
	check("every debuffing Juggernaut attack lays 3 Sundered",
		debuffArray.length > 0 && debuffArray.every((card) => {
			const entry = sunderedEntry(card);
			return entry != null && entry.stacks === 3;
		}),
		debuffArray.map((card) => card.index).join(", "));
	const sweep = moveCard("juggernautSweep");
	const sweepWeak = (sweep.effectArray || []).find((entry) => entry.index === "applyStatus" && entry.status === "weak");
	check("Log Sweep Weakens only the front, for 3",
		sweepWeak != null && sweepWeak.stacks === 3 && sweepWeak.targetOverride === "frontEnemy" && sunderedEntry(sweep) == null,
		JSON.stringify(sweepWeak));
	const supportArray = juggernaut.moveArray.map((move) => moveCard(move.card)).filter((card) => hasEffect(card, "cleanse"));
	check("the companion has support moves that cleanse", supportArray.length >= 1,
		supportArray.map((card) => card.index).join(", "));

	// --- The opening move, and the Sundered payoff ---
	check("the Juggernaut is defined to open with Avalanche", juggernaut.openingMove === "juggernautAvalanche");
	const openingEngine = newEngine();
	startRun(openingEngine, 8200, DEFAULT_PARTY);
	const openingCombat = openingEngine.combat.begin("juggernautHollow", {});
	const openingBoss = openingCombat.enemyArray.find((enemy) => enemy.enemyIndex === "juggernaut");
	check("and the engine telegraphs Avalanche on turn one",
		openingBoss.intentCardIndex === "juggernautAvalanche", String(openingBoss.intentCardIndex));
	const overhead = moveCard("juggernautOverhead");
	const overheadDamage = (overhead.effectArray || []).find((entry) => entry.index === "damage");
	check("Overhead Smash doubles against Sundered and applies nothing",
		overheadDamage != null && JSON.stringify(overheadDamage.amount).indexOf("ifStatus") >= 0 && !hasEffect(overhead, "applyStatus"));
	check("Avalanche is manually typed as a damage card",
		moveCard("juggernautAvalanche").typeArray != null && moveCard("juggernautAvalanche").typeArray.indexOf("damage") >= 0);

	// --- Behaviour: Log Sweep Weakens only the front; Overhead doubles against Sundered ---
	const sweepEngine = newEngine();
	const sweepRun = startRun(sweepEngine, 8300, DEFAULT_PARTY);
	const sweepCombat = sweepEngine.combat.begin("juggernautHollow", {});
	const sweepBoss = sweepCombat.enemyArray.find((enemy) => enemy.enemyIndex === "juggernaut");
	const sweepCard = sweepEngine.moveCard(sweepBoss, "juggernautSweep");
	const sweepContext = sweepEngine.newEffectContext({ source: sweepBoss, combat: sweepCombat, log: [] });
	sweepEngine.applyResolvedTargets(sweepContext, sweepCard.targetMode, sweepEngine.resolveTargetMode(sweepCard.targetMode, sweepContext));
	sweepEngine.resolveEffectArray(sweepCard.effectArray, sweepContext);
	const weakArray = sweepRun.partyArray.map((entry) => sweepEngine.statusStacks(entry, "weak"));
	check("Log Sweep Weakens only the front member, for 3",
		sweepEngine.statusStacks(sweepRun.partyArray[0], "weak") === 3 && weakArray.filter((count) => count > 0).length === 1,
		weakArray.join(", "));

	const damageFromOverhead = (withSundered) => {
		const engine = newEngine();
		const run = startRun(engine, withSundered ? 8302 : 8301, DEFAULT_PARTY);
		const fight = engine.combat.begin("juggernautHollow", {});
		const boss = fight.enemyArray.find((enemy) => enemy.enemyIndex === "juggernaut");
		const target = run.partyArray[0];
		if (withSundered) engine.applyStatus(target, "sundered", 1, engine.newEffectContext({ source: boss, combat: fight }));
		//Temporary HP absorbs part of a hit, so the damage is the drop in health AND temporary health.
		const before = target.health + target.temporaryHealth;
		const card = engine.moveCard(boss, "juggernautOverhead");
		const context = engine.newEffectContext({ source: boss, combat: fight, log: [] });
		engine.applyResolvedTargets(context, card.targetMode, engine.resolveTargetMode(card.targetMode, context));
		engine.resolveEffectArray(card.effectArray, context);
		return before - (target.health + target.temporaryHealth);
	};
	const baseOverhead = damageFromOverhead(false);
	const sunderedOverhead = damageFromOverhead(true);
	//Sundered 1 is 1.25x, applied on top of Overhead's own doubling: 12 x 2 x 1.25 = 30.
	check("Overhead Smash doubles against a Sundered target",
		baseOverhead === 12 && sunderedOverhead === 30, baseOverhead + " -> " + sunderedOverhead);

	// --- Cleanse strips debuffs, leaves buffs ---
	const member = run.partyArray[0];
	const statusContext = hc.newEffectContext({ source: member, combat: combat });
	hc.applyStatus(member, "weak", 2, statusContext);
	hc.applyStatus(member, "poison", 3, statusContext);
	hc.applyStatus(member, "strength", 2, statusContext);
	const cleanseContext = hc.newEffectContext({ source: member, combat: combat, log: [] });
	cleanseContext.targetArray = [member];
	hc.resolveEffectArray([{ index: "cleanse" }], cleanseContext);
	check("cleanse removes every debuff", hc.statusStacks(member, "weak") === 0 && hc.statusStacks(member, "poison") === 0);
	check("cleanse leaves buffs alone", hc.statusStacks(member, "strength") === 2);

	// --- A thrown item expands into a card and resolves on a random party member ---
	const scrapfall = moveCard("juggernautAvalanche");
	check("Scrapfall expands cards rather than dealing damage directly",
		hasEffect(scrapfall, "throwRandomCards") && !hasEffect(scrapfall, "damage"));
	const pool = scrapfall.effectArray.find((entry) => entry.index === "throwRandomCards").cardArray;
	const onceEverArray = pool.map((index) => moveCard(index)).filter((card) => card.onceEver === true);
	check("the throw pool holds nine things, exactly one of them once-ever",
		pool.length === 9 && onceEverArray.length === 1,
		pool.length + " / once-ever " + onceEverArray.length);
	const healthBefore = run.partyArray.reduce((sum, entry) => sum + entry.health, 0);
	const throwContext = hc.newEffectContext({ source: combat.enemyArray[0], combat: combat, log: [] });
	hc.resolveEffectArray([{ index: "throwRandomCards", count: 1, cardArray: ["thrownScrap"] }], throwContext);
	const healthAfter = run.partyArray.reduce((sum, entry) => sum + entry.health, 0);
	check("a thrown item logs as a move and lands on a random party member",
		throwContext.log.some((entry) => entry.type === "moveUsed" && entry.card === "thrownScrap") && healthAfter < healthBefore,
		healthBefore + " -> " + healthAfter);

	// --- The once-ever item fires once, then is gone for good ---
	const locketContext = hc.newEffectContext({ source: combat.enemyArray[0], combat: combat, log: [] });
	hc.resolveEffectArray([{ index: "throwRandomCards", count: 1, cardArray: ["thrownLocket"] }], locketContext);
	check("the once-ever item is recorded and pays a relic",
		hc.state.profile.onceEverArray.indexOf("thrownLocket") >= 0 && run.relicArray.length > 0,
		"flag " + (hc.state.profile.onceEverArray.indexOf("thrownLocket") >= 0) + ", relics " + run.relicArray.length);
	const againContext = hc.newEffectContext({ source: combat.enemyArray[0], combat: combat, log: [] });
	hc.resolveEffectArray([{ index: "throwRandomCards", count: 1, cardArray: ["thrownLocket"] }], againContext);
	check("a once-ever item already thrown is never thrown again",
		againContext.log.every((entry) => entry.type !== "moveUsed"),
		againContext.log.map((entry) => entry.type).join(", "));

	// --- The locket is exclusive to the Juggernaut encounter ---
	const locket = hc.findDefinition(hc.cardArray, "thrownLocket");
	const throwers = hc.cardArray
		.filter((card) => (card.effectArray || []).some((entry) => entry.cardArray != null && entry.cardArray.indexOf("thrownLocket") >= 0))
		.map((card) => card.index);
	check("only the Juggernaut's Avalanche can throw the locket",
		throwers.length === 1 && throwers[0] === "juggernautAvalanche", throwers.join(", "));
	check("the locket is an enemy card, so no reward or shop can offer it",
		locket != null && locket.rarity === "enemy" &&
		hc.tuning.reward.offerableRarityArray.indexOf(locket.rarity) < 0);
	// Nothing else in the content tables names it: no event grants it, no relic or equipment is it.
	const elsewhere = [];
	for (const event of hc.eventArray) {
		for (const choice of event.choiceArray || []) {
			for (const entry of choice.effectArray || []) {
				if (entry.card === "thrownLocket") elsewhere.push("event " + event.index);
			}
		}
	}
	check("no event, relic or equipment grants the locket", elsewhere.length === 0, elsewhere.join(", "));
}

console.log("\n[76] Art pass: card fit measured from font widths, with no browser");
{
	const hc = newEngine();
	const fit = hc.tuning.warnings.cardFit;
	const css = fs.readFileSync(path.join(ROOT, "..", "css", "honeycomb.css"), "utf8");
	// The body of the one rule whose selector list is exactly `selector`.
	const block = (selector) => {
		const start = css.indexOf("\n" + selector + " {");
		return start < 0 ? "" : css.slice(start, css.indexOf("}", start));
	};
	const number = (text, pattern) => { const match = text.match(pattern); return match == null ? null : Number(match[1]); };
	const percent = (text, property) => number(text, new RegExp("\\n\\s*" + property + ":\\s*([\\d.]+)%"));
	const cardUnits = (text, property) => number(text, new RegExp("\\n\\s*" + property + ":\\s*calc\\(([\\d.]+) \\* var\\(--hc-card-u\\)"));
	const plain = (text, property, unit) => number(text, new RegExp("\\n\\s*" + property + ":\\s*([\\d.]+)" + (unit || "") + "\\s*;"));

	// --- The measured boxes are the stylesheet's boxes ---
	const name = hc.findDefinition(fit.partArray, "name");
	const nameCss = block(".hcCardName");
	const smallNameCss = block(".hcCardSize-small .hcCardName");
	const row = hc.findDefinition(fit.partArray, "supertypes");
	const rowCss = block(".hcCardSupertypeRow");
	const text = hc.findDefinition(fit.partArray, "text");
	const textCss = block(".hcCardText");
	const icons = hc.findDefinition(fit.partArray, "supertypeIcons");
	const iconsCss = block(".hcCardSupertypeIcons");
	const mismatchArray = [];
	const same = (label, tuned, fromCss) => { if (tuned !== fromCss) mismatchArray.push(label + " tuning " + tuned + " css " + fromCss); };
	same("name left", name.leftPercent, percent(nameCss, "left"));
	same("name right", name.rightPercent, percent(nameCss, "right"));
	same("name height", name.heightPercent, percent(nameCss, "height"));
	same("name font", name.fontSizeUnits, number(nameCss, /font-size:\s*calc\(([\d.]+) \* var\(--hc-card-u\)/));
	same("name letter spacing", name.letterSpacingEm, plain(nameCss, "letter-spacing", "em"));
	same("name line height", name.lineHeight, plain(nameCss, "line-height"));
	same("name wrap line height", name.wrapLineHeight, number(css, /\.hcCardName\.hcCardNameWrap \{[^}]*line-height:\s*([\d.]+)/));
	same("small name left", name.bySize.small.leftPercent, percent(smallNameCss, "left"));
	same("small name right", name.bySize.small.rightPercent, percent(smallNameCss, "right"));
	same("small name height", name.bySize.small.heightPercent, percent(smallNameCss, "height"));
	same("supertypes left", row.leftPercent, percent(rowCss, "left"));
	same("supertypes right", row.rightPercent, percent(rowCss, "right"));
	same("supertypes font", row.fontSizeUnits, number(rowCss, /font-size:\s*calc\(([\d.]+) \* var\(--hc-card-u\)/));
	same("supertypes letter spacing", row.letterSpacingEm, plain(rowCss, "letter-spacing", "em"));
	same("supertypes column gap", row.columnGapEm, plain(rowCss, "column-gap", "em"));
	same("supertypes uppercase", row.uppercase, /text-transform:\s*uppercase/.test(rowCss));
	same("supertype icon gap", row.iconGapEm, plain(block(".hcCardSupertype"), "gap", "em"));
	same("supertype icon height", row.iconWidthEm, number(css, /\.hcCardSupertype img,\s*\.hcCardSupertype svg \{[^}]*height:\s*([\d.]+)em/));
	same("text left", text.leftPercent, percent(textCss, "left"));
	same("text right", text.rightPercent, percent(textCss, "right"));
	same("text top", text.topPercent, percent(textCss, "top"));
	same("text bottom", text.bottomPercent, percent(textCss, "bottom"));
	same("text font", text.fontSizeUnits, number(textCss, /font-size:\s*calc\(([\d.]+) \* var\(--hc-card-u\)/));
	same("text line height", text.lineHeight, plain(textCss, "line-height"));
	same("icons left", icons.leftPercent, percent(iconsCss, "left"));
	same("icons right", icons.rightPercent, percent(iconsCss, "right"));
	same("icons gap", icons.iconGapUnits, cardUnits(iconsCss, "gap"));
	same("icon width", icons.iconWidthUnits, number(css, /\.hcCardSupertypeIcons img,\s*\.hcCardSupertypeIcons svg \{[^}]*width:\s*calc\(([\d.]+) \* var\(--hc-card-u\)/));
	same("name font family", name.font === "display", /font-family:\s*var\(--hc-font-display\)/.test(nameCss));
	same("text font family", text.font === "body", /font-family:\s*var\(--hc-font-body\)/.test(textCss));
	check("every measured box, font size and spacing matches scripts/css/honeycomb.css", mismatchArray.length === 0, mismatchArray.join("; "));

	// --- The font table is what the font files say ---
	const metricsCheck = require("child_process").spawnSync(process.execPath,
		[path.join(__dirname, "generate-font-metrics.js"), "--check"], { encoding: "utf8" });
	check("honeycomb-font-metrics.js is up to date with the font files (generate-font-metrics.js --check)",
		metricsCheck.status === 0, (metricsCheck.stdout || "") + (metricsCheck.stderr || ""));
	const fontByToken = {};
	(css.match(/--hc-font-(body|display):\s*([a-z]+)/g) || []).forEach((line) => {
		const parts = line.split(/:\s*/);
		fontByToken[parts[0]] = parts[1];
	});
	check("each measured font is the family the stylesheet names first", hc.fontMetricArray.every((metric) =>
		path.basename(metric.file, path.extname(metric.file)) === fontByToken[metric.cssToken]),
		JSON.stringify(fontByToken));

	// --- Widths are real widths, not character counts ---
	check("a line of wide letters measures wider than a line of narrow ones of the same length",
		hc.warnings.textWidthEm("WWWWWW", "body") > 2 * hc.warnings.textWidthEm("iiiiii", "body"));
	check("letter spacing, uppercase and synthesised bold each widen a line",
		hc.warnings.textWidthEm("abc", "display", { letterSpacingEm: 0.1 }) > hc.warnings.textWidthEm("abc", "display") &&
		hc.warnings.textWidthEm("abc", "display", { uppercase: true }) !== hc.warnings.textWidthEm("abc", "display") &&
		hc.warnings.textWidthEm("abc", "body", { bold: true }) > hc.warnings.textWidthEm("abc", "body"));
	const keywordRun = hc.warnings.markupCharacterArray('Gain 2 <span class="hcKeyword" style="--hcKeywordColor:#fff">Lust</span> &amp; more');
	check("card markup reads as characters, with keyword letters bold and entities decoded",
		keywordRun.map((entry) => entry.character).join("") === "Gain 2 Lust & more" &&
		keywordRun.filter((entry) => entry.bold).map((entry) => entry.character).join("") === "Lust");

	// --- The rule reports what does not fit and passes what does ---
	hc.state = null;
	const readingsFor = (card, part, size) => hc.warnings.cardFitReadingArray(card).filter((entry) => entry.part === part && entry.size === size);
	const overlong = { index: "hcFitOverlong", name: "Brobdingnagian Wallwalker", costArray: { energy: 1 }, targetMode: "enemy",
		text: "Deal 1 damage. ".repeat(24),
		effectArray: [{ index: "damage", amount: 1 }] };
	const short = { index: "hcFitShort", name: "Jab", costArray: { energy: 1 }, targetMode: "enemy", effectArray: [{ index: "damage", amount: 1 }] };
	hc.cardArray.push(overlong, short);
	const overlongWarnings = hc.warningRuleArray.find((rule) => rule.index === "cardFit").check(overlong, hc.tuning.warnings);
	const shortWarnings = hc.warningRuleArray.find((rule) => rule.index === "cardFit").check(short, hc.tuning.warnings);
	check("an overlong card is reported at every size that prints its text, and a short one is not",
		["medium", "large"].every((size) => overlongWarnings.some((message) => message.indexOf("text at " + size) >= 0)) && shortWarnings.length === 0,
		overlongWarnings.join(" | ") + " || " + shortWarnings.join(" | "));
	check("every size is measured: small prints the name alone, medium and large print name, supertypes and text",
		readingsFor(short, "name", "small").length === 1 && readingsFor(short, "text", "small").length === 0 &&
		["medium", "large"].every((size) => ["name", "supertypes", "text"].every((part) => readingsFor(short, part, size).length === 1)));
	hc.cardArray.splice(hc.cardArray.indexOf(overlong), 2);

	// --- A known working reference raises the budget to its own measured fill ---
	const fullest = hc.cardArray.map((card) => ({ card: card, reading: readingsFor(hc.resolveCard({ cardIndex: card.index }), "text", "medium")[0] }))
		.filter((entry) => entry.reading != null).sort((a, b) => b.reading.fill - a.reading.fill)[0];
	fit.referenceArray.push({ part: "text", size: "medium", card: fullest.card.index });
	const budget = hc.warnings.cardFitBudget("text", "medium");
	check("a reference card's measured fill becomes the budget when it measures past the box, and the box otherwise",
		budget.fill === Math.max(1, fullest.reading.fill) && hc.warnings.cardFitBudget("text", "large").fill === 1,
		fullest.card.index + " " + fullest.reading.fill + " budget " + budget.fill);
	fit.referenceArray.pop();

	// --- The rename lengthened Severine's card text; none of it is past its box ---
	const severineOver = [];
	hc.cardArray.filter((card) => card.characterIndex === "severine").forEach((card) => {
		hc.warnings.cardFormArray(card).forEach((form) => hc.warnings.cardFitReadingArray(form.resolved).forEach((reading) => {
			if (reading.fill > 1) severineOver.push(form.label + " " + reading.part + "@" + reading.size + " " + reading.fill.toFixed(3));
		}));
	});
	check("no form of any Severine card is measured past its box after the rename", severineOver.length === 0, severineOver.join(", "));
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[77] Balance report -- cards measured against the intended rate (MECHANICS-02.md)");
{
	const hc = newEngine();
	const energyOf = (card) => card.costArray == null || card.costArray.energy == null || card.costArray.energy <= 0 ? null : card.costArray.energy;
	const numericAmount = (effect) => typeof effect.amount === "number" ? effect.amount
		: (effect.amount != null && effect.amount.index === "fixed" ? effect.amount.amount : null);
	const flatEffectArray = (card) => {
		const result = [];
		const walk = (list) => { for (const entry of list || []) { result.push(entry); walk(entry.effectArray); walk(entry.thenArray); walk(entry.elseArray); for (const option of entry.optionArray || []) walk(option.effectArray); } };
		walk(card.effectArray);
		return result;
	};
	const rateCard = (card, effectIndex) => {
		const energy = energyOf(card);
		if (energy == null) return null;
		let total = 0;
		for (const entry of flatEffectArray(card)) if (entry.index === effectIndex) { const amount = numericAmount(entry); if (amount != null) total += amount; }
		return total <= 0 ? null : { rate: total / energy, total: total, energy: energy };
	};

	// --- Rank collapse and reward pool -------------------------------------------------------------
	check("no card carries the retired Uncommon rank", hc.cardArray.every((card) => card.rarity !== "uncommon"));
	check("the reward pool offers exactly Common and Rare",
		hc.tuning.reward.offerableRarityArray.slice().sort().join(",") === "common,rare" &&
		hc.tuning.reward.rarityWeightArray.uncommon === undefined);

	// --- Damage rate: plain single-hit attacks sit in the 4-9 band --------------------------------
	// Cinder's aggressive basic Impale prints 9 at 1 energy, deliberately one above the old 8 ceiling:
	// it pays for the excess with 1 Sundered on Cinder herself.
	// Outfit signatures are Noodle's own numbers (OUTFITS-LIST: Pop deals 12, Blood Moon 20), so the band
	// holds the basics and the pool, not the signatures.
	const signatureSet = new Set();
	for (const character of hc.characterArray) {
		for (const outfit of character.outfitArray) for (const added of (outfit.cardAdditionArray || [])) signatureSet.add(added.index);
	}
	const damageRateArray = ["starter", "common", "rare"].map((rank) => {
		const rateArray = hc.cardArray.filter((card) => card.rarity === rank && signatureSet.has(card.index) == false).map((card) => rateCard(card, "damage")).filter((r) => r != null).map((r) => r.rate);
		return { rank: rank, count: rateArray.length, minimum: Math.min.apply(null, rateArray), maximum: Math.max.apply(null, rateArray) };
	});
	console.log("       damage per energy by rank: " + damageRateArray.map((r) => `${r.rank} n=${r.count} ${r.minimum.toFixed(1)}-${r.maximum.toFixed(1)}`).join("  "));
	check("a starter attack never exceeds 9 damage per energy", damageRateArray[0].maximum <= 9, JSON.stringify(damageRateArray[0]));
	check("a common attack applies at least 3 damage per energy", damageRateArray[1].minimum >= 3, JSON.stringify(damageRateArray[1]));

	// --- Poison density: Nettle's appliers are thinned; the payoffs remain --------------------------
	const nettlePool = hc.cardArray.filter((card) => card.characterIndex === "nettle");
	const appliesPoison = (card) => flatEffectArray(card).some((entry) => entry.index === "applyStatus" && entry.status === "poison");
	const readsPoison = (card) => flatEffectArray(card).some((entry) => (entry.index === "consumeStatus" && entry.status === "poison") ||
		(entry.index === "spreadStatus" && entry.status === "poison") ||
		(entry.value != null && entry.value.status === "poison") ||
		(entry.amount != null && entry.amount.status === "poison") ||
		(entry.amount != null && entry.amount.left != null && entry.amount.left.status === "poison"));
	const draftablePool = nettlePool.filter((card) => card.rarity === "starter" || card.rarity === "common" || card.rarity === "rare");
	const applierArray = draftablePool.filter(appliesPoison);
	const readerArray = draftablePool.filter(readsPoison);
	const poisonIntensity = applierArray.reduce((sum, card) => {
		const energy = energyOf(card) || 1;
		let stacks = 0;
		for (const entry of flatEffectArray(card)) if (entry.index === "applyStatus" && entry.status === "poison" && entry.condition == null && typeof entry.stacks === "number") stacks += entry.stacks;
		return sum + stacks / energy;
	}, 0) / Math.max(1, applierArray.length);
	console.log("       Nettle poison: " + applierArray.length + " appliers, average " + poisonIntensity.toFixed(2) + " Poison per energy");
	//SESSION 33 (CARD-POOL-01 1.2): commons price Poison at 5 per energy, so the old 2.25 ceiling is retired.
	check("Nettle poison density averages at most the common rate of 5 Poison per energy", poisonIntensity <= 5, poisonIntensity.toFixed(3));
	check("Nettle has at least 4 cards that cash Poison in", readerArray.length >= 4, readerArray.map((c) => c.index).join(", "));

	// --- Broken-form coverage: one unique form per rank, per character ----------------------------
	const brokenCoverage = [];
	for (const character of hc.characterArray) {
		if (character.inDevelopment === true) continue;
		for (const rank of ["starter", "common", "rare"]) {
			const owned = hc.cardArray.filter((card) => card.characterIndex === character.index && card.rarity === rank && card.brokenCard != null);
			const named = owned.find((card) => {
				const broken = hc.findDefinition(hc.cardArray, card.brokenCard);
				return broken != null && broken.rarity === "broken" && broken.characterIndex === character.index;
			});
			if (named == null) brokenCoverage.push(character.index + "/" + rank);
		}
	}
	check("every character has a unique broken form at starter, common and rare", brokenCoverage.length === 0, brokenCoverage.join(", "));

	// --- Penance: Clemence's self-Lust is tagged ------------------------------------------------
	check("Clemence's own Lust build-up carries the Penance tag",
		hc.cardArray.filter((card) => card.characterIndex === "clemence").some((card) => JSON.stringify(card).indexOf('"penance"') >= 0) &&
		hc.cardTagArray.some((tag) => tag.index === "penance" && tag.lustTag === true));

	// --- Repertoire: a stolen move is kept only while the posture is worn ------------------------
	const repertoire = (() => {
		const run = startRun(hc, 7701, [{ characterIndex: "cassadora", outfitIndex: "default" }]);
		hc.combat.begin("sporePair");
		const combat = hc.state.run.combat;
		const cassadora = run.partyArray[0];
		//The Archivist outfit was retired in session 25; grant the posture directly to test the seam.
		hc.applyStatus(cassadora, "repertoire", 1, hc.newEffectContext({ combat: combat }));
		const deckBefore = run.deckArray.length;
		const kept = hc.giveStolenCard("sporelingSpit", cassadora, "sporeling", hc.newEffectContext({ combat: combat }));
		const heldExhausts = kept.exhausts;
		const persisted = run.deckArray.length === deckBefore + 1;
		hc.removeStatus(cassadora, "repertoire", 99, hc.newEffectContext({ combat: combat }));
		const plain = hc.giveStolenCard("sporelingSpores", cassadora, "sporeling", hc.newEffectContext({ combat: combat }));
		return { heldExhausts: heldExhausts, persisted: persisted, plainExhausts: plain.exhausts };
	})();
	check("Repertoire keeps a stolen move and writes a copy to the deck",
		repertoire.heldExhausts === false && repertoire.persisted === true);
	check("without Repertoire a stolen move still exhausts", repertoire.plainExhausts === true);

	// --- Shelter's front-rank bonus reads the ally it lands on, not the caster --------------------
	const shelter = (() => {
		const run = startRun(hc, 7710, [{ characterIndex: "brienne", outfitIndex: "default" }, { characterIndex: "cinder", outfitIndex: "default" }, { characterIndex: "nettle", outfitIndex: "default" }]);
		hc.combat.begin("sporePair");
		const combat = hc.state.run.combat;
		combat.phase = "playerTurn";
		hc.setResource("energy", 20);
		const allyArray = hc.livingEntityArray("ally", combat);
		const front = allyArray[0];
		const back = allyArray[allyArray.length - 1];
		const frontBefore = front.temporaryHealth;
		const frontCard = hc.addCardToPile("brienneShelter", "hand", hc.newEffectContext({ combat: combat }));
		hc.combat.playCard(frontCard.instanceId, front.instanceId);
		const frontGain = front.temporaryHealth - frontBefore;
		const backBefore = back.temporaryHealth;
		const backCard = hc.addCardToPile("brienneShelter", "hand", hc.newEffectContext({ combat: combat }));
		hc.combat.playCard(backCard.instanceId, back.instanceId);
		const backGain = back.temporaryHealth - backBefore;
		return { frontGain: frontGain, backGain: backGain };
	})();
	check("Shelter's front-rank bonus lands on the ally it was played on",
		shelter.frontGain === 12 && shelter.backGain === 8, JSON.stringify(shelter));
}

