console.log("\n[78] Session 21: card telemetry, report and the run counters");
{
	const hc = newEngine();
	check("a fresh engine has an empty ledger",
		hc.telemetry.reportArray().length === 0 && hc.telemetry.load().runsStarted === 0);

	startRun(hc, 7801, DEFAULT_PARTY);
	check("starting a run counts one started", hc.telemetry.load().runsStarted === 1);

	// A reward roll counts every offer; taking and skipping are counted where the player answers.
	hc.combat.begin("loneSporeling", {});
	const offerArray = hc.combat.rollCardReward(hc.findDefinition(hc.encounterArray, "loneSporeling"), hc.state.run.combat);
	check("every offered card is counted", offerArray.length > 0 &&
		offerArray.every((offer) => hc.telemetry.load().offerArray[offer.cardIndex] >= 1));

	// deckAdd is counted at the one door, from any source.
	hc.addCardToRunDeck("neutralFocus", null);
	check("a card joining the deck is counted", hc.telemetry.load().deckAddArray.neutralFocus === 1);

	// The report reads as a table and sorts the most-decided card first.
	const row = hc.telemetry.reportArray().find((entry) => entry.cardIndex === offerArray[0].cardIndex);
	check("the report carries offered / taken / skipped / added",
		row != null && row.offered >= 1 && row.taken === 0 && row.skipped === 0 && row.added === 0);
	check("the report text names the card and its index", (() => {
		const text = hc.telemetry.reportText();
		const definition = hc.findDefinition(hc.cardArray, offerArray[0].cardIndex);
		return text.indexOf(definition.name) >= 0 && text.indexOf(offerArray[0].cardIndex) >= 0;
	})());

	// Clearing leaves the counters empty but keeps the ledger readable.
	hc.telemetry.clear();
	check("clearing empties the ledger", hc.telemetry.reportArray().length === 0 &&
		hc.telemetry.load().runsStarted === 0);
}

