console.log("\n[79] Session 21: the sound library and the explicit card sfx table");
{
	const hc = newEngine();
	const audio = hc.tuning.audio;
	const libraryFolder = path.resolve(ROOT, "..", "..", "honeycomb sound", "sfx");

	// Every file an event names must EXIST: a typo is otherwise silent forever.
	const missing = [];
	for (const eventIndex in audio.fileMap) {
		const file = path.join(libraryFolder, audio.fileMap[eventIndex] + ".mp3");
		if (!fs.existsSync(file)) missing.push(eventIndex + " -> " + audio.fileMap[eventIndex]);
	}
	check("every mapped sound file exists in honeycomb sound/sfx", missing.length === 0, missing.join(", "));

	// The five stingers are wired and present.
	const stingerArray = ["broken", "exposedTorn", "outfitChange", "victoryBattle", "victoryFull"];
	check("the five named stingers have library files",
		stingerArray.every((eventIndex) => audio.fileMap[eventIndex] != null));

	// THE TABLE IS EXPLICIT AND COMPLETE (session 21 follow-up): every card and every enemy move must
	// name its own stem, and every stem must be a real file. No auto-assignment, no silent card.
	const sfxFor = (cardIndex) => hc.cardSfxStem(hc.findDefinition(hc.cardArray, cardIndex));
	const unassigned = hc.cardArray
		.filter((card) => sfxFor(card.index) == null)
		.map((card) => card.index);
	check("every card in the table names a sound", unassigned.length === 0, unassigned.slice(0, 12).join(", "));
	const assignedEnemyMoves = hc.enemyCardArray.filter((move) => hc.cardSfxStem(move) == null).map((move) => move.index);
	check("every enemy move names a sound", assignedEnemyMoves.length === 0, assignedEnemyMoves.slice(0, 12).join(", "));
	const unknownStem = [];
	const stemSeen = {};
	for (const card of hc.cardArray.concat(hc.enemyCardArray)) {
		const stem = hc.cardSfxStem(card);
		if (stem == null || stemSeen[stem] == true) continue;
		stemSeen[stem] = true;
		if (!fs.existsSync(path.join(libraryFolder, stem + ".mp3"))) unknownStem.push(stem);
	}
	check("every named stem is a file that exists", unknownStem.length === 0, unknownStem.join(", "));

	// DIRECTION IS RESPECTED (session 21 follow-up: "cards I tested that debuff the party" must use the
	// party debuff sfx): the clear party-harm cards are on debuffSingle, and a charm spell is not a slap.
	check("a card that costs its owner blood uses the single-target debuff sound", sfxFor("severineBloodlet") === "debuffSingle", String(sfxFor("severineBloodlet")));
	check("and so does a self-harming cost paid for resources", sfxFor("severineBloodPact") === "debuffSingle", String(sfxFor("severineBloodPact")));
	check("a blood price that HEALS an ally sounds like the heal, not the price", sfxFor("severineTransfusion") === "healSmall", String(sfxFor("severineTransfusion")));
	check("a charm spell is mind magic, not a body sound", sfxFor("severineEnthrall") === "magicWeird", String(sfxFor("severineEnthrall")));
	check("a heal is a heal", sfxFor("clemenceLayOnHands") === "magicHolyChoir", String(sfxFor("clemenceLayOnHands")));
	check("a poison card is necrotic, not a weapon", sfxFor("nettleBlightNeedle") === "magicDarkGeneric", String(sfxFor("nettleBlightNeedle")));
	check("an enemy move that debuffs the party uses the party sound", hc.cardSfxStem(hc.findDefinition(hc.enemyCardArray, "matriarchBloom")) === "debuffParty");
	check("a card that names its own sfx wins over the table", (() => {
		const card = { index: "nettleBlightNeedle", name: "Probe", tagArray: [], effectArray: [], sfx: "magicIce" };
		return hc.cardSfxStem(card) === "magicIce";
	})());
	check("the unassigned fallback still resolves through the type table", (() => {
		const card = { index: "zzNewCard", characterIndex: "nettle", cardTypeArray: null, effectArray: [{ index: "damage", amount: 1 }] };
		const cardView = Object.assign({}, card, { typeArray: null });
		return hc.cardSfxStem(cardView) === null;
	})());
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[80] Session 21: the poison barrage and the halving maths");
{
	const hc = newEngine();
	startRun(hc, 8001, DEFAULT_PARTY);
	hc.combat.begin("sporePair", {});
	const combat = hc.state.run.combat;
	const enemy = combat.enemyArray[0];
	hc.applyStatus(enemy, "poison", 3, hc.newEffectContext({ combat: combat }));
	const before = enemy.health;
	hc.combat.endPlayerTurn();
	check("poison ticks as the player's turn closes", before - enemy.health === 3, String(before - enemy.health));
	check("and the tick weakens it by one", hc.statusStacks(enemy, "poison") === 2, String(hc.statusStacks(enemy, "poison")));

	// THE MATHS NOODLE ASKED FOR: total damage over a whole life from N stacks, both decay modes.
	// Decrement gives the triangular numbers (N²/2-ish); halving gives ~2N, so the rework is a real,
	// measurable nerf at any stack worth building around.
	const totalFor = (mode, count) => {
		let stacks = count;
		let total = 0;
		let guard = 0;
		while (stacks > 0 && guard < 100) {
			total += stacks;
			stacks = mode === "halve" ? Math.floor(stacks / 2) : stacks - 1;
			guard += 1;
		}
		return total;
	};
	check("decrement totals are the triangular numbers",
		[1, 2, 3, 4, 6, 10].every((count) => totalFor("decrement", count) === count * (count + 1) / 2));
	check("halving totals roughly double the stacks", totalFor("halve", 6) === 10 && totalFor("halve", 10) === 18);
	const report = [1, 2, 3, 4, 6, 10].map((count) =>
		count + ": " + totalFor("decrement", count) + " -> " + totalFor("halve", count)).join("  |  ");
	console.log("       poison totals per stack count (decrement -> halve): " + report);
	check("the halving option is a real nerf at scale", totalFor("halve", 10) < totalFor("decrement", 10) / 2,
		totalFor("halve", 10) + " vs " + totalFor("decrement", 10));
	check("the shipped rule is still decrement (the halving switch is Noodle's call)",
		hc.findDefinition(hc.statusArray, "poison").decayMode === "decrement");
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[81] Session 22: sound measured rather than named, and poison's barrage pace");
{
	const hc = newEngine();
	const audio = hc.tuning.audio;
	const libraryFolder = path.resolve(ROOT, "..", "..", "honeycomb sound", "sfx");
	const metrics = JSON.parse(fs.readFileSync(path.resolve(__dirname, "sfx-metrics.json"), "utf8"));
	const { durationSeconds } = require("./sfx-durations.js");

	// THE MEASUREMENTS MUST MATCH THE FILES ON DISK. sfx-metrics.json is generated by sfx-report.html
	// (loudness and audible length need a decoder, and Node has none); the frame-header reader here
	// proves the generated file has not gone stale behind a replaced sound.
	const staleArray = [];
	const fileArray = fs.readdirSync(libraryFolder).filter((name) => name.endsWith(".mp3")).map((name) => name.slice(0, -4));
	for (const stem of fileArray) {
		const recorded = metrics.stemMap[stem];
		if (recorded == null) { staleArray.push(stem + " has no measurement"); continue; }
		const measured = durationSeconds(path.join(libraryFolder, stem + ".mp3"));
		if (measured != null && Math.abs(measured - recorded.fileSeconds) > 0.06) {
			staleArray.push(stem + " is " + measured.toFixed(2) + "s, metrics say " + recorded.fileSeconds);
		}
	}
	check("every sound file is measured, and the measurements are current", staleArray.length === 0,
		staleArray.slice(0, 6).join("; ") + " -- regenerate with sfx-report.html");
	check("the frame-header reader agrees with the decoder", (() => {
		const spot = durationSeconds(path.join(libraryFolder, "miscWind.mp3"));
		return spot != null && Math.abs(spot - metrics.stemMap["miscWind"].fileSeconds) < 0.06;
	})());

	// NO SOUND MAY OUTLAST ITS MOMENT. This is the rule session 21 had no way to break: miscWind is
	// 11.9 seconds of ambient wind, and reading its NAME cannot say that. It reached the card draw and
	// five of Cinder's cards before anybody heard it.
	const momentOf = (eventIndex) => audio.eventMomentMap[eventIndex] == null ? audio.defaultMoment : audio.eventMomentMap[eventIndex];
	const overrunArray = [];
	const weigh = (subject, stem, momentIndex) => {
		const recorded = metrics.stemMap[stem];
		const moment = hc.findDefinition(audio.momentArray, momentIndex);
		if (recorded == null || moment == null) { overrunArray.push(subject + " -> " + stem + " (unmeasured)"); return; }
		if (recorded.audibleSeconds > moment.maximumSeconds + 0.001) {
			overrunArray.push(subject + " -> " + stem + " " + recorded.audibleSeconds + "s in a " +
				moment.index + " (max " + moment.maximumSeconds + "s)");
		}
	};
	for (const eventIndex in audio.fileMap) weigh("event " + eventIndex, audio.fileMap[eventIndex], momentOf(eventIndex));
	for (const card of hc.cardArray.concat(hc.enemyCardArray)) {
		const stem = hc.cardSfxStem(card);
		if (stem == null) continue;
		weigh("card " + card.index, stem, card.rarity === "enemy" ? "enemyMove" : "cardPlay");
	}
	check("no sound outlasts the moment it plays at", overrunArray.length === 0, overrunArray.slice(0, 8).join("; "));
	check("the wind bed is off every card",
		hc.cardArray.concat(hc.enemyCardArray).every((card) => hc.cardSfxStem(card) !== "miscWind"));

	// EVERY FILE IS TRIMMED TO ONE LEVEL. The library spans 22.7 dB untrimmed; the trims are generated
	// from the measurements, so this holds the shipped table to them.
	const driftArray = [];
	for (const stem of fileArray) {
		const recorded = metrics.stemMap[stem];
		if (recorded == null) continue;
		const ideal = Math.pow(10, (metrics.targetLoudnessDb - recorded.loudnessDb) / 20);
		const wanted = Number(Math.min(audio.fileVolumeTrimRange.maximum,
			Math.max(audio.fileVolumeTrimRange.minimum, ideal)).toFixed(2));
		// A trim chosen by ear (fileVolumeByEarMap, Noodle 2026-09-23) is his to set; the measured table still
		// has to hold the measured value underneath it.
		const shipped = audio.fileVolumeScaleMap[stem] == null ? 1 : audio.fileVolumeScaleMap[stem];
		if (Math.abs(shipped - wanted) > 0.005) driftArray.push(stem + " ships " + shipped + ", measures " + wanted);
	}
	check("every volume trim is the measured one", driftArray.length === 0,
		driftArray.slice(0, 6).join("; ") + " -- regenerate with: node sfx-report.js --trims");
	const byEarMap = audio.fileVolumeByEarMap || {};
	check("every trim chosen by ear names a real file and sits inside the trim range",
		Object.keys(byEarMap).every((stem) => fileArray.indexOf(stem) >= 0 &&
			byEarMap[stem] >= audio.fileVolumeTrimRange.minimum && byEarMap[stem] <= audio.fileVolumeTrimRange.maximum),
		JSON.stringify(byEarMap));

	// AN EVENT NAME SAYS WHEN A SOUND PLAYS. Borrowing one for a different moment is how four seconds
	// of footsteps on wood ended up on every party shift in a fight.
	// Either table counts. What matters is that it is its own event and never the footsteps.
	check("the party shift, the summons and the retort have their own events",
		["partyShift", "enemySummoned", "allySummoned", "damageRetort"].every((eventIndex) =>
			audio.fileMap[eventIndex] != null || audio.eventMap[eventIndex] != null) &&
		audio.fileMap.partyShift !== "miscWalkingWood");
	check("nothing is mapped for an event no code plays",
		audio.fileMap.statusApplied == null && audio.eventMap.statusApplied == null);
	check("an ordinary hit from a card makes no second sound of its own",
		audio.fileMap.damageDealt == null && audio.damageTypeSoundMap.damageDealt == null);
	check("but a hit with no card behind it still speaks",
		audio.damageTypeSoundMap.poison === "poisonTick" && audio.damageTypeSoundMap.thorns === "damageRetort");

	// POISON'S DECAY RIDES ITS OWN TICK. Measured in the browser at 410ms an enemy before this: the
	// damage beat asked for 90ms and the stack change then charged a full 320ms status pulse.
	check("the barrage pace is a table entry", hc.tuning.animation.beatPaceMsMap.barrage === 0);
	{
		const engine = newEngine();
		startRun(engine, 8102, DEFAULT_PARTY);
		engine.combat.begin("sporePair", {});
		const combat = engine.state.run.combat;
		for (const enemy of combat.enemyArray) {
			engine.applyStatus(enemy, "poison", 4, engine.newEffectContext({ combat: combat }));
		}
		const context = engine.combat.endPlayerTurn();
		const decayArray = context.log.filter((entry) => entry.type === "status" && entry.status === "poison");
		check("every poison decay in the barrage is barrage-paced",
			decayArray.length === combat.enemyArray.length && decayArray.every((entry) => entry.pace === "barrage"),
			decayArray.map((entry) => String(entry.pace)).join(","));
		check("and the damage beats are still one per poisoned body",
			context.log.filter((entry) => entry.type === "damage" && entry.damageType === "poison").length === combat.enemyArray.length);
	}
	check("a status change outside a barrage still names no pace", (() => {
		const engine = newEngine();
		startRun(engine, 8103, DEFAULT_PARTY);
		engine.combat.begin("sporePair", {});
		const combat = engine.state.run.combat;
		const context = engine.newEffectContext({ combat: combat });
		engine.applyStatus(combat.enemyArray[0], "weak", 2, context);
		engine.removeStatus(combat.enemyArray[0], "weak", 1, context);
		const last = context.log[context.log.length - 1];
		return last.type === "status" && last.pace == null;
	})());
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[82] Session 22: every named image is a file that exists");
{
	// A card naming art that was never drawn shows the placeholder frame with an empty window, which
	// looks deliberate and so is never reported. `severineBroken` named cards/art/severine-rake for
	// three sessions; it was found by MEASURING the boot warm, not by looking at the game.
	//
	// Art that is knowingly not drawn yet goes in plannedArray with the reason, so the gap stays
	// visible and countable instead of being indistinguishable from a typo.
	const hc = newEngine();
	const imageFolder = path.resolve(ROOT, "..", "..", "v13 spire images");
	const plannedArray = [
		{ path: "cards/frames/playerBack", why: "HC-PLACEHOLDER: the card back is CSS until it is drawn" },
		{ path: "cards/frames/enemyBack", why: "HC-PLACEHOLDER: the enemy card back is CSS until it is drawn" },
	];
	//Cards written before their art (session 33, CARD-POOL-01) say so with `artOwed` and are planned too.
	for (const card of hc.cardArray) if (card.artOwed === true) plannedArray.push({ path: card.artPath, why: "artOwed: " + card.index });
	// >>> LANE E7 | flora | planned enemy art >>>
	// LANE E7: the same declaration for an ENEMY. Until session 45 every artOwed enemy happened to have a
	// recoloured stand-in on disk, so the warm found a file and the gap was invisible here; Act1-B's are
	// written the night before their drawings exist. The two frames the boot warm asks for are what the
	// flag has to cover -- `artOwed` on an enemy whose art IS drawn still resolves through exists().
	for (const enemy of hc.enemyArray) {
		if (enemy.artOwed !== true) continue;
		// The frames come from the art file (2026-09-21): an ordinary enemy is warmed by its `1-combat` and
		// nothing else. This loop used to spell `1-basic` and `2-basic` by hand, which was one of the things
		// that made an enemy's `-basic` files impossible to remove. See block [126].
		for (const warmPath of hc.art.enemyWarmPaths(enemy)) plannedArray.push({ path: warmPath, why: "artOwed: " + enemy.index });
	}
	// <<< LANE E7 | flora | planned enemy art <<<
	const isPlanned = (imagePath) => plannedArray.some((entry) => entry.path === imagePath);
	const exists = (imagePath) => fs.existsSync(path.join(imageFolder, imagePath + ".webp"));

	const missingArray = [];
	const seenMap = {};
	const weigh = (imagePath, owner) => {
		if (imagePath == null || seenMap[imagePath] === true) return;
		seenMap[imagePath] = true;
		if (isPlanned(imagePath) || exists(imagePath)) return;
		missingArray.push(owner + " -> " + imagePath);
	};
	for (const card of hc.cardArray.concat(hc.enemyCardArray)) weigh(card.artPath, "card " + card.index);
	for (const enemy of hc.enemyArray) weigh(enemy.artPath, "enemy " + enemy.index);
	for (const relic of hc.relicArray || []) weigh(relic.artPath, "relic " + relic.index);
	check("every card, enemy and relic names art that exists", missingArray.length === 0,
		missingArray.slice(0, 10).join("; "));

	// Every live OUTFIT needs its pose set, or wearing it requests two 404s and falls back to the
	// default portrait (Cassadora's soothsayer was missing its set; found round 07).
	const outfitMissingArray = [];
	for (const character of hc.characterArray) {
		for (const outfit of (character.outfitArray || [])) {
			if (outfit.legacyFixture == true) continue;
			if (exists("characters/" + character.artFolder + "/" + outfit.index + "/0-portrait") == false) {
				outfitMissingArray.push(character.index + "/" + outfit.index);
			}
		}
	}
	check("every character outfit names a portrait that exists", outfitMissingArray.length === 0,
		outfitMissingArray.join(", "));

	// The boot warm asks for each of these by name, so anything missing is a request that always 404s
	// on every player's first seconds. Planned placeholders are allowed, and only those.
	const warmArray = [];
	const realWarm = hc.preload.warm;
	hc.preload.warm = (pathArray) => { for (const one of pathArray) warmArray.push(one); };
	hc.preload.warmCommon();
	hc.preload.warm = realWarm;
	const warmMissingArray = [];
	const warmSeenMap = {};
	for (const imagePath of warmArray) {
		if (warmSeenMap[imagePath] === true) continue;
		warmSeenMap[imagePath] = true;
		if (isPlanned(imagePath) || exists(imagePath)) continue;
		warmMissingArray.push(imagePath);
	}
	check("the boot warm asks only for images that are there", warmMissingArray.length === 0,
		warmMissingArray.slice(0, 10).join("; "));
	check("the warm is a real list, not an empty one", warmArray.length > 50, String(warmArray.length));
	console.log("       boot warm: " + warmArray.length + " paths, " + Object.keys(warmSeenMap).length +
		" unique, " + plannedArray.length + " known-undrawn");
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[83] Session 22: the Battle Lab's engine seams");
{
	// The lab is presentation -- handles drawn onto the live battle screen -- so what is testable
	// headlessly is the SEAMS it drives. If these hold, every control on the board holds, because each
	// one is a call to exactly one of them. The lab's own file is not loaded here: it needs a document.
	const hc = newEngine();
	startRun(hc, 8301, DEFAULT_PARTY);
	hc.combat.begin("sporePair", {});
	const combat = hc.state.run.combat;

	// ANY CARD INTO HAND, at any upgrade level. This is what "play any card in the game" rests on.
	{
		const context = hc.newEffectContext({ combat: combat });
		const before = combat.handArray.length;
		const instance = hc.addCardToPile("cassadoraPuppetStrings", "hand", context);
		check("any card in the game can be put in hand", instance != null && combat.handArray.length === before + 1);
		// The upgrade level is a plain integer on the instance, which is how the + form is reached.
		instance.upgradeLevel = 1;
		const resolved = hc.resolveCard(instance);
		const base = hc.resolveCard({ instanceId: null, cardIndex: "cassadoraPuppetStrings", upgradeLevel: 0 });
		check("and at its upgraded level", resolved != null && base != null && resolved.name !== base.name,
			String(base == null ? "?" : base.name) + " -> " + String(resolved == null ? "?" : resolved.name));
	}
	// A broken form is a DIFFERENT card, so reaching it is reaching another row of the table.
	check("a broken form is its own card", (() => {
		const brokenArray = hc.cardArray.filter((card) => card.rarity === "broken");
		if (brokenArray.length === 0) return false;
		const context = hc.newEffectContext({ combat: combat });
		return hc.addCardToPile(brokenArray[0].index, "hand", context) != null;
	})());
	// The hand has a ceiling, and the lab reports it rather than appearing to fail.
	check("the hand cap is a number the lab can read", hc.tuning.combat.handSizeMaximum > 0);

	// A BODY ON EITHER SIDE. summonCombatant already takes a side, which is the whole of "add enemies
	// and party members of my choice to either side".
	{
		const context = hc.newEffectContext({ combat: combat });
		const enemyCount = combat.enemyArray.length;
		const ally = hc.summonCombatant({ side: "ally", enemyIndex: "gloomWisp" }, context);
		check("an enemy can be stood in the party", ally != null && ally.side === "ally" &&
			hc.state.run.partyArray.indexOf(ally) >= 0);
		const foe = hc.summonCombatant({ side: "enemy", characterIndex: "clemence", outfitIndex: "default" }, context);
		check("and a character on the enemy line", foe != null && foe.side === "enemy" &&
			combat.enemyArray.length === enemyCount + 1);
	}

	// WHAT AN ENEMY WILL DO, chosen rather than rolled.
	check("an enemy's next move can be chosen", (() => {
		const enemy = combat.enemyArray.find((entity) => entity.enemyIndex != null);
		if (enemy == null) return false;
		const moveArray = hc.aiMoveArray(enemy);
		if (moveArray.length < 2) return false;
		const wanted = moveArray[moveArray.length - 1].card;
		const context = hc.newEffectContext({ combat: combat });
		hc.changeIntent(enemy, wanted, context);
		return enemy.intentCardIndex === wanted;
	})());
	check("and handed back to the AI", (() => {
		const enemy = combat.enemyArray.find((entity) => entity.enemyIndex != null);
		const context = hc.newEffectContext({ combat: combat });
		hc.changeIntent(enemy, null, context);
		return enemy.intentCardIndex != null;
	})());

	// THE ONE NEW ENGINE FLAG. Without it an emptied enemy line is an instant victory, and a bench
	// cannot be used to watch a death animation.
	{
		const engine = newEngine();
		startRun(engine, 8302, DEFAULT_PARTY);
		engine.combat.begin("loneSporeling", {});
		const fight = engine.state.run.combat;
		fight.enemyArray.length = 0;
		const context = engine.newEffectContext({ combat: fight });
		fight.labNoEnd = true;
		check("an empty enemy line does not end the fight while the lab is armed",
			engine.combat.checkEnd(context) == null, String(fight.phase));
		fight.labNoEnd = false;
		check("and does the moment it is disarmed", engine.combat.checkEnd(context) === "victory", String(fight.phase));
	}
	check("the flag is off on every ordinary fight", (() => {
		const engine = newEngine();
		startRun(engine, 8303, DEFAULT_PARTY);
		engine.combat.begin("loneSporeling", {});
		return engine.state.run.combat.labNoEnd == null || engine.state.run.combat.labNoEnd === false;
	})());

	// The lab's own numbers are tuning, not literals in the overlay.
	check("the lab's numbers live in tuning", hc.tuning.lab != null && hc.tuning.lab.energyRefill > 0);
}

