	const gathered = hc.starterUpgradeArrayFor(owner, "brienneCleave");
	check("a member's modifier list supplies the upgrade", gathered.length === 1 && gathered[0].amount === -2);
	const resolved = hc.resolveCard({ instanceId: null, cardIndex: "brienneCleave", ownerInstanceId: null, upgradeLevel: 0, upgradeOwner: owner });
