console.log("\n[99] AUDIT-01 answers -- outfit signatures upgrade once; the old rare Blood Moon is renamed");
{
	// NODES-LIST §D: "Outfit-signature cards should be allowed, they just don't upgrade infinitely".
	const hc = newEngine();
	hc.state = hc.newProfile();
	const signatureArray = hc.cardArray.filter((card) => card.outfitSignature === true);
	const signatureSet = new Set();
	for (const character of hc.characterArray) {
		for (const outfit of character.outfitArray || []) {
			for (const addition of outfit.cardAdditionArray || []) {
				const card = hc.findDefinition(hc.cardArray, addition.index);
				if (card != null && card.rarity === "starter") signatureSet.add(card.index);
			}
		}
	}
	check("every outfit's starter-rarity card is marked as a signature",
		signatureSet.size > 0 && [...signatureSet].every((index) => signatureArray.some((card) => card.index === index)),
		[...signatureSet].filter((index) => !signatureArray.some((card) => card.index === index)).join(", "));
	check("every signature is upgradable, with a ladder of exactly one level",
		signatureArray.length === 18 && signatureArray.every((card) => hc.cardIsUpgradable(card) && hc.cardUpgradeArray(card).length === 1),
		signatureArray.length + " signatures");
	check("starter basics are still not upgradable",
		hc.cardArray.filter((card) => card.rarity === "starter" && card.outfitSignature !== true).every((card) => hc.cardIsUpgradable(card) === false));

	hc.newRun([{ characterIndex: "nettle", outfitIndex: "rotsinger" }], 9901);
	const pop = hc.state.run.deckArray.find((card) => card.cardIndex === "nettlePop");
	hc.upgradeCardInstance(pop.instanceId, 1);
	hc.upgradeCardInstance(pop.instanceId, 1);
	check("an upgrade service stops a signature at its one level", pop.upgradeLevel === 1 && hc.cardUpgradesRemaining(pop) === 0,
		"level " + pop.upgradeLevel);

	hc.combat.begin("loneSporeling", {});
	const combat = hc.state.run.combat;
	const enemy = combat.enemyArray[0];
	enemy.health = 200; enemy.maxHealth = 200;
	enemy.statusArray = [{ index: "poison", stacks: 1 }];
	combat.handArray.push(pop.instanceId);
	hc.combat.playCard(pop.instanceId, enemy.instanceId);
	check("Pop+ played in a fight deals 16", 200 - enemy.health === 16, (200 - enemy.health) + " damage");

	const tailored = newEngine();
	tailored.state = tailored.newProfile();
	tailored.state.profile.progressionArray = { brienne: ["briU2"] };
	tailored.newRun([{ characterIndex: "brienne", outfitIndex: "siegeplate" }], 9902);
	const edge = tailored.state.run.deckArray.find((card) => card.cardIndex === "briennePlateEdge");
	check("a Tailored signature arrives as Plate Edge+ and has nothing left to climb",
		edge != null && tailored.resolveCard(edge).name === "Plate Edge+" && tailored.cardUpgradesRemaining(edge) === 0,
		edge == null ? "no copy" : "level " + edge.upgradeLevel);

	const rare = hc.findDefinition(hc.cardArray, "severineBloodMoon");
	check("the old rare and its status are named Blood for Blood",
		rare.name === "Blood for Blood" && hc.findDefinition(hc.statusArray, "bloodMoon").name === "Blood for Blood");
	check("Hedge Witch's Jinx (a random Weak or Sundered on an enemy) is a Negative card, not Support",
		hc.cardTypeIndexArray(hc.findDefinition(hc.cardArray, "cassadoraIllWish"))[0] === "negative");
	check("no card-name clash mentions Blood Moon",
		hc.warnings.report().warningArray.filter((warning) => warning.rule === "duplicateCardName" && /Blood Moon/.test(warning.message)).length === 0);
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[100] AUDIT-01 answers -- Cassadora's Orb: four slots, filled by the intents she changes, spent by her A2");
{
	// Noodle: four free slots (repeats allowed); a slot fills with the type of an intent Cassadora changes
	// or turns; an A2 that reads the Orb empties it. Played in fights, never read off the definitions.
	const bothNodes = { cassadora: ["casAbility1", "casAbility2"] };
	const fight = (outfitIndex, nodes, encounter) => {
		const hc = newEngine();
		hc.state = hc.newProfile();
		hc.state.profile.progressionArray = nodes == null ? bothNodes : nodes;
		hc.newRun([{ characterIndex: "cassadora", outfitIndex: outfitIndex }], 10100);
		hc.combat.begin(encounter || "deepSwarm", {});
		return hc;
	};
	const live = (hc) => hc.state.run.combat;
	const cas = (hc) => hc.state.run.partyArray[0];
	const ctx = (hc) => hc.newEffectContext({ combat: live(hc), source: cas(hc) });
	const orb = (hc) => hc.mechanicSymbolArray(cas(hc), "foresight");
	const fill = (hc, symbolArray) => { for (const symbol of symbolArray) hc.addMechanicSymbol(cas(hc), "foresight", symbol, ctx(hc)); };
	const give = (hc, cardIndex) => {
		const card = hc.addCardToRunDeck(cardIndex, cas(hc).instanceId);
		live(hc).handArray.push(card.instanceId);
		return card;
	};
	const use = (hc, abilityIndex, targetId, pick) => {
		let result = hc.abilities.use(cas(hc).instanceId, abilityIndex, targetId);
		for (let guard = 0; result.reason === "needsChoice" && guard < 6; guard++) {
			result = hc.abilities.use(cas(hc).instanceId, abilityIndex, targetId, result.answerArray.concat([{ chosenArray: pick(result.choice) }]));
		}
		return result;
	};

	{
		const hc = fight("default");
		const enemy = live(hc).enemyArray[0];
		const before = enemy.intentCardIndex;
		const result = use(hc, "cassadoraGlimpse", enemy.instanceId);
		check("Glimpse fills one slot with the type of the move she changed",
			result.used !== false && orb(hc).length === 1 && orb(hc)[0] === hc.cardSymbolIndex(before) && orb(hc)[0] != null,
			JSON.stringify(orb(hc)) + " from " + before);
		const turned = live(hc).enemyArray[1];
		hc.applyStatus(turned, "turncoat", 1, ctx(hc));
		check("turning an intent fills a slot with that move's type",
			orb(hc).length === 2 && orb(hc)[1] === hc.cardSymbolIndex(turned.intentCardIndex), JSON.stringify(orb(hc)));
	}
	{
		const hc = fight("default");
		fill(hc, ["damage", "damage", "support", "lewd", "negative"]);
		check("the Orb holds four symbols, repeats allowed, and a fifth adds nothing",
			JSON.stringify(orb(hc)) === JSON.stringify(["damage", "damage", "support", "lewd"]) && hc.mechanicValue(cas(hc), "foresight") === 4);
		hc.spendMechanic(cas(hc), "foresight", 1, ctx(hc));
		check("a partial spend empties the oldest slot first", JSON.stringify(orb(hc)) === JSON.stringify(["damage", "support", "lewd"]));
		hc.resetMechanics(cas(hc), "combatStart", ctx(hc));
		check("the Orb empties at the start of a fight", orb(hc).length === 0 && hc.mechanicValue(cas(hc), "foresight") === 0);
	}
	{
		const hc = fight("default");
		fill(hc, ["damage", "negative", "support"]);
		const handBefore = live(hc).handArray.length;
		use(hc, "cassadoraMagicTrick", null);
		check("Magic Trick conjures one move per symbol, then empties the Orb",
			live(hc).handArray.length - handBefore === 3 && orb(hc).length === 0, (live(hc).handArray.length - handBefore) + " cards");
	}
	{
		const hc = fight("hedgeWitch");
		fill(hc, ["damage", "lewd"]);
		use(hc, "cassadoraHexStorm", null);
		const debuffs = live(hc).enemyArray.map((enemy) => (enemy.statusArray || []).filter((s) => s.index === "weak" || s.index === "sundered")
			.reduce((sum, s) => sum + s.stacks, 0));
		check("Hex Storm: one debuff per symbol on every enemy, then the Orb is empty",
			debuffs.every((count) => count === 2) && orb(hc).length === 0, JSON.stringify(debuffs));
	}
	{
		const hc = fight("soothsayer");
		const combat = live(hc);
		const abilityList = hc.abilities.indexArray(cas(hc));
		combat.discardPileArray = combat.discardPileArray.concat(combat.handArray);
		combat.handArray = [];
		fill(hc, ["damage", "support"]);
		use(hc, "cassadoraSecondSight", null);
		const drawn = combat.handArray.map((id) => hc.resolveCard(hc.combat.cardInstance(id)));
		check("Soothsayer: Magic Trick becomes Second Sight",
			abilityList.indexOf("cassadoraSecondSight") >= 0 && abilityList.indexOf("cassadoraMagicTrick") < 0);
		check("Second Sight draws one card of each symbol's type, then empties the Orb",
			drawn.length === 2 && hc.cardHasType(drawn[0], "damage") && hc.cardHasType(drawn[1], "support") && orb(hc).length === 0,
			drawn.map((card) => card.name).join(", "));
	}
	{
		const hc = fight("grifter");
		const combat = live(hc);
		const abilityList = hc.abilities.indexArray(cas(hc));
		check("Grifter: Magic Trick becomes Vanishing Act",
			abilityList.indexOf("cassadoraVanishingAct") >= 0 && abilityList.indexOf("cassadoraMagicTrick") < 0);
		fill(hc, ["negative", "negative", "negative"]);
		check("Vanishing Act needs a full Orb", hc.abilities.usability(cas(hc), "cassadoraVanishingAct", combat).usable === false);
		fill(hc, ["negative"]);
		combat.handArray = [];
		const damageCard = give(hc, "cassadoraWispBolt");
		const negativeCard = give(hc, "cassadoraFizzle");
		// A second legal card, so the question is really asked rather than answered for the player.
		give(hc, "cassadoraStillness");
		let offered = null;
		use(hc, "cassadoraVanishingAct", null, (choice) => {
			offered = hc.choiceKind(choice).gather(choice).map((option) => option.index);
			return [negativeCard.instanceId];
		});
		const typesOk = hc.cardHasType(hc.resolveCard(negativeCard), "negative");
		const deckIds = hc.state.run.deckArray.map((card) => card.instanceId);
		check("only cards of an Orb type are offered",
			typesOk && offered != null && offered.indexOf(negativeCard.instanceId) >= 0 &&
				(hc.cardHasType(hc.resolveCard(damageCard), "negative") || offered.indexOf(damageCard.instanceId) < 0),
			JSON.stringify(offered));
		check("the chosen card is erased from the deck, sits in the exhaust pile, and the Orb is empty",
			// live(hc), not `combat`: a question rewinds the fight to a snapshot, so the earlier reference is stale.
			deckIds.indexOf(negativeCard.instanceId) < 0 && live(hc).exhaustPileArray.indexOf(negativeCard.instanceId) >= 0 &&
				hc.combat.cardInstance(negativeCard.instanceId) != null && orb(hc).length === 0);
	}
	{
		const hc = fight("default");
		fill(hc, ["damage", "lewd"]);
		// honeycomb-ui.js is not loaded headless; the widget table is lifted from source, as block [60] does.
		const uiSource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-ui.js"), "utf8");
		hc.ui = hc.ui || {};
		new Function("honeycomb", /\nhoneycomb\.ui\.mechanicWidgetArray = \[[\s\S]*?\n\];/.exec(uiSource)[0])(hc);
		const definition = hc.findDefinition(hc.mechanicArray, "foresight");
		const markup = hc.findDefinition(hc.ui.mechanicWidgetArray, definition.kind).build(cas(hc), definition, live(hc));
		const damageColor = hc.cardType("damage").color, lewdColor = hc.cardType("lewd").color;
		check("the Orb draws as a four-wedge pie in its symbols' type colours",
			markup.indexOf("hcMechanicPie") >= 0 && markup.indexOf(damageColor) >= 0 && markup.indexOf(lewdColor) >= 0 &&
				(markup.match(/var\(--hcMechanicSlotEmpty\)/g) || []).length === 2);
		const panel = hc.findDefinition(hc.tooltipKindArray, "mechanic");
		const rendered = panel == null ? "" : panel.render("foresight/" + cas(hc).instanceId);
		check("its tooltip lists what it holds", /Holds: Damage, Lewd\./.test(rendered), rendered.replace(/<[^>]+>/g, " ").slice(0, 160));
	}
}

