console.log("\n[101] Session 31 -- duplicate cards culled, old saves carried over, Plumefall");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	check("every retired card is gone from the table and names a live replacement",
		hc.retiredCardArray.length === 10 + 17 && hc.retiredCardArray.every((entry) => {
			const still = hc.findDefinition(hc.cardArray, entry.index);
			return (still == null || still.legacyFixture === true) && hc.findDefinition(hc.cardArray, entry.replacement) != null;
		}));
	const warningArray = hc.warnings.report().warningArray;
	check("no card plays exactly like another card of the same character",
		warningArray.filter((warning) => warning.rule === "duplicateCardRules").length === 0,
		warningArray.filter((warning) => warning.rule === "duplicateCardRules").map((warning) => warning.message).join(" | "));
	const nameClashArray = warningArray.filter((warning) => warning.rule === "duplicateCardName" && /"Jinx"/.test(warning.message) == false);
	check("no two cards share a name (Jinx is waiting on Noodle)", nameClashArray.length === 0, nameClashArray.map((warning) => warning.message).join(" | "));

	// A save written before the cull: its deck holds retired cards, and a map is keyed by one.
	hc.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 10101);
	const saved = JSON.parse(JSON.stringify(hc.state));
	saved.run.deckArray[0].cardIndex = "severineFlurry";
	saved.run.deckArray[1].cardIndex = "severineDrain";
	saved.profile.retiredProbeMap = { severineFlurry: 2 };
	saved.formatVersion = hc.tuning.save.formatVersion;
	hc.save.migrate(saved);
	check("an old save's retired cards load as their replacements",
		saved.run.deckArray[0].cardIndex === "severineRend" && saved.run.deckArray[1].cardIndex === "severineQuaff" &&
			saved.profile.retiredProbeMap.severineRend === 2 && saved.profile.retiredProbeMap.severineFlurry == null);

	const bladed = hc.memberCardEntryArray({ characterIndex: "brienne", outfitIndex: "default", equipmentArray: ["duelistBlade"] });
	check("Duelist's Blade turns the live Sword Strike into Riposte",
		bladed.some((entry) => entry.index === "brienneRiposte") && bladed.every((entry) => entry.index !== "brienneCleave"));
	check("Vanguard Plume's dive has its own name", hc.findDefinition(hc.abilityArray, "cinderPhoenixDiveStrength").name === "Plumefall");
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[102] Session 33 -- the card pool overhaul: pool shape, gates, reactions, and the three mechanics");
{
	const PARTY_A = [
		{ characterIndex: "brienne", outfitIndex: "default" },
		{ characterIndex: "clemence", outfitIndex: "default" },
		{ characterIndex: "cinder", outfitIndex: "default" },
	];
	const PARTY_B = [
		{ characterIndex: "nettle", outfitIndex: "default" },
		{ characterIndex: "severine", outfitIndex: "default" },
		{ characterIndex: "cassadora", outfitIndex: "default" },
	];
	const hc = newEngine();
	const begin = (party, seed, encounter, ability1Array) => {
		startRun(hc, seed || 3301, party);
		for (const characterIndex of ability1Array || []) unlockAbility1(hc, characterIndex);
		hc.combat.begin(encounter || "sporePair");
		hc.state.run.combat.phase = "playerTurn";
		return hc.state.run.combat;
	};
	const member = (characterIndex) => hc.state.run.partyArray.find((entry) => entry.characterIndex === characterIndex);
	const enemy = (slot) => hc.livingEntityArray("enemy", hc.state.run.combat)[slot || 0];
	const ctx = (source, target) => hc.newEffectContext({ combat: hc.state.run.combat, source: source || null, target: target || null });
	const hit = (source, target, amount, entry) => hc.dealDamage(source, target, amount, Object.assign({ ignoresStrength: true }, entry || {}), ctx(source, target));
	const run = (source, target, effectArray) => hc.resolveEffectArray(effectArray, ctx(source, target));
	const fire = (hookIndex, entity, extra) => hc.fireEntityHooks(hookIndex, Object.assign({ entity: entity, context: ctx(entity) }, extra || {}));
	const pool = (characterIndex) => hc.cardArray.filter((card) => card.characterIndex === characterIndex && (card.rarity === "common" || card.rarity === "rare") && card.legacyFixture !== true);

	// --- The pool's shape (CARD-POOL-01 1.1 and 1.3) ------------------------------------------------
	const shapeProblemArray = [];
	for (const characterIndex of ["brienne", "nettle", "severine", "cinder", "clemence", "cassadora"]) {
		const cardArray = pool(characterIndex);
		const gateOf = (card) => card.offerCondition == null ? "base" : card.offerCondition.index;
		const count = (rarity, gate) => cardArray.filter((card) => card.rarity === rarity && gateOf(card) === gate).length;
		const shape = [count("common", "base"), count("rare", "base"), count("common", "outfitUnlocked"), count("rare", "outfitUnlocked"), count("rare", "wearsOutfit")].join("/");
		// BRIENNE IS ONE CARD OFF, ON PURPOSE (session 55). Noodle asked for Take the Hit, a common gated
		// behind Bastion, to be replaced by "Suffer the Blows (rare) 0 cost", so one of her outfit-gated
		// commons became a rare and her shape is 12/5/8/4/3. Her Bastion outfit still gates five cards
		// with one worn-only, which is the rule the per-outfit check below holds. The clean way back to
		// 12/5/9/3/3 is to demote one of her other Bastion rares to common, and which one is his call --
		// this exception is here so the suite reports real drift rather than his decision.
		const expectedShape = characterIndex === "brienne" ? "12/5/8/4/3" : "12/5/9/3/3";
		if (shape !== expectedShape) shapeProblemArray.push(characterIndex + " " + shape);
		const chooseArray = cardArray.filter((card) => card.offerCondition == null && JSON.stringify(card.effectArray).indexOf('"chooseOption"') >= 0);
		if (chooseArray.length !== 1) shapeProblemArray.push(characterIndex + " has " + chooseArray.length + " base Choose Ones");
		const character = hc.findDefinition(hc.characterArray, characterIndex);
		for (const outfit of character.outfitArray.filter((entry) => entry.legacyFixture !== true && entry.index !== character.defaultOutfit)) {
			const unlocked = cardArray.filter((card) => card.offerCondition != null && card.offerCondition.outfit === outfit.index);
			const worn = unlocked.filter((card) => card.offerCondition.index === "wearsOutfit");
			if (unlocked.length !== 5 || worn.length !== 1) shapeProblemArray.push(characterIndex + "/" + outfit.index + " gates " + unlocked.length + " (" + worn.length + " worn-only)");
		}
	}
	check("every character: 12 C + 5 R from the start, 3 C + 2 R per alt outfit (one worn-only), one base Choose One",
		shapeProblemArray.length === 0, shapeProblemArray.join("; "));

	// --- Clemence's two rules (CARD-POOL-01 2 and 4.5) -----------------------------------------------
	const clemenceAll = hc.cardArray.filter((card) => card.characterIndex === "clemence" && card.legacyFixture !== true);
	const soothesAnAlly = (card) => {
		const flat = [];
		const walk = (list) => { for (const entry of list || []) { if (entry == null) continue; flat.push(entry); walk(entry.effectArray); walk(entry.thenArray); for (const option of entry.optionArray || []) walk(option.effectArray); } };
		walk(card.effectArray);
		for (const level of card.upgradeArray || []) walk(level.effectArray);
		const selfAimed = card.targetMode === "owner" || card.targetMode === "self";
		return flat.some((entry) => entry.index === "soothe" && entry.targetOverride !== "owner" && !(entry.targetOverride == null && selfAimed));
	};
	check("Clemence never takes Lust off an ally: no card, upgrade or broken form of hers soothes anyone but herself",
		clemenceAll.every((card) => !soothesAnAlly(card)), clemenceAll.filter(soothesAnAlly).map((card) => card.index).join(", "));
	const spendsHerLust = (card) => card != null && JSON.stringify(card.effectArray).indexOf('"soothe"') >= 0;
	const spenderFromCommon = clemenceAll.filter((card) => (card.rarity === "common" || card.rarity === "starter") && spendsHerLust(hc.findDefinition(hc.cardArray, card.brokenCard)));
	check("broken, only her rares spend her Lust; starters and commons keep their own effect",
		spenderFromCommon.length === 0, spenderFromCommon.map((card) => card.index).join(", "));

	// --- Outfit gates --------------------------------------------------------------------------------
	//Every alt outfit is unlocked from the start until the unlock routes land (CARD-POOL-01 step 7), so
	//the gate is proven on an outfit locked here.
	const siegeplate = hc.findOutfit(hc.findDefinition(hc.characterArray, "brienne"), "siegeplate");
	const siegeplateFromStart = siegeplate.unlockedFromStart;
	siegeplate.unlockedFromStart = false;
	begin(PARTY_A);
	const brienne = member("brienne");
	const offered = () => hc.combat.rewardPoolFor(brienne, hc.state.run.combat).map((entry) => entry.index);
	const lockedPool = offered();
	check("an alt outfit's cards stay out of the pool until the outfit is unlocked",
		lockedPool.indexOf("brienneShieldBash") >= 0 && lockedPool.indexOf("brienneRiposte") < 0 && lockedPool.indexOf("brienneUnstoppable") < 0);
	hc.unlocks.grant("outfit", "siegeplate", "brienne");
	const unlockedPool = offered();
	check("unlocking it opens its commons and its any-pool rare, but not its worn-only rare",
		unlockedPool.indexOf("brienneRiposte") >= 0 && unlockedPool.indexOf("brienneForgeTheLine") >= 0 && unlockedPool.indexOf("brienneUnstoppable") < 0);
	brienne.outfitIndex = "siegeplate";
	check("wearing it opens the worn-only rare", offered().indexOf("brienneUnstoppable") >= 0);
	brienne.outfitIndex = "default";
	siegeplate.unlockedFromStart = siegeplateFromStart;

	// --- Resolve, Devotion and Stride (CARD-POOL-01 3) -------------------------------------------------
	begin(PARTY_A, 3302, null, ["clemence", "cinder"]);
	let brienneNow = member("brienne");
	const clemence = member("clemence");
	const cinder = member("cinder");
	brienneNow.health = Math.max(1, brienneNow.health - 20);
	const devotionBefore = hc.mechanicValue(clemence, "devotion");
	run(clemence, brienneNow, [{ index: "heal", amount: 7 }]);
	check("Devotion: 1 per point of health Clemence gives", hc.mechanicValue(clemence, "devotion") - devotionBefore === 7,
		String(hc.mechanicValue(clemence, "devotion") - devotionBefore));
	run(clemence, brienneNow, [{ index: "temporaryHealth", amount: 5 }]);
	check("and 1 per point of Temporary HP", hc.mechanicValue(clemence, "devotion") - devotionBefore === 12);
	run(clemence, clemence, [{ index: "lust", amount: 9 }]);
	check("and none from her Lust", hc.mechanicValue(clemence, "devotion") - devotionBefore === 12);
	run(brienneNow, brienneNow, [{ index: "heal", amount: 4 }]);
	check("and none from someone else's healing", hc.mechanicValue(clemence, "devotion") - devotionBefore === 12);
	check("Resolve and Devotion both hold 100", hc.findDefinition(hc.mechanicArray, "resolve").maximum === 100 &&
		hc.findDefinition(hc.mechanicArray, "devotion").maximum === 100);
	const strideBefore = hc.mechanicValue(cinder, "stride");
	run(cinder, cinder, [{ index: "applyStatus", status: "sundered", stacks: 2 }]);
	check("Stride: one when Cinder gains a debuff, however many stacks", hc.mechanicValue(cinder, "stride") === strideBefore + 1);
	run(cinder, cinder, [{ index: "applyStatus", status: "strength", stacks: 1 }]);
	check("and none for a boon", hc.mechanicValue(cinder, "stride") === strideBefore + 1);

	// --- What survived the enemy turn (Brienne's Oath, Severine's Answer in Kind) --------------------
	begin(PARTY_A, 3303, "loneSporeling");
	const carrier = member("brienne");
	carrier.temporaryHealth = 20;
	hc.combat.endPlayerTurn();
	const healthAtEnd = carrier.health;
	hc.combat.runEnemyTurn();
	const goldAfterEnemy = carrier.temporaryHealth;
	const healthAfterEnemy = carrier.health;
	hc.combat.startPlayerTurn(ctx());
	check("carried Temporary HP is what survived the enemy turn, after her own halving",
		carrier.carriedTemporaryHealth === hc.decayedTemporaryHealth(goldAfterEnemy, hc.temporaryDecayFraction(carrier)),
		goldAfterEnemy + " -> " + carrier.carriedTemporaryHealth);
	check("and the health lost since her turn ended is recorded", carrier.healthLostLastEnemyTurn === Math.max(0, healthAtEnd - healthAfterEnemy),
		String(carrier.healthLostLastEnemyTurn));

	// --- Reactions --------------------------------------------------------------------------------------
	begin(PARTY_A, 3304, null, ["clemence", "cinder"]);
	const oathBrienne = member("brienne");
	const clemence2 = member("clemence");
	const cinder2 = member("cinder");
	run(oathBrienne, oathBrienne, [{ index: "applyStatus", status: "oathbound", stacks: 1 }]);
	oathBrienne.carriedTemporaryHealth = 5;
	let front = hc.frontOf("enemy", hc.state.run.combat);
	let frontBefore = front.health;
	const handBefore = hc.state.run.combat.handArray.length;
	fire("onTurnStart", oathBrienne);
	check("Unbroken Oath: gold carried in deals 6 to the front enemy and draws a card",
		frontBefore - front.health === 6 && hc.state.run.combat.handArray.length === handBefore + 1);
	oathBrienne.carriedTemporaryHealth = 0;
	frontBefore = front.health;
	fire("onTurnStart", oathBrienne);
	check("and nothing when none was carried", front.health === frontBefore);

	run(clemence2, clemence2, [{ index: "applyStatus", status: "blessing", stacks: 1 }]);
	cinder2.temporaryHealth = 0;
	run(cinder2, cinder2, [{ index: "temporaryHealth", amount: 5 }]);
	check("Blessing: an ally's gold arrives with 2 more, once (it does not feed itself)", cinder2.temporaryHealth === 7, String(cinder2.temporaryHealth));

	run(cinder2, cinder2, [{ index: "applyStatus", status: "phoenixHeart", stacks: 1 }]);
	front = hc.frontOf("enemy", hc.state.run.combat);
	frontBefore = front.health;
	run(cinder2, cinder2, [{ index: "applyStatus", status: "frail", stacks: 1 }]);
	check("Phoenix Heart: a debuff on Cinder hits the front enemy for 4", frontBefore - front.health === 4);

	//A fresh fight: Blessing, above, would add its own 2 to the drill.
	begin(PARTY_A, 3309, null, ["clemence", "cinder"]);
	const drillCinder = member("cinder");
	run(drillCinder, drillCinder, [{ index: "applyStatus", status: "formationDrill", stacks: 1 }]);
	const mover = member("clemence");
	const moverGold = mover.temporaryHealth || 0;
	hc.shiftEntity(mover, "back", ctx(drillCinder));
	const moverAfter = mover.temporaryHealth || 0;
	check("Formation Drill: an ally who moves gains 3 Temporary HP", moverAfter - moverGold === 3, String(moverAfter - moverGold));

	begin(PARTY_A, 3310, null, ["clemence", "cinder"]);
	const fontClemence = member("clemence");
	const fontBrienne = member("brienne");
	run(fontClemence, fontClemence, [{ index: "applyStatus", status: "fontOfGrace", stacks: 1 }]);
	fontBrienne.health = Math.max(1, fontBrienne.health - 30);
	const hurtBefore = fontBrienne.health;
	const lustBefore = fontClemence.lust || 0;
	fire("onTurnStart", fontClemence);
	check("Font of Grace: the most hurt ally heals 5 and Clemence gains 3 Lust",
		fontBrienne.health - hurtBefore === 5 && (fontClemence.lust || 0) - lustBefore >= 3);

	begin(PARTY_A, 3311, null, ["clemence", "cinder"]);
	const giftClemence = member("clemence");
	const giftCinder = member("cinder");
	run(giftClemence, giftClemence, [{ index: "applyStatus", status: "rapturesGift", stacks: 1 }]);
	const giftGold = giftCinder.temporaryHealth || 0;
	giftClemence.lust = giftClemence.health + (giftClemence.temporaryHealth || 0) + 5;
	hc.checkBreak(giftClemence, ctx(giftClemence));
	check("Rapture's Gift: when she Breaks, the others gain 2 Strength and 8 Temporary HP",
		giftClemence.broken === true && hc.statusStacks(giftCinder, "strength") >= 2 && (giftCinder.temporaryHealth || 0) - giftGold >= 8);

	begin(PARTY_A, 3305);
	run(member("cinder"), member("cinder"), [{ index: "applyStatus", status: "emberWatch", stacks: 1 }]);
	hc.shiftEntity(member("cinder"), "front", ctx(member("cinder")));
	const watchBefore = hc.livingEntityArray("enemy", hc.state.run.combat).map((entry) => entry.health);
	fire("onTurnEnd", member("cinder"));
	const watchAfter = hc.livingEntityArray("enemy", hc.state.run.combat).map((entry) => entry.health);
	check("Ember Watch at the front: 6 to every enemy", watchBefore.every((health, slot) => health - watchAfter[slot] === Math.min(health, 6)));
	hc.shiftEntity(member("cinder"), "back", ctx(member("cinder")));
	const goldBefore = hc.state.run.partyArray.map((entry) => entry.temporaryHealth || 0);
	fire("onTurnEnd", member("cinder"));
	check("and at the back: 4 Temporary HP to every ally",
		hc.state.run.partyArray.every((entry, slot) => (entry.temporaryHealth || 0) - goldBefore[slot] === 4));

	begin(PARTY_B, 3306);
	const nettle = member("nettle");
	const severine = member("severine");
	const cassadora = member("cassadora");
	run(nettle, nettle, [{ index: "applyStatus", status: "rotGarden", stacks: 1 }]);
	hit(severine, enemy(), 3);
	check("Rot Garden: any ally's hit leaves 1 Poison", hc.statusStacks(enemy(), "poison") === 1);
	hit(null, enemy(), 2, { damageType: "poison", ignoreTemporary: true });
	check("and a Poison tick never feeds it", hc.statusStacks(enemy(), "poison") === 1);
	run(severine, severine, [{ index: "applyStatus", status: "envenomed", stacks: 1 }]);
	const venomBefore = hc.statusStacks(enemy(1), "poison");
	hit(severine, enemy(1), 3);
	check("Plague Bearer's Envenomed: that ally's hit adds 2 Poison (plus the garden's 1)", hc.statusStacks(enemy(1), "poison") - venomBefore === 3,
		String(hc.statusStacks(enemy(1), "poison") - venomBefore));

	run(severine, severine, [{ index: "applyStatus", status: "scarTissue", stacks: 1 }]);
	severine.temporaryHealth = 0;
	run(severine, severine, [{ index: "loseHealth", amount: 4, targetOverride: "owner" }]);
	check("Scar Tissue: losing health leaves 3 Temporary HP", severine.temporaryHealth === 3, String(severine.temporaryHealth));

	run(severine, severine, [{ index: "applyStatus", status: "bloodDebt", stacks: 1 }]);
	cassadora.health = Math.max(1, cassadora.health - 20);
	const debtBefore = hc.livingEntityArray("enemy", hc.state.run.combat).reduce((sum, entry) => sum + entry.health, 0);
	run(cassadora, cassadora, [{ index: "heal", amount: 5 }]);
	const debtAfter = hc.livingEntityArray("enemy", hc.state.run.combat).reduce((sum, entry) => sum + entry.health, 0);
	check("Blood Debt: another ally's heal is dealt to a random enemy", debtBefore - debtAfter === 5, String(debtBefore - debtAfter));

	run(cassadora, cassadora, [{ index: "applyStatus", status: "covensCurse", stacks: 1 }]);
	const curseBefore = enemy().health;
	run(cassadora, enemy(), [{ index: "applyStatus", status: "weak", stacks: 1 }]);
	check("Coven's Curse: a debuff an ally lands costs the enemy 3", curseBefore - enemy().health === 3);

	begin(PARTY_B, 3312);
	run(member("nettle"), member("nettle"), [{ index: "applyStatus", status: "aphrodisiac", stacks: 1 }]);
	const lustPoisonBefore = hc.statusStacks(enemy(), "poison");
	run(member("cassadora"), enemy(), [{ index: "lust", amount: 4 }]);
	check("Aphrodisiac: Lust from an ally leaves 1 Poison", hc.statusStacks(enemy(), "poison") - lustPoisonBefore === 1);

	// --- The new verbs -----------------------------------------------------------------------------
	begin(PARTY_B, 3307);
	const target = enemy();
	target.statusArray = (target.statusArray || []).filter((entry) => entry.index !== "poison");
	hc.applyStatus(target, "poison", 6, ctx(member("nettle")));
	let before = target.health;
	run(member("nettle"), target, [{ index: "triggerStatus", status: "poison" }]);
	check("triggerStatus: Poison acts now for its stacks, then weakens", before - target.health === 6 && hc.statusStacks(target, "poison") === 5);
	before = target.health;
	run(member("nettle"), target, [{ index: "triggerStatus", status: "poison", times: 2 }]);
	check("twice means 5 then 4", before - target.health === 9 && hc.statusStacks(target, "poison") === 3);
	run(member("cassadora"), target, [{ index: "applyStatus", status: "weak", stacks: 2 }, { index: "transferStatuses", from: "target" }]);
	check("transferStatuses onto itself doubles every debuff", hc.statusStacks(target, "weak") === 4 && hc.statusStacks(target, "poison") === 6);
	const other = enemy(1);
	run(member("cassadora"), target, [{ index: "transferStatuses", from: "target", to: "otherEnemies" }]);
	check("and copies them onto every other enemy", other == null || (hc.statusStacks(other, "weak") >= 4 && hc.statusStacks(other, "poison") >= 6));
	const nettleGiver = member("nettle");
	hc.applyStatus(nettleGiver, "sundered", 2, ctx(nettleGiver));
	const sunderedBefore = hc.statusStacks(target, "sundered");
	run(nettleGiver, target, [{ index: "transferStatuses", from: "source", move: true }]);
	check("and a move strips the giver", hc.statusStacks(nettleGiver, "sundered") === 0 && hc.statusStacks(target, "sundered") === sunderedBefore + 2);
	check("the new target modes resolve", hc.resolveTargetMode("weakestEnemy", ctx(member("nettle"))).length === 1 &&
		hc.resolveTargetMode("mostHurtAlly", ctx(member("nettle"))).length === 1);

	// --- Art owed is planned, never requested ------------------------------------------------------
	const owed = hc.cardArray.filter((card) => card.artOwed === true);
	check("cards written before their art say so (artOwed), and name the path the art will take",
		owed.length > 0 && owed.every((card) => typeof card.artPath === "string" && card.artPath.indexOf("cards/art/") === 0));
}

console.log("\n[103] Session 36 -- FEEDBACK-08: one health baseline, stale saves cleared, wrong-side mirroring");
{
	const hc = newEngine();

	// --- One health baseline, tankiness bought with Vigour ranks ---------------------------------
	const shipped = hc.characterArray.filter((character) => character.inDevelopment !== true);
	check("every character starts at the same health", shipped.every((character) =>
		hc.characterBaseHealth(character) === hc.tuning.run.characterBaseHealth), 
		shipped.map((c) => c.index + ":" + hc.characterBaseHealth(c)).join(" "));
	check("no character overrides it", hc.characterArray.every((character) => character.baseHealth == null));
	const vigourFor = (characterIndex) => {
		const character = hc.findDefinition(hc.characterArray, characterIndex);
		return character.progressionTree.nodeArray.find((node) => node.name === "Vigour");
	};
	check("Brienne's Vigour has six ranks and Nettle's one, which is what separates them",
		(vigourFor("brienne").rankMaximum || 1) === 6 && (vigourFor("nettle").rankMaximum || 1) === 1);
	// SESSION 55 REPLACED THE RULE THIS CHECKED. FEEDBACK-08 made Vigour cost the same PER RANK for
	// everyone, so Nettle's single rank would not cost six ranks' worth -- which left Brienne paying six
	// times as much for the same node. Noodle: "One rank of Vigor on Brienne should not cost the same as
	// a rank of it on Nettle, since brienne has 6 ranks, it should cost 4 exp." The NODE costs about 25
	// now, whoever holds it, and the per-rank price is that divided by the ranks. Both complaints are
	// answered by the same rule: Nettle still pays 25 for her one rank, and Brienne pays 4 for each of six.
	check("Vigour's whole node costs about the same for everyone, however many ranks it splits into",
		vigourFor("brienne").cost * 6 <= 30 && vigourFor("nettle").cost === 25,
		"brienne " + vigourFor("brienne").cost + " x6, nettle " + vigourFor("nettle").cost + " x1");
	check("and one of Brienne's ranks costs the 4 he asked for", vigourFor("brienne").cost === 4,
		String(vigourFor("brienne").cost));
	check("so the health ceiling is ordered Brienne > Severine > Cassadora > Nettle", (() => {
		const ceiling = (index) => hc.tuning.run.characterBaseHealth +
			(vigourFor(index).rankMaximum || 1) * vigourFor(index).healthModifier;
		return ceiling("brienne") > ceiling("severine") && ceiling("severine") > ceiling("cassadora") &&
			ceiling("cassadora") > ceiling("nettle");
	})());

	// --- Starting gold ------------------------------------------------------------------------------
	check("a run opens on 30 gold, not 100", hc.tuning.run.startingResourceArray.gold === 30);

	// --- Stale alpha saves are deleted, not migrated ------------------------------------------------
	check("a save from before the cutoff is stale", hc.save.isStale({ formatVersion: hc.tuning.save.staleBeforeVersion - 1 }) === true);
	check("and one at the cutoff is not", hc.save.isStale({ formatVersion: hc.tuning.save.staleBeforeVersion }) === false);
	{
		const engine = newEngine();
		startRun(engine, 1234);
		engine.save.write(engine.tuning.save.autosaveSlot);
		check("an autosave written now reads back", engine.save.hasAutosave() === true);
		const cleared = engine.save.purgeStaleSlots();
		check("and a current save is left alone by the purge",
			cleared.length === 0 && engine.save.hasAutosave() === true);
		// Raising the cutoff past what is stored is the same shape as a save written before it.
		engine.tuning.save.staleBeforeVersion = engine.tuning.save.formatVersion + 1;
		const purged = engine.save.purgeStaleSlots();
		check("a save from before the cutoff is cleared from its slot rather than carried forward",
			purged.indexOf(engine.tuning.save.autosaveSlot) >= 0 && engine.save.hasAutosave() === false);
		check("and reading that slot no longer resumes anything",
			engine.save.read(engine.tuning.save.autosaveSlot) === false);
	}

	// --- A combatant on the wrong side is mirrored, IF its drawing is in profile --------------------
	// SUPERSEDED SESSION 43. This block used to assert that displacement alone mirrors, which is what
	// session 36 built. Noodle looked at a screenshot of five summoned pieces and asked "Why are they
	// backwards?" -- because every drawing in this project faces the VIEWER, and flipping one of those
	// turns the figure around. Mirroring is now opt-in per definition (`sideFacingArt`); block [108]
	// covers the new rule in full. These four are kept, pointed at the behaviour that actually ships.
	check("an enemy on the enemy line is not mirrored", hc.art.spriteFlipped({ enemyIndex: "sporeling", side: "enemy" }) === false);
	check("the same enemy summoned to the party's line is NOT mirrored either, since it faces the viewer",
		hc.art.spriteFlipped({ enemyIndex: "sporeling", side: "ally" }) === false);
	check("a character in the party is not mirrored", hc.art.spriteFlipped({ characterIndex: "brienne", side: "ally" }) === false);
	check("a character summoned to the enemy line is not mirrored either",
		hc.art.spriteFlipped({ characterIndex: "brienne", side: "enemy" }) === false);

	// --- The combat stance is on, and every pose it asks for exists ---------------------------------
	check("the resting pose is the combat stance", hc.art.restingPose() === "combat");

	// --- hasTag is registered ONCE, and still answers for a card ------------------------------------
	check("hasTag is registered exactly once",
		hc.conditionArray.filter((condition) => condition.index === "hasTag").length === 1);
	{
		const resolved = hc.resolveCard({ instanceId: null, cardIndex: "nettleMiasma", ownerInstanceId: null, upgradeLevel: 0 });
		check("and answers for a card's school as well as for a target mode",
			hc.testCondition({ index: "hasTag", of: "card", tag: "necromancy" }, hc.newEffectContext({ card: resolved })) === true);
	}

	// --- Brienne's Vow ------------------------------------------------------------------------------
	{
		const vow = hc.findDefinition(hc.characterArray, "brienne").progressionTree.nodeArray
			.find((node) => node.name === "Vow");
		const effectArray = vow.abilityUpgradeArray[0].effectArray;
		check("Vow soothes 10 and clears negative statuses",
			effectArray.some((entry) => entry.index === "soothe" && entry.amount === 10) &&
			effectArray.some((entry) => entry.index === "cleanse"));
	}

	// --- A broken card keeps the shape of the card it replaced --------------------------------------
	{
		const engine = newEngine();
		startRun(engine, 4242, [{ characterIndex: "brienne", outfitIndex: "default" }]);
		engine.combat.begin("loneSporeling", {});
		const member = engine.state.run.partyArray[0];
		member.broken = true;
		const shapeOf = (cardIndex) => {
			const resolved = engine.resolveCard({ instanceId: null, cardIndex: cardIndex,
				ownerInstanceId: member.instanceId, upgradeLevel: 0 });
			return { into: resolved.index, layout: resolved.layout, art: engine.cardArtPath(resolved) };
		};
		const wide = engine.cardArray.find((card) => card.characterIndex === "brienne" && card.layout === "horizontal" && card.rarity === "common");
		const tall = engine.cardArray.find((card) => card.characterIndex === "brienne" && card.layout === "vertical");
		const brokeWide = shapeOf(wide.index);
		const brokeTall = shapeOf(tall.index);
		check("both break into the same shared card", brokeWide.into === brokeTall.into && brokeWide.into === "brienneBroken");
		check("but a horizontal card breaks into a horizontal frame", brokeWide.layout === "horizontal", brokeWide.layout);
		check("and a vertical card into a vertical one", brokeTall.layout === "vertical", brokeTall.layout);
		check("each frame gets its own crop, since the two windows are different shapes",
			brokeWide.art !== brokeTall.art, brokeWide.art + " / " + brokeTall.art);
	}
	check("NO card changes shape when it breaks", (() => {
		const mismatch = [];
		for (const card of hc.cardArray) {
			if (card.rarity === "broken" || card.rarity === "enemy") continue;
			if (card.characterIndex == null || card.characterIndex === "neutral") continue;
			const brokenIndex = hc.brokenFormIndexFor(card);
			if (brokenIndex == null) continue;
			const broken = hc.findDefinition(hc.cardArray, brokenIndex);
			if (broken == null) continue;
			// The resolver copies the replaced card's layout across unless the form fixes its own.
			const shown = broken.layoutFixed === true || card.layout == null ? broken.layout : card.layout;
			if (shown !== card.layout) mismatch.push(card.index + " " + card.layout + "->" + shown);
		}
		return mismatch.length === 0;
	})());
	check("a broken form that can wear either frame carries a crop for each", hc.cardArray.every((card) => {
		if (card.rarity !== "broken") return true;
		// Only the SHARED forms (the ones a character points every card at) are dealt into both.
		const shared = hc.characterArray.some((character) => character.brokenCard === card.index);
		if (!shared) return true;
		return card.artPathByLayout != null &&
			card.artPathByLayout.horizontal != null && card.artPathByLayout.vertical != null;
	}));

	// --- The compendium reads in an order a player can follow ---------------------------------------
	{
		const ordered = hc.obtainableCardArray("brienne").slice().sort(hc.compareCardsForReading);
		const rankArray = ordered.map((card) => hc.cardRarityRank(card));
		check("a character's cards read starter, then common, then rare",
			rankArray.every((rank, index) => index === 0 || rankArray[index - 1] <= rank),
			ordered.map((card) => card.rarity).join(","));
		const bestiary = hc.enemyArray.slice().sort(hc.compareEnemiesForReading);
		const roleRank = bestiary.filter((enemy) => hc.definitionHasTag(enemy, "golem") === false)
			.map((enemy) => hc.enemyDifficultyRank(enemy));
		check("the bestiary reads weakest role first and bosses last",
			roleRank.every((rank, index) => index === 0 || roleRank[index - 1] <= rank),
			bestiary.map((enemy) => enemy.role).join(","));
		const lastOrdinary = bestiary.filter((enemy) => hc.definitionHasTag(enemy, "golem") === false).pop();
		check("and the last enemy before the golems is a boss", lastOrdinary.role === "boss", lastOrdinary.index);
		const firstGolemAt = bestiary.findIndex((enemy) => hc.definitionHasTag(enemy, "golem"));
		check("the golems are last of all, not first",
			firstGolemAt > 0 && bestiary.slice(firstGolemAt).every((enemy) => hc.definitionHasTag(enemy, "golem")));
	}

	// --- The compendium picks before it reads (the logbook shape) -----------------------------------
	{
		const source = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-title.js"), "utf8");
		check("the compendium has a picker, used by both tabs",
			/honeycomb\.compendium\.renderPicker = function/.test(source) &&
			(source.match(/honeycomb\.compendium\.renderPicker\(\{/g) || []).length === 2);
		check("the bestiary no longer stacks every enemy's block into one scroll",
			/renderBestiaryEntry = function/.test(source) &&
			/renderBestiary = function[\s\S]{0,1200}renderPicker/.test(source));
		check("every enemy falls under a named group heading", hc.enemyArray.every((enemy) =>
			hc.compendium == null || hc.compendium.enemyGroupName == null ||
			hc.compendium.enemyGroupName(enemy) !== "Other"),
			"honeycomb-scene-title.js is not loaded headlessly; the group table is checked below");
		// The heading table has to cover every role the balance template declares, or an enemy written
		// to a new role quietly lands in "Other".
		const headingArray = (source.match(/\{ index: "(\w+)", name: "[^"]+" \}/g) || []).join(" ");
		check("the group headings cover every role in the balance template",
			hc.tuning.balance.enemyRoleArray.every((role) => headingArray.indexOf('index: "' + role.index + '"') >= 0),
			hc.tuning.balance.enemyRoleArray.map((role) => role.index).join(","));
	}

	// --- The progression column has room for a two-line name plus its price -------------------------
	{
		const view = hc.tuning.progression.treeView;
		const deepestLabel = view.nodeRadius + view.labelOffset + 3 * view.labelLineHeight;
		check("the tree reserves room below the last row for a two-line name and its cost",
			view.bottomMargin >= deepestLabel, view.bottomMargin + " < " + deepestLabel);
	}
}

console.log("\n[104] Session 38 -- FEEDBACK-09: the rarity gem marks rarity instead of decorating every card");
{
	const hc = newEngine();

	// --- The gem is opt-in, per rarity -------------------------------------------------------------
	// Noodle: "remove the rarity gems from common cards". The gem used to be drawn on every card, so
	// it said nothing at all; it is now a piece the RARITY asks for.
	const gemPiece = hc.tuning.art.cardChrome.pieceArray.find((piece) => piece.rarityGem === true);
	check("exactly one chrome piece is the rarity mark",
		gemPiece != null && hc.tuning.art.cardChrome.pieceArray.filter((piece) => piece.rarityGem === true).length === 1);
	const rarityOf = (index) => hc.findDefinition(hc.cardRarityArray, index);
	check("common cards draw no gem", rarityOf("common").showRarityGem !== true);
	check("nor do starters, which sit below common", rarityOf("starter").showRarityGem !== true);
	check("rare cards do", rarityOf("rare").showRarityGem === true);
	//Special is two curses and two stand-ins, so a gold mark there would read as a reward.
	check("a curse is not dressed up as a prize", rarityOf("special").showRarityGem !== true);
	check("the gem therefore means exactly one thing",
		hc.cardRarityArray.filter((rarity) => rarity.showRarityGem === true).map((rarity) => rarity.index).join(",") === "rare");
	check("every rarity states its answer rather than leaving it to a default",
		hc.cardRarityArray.every((rarity) => typeof rarity.showRarityGem === "boolean"),
		hc.cardRarityArray.filter((rarity) => typeof rarity.showRarityGem !== "boolean").map((rarity) => rarity.index).join(","));

	// --- What a CARD answers, which is what the chrome reads ---------------------------------------
	const cardNamed = (index) => hc.findDefinition(hc.cardArray, index);
	const someOfRarity = (rarity) => hc.cardArray.filter((card) => card.rarity === rarity);
	check("a common card says no", someOfRarity("common").length > 0 &&
		someOfRarity("common").every((card) => hc.cardShowsRarityGem(card) === false));
	check("a rare card says yes", someOfRarity("rare").length > 0 &&
		someOfRarity("rare").every((card) => hc.cardShowsRarityGem(card) === true));
	check("an enemy's move wears no rarity it could boast of",
		someOfRarity("enemy").every((card) => hc.cardShowsRarityGem(card) === false));
	check("and no curse does either",
		hc.cardArray.filter((card) => card.type === "curse").every((card) => hc.cardShowsRarityGem(card) === false));
	check("a card with no rarity at all draws none rather than throwing", hc.cardShowsRarityGem({ index: "none" }) === false);
	check("and neither does nothing", hc.cardShowsRarityGem(null) === false);

	// --- The renderer actually gates on it ---------------------------------------------------------
	// The markup lives in honeycomb-ui.js, which the harness does not load, so the seam is read from
	// source: the piece is skipped unless the caller passed the card's own answer.
	{
		const source = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-ui.js"), "utf8");
		check("the chrome skips the rarity piece unless the card asks for it",
			/piece\.rarityGem == true && showRarityGem != true/.test(source));
		check("and the card's own rarity is what it passes",
			/cardChrome\([\s\S]{0,160}honeycomb\.cardShowsRarityGem\(resolved\)/.test(source));
	}

	// --- Moss is Nettle (FEEDBACK-08 D1, answered session 38) --------------------------------------
	// "moss should have 1, Brienne having 6" -- moss is Nettle's former name, so the ranks stand.
	const vigourRank = (characterIndex) => {
		const character = hc.findDefinition(hc.characterArray, characterIndex);
		const node = character.progressionTree.nodeArray.find((entry) => entry.name === "Vigour");
		//A single-rank node leaves `rankMaximum` off (the generator only writes it above 1), so the
		//ceiling is asked of the progression layer rather than read off the node.
		return node == null ? null : hc.progression.rankMaximum(node);
	};
	check("Nettle is the least tanky of the six, at one rank of Vigour", vigourRank("nettle") === 1, String(vigourRank("nettle")));
	check("and Brienne the most, at six", vigourRank("brienne") === 6, String(vigourRank("brienne")));
	check("no character named Moss was ever added by mistake",
		hc.characterArray.every((character) => String(character.name).toLowerCase() !== "moss"));
}

console.log("\n[105] Session 40 -- FEEDBACK-09: an in-development character is not advertised, not even as a locked slot");
{
	const hc = newEngine();

	// --- The gate is one function, in a file the suite can see -------------------------------------
	// BASICS, the demo scope: Anastasia "being shown as secret is also bad if she doesn't make it, I
	// don't need 10k emails asking how to unlock her". So the bar is not "she cannot be picked", it is
	// "nothing on screen implies she exists".
	check("the shipped roster is asked for rather than filtered inline", typeof hc.shippedCharacterArray === "function");
	const shipped = hc.shippedCharacterArray();
	check("no character still in development is in it",
		shipped.every((character) => character.inDevelopment != true),
		shipped.filter((character) => character.inDevelopment == true).map((character) => character.index).join(","));
	check("all six shipped characters are",
		["brienne", "nettle", "severine", "cassadora", "cinder", "clemence"]
			.every((index) => shipped.some((character) => character.index === index)),
		shipped.map((character) => character.index).join(","));
	check("Anastasia is not", shipped.every((character) => character.index !== "anastasia"));

	// --- The gate is doing something (divergence, not a no-op that happens to read green) ----------
	const hiddenCount = hc.characterArray.length - shipped.length;
	check("the gate actually removes somebody, so these checks are not vacuous", hiddenCount > 0, String(hiddenCount));
	check("and it removes exactly the in-development characters",
		hiddenCount === hc.characterArray.filter((character) => character.inDevelopment == true).length);

	// --- The bug this block exists for ------------------------------------------------------------
	// The teambuilding roster drew one locked "???" tile per character it had not shown, counted off the
	// UNFILTERED table -- so a fully unlocked profile showed a phantom slot for Anastasia. The count has
	// to come off the shipped roster. This asserts the old formula's error is exactly the hidden count,
	// which is the shape of the failure rather than a restatement of the fix.
	check("counting locked slots off the whole table would invent one tile per hidden character",
		hc.characterArray.length - shipped.length === hiddenCount && hiddenCount >= 1);

	// --- The screens that read it. Scene files need a DOM, so the seam is read from source ---------
	{
		const teambuilding = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-teambuilding.js"), "utf8");
		const rosterColumn = teambuilding.slice(
			teambuilding.indexOf("honeycomb.teambuilding.buildRosterColumn = function"),
			teambuilding.indexOf("honeycomb.teambuilding.buildRosterEntry = function"));
		check("the roster column asks for the shipped roster", /shippedCharacterArray\(\)/.test(rosterColumn));
		check("the locked count comes off that roster, not the whole table",
			/lockedCount = rosterArray\.length - shownCount/.test(rosterColumn));
		// The prose in that function names characterArray to explain why it does not read it, so this
		// asks about the USE -- honeycomb.characterArray -- rather than the word.
		check("and the column no longer reads the unfiltered table",
			/honeycomb\.characterArray/.test(rosterColumn) === false);

		const title = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-title.js"), "utf8");
		check("the compendium uses the same gate rather than its own copy of the filter",
			/rosterArray = honeycomb\.shippedCharacterArray\(\)/.test(title) &&
			/characterArray\.filter\(function \(character\) \{ return character\.inDevelopment/.test(title) === false);
	}

	// --- Nothing offers her either ----------------------------------------------------------------
	// The roster tile was the visible half; the profile is the other. A fresh profile must not carry her.
	//newProfile returns the STATE; the profile hangs off it.
	const profile = hc.newProfile().profile;
	check("a fresh profile does not unlock her",
		profile.unlockedCharacterArray.indexOf("anastasia") < 0,
		profile.unlockedCharacterArray.join(","));
	check("and she does not claim to start unlocked",
		hc.findDefinition(hc.characterArray, "anastasia").unlockedFromStart !== true);
}

console.log("\n[106] Session 43 -- chessmaster A12: a side takes the share of the battlefield its crowd needs");
{
	const hc = newEngine();

	// --- The weighting is a tuning entry and a visible function ------------------------------------
	// A12 measured the fix and then it sat in a document for a session. Both numbers are tuning entries
	// rather than CSS literals, per BASICS: "A numeric literal buried inside a function body is a bug."
	check("the weighting is a tuning entry", typeof hc.tuning.layout.sideGrowPerExtraFighter === "number");
	check("and the suite can see the function that applies it", typeof hc.sideGrowFactor === "function");
	check("the measured setting is 0.25", hc.tuning.layout.sideGrowPerExtraFighter === 0.25,
		String(hc.tuning.layout.sideGrowPerExtraFighter));

	// --- An ordinary fight is untouched ------------------------------------------------------------
	// The whole point of weighting by count is that it does nothing when the counts match, so no
	// existing encounter moves. A side with nobody in its row (everyone anchored) must not go below 1.
	check("an empty row grows at 1", hc.sideGrowFactor(0) === 1, String(hc.sideGrowFactor(0)));
	check("a lone fighter grows at 1", hc.sideGrowFactor(1) === 1, String(hc.sideGrowFactor(1)));
	check("null is treated as empty rather than arithmetic", hc.sideGrowFactor(null) === 1);
	for (let evenCount = 1; evenCount <= 5; evenCount++) {
		const both = hc.sideGrowFactor(evenCount);
		check("a " + evenCount + "-on-" + evenCount + " fight still splits the battlefield evenly",
			both / (both + both) === 0.5, String(both));
	}

	// --- Five allies against one enemy, which is the case that killed the character concept ---------
	// > In practice, 5 party members shrinking the roster size looks very silly.
	// Measured at 1280x800: the even split gave the ally row 595px and 161px figures; the weighting
	// gives it 777px and 215px, against 193px for three allies today. So the share is what is asserted
	// here -- pixels belong to the browser, the ratio belongs to the engine.
	const allyGrow = hc.sideGrowFactor(5);
	const enemyGrow = hc.sideGrowFactor(1);
	check("five in a row grows at 2", allyGrow === 2, String(allyGrow));
	const share = allyGrow / (allyGrow + enemyGrow);
	check("so the crowded side takes two thirds of the battlefield", Math.abs(share - 2 / 3) < 1e-9, String(share));
	check("which is more than the even split it replaces", share > 0.5, String(share));
	// And the knob has to matter in the other direction too: pure count weighting starved the enemy row
	// down to 117px, so a setting that overshoots must be reachable and visibly different.
	check("pure count weighting would take five sixths, which is why 0.25 was chosen instead",
		Math.abs((1 + 4 * 1) / ((1 + 4 * 1) + 1) - 5 / 6) < 1e-9);

	// --- Falsification: the old behaviour is recoverable from the tuning entry ----------------------
	// If the weighting were hardcoded anywhere, zeroing the tuning entry would not restore the even
	// split. This is the check that would go red if a later session inlined the number.
	{
		const restore = hc.tuning.layout.sideGrowPerExtraFighter;
		hc.tuning.layout.sideGrowPerExtraFighter = 0;
		check("zeroing the weighting restores the old even split at every count",
			[0, 1, 2, 3, 4, 5].every((count) => hc.sideGrowFactor(count) === 1));
		hc.tuning.layout.sideGrowPerExtraFighter = restore;
		check("and putting it back restores the weighting", hc.sideGrowFactor(5) === 2);
	}

	// --- The side padding -------------------------------------------------------------------------
	// 5% of 1280 was 124px off a side already too narrow for five figures. A layout that leaves the
	// field out keeps the stylesheet's own 5%, so the layouts nobody ships are not silently changed.
	const bridge = hc.battleLayoutPropertyArray.find((entry) => entry.field === "sidePaddingPercent");
	check("the side padding reaches the stylesheet through the layout bridge", bridge != null);
	check("as a percentage named --hc-side-padding",
		bridge != null && bridge.variable === "--hc-side-padding" && bridge.unit === "%");
	const scene = hc.battleLayout();
	check("the shipped layout is scene", scene.index === "scene", scene.index);
	check("and it cuts the side padding to 2%", scene.sidePaddingPercent === 2, String(scene.sidePaddingPercent));

	// --- The seam in the scene file, read from source ----------------------------------------------
	// renderSide lives in a scene file, which the suite does not load, so the wiring is asserted against
	// the text. The load-bearing detail is WHICH count it passes: `inRowCount` excludes anchored
	// fighters, and an anchored boss is sized off the battlefield's height, so counting one would widen
	// a side on behalf of a figure that cannot use the room.
	{
		const combat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
		const renderSide = combat.slice(
			combat.indexOf("honeycomb.combatScene.renderSide = function"),
			combat.indexOf("honeycomb.combatScene.renderFighter = function"));
		check("renderSide asks the engine for the grow factor", /honeycomb\.sideGrowFactor\(/.test(renderSide));
		check("and passes the in-row count, not everyone on the side",
			/sideGrowFactor\(inRowCount\)/.test(renderSide));
		check("the side writes the variable the stylesheet reads",
			/--hc-side-grow: *' *\+ *sideGrow/.test(renderSide));
	}

	// --- The stylesheet no longer carries either number ---------------------------------------------
	{
		const css = fs.readFileSync(path.join(ROOT, "..", "css", "honeycomb.css"), "utf8");
		const sideRule = css.slice(css.indexOf(".hcSide {"), css.indexOf(".hcSide-ally {"));
		check("the side grows by the variable rather than a fixed 1",
			/flex-grow: *var\(--hc-side-grow, *1\)/.test(sideRule));
		check("the old even-split shorthand is gone", /flex: *1 1 0/.test(sideRule) === false, sideRule.slice(0, 400));
		check("both paddings read the layout variable",
			/padding-left: *var\(--hc-side-padding, *5%\)/.test(sideRule) &&
			/padding-right: *var\(--hc-side-padding, *5%\)/.test(sideRule));
		check("and neither is a bare 5% any more",
			/padding-left: *5%/.test(sideRule) === false && /padding-right: *5%/.test(sideRule) === false);
	}
}

console.log("\n[107] Session 43 -- chessmaster A18/A21: the pieces are sized, and a small piece wears its plate lower");
{
	const hc = newEngine();

	// --- Every piece is sized, because the art cannot size them ------------------------------------
	// All twelve are drawn on one 889x1300 canvas and each fills it, so without a scale a Pawn stands
	// exactly as tall as a Rook. That is the "pawns way too big" report, and the scale is the only lever.
	const PIECE_ORDER = ["Knight", "Rook", "Bishop", "Queen", "Pawn"];
	const SIDE_ARRAY = ["celestial", "infernal"];
	const pieceOf = (side, piece) => hc.findDefinition(hc.enemyArray, side + piece);

	for (const side of SIDE_ARRAY) {
		for (const piece of PIECE_ORDER) {
			const found = pieceOf(side, piece);
			check("the " + side + " " + piece + " carries its own scale",
				found != null && found.presentation != null && typeof found.presentation.scale === "number",
				found == null ? "missing" : JSON.stringify(found.presentation));
		}
	}

	// --- Noodle's order, which is the whole content of the item -------------------------------------
	// > Of the pieces aside from the king, tallest to smallest is knight (tall but thin), rook, bishop
	// > (floating and tall), queen (pawn-sized but floating and her ribbons take up space), and then pawn.
	for (const side of SIDE_ARRAY) {
		const scaleArray = PIECE_ORDER.map((piece) => pieceOf(side, piece).presentation.scale);
		const descending = scaleArray.every((value, i) => i === 0 || scaleArray[i - 1] > value);
		check("the " + side + " pieces run knight > rook > bishop > queen > pawn",
			descending, PIECE_ORDER.map((p, i) => p + " " + scaleArray[i]).join(" > "));
	}
	// A twin is the same drawing recoloured, so a size that differed between alignments would be a slip.
	for (const piece of PIECE_ORDER) {
		check("the two " + piece + "s are the same size as each other",
			pieceOf("celestial", piece).presentation.scale === pieceOf("infernal", piece).presentation.scale);
	}
	// The Pawn is the body the board fills with, so it is the one that has to be clearly small.
	check("a Pawn is comfortably smaller than a Knight",
		pieceOf("celestial", "Pawn").presentation.scale < pieceOf("celestial", "Knight").presentation.scale * 0.8,
		pieceOf("celestial", "Pawn").presentation.scale + " vs " + pieceOf("celestial", "Knight").presentation.scale);

	// --- The Kings are NOT in that order and must not have been swept into it ----------------------
	// A17: the King is anchored behind the party, sized off the battlefield's height. A scale under 1
	// on him would shrink a figure that is meant to loom.
	for (const side of SIDE_ARRAY) {
		const king = pieceOf(side, "King");
		check("the " + side + " King still stands at full size, anchored behind the row",
			king.presentation.scale === 1 && king.presentation.anchor === "back",
			JSON.stringify(king.presentation));
	}

	// --- Nothing else was resized by the same pass -------------------------------------------------
	// The trap this guards: "Never edit content tables with a greedy regex." A pattern anchored on the
	// wrong line would have written a scale onto unrelated enemies, and none of it would look like a bug.
	const golemArray = hc.enemyArray.filter((entry) => (entry.tagArray || []).indexOf("golem") >= 0 && entry.unlisted !== true);
	check("all twelve pieces are tagged golem", golemArray.length === 12, String(golemArray.length));
	// Read from the data, not from comment text: the ten pieces that fight (every colour's Pawn, Knight,
	// Bishop, Rook and Queen) each carry their own height, and the pieces do not all share one.
	{
		const fighterArray = SIDE_ARRAY.flatMap((side) => PIECE_ORDER.filter((piece) => piece !== "King").map((piece) => side + piece));
		const scaleArray = fighterArray.map((index) => {
			const definition = hc.findDefinition(hc.enemyArray, index);
			return definition == null || definition.presentation == null ? null : definition.presentation.scale;
		});
		check("the sizing pass gave all ten fighting pieces a height", fighterArray.length === 10 &&
			scaleArray.every((scale) => typeof scale === "number" && scale > 0),
			fighterArray.filter((index, at) => typeof scaleArray[at] !== "number").join(", "));
		check("and the pieces do not all stand at one height", new Set(scaleArray).size > 1, scaleArray.join(", "));
	}

	// --- The plate follows the figure down (A21) ---------------------------------------------------
	// > Not only to have smaller characters have their nameplate lower, but also to exaggerate the
	// > stepping more.
	// The art wrap scales from the feet, so a Pawn at 0.68 stands a third shorter; a plate pinned to a
	// fixed share of the frame would then float above its head.
	check("the plate multiplier is a function the suite can see", typeof hc.vitalsScaleFor === "function");
	check("the follow amount is a tuning entry", typeof hc.tuning.layout.vitalsFollowScale === "number");
	check("a fighter with no scale does not move its plate",
		hc.vitalsScaleFor(1) === 1 && hc.vitalsScaleFor(null) === 1);
	check("a Pawn brings its plate down by exactly its own scale",
		hc.vitalsScaleFor(pieceOf("celestial", "Pawn").presentation.scale) === pieceOf("celestial", "Pawn").presentation.scale);

	// Falsification: if the multiplier were hardcoded, zeroing the knob would not restore the old plate.
	{
		const restore = hc.tuning.layout.vitalsFollowScale;
		hc.tuning.layout.vitalsFollowScale = 0;
		check("zeroing the knob restores the fixed plate every fighter had before A18",
			[1, 0.95, 0.82, 0.68].every((scale) => hc.vitalsScaleFor(scale) === 1));
		hc.tuning.layout.vitalsFollowScale = restore;
		check("and putting it back makes the plate follow again", hc.vitalsScaleFor(0.68) === 0.68);
	}

	// --- The seams, read from source ---------------------------------------------------------------
	{
		const combat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
		check("the fighter element carries the plate multiplier",
			/vitalsScaleStyle\(entity\.placement\)/.test(combat));
		// It has to be on the FIGHTER, not the art wrap, or the vitals could not inherit it.
		const styleFn = combat.slice(combat.indexOf("honeycomb.combatScene.vitalsScaleStyle = function"),
			combat.indexOf("honeycomb.combatScene.placementStyle = function"));
		check("and nothing is emitted for a fighter standing at full size",
			/followed == 1 \? "" :/.test(styleFn));

		const css = fs.readFileSync(path.join(ROOT, "..", "css", "honeycomb.css"), "utf8");
		const vitalsCount = (css.match(/var\(--hc-vitals-bottom, 24%\) \* var\(--hcVitalsScale, 1\)/g) || []).length;
		check("all three plate rules multiply by it -- the base and both staggers",
			vitalsCount === 3, String(vitalsCount));
		check("no plate rule reads the bare bottom any more",
			/bottom: var\(--hc-vitals-bottom, 24%\);/.test(css) === false);
	}
}

console.log("\n[108] Session 43 -- a front-facing drawing is never mirrored (Noodle: \"Why are they backwards?\")");
{
	const hc = newEngine();

	// The report, twice over:
	// > Enemies are facing away from me, why are they mirrored on the enemy side?   (FEEDBACK-01 B)
	// > Why are they backwards?                                                     (session 43)
	// Session 36 answered the first by mirroring only a DISPLACED combatant. That is correct for art
	// drawn in profile and wrong for art drawn facing the viewer -- and every drawing in this project
	// faces the viewer. The Chessmaster's pieces are enemy-table entities standing on the ALLY side, so
	// they were displaced by construction and mirrored in every fight they ever appeared in.
	check("whether a drawing is in profile is asked, not assumed", typeof hc.art.sideFacingArt === "function");

	// A summoned piece: an enemy definition standing with the party.
	const asAlly = (enemyIndex) => ({ enemyIndex: enemyIndex, side: "ally", instanceId: "test-" + enemyIndex });
	const asEnemy = (enemyIndex) => ({ enemyIndex: enemyIndex, side: "enemy", instanceId: "test-" + enemyIndex });

	check("a summoned Pawn is NOT mirrored, because its drawing faces the viewer",
		hc.art.spriteFlipped(asAlly("celestialPawn")) === false);
	// REVERSED session 57 (Noodle: "the enemies are backwards"). The set is drawn facing right, into the
	// fight from HER line, so fought on the enemy line it faced away from the party. drawnForSide: "ally".
	check("but one fought on the enemy side IS mirrored, to face the party",
		hc.art.spriteFlipped(asEnemy("celestialPawn")) === true);
	for (const piece of ["infernalPawn", "infernalKnight", "infernalBishop", "infernalRook", "infernalQueen",
		"celestialPawn", "celestialKnight", "celestialBishop", "celestialRook", "celestialQueen",
		"gauntletCelestialQueen", "gauntletInfernalQueen"]) {
		check("every piece fought in the gauntlet faces the party: " + piece, hc.art.spriteFlipped(asEnemy(piece)) === true);
	}
	check("an ordinary enemy on the enemy line is still not mirrored", hc.art.spriteFlipped(asEnemy("sporeling")) === false);
	for (const piece of ["celestialKnight", "celestialRook", "celestialBishop", "celestialQueen", "infernalPawn"]) {
		check("nor is a summoned " + piece, hc.art.spriteFlipped(asAlly(piece)) === false);
	}

	// Nothing in the shipped content is drawn in profile, so nothing should mirror anywhere. This is the
	// check that fails the day a side-facing set is added without the field being considered.
	const profileArray = hc.enemyArray.concat(hc.characterArray).filter((entry) => entry.sideFacingArt === true);
	check("no shipped definition claims side-facing art yet", profileArray.length === 0,
		profileArray.map((entry) => entry.index).join(", "));

	// --- The design space is kept: the mirror still works when the art earns it --------------------
	// Marking a definition side-facing brings the displacement rule back for that entry alone.
	{
		const pawn = hc.findDefinition(hc.enemyArray, "sporeling");
		pawn.sideFacingArt = true;
		check("a side-facing piece IS mirrored when it stands on the wrong side",
			hc.art.spriteFlipped(asAlly("sporeling")) === true);
		check("but not when it stands where it belongs",
			hc.art.spriteFlipped(asEnemy("sporeling")) === false);
		check("and its neighbours are unaffected",
			hc.art.spriteFlipped(asAlly("celestialRook")) === false);
		// The master switch still turns the whole rule off.
		hc.art.mirrorWhenDisplaced = false;
		check("the master switch still disables mirroring outright",
			hc.art.spriteFlipped(asAlly("sporeling")) === false);
		hc.art.mirrorWhenDisplaced = true;
		delete pawn.sideFacingArt;
		check("and reverting the field reverts the mirror",
			hc.art.spriteFlipped(asAlly("sporeling")) === false);
	}

	// --- Falsification -----------------------------------------------------------------------------
	// Prove the old rule is what produced the bug, so this block is testing the fix and not the weather.
	check("the OLD displacement-only rule would have mirrored every summoned piece",
		["celestialPawn", "celestialKnight", "infernalRook"].every((enemyIndex) => {
			const entity = asAlly(enemyIndex);
			const standingOn = entity.side === "enemy" ? "enemy" : "ally";
			return standingOn !== hc.art.nativeSideFor(entity);
		}));
}

console.log("\n[109] Session 43 -- A25 groundwork: an aimed ability obeys the rules a dragged card obeys");
{
	const hc = newEngine();

	// --- The mode that started it ------------------------------------------------------------------
	// `allyOther` carries excludeSelf, and its own comment promises it "keeps the source off the
	// legal-target list". Only the card path honoured that. Cinder's Marshal's Call is the one shipped
	// ability using the mode, so she was offered as a legal target for her own ability and it resolved
	// to nobody -- spending the charge with no feedback.
	const allyOther = hc.targetModeDefinition("allyOther");
	check("allyOther still excludes its user", allyOther != null && allyOther.excludeSelf === true);
	const marshal = hc.findDefinition(hc.abilityArray, "cinderMarshalsCall");
	check("Marshal's Call still uses it", marshal != null && marshal.targetMode === "allyOther",
		marshal == null ? "missing" : marshal.targetMode);
	// If the mode resolves to nothing when aimed at its own user, offering that user is a wasted charge.
	{
		const context = hc.newEffectContext({ combat: null });
		const source = { instanceId: "who" };
		context.source = source;
		context.target = source;
		check("aimed at its own user the mode resolves to nobody, which is why offering it is a bug",
			allyOther.resolve({}, context).length === 0);
	}

	// --- The legality check now asks what the card path asks ----------------------------------------
	// isLegalAbilityTarget reads combatScene, which lives in a scene file the suite does not load, so
	// the four checks are asserted against the SOURCE. Each pattern names one question that was missing.
	{
		const combat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
		check("the aim path asks the shared predicate", /targetModeAllows\(pending\.targetMode/.test(combat));
		check("the card's drop test asks it too", /targetModeAllows\(resolved\.targetMode/.test(combat));
		check("and so does the card's legal-target marking",
			(combat.match(/honeycomb\.targetModeAllows\(/g) || []).length === 3,
			String((combat.match(/honeycomb\.targetModeAllows\(/g) || []).length));
		check("the old side-only ability check is gone", /isLegalAbilityTarget/.test(combat) === false);

		// --- The golem Move row is no longer collateral of closing an ability menu ------------------
		// renderGolemMove borrows .hcAbilityMenu for its chrome, so an unqualified sweep removed every
		// piece's Move control from the board.
		const closeAt = combat.indexOf("honeycomb.combatScene.closeAbilityMenu = function");
		const close = combat.slice(closeAt, closeAt + 700);
		check("closing an ability menu spares the golem Move rows",
			/querySelectorAll\("\.hcAbilityMenu:not\(\.hcGolemMove\)"\)/.test(close), close.slice(0, 200));
		check("and no unqualified .hcAbilityMenu sweep is left anywhere",
			/querySelectorAll\("\.hcAbilityMenu"\)/.test(combat) === false);
		check("and the Move row is still built on that shared chrome, so the exclusion is load-bearing",
			/"hcAbilityMenu hcGolemMove"/.test(combat));
	}

	// --- The predicate itself, exercised rather than read ------------------------------------------
	// It lives in honeycomb-effects.js beside the modes it reads, NOT on combatScene: a scene file is
	// invisible to this suite, and something three interactions depend on has to be checkable.
	check("the shared predicate is reachable", typeof hc.targetModeAllows === "function");
	{
		const ally = { instanceId: "a1", side: "ally" };
		const mate = { instanceId: "a2", side: "ally" };
		const foe = { instanceId: "e1", side: "enemy" };
		const fallen = { instanceId: "a3", side: "ally", downed: true };

		check("allyOther accepts another ally", hc.targetModeAllows("allyOther", ally.instanceId, "ally", mate) === true);
		check("allyOther REFUSES its own user -- the Cinder bug, asserted",
			hc.targetModeAllows("allyOther", ally.instanceId, "ally", ally) === false);
		check("allyOther refuses an enemy", hc.targetModeAllows("allyOther", ally.instanceId, "ally", foe) === false);
		check("nothing accepts a downed fighter", hc.targetModeAllows("allyOther", ally.instanceId, "ally", fallen) === false);
		check("and nothing accepts nobody", hc.targetModeAllows("allyOther", ally.instanceId, "ally", null) === false);
		check("an enemy mode refuses an ally", hc.targetModeAllows("enemy", ally.instanceId, "ally", mate) === false);
		check("and accepts an enemy", hc.targetModeAllows("enemy", ally.instanceId, "ally", foe) === true);
		// A mode's side is relative to its USER, so an enemy aiming "enemy" means the party.
		check("a mode's side is relative to its user", hc.targetModeAllows("enemy", foe.instanceId, "enemy", mate) === true);
		// Falsification: without the excludeSelf branch, allyOther would accept its own user, because
		// the side check alone cannot tell them apart.
		check("the side check alone could not have caught it",
			ally.side === mate.side && hc.targetModeDefinition("allyOther").excludeSelf === true);
	}

	// --- A11: nothing on the ability path repaints the board any more -------------------------------
	// > Every time I click the ability menu shrinks and expands again, like if my mouse suddenly
	// > vanished for a single frame (thus they are no longer hovered) and then returned
	// `repaint` is `root.innerHTML = render()`. Every fighter element is destroyed and rebuilt, so the
	// depth-focus :hover rule stops applying until the pointer moves. Two places did it: opening the
	// medallion menu, and entering an ability aim. Both now update in place.
	{
		const combat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
		const medallionAt = combat.indexOf("honeycomb.combatScene.onMedallionClick = function");
		const medallion = combat.slice(medallionAt, medallionAt + 900);
		check("pressing the medallion no longer repaints the board",
			/repaint\(\)/.test(medallion) === false, medallion.slice(0, 200));
		check("it opens the menu in place instead", /openAbilityMenu\(memberInstanceId\)/.test(medallion));
		check("and the in-place opener exists", /honeycomb\.combatScene\.openAbilityMenu = function/.test(combat));

		const pickAt = combat.indexOf("honeycomb.combatScene.onAbilityPick = function");
		const pick = combat.slice(pickAt, combat.indexOf("honeycomb.combatScene.isLegalAimTarget", pickAt));
		check("entering an ability aim no longer repaints either", /repaint\(\)/.test(pick) === false);
		check("it marks the targets in place", /beginAim\(\{/.test(pick));

		// Entering an aim marks in place; COMMITTING is allowed to repaint, because the board really
		// changed. Asserting that keeps a later session from "fixing" the wrong one.
		const commitAt = combat.indexOf("honeycomb.combatScene.commitActivationAim = function");
		check("committing a piece's Move still repaints, because the line really moved",
			/repaint\(\)/.test(combat.slice(commitAt, commitAt + 700)));
	}

	// --- The pieces the unified aim mode will need already exist ------------------------------------
	// A25 turns the Knight's open slot list into a button that aims at an ALLY. The conversion from a
	// picked fighter to the rank `moveEntityToRank` wants is `entityRank`, which is already the function
	// renderGolemMove uses to grey out the slot a piece is standing in.
	check("a fighter can be converted to the rank a move needs", typeof hc.entityRank === "function");
	check("and the move itself takes that rank", typeof hc.moveEntityToRank === "function");
	check("the Knight still declares a rank pick to convert",
		["celestialKnight", "infernalKnight"].every((index) => {
			const knight = hc.findDefinition(hc.enemyArray, index);
			return knight != null && knight.allyActivation != null && knight.allyActivation.pick === "rank";
		}));
}

console.log("\n[110] Session 43 -- A25 stage 2: an aim is DRAGGED, on the card's machinery");
{
	const hc = newEngine();

	// --- The preview must agree with the move, or the board lies before you let go -----------------
	// A dragged card shows where it would move its owner; a dragged aim shows the same for the piece it
	// is moving. previewMoveToRank mirrors moveEntityToRank's splice -- backward lands AFTER the anchor,
	// forward lands BEFORE it -- and this asserts the two agree by running both.
	check("the preview exists", typeof hc.previewMoveToRank === "function");
	{
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 42);
		hc.combat.begin("loneSporeling", {});
		const combat = hc.state.run.combat;
		for (const piece of ["celestialKnight", "celestialPawn", "celestialRook"]) {
			hc.summonCombatant({ side: "ally", enemyIndex: piece }, { combat: combat });
		}
		const living = () => hc.livingEntityArray("ally", combat).map((e) => e.instanceId);
		check("four allies stand in the row", living().length === 4, living().join(","));

		// Every from/to pair the Knight could be dragged to, checked against the real move.
		let agreed = 0;
		let disagreed = [];
		for (let targetRank = 0; targetRank < living().length; targetRank++) {
			// Fresh state each time: rebuild the run so the order is the same at the start of every pair.
			hc.state = hc.newProfile();
			hc.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 42);
			hc.combat.begin("loneSporeling", {});
			const fresh = hc.state.run.combat;
			for (const piece of ["celestialKnight", "celestialPawn", "celestialRook"]) {
				hc.summonCombatant({ side: "ally", enemyIndex: piece }, { combat: fresh });
			}
			const knight = hc.state.run.partyArray.find((e) => e.enemyIndex === "celestialKnight");
			const predicted = hc.previewMoveToRank(knight, targetRank, fresh);
			const moved = hc.moveEntityToRank(knight, targetRank, hc.newEffectContext({ combat: fresh, source: knight }));
			const actual = hc.livingEntityArray("ally", fresh).map((e) => e.instanceId);
			if (predicted == null) {
				// No preview means no move; the two must agree about that too.
				if (moved === false) agreed++; else disagreed.push("rank " + targetRank + ": no preview but it moved");
				continue;
			}
			if (moved === true && predicted.orderIdArray.join(",") === actual.join(",")) agreed++;
			else disagreed.push("rank " + targetRank + ": predicted " + predicted.orderIdArray.join(",") + " got " + actual.join(","));
		}
		check("the preview matches the move at every rank", disagreed.length === 0, disagreed.join(" | "));
		check("and every rank was actually exercised", agreed === 4, String(agreed));
	}

	// --- The threshold is a tuning entry, in honeycomb pixels ---------------------------------------
	// A card's threshold is a share of the CARD's height. An aim is dragged from a small button on a
	// nameplate, so a share of that would be a few pixels and every press would become a drag.
	check("the aim drag threshold is a tuning entry",
		typeof hc.tuning.combat.aimDragThresholdPixels === "number" && hc.tuning.combat.aimDragThresholdPixels > 0,
		String(hc.tuning.combat.aimDragThresholdPixels));
	check("and it is not just the card's threshold reused",
		hc.tuning.combat.aimDragThresholdPixels !== hc.tuning.combat.dragPlayThresholdPercent);

	// --- The gesture, read from source (scene file) --------------------------------------------------
	{
		const combat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
		for (const fn of ["onAimPointerDown", "onAimPointerMove", "onAimPointerUp", "endAimDrag",
			"aimTargetAtPoint", "setAimDragTarget", "showAimMovePreview", "aimDescriptorFor"]) {
			check("the drag has " + fn, combat.indexOf("honeycomb.combatScene." + fn + " = function") >= 0);
		}
		// THE JIGGY RULE (REQUIREMENTS section 8): jiggy.js holds permanent document-level mousemove /
		// mouseup / touchmove / touchend / wheel handlers. Honeycomb adds NOTHING to the document, so
		// the aim drag must capture on its own control exactly as the card drag does.
		const downAt = combat.indexOf("honeycomb.combatScene.onAimPointerDown = function");
		const down = combat.slice(downAt, combat.indexOf("honeycomb.combatScene.onAimPointerMove = function"));
		check("the aim drag captures the pointer on its own control", /setPointerCapture\(event\.pointerId\)/.test(down));
		check("and listens on that control, never the document",
			/control\.addEventListener/.test(down) && /document\.addEventListener/.test(down) === false);
		check("no honeycomb file adds a document-level pointer or mouse listener",
			/document\.addEventListener\(\s*"(pointer|mouse|touch)/.test(combat) === false);

		// The controls are draggable, and an ability that needs no target is not.
		check("a picking activation carries a pointerdown", /activation\.pick != null\s*\n?\s*\? ' onpointerdown=/.test(combat) ||
			/onAimPointerDown\(event, \\'activation\\'/.test(combat) || /onAimPointerDown\(event, 'activation'/.test(combat));
		check("an ability row is draggable only when it picks a target",
			/var draggable = honeycomb\.targetModeRequiresPick\(ability\.definition\.targetMode\) == true/.test(combat));

		// The arrow serves both paths now.
		check("the aiming line takes whatever is doing the aiming",
			/drawTargetArrow = function \(clientX, clientY, fromElement, targetId\)/.test(combat));
		check("and the aim draws it from the FIGURE, not the fighter's whole column",
			/getElementsByClassName\("hcFighterArt"\)\[0\]/.test(combat));

		// The single-shot click suppression. A sticky flag silently eats the next press.
		const upAt = combat.indexOf("honeycomb.combatScene.onAimPointerUp = function");
		const up = combat.slice(upAt, combat.indexOf("honeycomb.combatScene.endAimDrag = function"));
		check("a committed drag suppresses exactly one click",
			/aimDragSuppressClick = true/.test(up) && /setTimeout\(function \(\) \{ honeycomb\.combatScene\.aimDragSuppressClick = false; \}, 0\)/.test(up));
		// It must NOT go through honeycomb.duration: the player's speed setting deciding whether a click
		// is eaten would be a genuinely baffling bug.
		check("and that yield is not a play-speed duration", /honeycomb\.duration\(0\)/.test(up) === false);
	}
}

console.log("\n[111] Session 44 -- enemy_overhaul E1/E2/E3/E4/E6: the roster is recast, and the Lust lift is measured");
{
	const hc = newEngine();

	// RETOOL, DON'T RELOCATE. The law the whole pathway runs on: an enemy keeps its `index`, its act and
	// its encounters, and only who it IS changes. Indices are also what a telegraphed move and a
	// mid-combat save store, so a rename that reached them would strand saves.
	// The Scrap Salvager is the one deliberate exception to "and its role": Noodle promoted him to elite
	// this session, which is a stat change and is pinned here as one.
	const recastArray = [
		{ index: "cordycepsHusk", name: "Sporeguard", role: "soldier", health: 32 },
		{ index: "gardener", name: "Earthstar", role: "support", health: 26 },
		{ index: "sage", name: "Bracket Elder", role: "caster", health: 30 },
		{ index: "moldshaper", name: "Witch's Butter", role: "support", health: 28 },
		{ index: "alchemist", name: "Spore Alchemist", role: "support", health: 28 },
		{ index: "siltCrawler", name: "Shieldcap", role: "minion", health: 36 },
		{ index: "mireEel", name: "Cagecap", role: "striker", health: 44 },
		{ index: "bogToad", name: "Bolete Hook", role: "tank", health: 84 },
		{ index: "lanternJelly", name: "Foxfire", role: "caster", health: 52 },
		{ index: "drownedSalvager", name: "Scrap Salvager", role: "elite", health: 135 },
	];
	for (const expected of recastArray) {
		const enemy = hc.findDefinition(hc.enemyArray, expected.index);
		check(`${expected.index} is still in the table under its own index`, enemy != null);
		if (enemy == null) continue;
		check(`  and reads "${expected.name}"`, enemy.name === expected.name, `reads "${enemy.name}"`);
		check(`  and keeps role ${expected.role} and ${expected.health} health`,
			enemy.role === expected.role && enemy.baseHealth === expected.health,
			`${enemy.role} / ${enemy.baseHealth}`);
	}

	// E6: the husk's species tag. `undead` was the tone rule's blocked idea wearing a tag.
	const sporeguard = hc.findDefinition(hc.enemyArray, "cordycepsHusk");
	check("the Sporeguard is a plant, not undead",
		hc.definitionHasTag(sporeguard, "plant") === true && hc.definitionHasTag(sporeguard, "undead") === false);
	// E2: four of the five recast are myconids; the Salvager is deliberately NOT, because his being an
	// Act 2 intruder is the point (story bible section 4, and enemy_overhaul E4).
	for (const index of ["siltCrawler", "mireEel", "bogToad", "lanternJelly"]) {
		check(`${index} is tagged plant`, hc.definitionHasTag(hc.findDefinition(hc.enemyArray, index), "plant") === true);
	}
	check("the Scrap Salvager stays a kobold -- he is the Act 2 intruder, not a myconid",
		hc.definitionHasTag(hc.findDefinition(hc.enemyArray, "drownedSalvager"), "kobold") === true);

	// THE SALVAGER'S PROMOTION REACHES THE ENCOUNTER TABLE. An elite that is still fielded three times a
	// run as a normal body is a promotion in name only, and it would break the elite tier's budgets.
	const salvagerEncounterArray = hc.encounterArray.filter((encounter) =>
		(encounter.enemyIndexArray || []).indexOf("drownedSalvager") >= 0);
	check("the Scrap Salvager appears only in elite encounters now",
		salvagerEncounterArray.length > 0 && salvagerEncounterArray.every((encounter) => encounter.isElite === true),
		salvagerEncounterArray.map((e) => e.index + (e.isElite ? " (elite)" : " (NORMAL)")).join(", "));
	check("  and he is fielded at both middle and late, like the other two elites",
		["middle", "late"].every((tier) => salvagerEncounterArray.some((encounter) => encounter.tier === tier)));

	// THE TONE RULE, as a string check. "No death, no gore. Nothing in the catacombs is a corpse or
	// rots", and the cordyceps zombie is its named blocked idea. The dropped water theme goes with it.
	// ENEMY-SIDE CONTENT ONLY. The tone rule is about what lives in the catacombs, not about the
	// party: Nettle is a necromancer and her "Rot Garden" is hers to be called that. Statuses are
	// therefore narrowed to the ones an enemy actually carries or applies -- scanning honeycomb.statusArray
	// whole reported her card and was wrong to.
	const bannedArray = ["cordyceps", "husk", "rot ", "rotting", "drowned", "corpse", "bog ", "mire", "silt"];
	const nameProblemArray = [];
	function scanName(where, name) {
		if (name == null) return;
		const lower = String(name).toLowerCase() + " ";
		for (const banned of bannedArray) if (lower.indexOf(banned) >= 0) nameProblemArray.push(`${where} "${name}" contains "${banned.trim()}"`);
	}
	const enemyStatusSet = new Set();
	for (const enemy of hc.enemyArray) {
		for (const starting of enemy.startingStatusArray || []) enemyStatusSet.add(starting.status);
	}
	for (const card of hc.cardArray) {
		if (card.rarity !== "enemy") continue;
		(function walk(effectArray) {
			for (const effect of effectArray || []) {
				if (effect == null) continue;
				if (effect.index === "applyStatus" && effect.status != null) enemyStatusSet.add(effect.status);
				walk(effect.effectArray);
			}
		})(card.effectArray);
	}
	for (const enemy of hc.enemyArray) scanName("enemy", enemy.name);
	for (const encounter of hc.encounterArray) scanName("encounter", encounter.name);
	for (const card of hc.cardArray) if (card.rarity === "enemy") scanName("move", card.name);
	for (const statusIndex of enemyStatusSet) {
		const status = hc.findDefinition(hc.statusArray, statusIndex);
		if (status != null) scanName("status", status.name);
	}
	check("no enemy, encounter, move or status name carries a blocked word or the dropped water theme",
		nameProblemArray.length === 0, nameProblemArray.join("\n          "));

	// ---- E3: THE MEASURE OF WHETHER THE OVERHAUL WORKED -------------------------------------------
	// The same walk !designDocs/honeycomb/tools/lust-share.js makes. Kept here as well as there because
	// a tool nobody runs is not a check.
	const LUST_TAG_ARRAY = hc.cardTagArray.filter((tag) => tag.lustTag === true).map((tag) => tag.index);
	function amounts(card) {
		let damage = 0, lust = 0;
		(function walk(effectArray, multiplier) {
			for (const effect of effectArray || []) {
				if (effect == null || effect.targetOverride === "self") continue;
				const amount = typeof effect.amount === "number" ? effect.amount : 0;
				if (effect.index === "damage" || effect.index === "damageIgnoringTemporary") damage += amount * multiplier;
				else if (effect.index === "lust") lust += amount * multiplier;
				else if (effect.index === "repeat") walk(effect.effectArray, multiplier * (effect.times || 1));
			}
		})(card.effectArray, 1);
		return { damage, lust };
	}
	function moveIndexArray(enemy) {
		const seen = new Set();
		for (const move of enemy.moveArray || []) if (move.card != null) seen.add(move.card);
		for (const phase of enemy.phaseArray || []) {
			for (const move of phase.moveArray || []) seen.add(typeof move === "string" ? move : move.card);
		}
		return [...seen];
	}

	const bestiaryArray = hc.enemyArray.filter((enemy) => hc.definitionHasTag(enemy, "golem") !== true);
	let moveCount = 0, lustMoveCount = 0;
	const tagCount = {}, silentArray = [], untaggedArray = [];
	for (const enemy of bestiaryArray) {
		let enemyLustMoves = 0;
		for (const cardIndex of moveIndexArray(enemy)) {
			const card = hc.findDefinition(hc.cardArray, cardIndex);
			if (card == null) continue;
			moveCount++;
			if (amounts(card).lust <= 0) continue;
			lustMoveCount++;
			enemyLustMoves++;
			// A lust move with no lust tag teaches the between-run ledger nothing, so it does not count.
			const tagArray = (card.tagArray || []).filter((tag) => LUST_TAG_ARRAY.indexOf(tag) >= 0);
			if (tagArray.length === 0) untaggedArray.push(`${enemy.index} / ${cardIndex}`);
			for (const tag of tagArray) tagCount[tag] = (tagCount[tag] || 0) + 1;
		}
		if (enemyLustMoves === 0) silentArray.push(enemy.index);
	}
	const share = moveCount === 0 ? 0 : lustMoveCount / moveCount;
	// The target enemy_overhaul/CATCH-UP.md sets: "roughly a quarter to a third of enemy moves".
	check(`Lust share is a quarter to a third of enemy moves (${lustMoveCount}/${moveCount} = ${(100 * share).toFixed(1)}%)`,
		share >= 0.25 && share <= 0.34);
	check("no enemy Lust move is untagged", untaggedArray.length === 0, untaggedArray.join(", "));

	// THE TWO DELIBERATE SILENCES, pinned so a later session cannot quietly add a third. Act1-A is the
	// sub-act Noodle wrote as "much less focus on lust", and the Shieldcap and the Bolete Hook are the
	// two bodies it fields most -- a tag on either is what made Restraint read as the sub-act's theme,
	// which is an identity Act1-B (venom) and Act1-C (charm) are supposed to own instead.
	check("exactly two enemies teach no lust tag, and they are Act1-A's two most-fielded bodies",
		silentArray.length === 2 && silentArray.indexOf("siltCrawler") >= 0 && silentArray.indexOf("bogToad") >= 0,
		silentArray.join(", "));

	// THE ACT 1 MIX LAW. The Mechanical Bible section 5 gives Act 1 "encounters with enemy lineups that
	// don't all hone in on a particular area" and reserves lineups that DO for Act 2. A roster where one
	// lust tag dominates cannot produce mixed lineups, and it also pre-spends the identity Act1-B and
	// Act1-C are supposed to arrive with. No tag may hold more than half the roster's lust moves.
	const biggestTag = Object.keys(tagCount).reduce((best, tag) => tagCount[tag] > (tagCount[best] || 0) ? tag : best, "");
	check(`no single lust tag dominates the roster (${biggestTag} holds ${tagCount[biggestTag]} of ${lustMoveCount})`,
		tagCount[biggestTag] <= lustMoveCount / 2,
		JSON.stringify(tagCount));
	// And all four live tags are actually taught, so the ledger has something to record in each column.
	for (const tag of ["venom", "restraint", "charm", "exposure"]) {
		check(`  ${tag} is taught by at least two enemy moves`, (tagCount[tag] || 0) >= 2, String(tagCount[tag] || 0));
	}
	// Torment stays at zero deliberately: a fifth tag costs 21 authored scenes, and whether it survives
	// the cut at all is lust_events/ B20's decision, not this folder's. See INFERENCES I4.
	check("Torment is still on no enemy move, deliberately", (tagCount.torment || 0) === 0);

	// ---- THE LIFT IS THREAT-NEUTRAL BY CONSTRUCTION (INFERENCES I3) -------------------------------
	// Numbers are not in scope for enemy_overhaul, and the budget tools count Lust AS damage. So a
	// converted move's damage plus its Lust must still equal what its damage alone used to be. Without
	// this check, "add some Lust" is an unreviewed way to make an enemy hit harder.
	const conversionArray = [
		{ card: "puffcapBurst", total: 7, tag: "venom" },
		{ card: "alchemistBrew", total: 2, tag: "charm" },
		{ card: "sentinelBash", total: 10, tag: "restraint" },
		{ card: "championThrust", total: 12, tag: "exposure" },
		{ card: "headGardenerWhip", total: 12, tag: "restraint" },
		{ card: "juggernautCrush", total: 18, tag: "restraint" },
	];
	for (const expected of conversionArray) {
		const card = hc.findDefinition(hc.cardArray, expected.card);
		const pair = card == null ? { damage: -1, lust: 0 } : amounts(card);
		check(`${expected.card} converted rather than added: ${pair.damage} damage + ${pair.lust} Lust = ${expected.total}`,
			pair.damage + pair.lust === expected.total && pair.lust > 0);
		check(`  and it teaches ${expected.tag}`, card != null && (card.tagArray || []).indexOf(expected.tag) >= 0);
	}
	// Withering Bloom is the fifth conversion and the only one paid for in Poison rather than damage:
	// Poison 3 costs 6 as it ticks down, Poison 2 costs 3, and 3 Lust makes up the difference exactly.
	const withering = hc.findDefinition(hc.cardArray, "sageWithering");
	const poisonStacks = (withering.effectArray || []).filter((e) => e.index === "applyStatus" && e.status === "poison")
		.reduce((sum, e) => sum + e.stacks, 0);
	check("Withering Bloom traded one Poison stack for three Lust, which is exactly threat-neutral",
		poisonStacks === 2 && amounts(withering).lust === 3);

	// The ADDITIONS went into slack their enemy already had. Named here so a later session that tightens
	// a budget knows which ones to look at first.
	for (const cardIndex of ["gardenerSow", "moldshaperVeil", "scavengerFumes", "headGardenerSnare", "tallyAudit"]) {
		const card = hc.findDefinition(hc.cardArray, cardIndex);
		check(`${cardIndex} carries the Lust it was given`, card != null && amounts(card).lust > 0);
	}
	// And the two that were taken back OUT deal none, which is the whole of Act1-A's low-lust brief.
	for (const cardIndex of ["crawlerScuttle", "toadTongue"]) {
		const card = hc.findDefinition(hc.cardArray, cardIndex);
		check(`${cardIndex} deals no Lust -- Act1-A is the low-lust sub-act`, card != null && amounts(card).lust === 0);
	}

	// ---- NAMES ------------------------------------------------------------------------------------
	// Story bible section 8: "Card names come from biological, structural or mechanical ideas, not from
	// what the card does to a health bar." The renames that named a hit rather than a thing were redone.
	const nameArray = [
		{ card: "gardenerSpade", name: "Stiff Ray" }, { card: "crawlerPinch", name: "Billhook" },
		{ card: "crawlerScuttle", name: "Pavise" }, { card: "eelBite", name: "Spur" },
		{ card: "toadSlam", name: "Shoulder" }, { card: "alchemistBrew", name: "Sweet Vapour" },
		{ card: "jellyPulse", name: "Gleam" },
	];
	for (const expected of nameArray) {
		check(`${expected.card} is named for a thing, not a hit: "${expected.name}"`,
			hc.findDefinition(hc.cardArray, expected.card).name === expected.name,
			hc.findDefinition(hc.cardArray, expected.card).name);
	}

	// A MISSING VERB THE LIFT EXPOSED. Two of the rewritten moves hand-write their prose, so they mark
	// their Lust as "{lust:4}" the way every hand-written card marks its damage. honeycomb.describeAmount
	// has always understood the kind -- it runs it through previewedLust -- but "lust" was absent from
	// the allowlist in honeycomb.cardTextTokenKindArray, so the token fell through to the unknown-kind
	// path and printed a flat number while the generated text beside it previewed the weakness.
	check("lust is a card-text token kind, so hand-written Lust previews like generated Lust",
		hc.cardTextTokenKindArray.indexOf("lust") >= 0);
	for (const cardIndex of ["puffcapBurst", "salvagerSnare"]) {
		const rendered = hc.cardText(hc.findDefinition(hc.cardArray, cardIndex), null, false);
		check(`  ${cardIndex} prints its Lust as a number, not as a token`,
			/\{lust:/.test(rendered) === false && /\d+ Lust/.test(rendered), rendered);
	}
}
// >>> LANE E7 | route | suite block >>>
// Inserted ABOVE [112] rather than appended, so lane E7 and lane ANA never write at the same anchor
// (reference/LANES.md section 3). Block ORDER does not change what the suite checks.
console.log("\n[113] Session 45 -- enemy_overhaul E7 Stage 1: the second region is chosen by the boss, not by position");
{
	// The route table is the release switch, so every check below states the OFF state it was written
	// against and then proves it can fail by moving the table in memory.
	const OFF_COUNTED = ["upperCatacombs", "floodedVault"];

	// =============================================================== the table, and the lane contract
	{
		const hc = newEngine();
		const route = hc.tuning.map.route;
		check("tuning.map.route exists", route != null);
		check("  and carries the four contracted fields",
			typeof route.regionsPerRun === "number" && typeof route.defaultSecondRegion === "string" &&
			Array.isArray(route.byBossArray) && Array.isArray(route.overrideArray));
		check("  its default second region is a real region",
			hc.findDefinition(hc.regionArray, route.defaultSecondRegion) != null, route.defaultSecondRegion);
		// Every row must name a boss encounter that exists, or a route silently falls through to the
		// default and nobody finds out until a player reports a run going the wrong way.
		const strayArray = [];
		for (const row of route.byBossArray) {
			if (hc.findDefinition(hc.encounterArray, row.bossEncounterIndex) == null) strayArray.push("boss " + row.bossEncounterIndex);
			if (hc.findDefinition(hc.regionArray, row.regionIndex) == null) strayArray.push("region " + row.regionIndex);
		}
		check("every byBossArray row names a real boss and a real region", strayArray.length === 0, strayArray.join(", "));
		// overrideArray is E7's to CREATE and lane ANA's to fill: E7 ships it empty and ANA lands one row
		// for the gauntlet. So what is pinned is the row SHAPE, not the count -- a malformed row here
		// would route a run into nowhere.
		const badOverrideArray = [];
		for (const row of route.overrideArray) {
			if (hc.findDefinition(hc.relicArray, row.relicIndex) == null) badOverrideArray.push("relic " + row.relicIndex);
			if (hc.findDefinition(hc.regionArray, row.regionIndex) == null) badOverrideArray.push("region " + row.regionIndex);
		}
		check("every overrideArray row names a real relic and a real region", badOverrideArray.length === 0,
			badOverrideArray.join(", "));

		// POSITIONS ARE SAVE DATA. An encounter's regionIndexArray holds positions in regionArray, so
		// this order is the contract both lanes build against (LANES.md section 4).
		check("regionArray position 2 is flora", hc.regionArray[2] != null && hc.regionArray[2].index === "flora",
			hc.regionArray[2] == null ? "missing" : hc.regionArray[2].index);
		check("regionArray position 3 is pollenRoad", hc.regionArray[3] != null && hc.regionArray[3].index === "pollenRoad",
			hc.regionArray[3] == null ? "missing" : hc.regionArray[3].index);
		// Positions 0-3 are the contract; lane ANA appends its gauntlet at 4 and may add nothing before
		// it, so what is pinned is the PREFIX, not the length.
		check("  and nothing was inserted ahead of them",
			hc.regionArray[0].index === "upperCatacombs" && hc.regionArray[1].index === "floodedVault",
			hc.regionArray.map((region) => region.index).join());
	}

	// =============================================================== countedRegionArray
	{
		const hc = newEngine();
		const route = hc.tuning.map.route;
		// DERIVED, NOT HARDCODED. These checks were first written while the route table was still in its
		// staging state with every row pointed at the default, and they encoded that state as if it were
		// the rule. Switching the routes on then failed them for being right. What is invariant is the
		// DERIVATION: position 0, the default, and every byBossArray target -- and nothing else.
		const expectedArray = [];
		for (const index of [hc.regionArray[0].index, route.defaultSecondRegion].concat(route.byBossArray.map((row) => row.regionIndex))) {
			if (expectedArray.indexOf(index) < 0 && hc.findDefinition(hc.regionArray, index) != null) expectedArray.push(index);
		}
		check("countedRegionArray is position 0, the default, and every boss row's region",
			hc.map.countedRegionArray().join() === expectedArray.join(),
			hc.map.countedRegionArray().join() + " vs " + expectedArray.join());

		// FALSIFY, from whatever state ships: switching every route off must leave exactly the two the
		// game had before routes existed, and switching one back on must add exactly one.
		const shippedArray = route.byBossArray.map((row) => row.regionIndex);
		for (const row of route.byBossArray) row.regionIndex = route.defaultSecondRegion;
		check("  pointing every row at the default leaves exactly the two original regions",
			hc.map.countedRegionArray().join() === OFF_COUNTED.join(), hc.map.countedRegionArray().join());
		route.byBossArray[1].regionIndex = "flora";
		check("  and switching one row back on adds exactly that region",
			hc.map.countedRegionArray().join() === OFF_COUNTED.concat(["flora"]).join(), hc.map.countedRegionArray().join());
		for (let rowIndex = 0; rowIndex < route.byBossArray.length; rowIndex++) route.byBossArray[rowIndex].regionIndex = shippedArray[rowIndex];

		// A SECRET REGION IS NEVER COUNTED. Lane ANA's gauntlet is reached by a held relic and nothing
		// else; counting it would promise a place the player has no way of hearing about.
		const before = hc.map.countedRegionArray().join();
		route.overrideArray.push({ relicIndex: "ironSigil", regionIndex: "gauntletGallery" });
		check("a region only an overrideArray row names stays out of the count",
			hc.map.countedRegionArray().join() === before, hc.map.countedRegionArray().join());
		// And that holds for every override row the game actually ships, not just the planted one.
		const countedArray = hc.map.countedRegionArray();
		const leakedArray = route.overrideArray
			.filter((row) => route.byBossArray.every((boss) => boss.regionIndex !== row.regionIndex) && row.regionIndex !== route.defaultSecondRegion)
			.filter((row) => countedArray.indexOf(row.regionIndex) >= 0);
		check("  including every override row the game ships", leakedArray.length === 0,
			leakedArray.map((row) => row.regionIndex).join());

		// A row pointing at nothing is a content error, not a crash and not a phantom entry.
		route.byBossArray[0].regionIndex = "zzNotARegion";
		check("a row naming a region that does not exist is skipped rather than counted",
			hc.map.countedRegionArray().indexOf("zzNotARegion") < 0);
	}

	// The between-run ledger counts what is reachable, not how many rows the table has.
	{
		const hc = newEngine();
		const kind = hc.findDefinition(hc.discoveryKindArray, "region");
		check("the discovery ledger's region total is the counted set, not regionArray.length",
			kind.allIndexArray().join() === hc.map.countedRegionArray().join(), kind.allIndexArray().join());
		check("  which is fewer than the table holds", kind.allIndexArray().length < hc.regionArray.length,
			kind.allIndexArray().length + " of " + hc.regionArray.length);
	}

	// =============================================================== depth resolution, and old saves
	{
		const hc = newEngine();
		startRun(hc, 4501, DEFAULT_PARTY);
		const run = hc.state.run;

		check("depth 0 is always the first region", hc.map.regionIndexForDepth(run, 0) === "upperCatacombs");
		run.routeRegionIndex = "pollenRoad";
		check("  even for a run already carrying a route", hc.map.regionIndexForDepth(run, 0) === "upperCatacombs");

		// THE SAVE THAT MATTERS: every run in progress tonight was written before routeRegionIndex
		// existed. Reading as the default is what keeps it alive rather than stranding it.
		run.routeRegionIndex = null;
		check("a run carrying no route descends into the default", hc.map.regionIndexForDepth(run, 1) === "floodedVault");
		check("  and so does a run object that has never heard of routes", hc.map.regionIndexForDepth({}, 1) === "floodedVault");
		run.routeRegionIndex = "flora";
		check("a run carrying a route descends into it", hc.map.regionIndexForDepth(run, 1) === "flora");

		// End to end, through the generator the game actually calls.
		run.regionsCleared = 1;
		run.routeRegionIndex = null;
		check("generateRegion() on an old-shaped run builds the default second region",
			hc.map.generateRegion().regionIndex === "floodedVault");
		run.routeRegionIndex = "pollenRoad";
		check("generateRegion() on a routed run builds that route's region",
			hc.map.generateRegion().regionIndex === "pollenRoad");
		run.regionsCleared = 0;
		check("  and depth 0 still builds the first region regardless",
			hc.map.generateRegion().regionIndex === "upperCatacombs");
	}

	// =============================================================== resolution order
	{
		const hc = newEngine();
		startRun(hc, 4502, DEFAULT_PARTY);
		const run = hc.state.run;
		hc.map.generateRegion();

		// The boss is READ off the map, never re-rolled: the fight whose preview the player was shown is
		// the fight that decides where they go.
		check("the first map names a boss", hc.map.mapBossEncounterIndex(run.map) != null);
		const naturalArray = [];
		for (let seed = 4510; seed < 4530; seed++) {
			startRun(hc, seed, DEFAULT_PARTY);
			hc.map.generateRegion();
			const boss = hc.map.mapBossEncounterIndex(hc.state.run.map);
			if (hc.findDefinition(hc.encounterArray, boss) == null) naturalArray.push(String(boss));
			if (hc.findDefinition(hc.regionArray, hc.map.resolveRouteRegionIndex(hc.state.run)) == null) naturalArray.push("unresolvable " + boss);
		}
		check("every rolled first boss resolves to a real region", naturalArray.length === 0, naturalArray.join(", "));
	}
	{
		const hc = newEngine();
		startRun(hc, 4503, DEFAULT_PARTY);
		const run = hc.state.run;
		hc.map.generateRegion();
		// Stand a known boss on the map, which is what a run that beat that boss looks like at this moment.
		const standBoss = (encounterIndex) => {
			for (const row of run.map.rowArray) {
				for (const node of row) if (node.typeIndex === "boss") node.encounterIndex = encounterIndex;
			}
		};

		const rowFor = (bossIndex) => hc.tuning.map.route.byBossArray.filter((row) => row.bossEncounterIndex === bossIndex)[0];
		standBoss("gardenerGrove");
		check("the Head Gardener resolves to whatever her row says",
			hc.map.resolveRouteRegionIndex(run) === rowFor("gardenerGrove").regionIndex, hc.map.resolveRouteRegionIndex(run));
		// FALSIFY: it reads the row for the right reason only if MOVING the row moves the answer.
		const savedGardener = rowFor("gardenerGrove").regionIndex;
		rowFor("gardenerGrove").regionIndex = "pollenRoad";
		check("  and follows that row when it is moved",
			hc.map.resolveRouteRegionIndex(run) === "pollenRoad", hc.map.resolveRouteRegionIndex(run));
		rowFor("gardenerGrove").regionIndex = savedGardener;

		standBoss("matriarchLair");
		check("a different boss reads a different row",
			hc.map.resolveRouteRegionIndex(run) === rowFor("matriarchLair").regionIndex, hc.map.resolveRouteRegionIndex(run));
		check("  and the three Act1-1 bosses do not all lead to one place",
			new Set(hc.tuning.map.route.byBossArray.map((row) => row.regionIndex)).size > 1,
			hc.tuning.map.route.byBossArray.map((row) => row.regionIndex).join());
		standBoss("zzNotABoss");
		check("a boss the table does not name falls back to the default",
			hc.map.resolveRouteRegionIndex(run) === "floodedVault", hc.map.resolveRouteRegionIndex(run));

		// A HELD RELIC OUTRANKS THE BOSS. Lane ANA's gauntlet is reached this way and no other.
		standBoss("gardenerGrove");
		const withoutOverride = hc.map.resolveRouteRegionIndex(run);
		hc.tuning.map.route.overrideArray.push({ relicIndex: "zzRouteKey", regionIndex: "pollenRoad" });
		check("an override the run does not hold changes nothing",
			hc.map.resolveRouteRegionIndex(run) === withoutOverride, hc.map.resolveRouteRegionIndex(run));
		run.relicArray.push({ index: "zzRouteKey" });
		check("an override the run DOES hold outranks the boss",
			hc.map.resolveRouteRegionIndex(run) === "pollenRoad", hc.map.resolveRouteRegionIndex(run));
	}

	// =============================================================== descending records the route once
	{
		const hc = newEngine();
		hc.overlay.closeAll = () => {};
		hc.scene.go = () => {};
		startRun(hc, 4504, DEFAULT_PARTY);
		const run = hc.state.run;
		hc.map.generateRegion();
		for (const row of run.map.rowArray) {
			for (const node of row) if (node.typeIndex === "boss") node.encounterIndex = "gardenerGrove";
		}
		hc.tuning.map.route.byBossArray[1].regionIndex = "flora";

		check("a run carries no route before it descends", run.routeRegionIndex == null);
		hc.descendRegion();
		check("descending records the route the boss chose", run.routeRegionIndex === "flora", String(run.routeRegionIndex));
		check("  and lands the run in that region", run.map.regionIndex === "flora", run.map.regionIndex);
		check("  and counts the region as cleared", run.regionsCleared === 1);

		// Recorded ONCE. A second descent must not re-decide, or a reload could move a run's route.
		hc.tuning.map.route.byBossArray[1].regionIndex = "pollenRoad";
		hc.descendRegion();
		check("a later descent does not re-decide the route", run.routeRegionIndex === "flora", String(run.routeRegionIndex));
	}

	// =============================================================== the route survives a save
	{
		// A RUN IN PROGRESS IS SAVE DATA. The route is written once and then has to survive every
		// reload for the rest of the run, and the saves that existed before the route did have to keep
		// working -- this is the property that decides whether shipping the routes strands anybody.
		const hc = newEngine();
		hc.overlay.closeAll = () => {};
		hc.scene.go = () => {};
		startRun(hc, 9001, DEFAULT_PARTY);
		let run = hc.state.run;
		hc.map.generateRegion();
		for (const row of run.map.rowArray) {
			for (const node of row) if (node.typeIndex === "boss") node.encounterIndex = "matriarchLair";
		}
		hc.tuning.map.route.byBossArray.filter((row) => row.bossEncounterIndex === "matriarchLair")[0].regionIndex = "pollenRoad";
		hc.descendRegion();
		const landed = run.map.regionIndex;
		check("a descended run is standing in its route's region", landed === "pollenRoad", landed);

		// Round-trip through the same serialisation a save uses.
		hc.state = JSON.parse(JSON.stringify(hc.state));
		run = hc.state.run;
		check("  and the route survives a save and reload", run.routeRegionIndex === "pollenRoad", String(run.routeRegionIndex));
		check("  and regenerating the map after the reload rebuilds the same region",
			hc.map.generateRegion().regionIndex === "pollenRoad", hc.state.run.map.regionIndex);

		// A SAVE FROM BEFORE THE ROUTE TABLE EXISTED has no routeRegionIndex at all -- not null, absent.
		const oldSave = JSON.parse(JSON.stringify(hc.state));
		delete oldSave.run.routeRegionIndex;
		oldSave.run.regionsCleared = 1;
		hc.state = oldSave;
		check("a run saved before routes existed is not stranded, it descends into the default",
			hc.map.generateRegion().regionIndex === hc.tuning.map.route.defaultSecondRegion,
			hc.state.run.map.regionIndex);
		check("  and generating its map does not invent a route for it",
			hc.state.run.routeRegionIndex == null, String(hc.state.run.routeRegionIndex));
	}

	// =============================================================== the win condition
	{
		// Built through the real overlay, because the bug being guarded against is a run that stops in
		// the wrong place -- and that is a string on a panel, not a number in a variable.
		// The reward rows are markup helpers the headless engine does not load; the branch under test is
		// the title and the button, so they are stubbed rather than reproduced.
		const titleAfter = (hc, cleared) => {
			hc.ui.globalExperienceTile = () => "";
			hc.ui.personalShareRow = () => "";
			startRun(hc, 4505, DEFAULT_PARTY);
			hc.state.run.regionsCleared = cleared;
			hc.map.generateRegion();
			const layer = { innerHTML: "" };
			hc.findDefinition(hc.overlayArray, "regionCleared").build(layer);
			return layer.innerHTML;
		};

		const hc = newEngine();
		check("clearing the first of two regions opens the way down",
			/The Way Down Opens/.test(titleAfter(hc, 0)));
		check("clearing the second wins the run",
			/The Catacombs Are Yours/.test(titleAfter(hc, 1)));
		// FOUR REGIONS IN THE TABLE, TWO IN A RUN. Counting regionArray here would have moved the ending
		// the moment Stage 1 added flora and pollenRoad.
		check("  with more regions in the table than in a run, so the table's length is not what ends one",
			hc.regionArray.length > hc.tuning.map.route.regionsPerRun,
			hc.regionArray.length + " regions, " + hc.tuning.map.route.regionsPerRun + " per run");

		// FALSIFY: the ending must move when the tuned length moves, and only then.
		const longer = newEngine();
		longer.tuning.map.route.regionsPerRun = 3;
		check("raising regionsPerRun moves the ending",
			/The Way Down Opens/.test(titleAfter(longer, 1)));
		check("  and the run still ends at the new length",
			/The Catacombs Are Yours/.test(titleAfter(longer, 2)));
	}
}
// <<< LANE E7 | route | suite block <<<
console.log("\n[112] Session 43 -- A14 promoteEntity (a card saying A->B) and A16 token cards");
{
	const hc = newEngine();

	// =============================================================== A14
	check("promoteEntity exists", typeof hc.promoteEntity === "function");
	check("and a card can reach it", hc.effectArray.filter((e) => e.index === "promote").length === 1);

	// NO LADDER, ANYWHERE. Noodle: "It's not a pool or a ladder, it's cards that say A->B".
	// A `tier`, a `nextPiece` or a `promotesTo` on a piece would be the ladder sneaking back in, and it
	// would quietly re-impose an order nobody asked for.
	{
		const golemArray = hc.enemyArray.filter((e) => (e.tagArray || []).indexOf("golem") >= 0 && e.unlisted !== true);
		const laddered = golemArray.filter((e) =>
			e.tier != null || e.nextPiece != null || e.promotesTo != null || e.promotionRank != null);
		check("no piece carries an implied order of pieces", laddered.length === 0,
			laddered.map((e) => e.index).join(", "));
	}

	{
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 42);
		hc.combat.begin("loneSporeling", {});
		const combat = hc.state.run.combat;
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		const pawn = hc.state.run.partyArray.find((e) => e.enemyIndex === "celestialPawn");
		check("a Pawn stands with the party", pawn != null);

		const keptId = pawn.instanceId;
		const pawnMax = pawn.maxHealth;
		// Hurt it, so the health carry-over is actually exercised rather than trivially equal.
		pawn.health = Math.max(1, Math.round(pawn.maxHealth * 0.5));
		// Session 46: the chain passives are cut. A Pawn carries no passive; a Rook carries Plated, and that
		// is the passive the shape rule is proven with below.
		check("a Pawn carries no passive of its own", pawn.statusArray.length === 0,
			pawn.statusArray.map((s) => s.index).join(","));

		const promoted = hc.promoteEntity(pawn, "celestialRook", hc.newEffectContext({ combat: combat, source: pawn }));
		check("the promotion happens", promoted === true);
		check("it is the SAME body -- the instance id is kept",
			pawn.instanceId === keptId,
			"so the chain, statuses and any aim still point at it");
		check("and it is now a Rook", pawn.enemyIndex === "celestialRook");
		check("its maximum is the Rook's, not the Pawn's", pawn.maxHealth > pawnMax,
			pawnMax + " -> " + pawn.maxHealth);
		// SESSION 47 FLIPPED THE TUNED DEFAULT to "full". It used to be "fraction" -- promotion is a
		// conversion, not a heal -- and this checked that a half-dead Pawn became a half-dead Rook. Noodle:
		// "I think promotion is below rate. Rook lift for example: [...] you get +1 damage and the meat
		// shield is more durable. Now your turn is over." Healing the body is what pays for that tempo.
		// Both modes still work; the check follows whichever is tuned, so neither can silently stop.
		check("the health mode is a tuning entry", typeof hc.tuning.chessmaster.promotionHealthMode === "string");
		check("a promoted piece arrives at its new shape's full health",
			hc.tuning.chessmaster.promotionHealthMode !== "full" || pawn.health === pawn.maxHealth,
			pawn.health + "/" + pawn.maxHealth);
		check("and carries its wound instead when the mode says fraction",
			hc.tuning.chessmaster.promotionHealthMode !== "fraction" || pawn.health < pawn.maxHealth,
			pawn.health + "/" + pawn.maxHealth);

		// The passive belongs to the SHAPE.
		check("the Rook's passive arrived with the shape",
			pawn.statusArray.some((s) => s.index === "plated"),
			pawn.statusArray.map((s) => s.index).join(","));
		check("and the promoted piece telegraphs its new shape's first move at once",
			pawn.intentCardIndex === "celestialRookImmure", String(pawn.intentCardIndex));
		{
			// The passive LEAVES with the shape too: a Rook promoted onward is no longer Plated. Done on a
			// throwaway body so the refusal checks below still see a Rook.
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialRook" }, { combat: combat });
			const rook = hc.state.run.partyArray.filter((e) => e.enemyIndex === "celestialRook").pop();
			hc.promoteEntity(rook, "celestialQueen", hc.newEffectContext({ combat: combat }));
			check("and the Rook's passive leaves with the Rook",
				rook.enemyIndex === "celestialQueen" && rook.statusArray.some((s) => s.index === "plated") === false,
				rook.statusArray.map((s) => s.index).join(","));
			hc.dealDamage(null, rook, 999, { ignoresStrength: true }, hc.newEffectContext({ combat: combat }));
		}

		// Refusals.
		check("promoting into what it already is is refused",
			hc.promoteEntity(pawn, "celestialRook", hc.newEffectContext({ combat: combat })) === false);
		check("promoting into nothing is refused",
			hc.promoteEntity(pawn, "notAPiece", hc.newEffectContext({ combat: combat })) === false);
		check("and promoting nobody is refused", hc.promoteEntity(null, "celestialRook", null) === false);

		// A->C as readily as A->B: the destination is the caller's, so nothing constrains the pairing.
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		const second = hc.state.run.partyArray.filter((e) => e.enemyIndex === "celestialPawn").pop();
		check("the same piece promotes somewhere else entirely",
			hc.promoteEntity(second, "celestialBishop", hc.newEffectContext({ combat: combat })) === true &&
			second.enemyIndex === "celestialBishop");

		// A FULL BOARD MAY STILL PROMOTE: the cap counts bodies and a promotion creates none. That is
		// what makes promotion the answer once the board cannot grow.
		while (hc.regularAllyCount(combat) < hc.tuning.chessmaster.regularSlotCount) {
			if (hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat }) == null) break;
		}
		check("the board is full", hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat }) == null);
		const last = hc.state.run.partyArray.filter((e) => e.enemyIndex === "celestialPawn").pop();
		check("and a full board still promotes",
			last != null && hc.promoteEntity(last, "celestialQueen", hc.newEffectContext({ combat: combat })) === true);
	}

	// =============================================================== A16
	check("card kinds are a registry", Array.isArray(hc.cardKindArray) && hc.cardKindArray.length >= 2);
	check("a card that says nothing is normal", hc.cardKindDefinition({}).index === "normal");
	check("an UNREGISTERED kind falls back to normal", hc.cardKindDefinition({ kind: "wat" }).index === "normal");
	check("which is why there is a rule for it",
		hc.warningRuleArray.some((r) => r.index === "cardKindRegistered"));
	check("and a rule for an encounter offering one",
		hc.warningRuleArray.some((r) => r.index === "phantomNotOffered"));

	const king = hc.findDefinition(hc.cardArray, "anastasiaKingsInvocation");
	check("King's Invocation is a token", king != null && king.kind === "phantom", king == null ? "missing" : String(king.kind));
	check("so it may not be offered", hc.cardIsOfferable(king) === false);
	check("nor granted", hc.cardIsGrantable(king) === false);
	{
		const ordinary = hc.cardArray.find((c) => c.kind == null && c.rarity === "common");
		check("an ordinary common is both", hc.cardIsOfferable(ordinary) === true && hc.cardIsGrantable(ordinary) === true);
	}

	// THE REPORTED BUG, asserted. "Random starter card included King's invocation".
	// The default outfit's randomCardCount rolls from the character's whole pool, which is how a
	// one-shot payoff card turned up in an opening hand.
	//
	// Tested on a SHIPPED character rather than Anastasia: she carries `inDevelopment`, so a run cannot
	// be built with her and the roll comes back empty -- which would make "it never appeared" pass for
	// the wrong reason. The gate is generic, so proving it for a shipped character proves it for her.
	{
		const hc2 = newEngine();
		const victim = hc2.cardArray.find((c) => c.characterIndex === "severine" && c.rarity === "common" && c.kind == null);
		check("a shipped common is available to mark as a token", victim != null);
		hc2.state = hc2.newProfile();

		// FIRST: it IS rollable while it is normal. Without this, the next check proves nothing.
		let rolled = 0;
		let seenNormal = 0;
		for (let seed = 1; seed <= 120; seed++) {
			hc2.newRun([{ characterIndex: "severine", outfitIndex: "default" }], seed);
			const array = hc2.state.run.partyArray[0].randomCardIndexArray || [];
			rolled += array.length;
			if (array.indexOf(victim.index) >= 0) seenNormal++;
		}
		check("run-start random cards are actually rolled", rolled > 0, String(rolled));
		check("and the card turns up while it is a normal card", seenNormal > 0, seenNormal + " of 120 seeds");

		// NOW make it a token and roll the identical seeds.
		victim.kind = "phantom";
		let seenToken = 0;
		for (let seed = 1; seed <= 120; seed++) {
			hc2.newRun([{ characterIndex: "severine", outfitIndex: "default" }], seed);
			const array = hc2.state.run.partyArray[0].randomCardIndexArray || [];
			if (array.indexOf(victim.index) >= 0) seenToken++;
		}
		check("as a token it never reaches a starting deck again", seenToken === 0, seenToken + " of 120 seeds");

		// And it leaves the reward pool and the shelf at the same time.
		hc2.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 9);
		hc2.combat.begin("loneSporeling", {});
		const pool = hc2.combat.rewardPoolFor(hc2.state.run.partyArray[0], hc2.state.run.combat, null, "severine", null);
		const indexOf = (entry) => (entry.card != null ? entry.card.index : (entry.cardIndex != null ? entry.cardIndex : entry.index));
		check("the reward pool has cards in it", pool.length > 0, String(pool.length));
		check("and the token is not among them",
			pool.map(indexOf).indexOf(victim.index) < 0, pool.map(indexOf).slice(0, 6).join(","));
		check("nor is it offerable to the party", hc2.cardOfferableForParty(victim) === false);
		delete victim.kind;
		check("and clearing the kind restores it", hc2.cardIsOfferable(victim) === true);
	}
}

console.log("\n[114] Session 46 (lane ANA) -- Anastasia rebuilt: the resequence, the cut chain, the kit, the gate, the gauntlet");
{
	const hc = newEngine();
	// THE TWELVE CANONICAL PIECES. An `unlisted` copy -- the gauntlet's two Queens, who wear the real
	// ones' moves but CAST the King instead of shuffling him in -- is the same piece wearing one
	// different card, not a thirteenth shape, so it is not counted as one.
	const golemArray = hc.enemyArray.filter((e) => (e.tagArray || []).indexOf("golem") >= 0 && e.unlisted !== true);
	const herCardArray = hc.cardArray.filter((c) => c.characterIndex === "anastasia");
	const piecesOf = () => hc.state.run.partyArray.filter((e) => e.enemyIndex != null);
	// Her abilities come from her tree now. A fresh profile has bought no nodes, so the fights below hand her
	// A1 the way a bought node would -- as a starting ability on this isolated engine's copy of her entry.
	hc.findDefinition(hc.characterArray, "anastasia").startingAbilityArray = [{ index: "anastasiaTransposition" }];
	const startFight = (seed) => {
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "anastasia", outfitIndex: "default" }], seed);
		hc.combat.begin("loneSporeling", {});
	};
	const aimed = (target) => {
		const context = hc.newEffectContext({ combat: hc.state.run.combat, source: hc.state.run.partyArray[0] });
		context.target = target;
		context.targetArray = target == null ? [] : [target];
		return context;
	};

	// =============================================================== the pieces
	check("there are twelve pieces", golemArray.length === 12, String(golemArray.length));
	check("every piece walks its list in order -- never a dice roll",
		golemArray.every((e) => e.moveStrategy === "sequence"),
		golemArray.filter((e) => e.moveStrategy !== "sequence").map((e) => e.index).join(","));
	// TWO MOVES EACH, AND THE QUEENS ARE THE EXCEPTION (session 47). Noodle, rewriting the piece table:
	// "The only piece to have more than 2 moves, secondary enabler beyond a2, gives a long-term game plan."
	// The rule still binds everyone else -- the pair is what makes a switched intent a real question --
	// so the exception is asserted rather than the rule being softened away.
	check("every piece except a Queen has exactly two moves (BUILD-ANASTASIA s4)",
		golemArray.filter((e) => (e.tagArray || []).indexOf("queen") < 0).every((e) => (e.moveArray || []).length === 2),
		golemArray.filter((e) => (e.tagArray || []).indexOf("queen") < 0 && (e.moveArray || []).length !== 2).map((e) => e.index).join(","));
	check("and a Queen has five",
		golemArray.filter((e) => (e.tagArray || []).indexOf("queen") >= 0).every((e) => (e.moveArray || []).length === 5),
		golemArray.filter((e) => (e.tagArray || []).indexOf("queen") >= 0).map((e) => e.index + ":" + (e.moveArray || []).length).join(","));
	check("and every move is a registered card",
		golemArray.every((e) => e.moveArray.every((m) => hc.findDefinition(hc.cardArray, m.card) != null)));
	check("every piece names a twin, and the twin names it back",
		golemArray.every((e) => {
			const twin = hc.findDefinition(hc.enemyArray, e.alignmentTwin);
			return twin != null && twin.alignmentTwin === e.index;
		}));

	// =============================================================== the chain is cut
	{
		const dir = path.join(ROOT, "honeycomb");
		const offenderArray = [];
		for (const name of fs.readdirSync(dir).filter((f) => f.endsWith(".js"))) {
			const source = fs.readFileSync(path.join(dir, name), "utf8");
			if (/chainBuffer|cashOutChain|chessmaster\.chain\b|chessmaster\.piece\b/.test(source)) offenderArray.push(name);
		}
		check("nothing reads the chain buffer, the cash-out or their tuning", offenderArray.length === 0, offenderArray.join(","));
		check("no chain status survives",
			hc.statusArray.every((s) => /Chain$/.test(s.index) === false && s.index !== "grandmastersEye"));
		check("the chain verb is gone", hc.effectArray.every((e) => e.index !== "chain"));
		check("and the old A1 with it", hc.findDefinition(hc.abilityArray, "anastasiaOpeningMove") == null);
	}

	// =============================================================== setIntent: a swap, never a skip
	{
		startFight(42);
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: hc.state.run.combat });
		const pawn = piecesOf()[0];
		const firstMove = pawn.intentCardIndex;
		check("a summoned Pawn telegraphs its first move", firstMove === "celestialPawnBulwark", String(firstMove));
		check("a switch knows where it lands before it happens", hc.intentSwitchPosition(pawn, null) === 1);
		hc.resolveEffectArray([{ index: "setIntent" }], aimed(pawn));
		check("the switch telegraphs the OTHER move", pawn.intentCardIndex === "celestialPawnJab", String(pawn.intentCardIndex));
		// THE IMPLEMENTATION RULE: the pointer moves too. Left alone it would still read 1, and the next pick
		// would be Jab again -- Jab, Jab, the Bulwark skipped outright.
		check("and the pointer moved with it", pawn.movePosition === 2, String(pawn.movePosition));
		const nextPick = hc.selectMove(pawn);
		check("so the next turn plays the move that was switched AWAY from -- a swap, not a skip",
			nextPick === firstMove, String(nextPick));
		check("and the turn after that is back in step", hc.selectMove(pawn) === "celestialPawnJab");

		// Falsified: the telegraph-only version of the verb really does skip.
		const naive = piecesOf()[0];
		naive.movePosition = 1;
		naive.intentCardIndex = "celestialPawnJab";
		check("(a switch that left the pointer alone WOULD repeat the move -- so the check above can fail)",
			hc.selectMove(naive) === "celestialPawnJab");

		check("a named move the piece does not own is refused", hc.intentSwitchPosition(pawn, "infernalKingRuin") === -1);
		check("and a player character has no intent to switch", hc.intentSwitchPosition(hc.state.run.partyArray[0], null) === -1);
	}

	// =============================================================== her pool
	{
		const poolArray = herCardArray.filter((c) => c.kind == null);
		// CEILING RAISED SESSION 47, from 18. Five commons were added at Noodle's word ("Give anastasia a
		// few commons that sacrifice pawns for benefits" plus the field clearer), which is the pool growing
		// toward the 21 C / 11 R a shipped character carries -- not a pool that has got away from itself.
		check("her pool is 12-24 cards plus the two starters' worth (BUILD-ANASTASIA s12)",
			poolArray.length >= 12 && poolArray.length <= 24, String(poolArray.length));
		check("every card of hers names its pose",
			herCardArray.every((c) => c.pose === "offense" || c.pose === "passive"),
			herCardArray.filter((c) => c.pose == null).map((c) => c.index).join(","));
		check("the pool uses the snap", herCardArray.some((c) => c.pose === "offense"));
		check("and the crouch", herCardArray.some((c) => c.pose === "passive"));
		check("her poses are held longer than the command lead, so the snap is still up when the piece appears",
			hc.findDefinition(hc.characterArray, "anastasia").poseHoldMs > hc.tuning.animation.commandLeadMs);
		check("and a card's presentation carries that hold",
			hc.art.cardPresentation(hc.findDefinition(hc.cardArray, "anastasiaAdvance")).holdMs === hc.tuning.chessmaster.poseHoldMs);
		check("somebody else's card carries none",
			hc.art.cardPresentation(hc.cardArray.find((c) => c.characterIndex === "severine")).holdMs == null);

		const character = hc.findDefinition(hc.characterArray, "anastasia");
		check("her starters are 2x one attack and 2x one defence",
			character.startingCardArray.length === 2 && character.startingCardArray.every((entry) => entry.count === 2));
		const summons = (card) => JSON.stringify(card.effectArray).indexOf('"summon"') >= 0;
		check("and one of them puts a Pawn on the board",
			character.startingCardArray.some((entry) => summons(hc.findDefinition(hc.cardArray, entry.index))));
		check("every verb of the five has a card",
			["summon", "promote", "setIntent", "applyStatus", "shiftParty"].every((verb) =>
				herCardArray.some((c) => JSON.stringify(c.effectArray).indexOf('"' + verb + '"') >= 0)));
		// Top-level effects only: nested indices are conditions and values, which have their own registries.
		const kitCardArray = hc.cardArray.filter((c) => c.characterIndex === "anastasia" || /^(celestial|infernal|gauntlet)/.test(c.index));
		const unregisteredArray = [];
		for (const card of kitCardArray) {
			for (const entry of card.effectArray) {
				if (hc.findDefinition(hc.effectArray, entry.index) == null) unregisteredArray.push(card.index + ":" + entry.index);
			}
		}
		check("every effect her cards and the pieces' moves name is a registered verb",
			kitCardArray.length > 30 && unregisteredArray.length === 0, unregisteredArray.join(","));
	}

	// =============================================================== the corpse is inventory
	{
		startFight(7);
		const combat = hc.state.run.combat;
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		const pawn = piecesOf()[0];
		const keptId = pawn.instanceId;
		const slot = hc.state.run.partyArray.indexOf(pawn);
		hc.applyStatus(pawn, "strength", 3, aimed(pawn));
		hc.dealDamage(null, pawn, 999, { ignoresStrength: true }, aimed(pawn));
		check("a Pawn falls", pawn.downed === true);
		check("and a fallen Pawn is a Gambit", hc.mechanicValue(hc.state.run.partyArray[0], "gambit") === 1);
		const lengthBefore = hc.state.run.partyArray.length;

		const raised = hc.summonCombatant({ side: "ally", enemyIndex: "infernalPawn" }, { combat: combat });
		check("the next Pawn summon fills the corpse's place instead of adding a body",
			raised === pawn && hc.state.run.partyArray.length === lengthBefore && hc.state.run.partyArray.indexOf(pawn) === slot);
		check("the same body", pawn.instanceId === keptId);
		check("standing, at full health, as what was summoned",
			pawn.downed !== true && pawn.health === pawn.maxHealth && pawn.enemyIndex === "infernalPawn");
		check("with nothing of its last life on it", hc.statusStacks(pawn, "strength") === 0);
		check("and telegraphing", pawn.intentCardIndex === "infernalPawnGnash", String(pawn.intentCardIndex));

		// SESSION 47 CHANGED WHAT THIS ASSERTS. It used to read "a fallen Rook is not refilled -- only a
		// Pawn's corpse is inventory". Noodle: "pawn summons should always eat dead pieces", so the CORPSE
		// no longer has to be a Pawn; refillTagArray now names which SUMMONS do the eating. A Rook summon
		// is not one of them, which is what is still true here.
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialRook" }, { combat: combat });
		const rook = piecesOf().find((e) => e.enemyIndex === "celestialRook");
		hc.dealDamage(null, rook, 999, { ignoresStrength: true }, aimed(rook));
		const before = hc.state.run.partyArray.length;
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialRook" }, { combat: combat });
		check("a Rook summon refills nothing -- only a Pawn summon eats a corpse",
			rook.downed === true && hc.state.run.partyArray.length === before + 1);
		check("which summons refill is a tuning entry", Array.isArray(hc.tuning.chessmaster.refillTagArray));

		// TRANSPOSITION.
		const ana = hc.state.run.partyArray[0];
		check("with its node bought she holds Transposition",
			hc.abilities.usability(ana, "anastasiaTransposition", combat).usable === true);
		hc.dealDamage(null, pawn, 999, { ignoresStrength: true }, aimed(pawn));
		check("the `piece` mode may land on a downed Pawn", hc.targetModeAllows("piece", ana.instanceId, "ally", pawn) === true);
		check("no other mode may land on the fallen", hc.targetModeAllows("ally", ana.instanceId, "ally", pawn) === false);
		check("nor may `piece` land on a fallen Rook", hc.targetModeAllows("piece", ana.instanceId, "ally", rook) === false);
		check("nor on Anastasia", hc.targetModeAllows("piece", ana.instanceId, "ally", ana) === false);
		const used = hc.abilities.use(ana.instanceId, "anastasiaTransposition", pawn.instanceId);
		check("Transposition raises a downed Pawn as its twin",
			used.played === true && pawn.downed !== true && pawn.enemyIndex === "celestialPawn", JSON.stringify(used));
		check("and it is once a combat",
			hc.abilities.use(hc.state.run.partyArray[0].instanceId, "anastasiaTransposition", pawn.instanceId).played === false);
	}

	// =============================================================== her pool, session 47
	{
		const card = (index) => hc.findDefinition(hc.cardArray, index);

		// THE ATTACK STARTER SUMMONS. Noodle: "Her basic offensive really should be summoning an infernal
		// pawn, not a 6 damage attack."
		const advance = card("anastasiaAdvance");
		check("Advance exists and is a starter", advance != null && advance.rarity === "starter");
		check("and it summons rather than hits",
			JSON.stringify(advance.effectArray).indexOf('"summon"') >= 0 &&
			JSON.stringify(advance.effectArray).indexOf('"damage"') < 0);
		check("Check is a rare now", card("anastasiaCheck").rarity === "rare");
		check("and Castle is gone, replaced by Castling",
			card("anastasiaCastle") == null && card("anastasiaCastling") != null);

		// ADVANCE PUTS ITS PAWN AT THE FRONT, through the `lastSummoned` target mode. A rank would have
		// been wrong: a summon that refills a corpse does not land at the back.
		startFight(21);
		const combat = hc.state.run.combat;
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		{
			const context = hc.newEffectContext({ combat: combat, source: hc.state.run.partyArray[0] });
			hc.resolveEffectArray(advance.effectArray, context);
			const front = hc.livingEntityArray("ally", combat)[0];
			check("Advance's Pawn arrives at the front", front.enemyIndex === "infernalPawn", String(front.enemyIndex));
			check("and `lastSummoned` named it", context.tally.lastSummonedId === front.instanceId);
		}

		// DESPERADO spends the body it just made, wherever that body landed.
		{
			const context = hc.newEffectContext({ combat: combat, source: hc.state.run.partyArray[0] });
			const before = hc.livingEntityArray("enemy", combat).map((e) => e.health);
			hc.resolveEffectArray(card("anastasiaDesperado").effectArray, context);
			const summoned = hc.findEntity(context.tally.lastSummonedId, combat);
			check("Desperado's own Pawn is the one it kills", summoned != null && summoned.downed === true);
			check("and every enemy was hit",
				hc.entityArray("enemy", combat).every((e, i) => before[i] == null || e.health < before[i]));
		}

		// UNDERPROMOTION: "1 cost replace all broken pieces with celestial pawns."
		{
			const fallenArray = hc.entityArray("ally", combat).filter((e) => e.downed === true && e.enemyIndex != null);
			check("there are fallen pieces to raise", fallenArray.length > 0, String(fallenArray.length));
			const context = hc.newEffectContext({ combat: combat, source: hc.state.run.partyArray[0] });
			hc.resolveEffectArray(card("anastasiaUnderpromotion").effectArray, context);
			check("Underpromotion stands every one of them up as a Celestial Pawn",
				fallenArray.every((e) => e.downed !== true && e.enemyIndex === "celestialPawn"));
			check("and adds no body", hc.entityArray("ally", combat).filter((e) => e.downed === true).length === 0);
		}

		// DEEP CALCULATION'S BUG. "Lmao and Deep Calculation didn't actually draw me any cards with 2
		// pieces on board." partyTagCount reads tags through a CHARACTER definition, so a golem counted
		// zero; partyEntityTagCount asks entityHasTag, which knows both kinds. Falsified first.
		startFight(22);
		{
			const live = hc.state.run.combat;
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: live });
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: live });
			const context = hc.newEffectContext({ combat: live, source: hc.state.run.partyArray[0] });
			check("the OLD value still reads zero over two pieces -- the bug, pinned",
				hc.resolveValue({ index: "partyTagCount", tag: "celestial", livingOnly: true }, context) === 0);
			check("the new one counts them",
				hc.resolveValue({ index: "partyEntityTagCount", tag: "celestial" }, context) === 2);
			check("and it can leave the card's user out",
				hc.resolveValue({ index: "partyEntityTagCount", tag: "human", excludeSelf: true }, context) === 0);

			const handBefore = live.handArray.length;
			hc.resolveEffectArray(card("anastasiaDeepCalculation").effectArray,
				hc.newEffectContext({ combat: live, source: hc.state.run.partyArray[0] }));
			check("Deep Calculation draws two with two Celestial Pawns standing",
				live.handArray.length === handBefore + 2, String(live.handArray.length - handBefore));
			check("and it is a 3-cost rare, as asked",
				card("anastasiaDeepCalculation").costArray.energy === 3 && card("anastasiaDeepCalculation").rarity === "rare");
		}

		// PROMOTION PAYS BETTER NOW. "I think promotion is below rate. Rook lift for example..."
		check("a promotion heals the body to full", hc.tuning.chessmaster.promotionHealthMode === "full");
		check("and Rook Lift costs what the other promotions do",
			card("anastasiaRookLift").costArray.energy === card("anastasiaKnightsTour").costArray.energy);
	}

	// =============================================================== NEVER A SIXTH BODY (session 47)
	// Noodle, playing her: "CRITICAL: I summoned a pawn with 5 party members, and it gave me a sixth. We
	// should never have six, that was an extremely early requirement for her." The cause was the cap
	// counting the STANDING: a downed fighter is still drawn, so four standing plus a corpse admitted a
	// fifth body and the board showed six figures.
	{
		startFight(11);
		const combat = hc.state.run.combat;
		const bodies = () => hc.state.run.partyArray.length;
		const cap = hc.tuning.chessmaster.regularSlotCount;

		while (bodies() < cap) {
			if (hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat }) == null) break;
		}
		check("the board fills to the cap", bodies() === cap, String(bodies()));
		check("and refuses the next", hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat }) == null);

		// A corpse holds its slot. This is the report, reproduced: kill a body and summon again.
		const victim = piecesOf()[0];
		hc.dealDamage(null, victim, 999, { ignoresStrength: true }, aimed(victim));
		check("a piece falls but is still on the board", victim.downed === true && bodies() === cap);
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		check("a summon over a corpse never makes a sixth body", bodies() === cap, String(bodies()));
		check("it raised the corpse instead", victim.downed !== true);

		// THE CORPSE THAT CAUSED IT was a piece a Pawn summon could not eat. Under the old rules only a
		// fallen PAWN was inventory, so a fallen Knight sat on the board uncounted by the cap and the next
		// summon stood beside it. Both halves of the fix are needed, so both are asserted: the cap counts
		// the corpse, AND the summon eats it.
		const bigger = piecesOf().find((e) => e.enemyIndex !== "celestialPawn") || piecesOf()[1];
		hc.promoteEntity(bigger, "celestialKnight", aimed(bigger));
		hc.dealDamage(null, bigger, 999, { ignoresStrength: true }, aimed(bigger));
		check("a Knight falls", bigger.downed === true && bigger.enemyIndex === "celestialKnight");
		check("the cap counts its corpse", hc.regularAllyCount(combat) === cap, String(hc.regularAllyCount(combat)));
		const held = bodies();
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		check("and the summon eats it rather than making a sixth figure",
			bodies() === held && bigger.downed !== true && bigger.enemyIndex === "celestialPawn", String(bodies()));

		// A character never goes `downed` -- she BREAKS and keeps her place -- so she has always been
		// counted. Pinned so a later change to breaking cannot reopen this quietly.
		const ana = hc.state.run.partyArray[0];
		hc.dealDamage(null, ana, 999, { ignoresStrength: true }, aimed(ana));
		check("she breaks rather than falling", ana.broken === true && ana.downed !== true);
		check("and still holds her slot", hc.regularAllyCount(combat) === cap, String(hc.regularAllyCount(combat)));
	}

	// =============================================================== A PAWN SUMMON EATS ANY DEAD PIECE (session 47)
	// Noodle: "pawn summons should always eat dead pieces." A fallen Knight used to sit on the board with
	// nothing able to clear it, because only a fallen PAWN was inventory.
	{
		startFight(12);
		const combat = hc.state.run.combat;
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialKnight" }, { combat: combat });
		const knight = piecesOf()[0];
		const slot = hc.state.run.partyArray.indexOf(knight);
		hc.dealDamage(null, knight, 999, { ignoresStrength: true }, aimed(knight));
		check("a Knight falls", knight.downed === true);
		const before = hc.state.run.partyArray.length;
		const raised = hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		check("a Pawn summon eats it rather than adding a body",
			raised === knight && hc.state.run.partyArray.length === before);
		check("in the same place, as the summoned shape",
			hc.state.run.partyArray.indexOf(knight) === slot && knight.enemyIndex === "celestialPawn" && knight.downed !== true);
	}

	// =============================================================== the gate
	{
		hc.state = hc.newProfile();
		const listed = () => hc.shippedCharacterArray().some((c) => c.index === "anastasia");
		check("an unearned profile lists her nowhere", listed() === false);
		check("and does not count her", hc.unlocks.progress("character").total === 6, String(hc.unlocks.progress("character").total));
		check("the flag is NOT cleared -- she is still below the content standard",
			hc.findDefinition(hc.characterArray, "anastasia").inDevelopment === true);

		// SEALED: nothing of hers is in a total a player can see.
		const sealedEnemy = hc.discovery.allIndexArray("enemy");
		check("her pieces are in no enemy total", sealedEnemy.every((index) => /^(celestial|infernal|gauntlet)/.test(index) === false),
			sealedEnemy.filter((index) => /^(celestial|infernal|gauntlet)/.test(index)).join(","));
		check("the enemy total still counts everybody else", sealedEnemy.length === hc.enemyArray.filter((e) => e.sealedBy == null).length);
		check("her cards are in no card total", hc.discovery.allIndexArray("card").every((index) => /^anastasia/.test(index) === false));
		check("the invitation is in no relic total", hc.discovery.allIndexArray("relic").indexOf("gauntletInvitation") < 0);
		check("the gauntlet's fights are in no battle total",
			hc.discovery.allIndexArray("encounter").every((index) => /^gauntlet/.test(index) === false));
		check("her pieces' moves are in no intent total",
			hc.discovery.allIndexArray("intent").every((key) => /^(celestial|infernal|gauntlet)/.test(key) === false));
		check("the gauntlet's region is not counted",
			hc.map.countedRegionArray().indexOf(hc.tuning.chessmaster.gauntlet.regionIndex) < 0,
			hc.map.countedRegionArray().join(","));
		check("though it exists, at position 4",
			hc.regionArray.map((r) => r.index).indexOf(hc.tuning.chessmaster.gauntlet.regionIndex) === 4);
		check("every gauntlet encounter names position 4",
			hc.encounterArray.filter((e) => /^gauntlet/.test(e.index) && e.tier !== "boss").every((e) => e.regionIndexArray.join() === "4"));
		{
			const title = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-title.js"), "utf8");
			// SESSION 47 moved the filter into its own function, `bestiaryEnemyArray`, so the set-dressing
			// rule and the sealing rule sit together and both apply wherever the wall is built. The check
			// follows it there rather than pinning the filter to renderBestiary's own body.
			const bestiary = title.slice(title.indexOf("honeycomb.compendium.bestiaryEnemyArray = function"));
			check("the bestiary wall leaves sealed enemies off it", /isSealed\("enemy"/.test(bestiary.slice(0, 900)));
			check("and set dressing and unlisted copies too", /isUnlisted/.test(bestiary.slice(0, 900)));
		}
		// Met is known: the ledger cannot un-know a piece a profile has fought.
		hc.discovery.note("enemy", "infernalPawn");
		check("a piece that has been MET is no longer sealed", hc.discovery.isSealed("enemy", "infernalPawn") === false);

		hc.unlocks.grant("character", "anastasia");
		check("an earned profile lists her", listed() === true);
		check("and her content is counted from then on", hc.discovery.allIndexArray("card").some((index) => /^anastasia/.test(index)));
	}

	// =============================================================== the gauntlet
	{
		const hc2 = newEngine();
		hc2.state = hc2.newProfile();
		hc2.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 5);
		hc2.map.generateRegion();
		const firstBoss = hc2.findDefinition(hc2.encounterArray, "matriarchLair");
		const settings = hc2.tuning.chessmaster.gauntlet;
		const relic = hc2.findDefinition(hc2.relicArray, settings.relicIndex);

		// Noodle turned the switch on in session 57, after a player walked every route and was never offered
		// the invitation. The checks below that need it off turn it off themselves.
		check("THE RELEASE SWITCH SHIPS ON (Noodle, session 57)", settings.enabled === true);
		settings.enabled = false;
		// The relic's NAME is Noodle's ("Grandmaster's Invitation") and is exempt; what it SAYS is not.
		check("the relic is the one Noodle named", relic.name === "Grandmaster's Invitation", relic.name);
		check("its words and the region say nothing of who waits",
			[relic.description, hc2.findDefinition(hc2.regionArray, settings.regionIndex).name,
				hc2.findDefinition(hc2.regionArray, settings.regionIndex).description]
				.every((text) => /anastasia|chess|grandmaster/i.test(text) === false));
		check("chance never pays the invitation", hc2.uncarriedRelicArray(null, null).every((r) => r.index !== settings.relicIndex) &&
			hc2.relicPool(relic) !== "common");

		// Clear every route FIRST, so the only thing standing between the player and the relic is the switch.
		for (const row of hc2.tuning.map.route.byBossArray) hc2.discovery.record("region", row.regionIndex, null);
		// THE SHOP SELLS IT (Noodle), on a shelf slot of its own, and nothing else hands it out.
		const onShelf = (engine) => engine.shop.guaranteedRelicArray().map((r) => r.index);
		check("with the switch off the relic is never offerable, whatever the profile has done",
			hc2.relicOfferable(relic) === false && onShelf(hc2).length === 0, onShelf(hc2).join(","));
		check("and a boss no longer pays it -- that seam is gone", hc2.combat.promisedRewardRelic === undefined);

		settings.enabled = true;
		check("switched on, a devoted profile finds it on the shop's guaranteed shelf",
			onShelf(hc2).join() === settings.relicIndex, onShelf(hc2).join(","));
		check("the shop's ordinary roll still never picks it",
			[1, 2, 3, 4, 5, 6, 7, 8].every(() => { const r = hc2.rollRelicOfferForShop([]); return r == null || r.index !== settings.relicIndex; }));
		{
			const hc3 = newEngine();
			hc3.state = hc3.newProfile();
			hc3.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 5);
			check("a profile that has NOT cleared every route does not see it, switch or no switch", onShelf(hc3).length === 0);
			hc3.tuning.chessmaster.gauntlet.requiresRoutesCleared = false;
			check("unless tuning says the routes do not matter", onShelf(hc3).join() === settings.relicIndex);
		}
		hc2.state.run.regionsCleared = 1;
		check("nor is it sold deeper than the first region, where it could do nothing", onShelf(hc2).length === 0);
		hc2.state.run.regionsCleared = 0;

		hc2.grantRelic(settings.relicIndex, hc2.newEffectContext({}));
		check("held, it outranks the boss and sends the run to the gauntlet",
			hc2.map.resolveRouteRegionIndex(hc2.state.run) === settings.regionIndex);
		check("and a shop does not sell a second one", onShelf(hc2).length === 0);

		hc2.state.run.routeRegionIndex = settings.regionIndex;
		hc2.state.run.regionsCleared = 1;
		hc2.map.generateRegion();
		const rolledArray = [];
		hc2.state.run.map.rowArray.forEach((row) => row.forEach((node) => { if (node.encounterIndex != null) rolledArray.push(node.encounterIndex); }));
		check("the gauntlet's map is built", hc2.state.run.map.regionIndex === settings.regionIndex && rolledArray.length > 0);
		check("and every fight on it is a gauntlet fight", rolledArray.every((index) => /^gauntlet/.test(index)),
			rolledArray.filter((index) => /^gauntlet/.test(index) === false).join(","));

		// THE BOSS.
		hc2.combat.begin("gauntletGrandmaster", {});
		const lineUp = hc2.state.run.combat.enemyArray;
		const her = lineUp.find((e) => e.enemyIndex === "gauntletAnastasia");
		// HER OPENING BUFFS: on the enemy side only, on everything in the fight, and never on her own board.
		const bossBuff = hc2.tuning.chessmaster.gauntlet.bossStatusArray.find((entry) => entry.status === "strength").stacks;
		check("the fight puts its buffs on every enemy from the first moment",
			bossBuff > 0 && lineUp.every((e) => hc2.statusStacks(e, "strength") === bossBuff && hc2.statusStacks(e, "plated") > 0),
			lineUp.map((e) => e.enemyIndex + ":" + hc2.statusStacks(e, "strength")).join(","));
		{
			const context = hc2.newEffectContext({ combat: hc2.state.run.combat, source: lineUp[lineUp.length - 1] });
			const summoned = hc2.summonCombatant({ side: "enemy", enemyIndex: "infernalPawn" }, context);
			check("a Pawn she summons mid-fight arrives with them", summoned != null && hc2.statusStacks(summoned, "strength") === bossBuff);
			hc2.promoteEntity(summoned, "infernalKnight", context);
			check("and a promotion does not pay them twice", hc2.statusStacks(summoned, "strength") === bossBuff);
			hc2.dealDamage(null, summoned, 9999, { ignoresStrength: true }, context);
			const friend = hc2.summonCombatant({ side: "ally", enemyIndex: "infernalPawn" }, context);
			check("a piece on the PARTY's side never carries them", friend != null && hc2.statusStacks(friend, "strength") === 0);
			hc2.dealDamage(null, friend, 9999, { ignoresStrength: true }, context);
		}
		check("every gauntlet fight names its buffs from tuning",
			hc2.encounterArray.filter((e) => /^gauntlet/.test(e.index)).every((e) => Array.isArray(e.enemyStartingStatusArray) && e.enemyStartingStatusArray.length > 0));
		check("and no gauntlet fight fields a King -- he is set dressing",
			hc2.encounterArray.filter((e) => /^gauntlet/.test(e.index)).every((e) => e.enemyIndexArray.every((i) => /King$/.test(i) === false)));
		// Counted among the STANDING: the buff checks above summoned and felled a Pawn, and the fallen stay
		// in the line-up array.
		check("she stands with four golems", her != null && lineUp.filter((e) => e.downed !== true).length === 5 &&
			lineUp.filter((e) => e.downed !== true && hc2.entityHasTag(e, "golem")).length === 4);
		check("she is the one AI combatant who picks at random", hc2.aiStrategyFor(her).index === "weighted");
		// REVERSED session 57 (Noodle: "Anastasia's backwards in her fight"): her drawings face right, for the
		// party line, so on the enemy line she is mirrored to face the party.
		check("she is mirrored on the enemy line, to face the party", hc2.art.spriteFlipped(her) === true);
		check("and not when she stands with the party", hc2.art.spriteFlipped({ characterIndex: "anastasia", side: "ally" }) === false);
		check("every move of hers names its pose",
			hc2.findDefinition(hc2.enemyArray, "gauntletAnastasia").moveArray
				.every((m) => ["offense", "passive"].indexOf(hc2.findDefinition(hc2.cardArray, m.card).pose) >= 0));
		{
			// Her Promotion is aimed at her whole side. Without `fromTag` it would promote HER.
			const context = hc2.newEffectContext({ combat: hc2.state.run.combat, source: her });
			context.targetArray = lineUp.slice();
			hc2.resolveEffectArray([{ index: "promote", to: "infernalKnight", fromTag: "pawn", limit: 1 }], context);
			check("her Promotion takes a Pawn and leaves her alone",
				her.enemyIndex === "gauntletAnastasia" && lineUp.filter((e) => e.enemyIndex === "infernalPawn").length === 0);
		}
		check("the ledger does not hold her yet", hc2.state.profile.unlockedCharacterArray.indexOf("anastasia") < 0);
		hc2.dealDamage(null, her, 9999, { ignoresStrength: true }, hc2.newEffectContext({ combat: hc2.state.run.combat }));
		hc2.combat.checkEnd(hc2.newEffectContext({ combat: hc2.state.run.combat }));
		check("beating her wins, whatever of her board still stands",
			hc2.state.run.combat.phase === "victory" && lineUp.some((e) => e.downed !== true), hc2.state.run.combat.phase);
		const reward = hc2.combat.finishVictory();
		check("and the win writes her into the ledger, through honeycomb.unlocks",
			hc2.state.profile.unlockedCharacterArray.indexOf("anastasia") >= 0 &&
			reward.unlockedArray.length === 1 && reward.unlockedArray[0].index === "anastasia");
		check("after which the invitation is never offered again",
			hc2.testCondition({ index: "gauntletOpen" }, hc2.newEffectContext({})) === false);
	}

	// =============================================================== the King is set dressing
	{
		startFight(3);
		const combat = hc.state.run.combat;
		const ana = hc.state.run.partyArray[0];
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		const bodiesBefore = hc.state.run.partyArray.length;
		const king = hc.findDefinition(hc.cardArray, "anastasiaKingsInvocation");
		check("King's Invocation summons nobody", JSON.stringify(king.effectArray).indexOf('"summon"') < 0);
		const context = hc.newEffectContext({ combat: combat, source: ana, card: king });
		context.target = ana; context.targetArray = [ana];
		hc.resolveEffectArray(king.effectArray.filter((e) => e.index !== "removeCardFromDeck"), context);
		check("no body joins the line", hc.state.run.partyArray.length === bodiesBefore);
		check("the King is recorded as set dressing behind her side",
			(combat.backdropPropArray || []).length === 1 && combat.backdropPropArray[0].enemy === "celestialKing" &&
			combat.backdropPropArray[0].side === "ally");
		// SESSION 47 REPLACED THE FLAT BUFF THIS USED TO CHECK (+4 Strength / +12 Temporary HP on every
		// piece). Noodle: "The king offering flat buffs feels too weak. Since she's a secret character I'm
		// okay with her being a little overpowered. Have the celestial king's on-play effect be to double
		// current party tHP, and its end of turn effect to be to deal damage at the end of your turn equal
		// to total party tHP to all enemies at once."
		check("she is left holding the Celestial Court", hc.statusStacks(ana, "celestialCourt") === 1);
		hc.resolveEffectArray([{ index: "showBackdropProp", enemy: "celestialKing" }], context);
		check("he is not drawn twice", combat.backdropPropArray.length === 1);
	}

	// =============================================================== THE TWO KINGS (session 47)
	{
		const card = (index) => hc.findDefinition(hc.cardArray, index);
		const runEffects = (index, source, combat) => {
			const context = hc.newEffectContext({ combat: combat, source: source, card: card(index) });
			context.target = source; context.targetArray = [source];
			hc.resolveEffectArray(card(index).effectArray.filter((e) => e.index !== "removeCardFromDeck"), context);
			return context;
		};

		// THE CELESTIAL KING DOUBLES THE WALL. Doubling has to be asked PER ALLY: an effect resolves its
		// amount once, so one `temporaryHealth` over allAllies would have given everyone the first ally's.
		startFight(31);
		{
			const combat = hc.state.run.combat;
			const ana = hc.state.run.partyArray[0];
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
			const pawn = piecesOf()[0];
			hc.grantTemporaryHealth(ana, 10, aimed(ana));
			hc.grantTemporaryHealth(pawn, 4, aimed(pawn));
			runEffects("anastasiaKingsInvocation", ana, combat);
			check("each ally's own wall is doubled, not the front one's copied",
				ana.temporaryHealth === 20 && pawn.temporaryHealth === 8,
				ana.temporaryHealth + " / " + pawn.temporaryHealth);

			// ...and the turn-end half pays out the WHOLE side's banked wall, once, to every enemy.
			// Given headroom first, or an overkill would floor at 0 and hide the figure being tested.
			const banked = ana.temporaryHealth + pawn.temporaryHealth;
			const enemyArray = hc.livingEntityArray("enemy", combat);
			for (const enemy of enemyArray) { enemy.maxHealth = 400; enemy.health = 400; enemy.temporaryHealth = 0; }
			hc.fireCombatHooks("onSideTurnResolved", hc.newEffectContext({ combat: combat }), "ally");
			check("Celestial Court throws the party's banked Temporary HP at every enemy",
				enemyArray.length > 0 && enemyArray.every((e) => 400 - e.health === banked),
				banked + " banked, enemies at " + enemyArray.map((e) => e.health).join(","));
		}

		// THE INFERNAL KING EATS THE BOARD AND ECHOES THE BEATING.
		startFight(32);
		{
			const combat = hc.state.run.combat;
			const ana = hc.state.run.partyArray[0];
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialRook" }, { combat: combat });
			const rook = piecesOf()[0];
			const fullHealth = rook.health;
			runEffects("anastasiaInfernalInvocation", ana, combat);
			check("every piece is halved", rook.health === fullHealth - Math.floor(fullHealth / 2),
				fullHealth + " -> " + rook.health);
			check("and she, who is not a piece, is untouched", ana.health === ana.maxHealth);
			check("she holds the Infernal Court instead", hc.statusStacks(ana, "infernalCourt") === 1);

			// The echo reads what the ENEMY side took, not the sum of each ally's damageDealtThisTurn --
			// otherwise the halving above (dealt BY her, TO her own piece) would echo back at the enemies.
			const target = hc.livingEntityArray("enemy", combat)[0];
			target.maxHealth = 400; target.health = 400;
			combat.enemyDamageTakenThisTurn = 0;
			hc.dealDamage(ana, target, 7, {}, aimed(target));
			check("only what the enemies took is counted", combat.enemyDamageTakenThisTurn === 7,
				String(combat.enemyDamageTakenThisTurn));
			// AN ECHO MAY NOT FEED THE COUNTER IT PAYS OUT OF. Found in the browser with both Kings in one
			// fight: the Celestial Court landed first, went into the count, and the Infernal Court echoed
			// the party's turn PLUS that hit. `echoed` on the damage entry is the general answer.
			hc.dealDamage(ana, target, 5, { echoed: true }, aimed(target));
			check("and an echo does not feed it", combat.enemyDamageTakenThisTurn === 7,
				String(combat.enemyDamageTakenThisTurn));
			const healthBefore = target.health;
			hc.fireCombatHooks("onSideTurnResolved", hc.newEffectContext({ combat: combat }), "ally");
			check("Infernal Court echoes the damage the side dealt this turn",
				healthBefore - target.health === 7, healthBefore + " -> " + target.health);
		}

		// WHICH KING ANSWERS IS THE BOARD'S ANSWER, and a tie goes Celestial.
		startFight(33);
		{
			const combat = hc.state.run.combat;
			const ana = hc.state.run.partyArray[0];
			const shuffled = () => {
				const context = hc.newEffectContext({ combat: combat, source: ana });
				hc.resolveEffectArray(hc.findDefinition(hc.abilityArray, "anastasiaKingsInvocation").effectArray, context);
				return context.log.map((e) => e.card).filter((c) => c != null).pop();
			};
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
			hc.summonCombatant({ side: "ally", enemyIndex: "infernalPawn" }, { combat: combat });
			check("an even board calls the Celestial King", shuffled() === "anastasiaKingsInvocation", String(shuffled()));
			hc.summonCombatant({ side: "ally", enemyIndex: "infernalPawn" }, { combat: combat });
			check("an Infernal majority calls the Infernal King", shuffled() === "anastasiaInfernalInvocation", String(shuffled()));
		}

		// THE KINGS ARE NOT UNITS. "Is the king a real unit or not? He has a compendium entry."
		const kingArray = hc.enemyArray.filter((e) => (e.tagArray || []).indexOf("king") >= 0);
		check("both King entries are marked set dressing",
			kingArray.length === 2 && kingArray.every((e) => e.setDressing === true));
		check("and neither is counted among the enemies a profile can meet",
			hc.discovery.allIndexArray("enemy").every((index) => kingArray.every((k) => k.index !== index)));
		// TWO PROPS ON ONE SIDE DO NOT STAND IN THE SAME PLACE. Found in the browser with both Kings in
		// one fight: each is placed at its side's edge, so the second landed exactly on the first.
		check("how far a second backdrop prop steps inward is a tuning number",
			typeof hc.tuning.layout.backdropPropStepPercent === "number" && hc.tuning.layout.backdropPropStepPercent > 0,
			String(hc.tuning.layout.backdropPropStepPercent));
		{
			const scene = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
			const renderer = scene.slice(scene.indexOf("honeycomb.combatScene.renderBackdropProps = function"));
			check("and the renderer reads it rather than a literal",
				/backdropPropStepPercent/.test(renderer.slice(0, 1400)));
		}
		check("nothing in the content tables summons a King",
			hc.cardArray.every((c) => JSON.stringify(c.effectArray || []).indexOf('King"') < 0 ||
				JSON.stringify(c.effectArray).indexOf('"showBackdropProp"') >= 0));
	}

	// =============================================================== HER HEIRLOOM (session 47)
	// The last thing the in-development warning was asking for. It pays her for spending bodies, which is
	// the one thing her whole kit does and the one thing nothing else rewarded.
	{
		const heirloom = hc.findDefinition(hc.equipmentArray, "grandmastersPocketwatch");
		check("she has an heirloom, and it is hers alone",
			heirloom != null && heirloom.characterIndex === "anastasia");
		check("and she starts in it",
			(hc.findDefinition(hc.characterArray, "anastasia").startingEquipmentArray || []).indexOf("grandmastersPocketwatch") >= 0);
		check("its number is a named field, not a literal in the hook",
			typeof heirloom.temporaryAmount === "number");

		startFight(51);
		const combat = hc.state.run.combat;
		const ana = hc.state.run.partyArray[0];
		// A live party member carries its worn list directly; startingEquipmentArray is what fills it.
		ana.equipmentArray = ["grandmastersPocketwatch"];
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		const pawn = piecesOf()[1];
		const front = hc.livingEntityArray("ally", combat)[0];
		front.temporaryHealth = 0;
		hc.dealDamage(null, pawn, 999, { ignoresStrength: true }, aimed(pawn));
		check("a piece falling walls the ally in front",
			pawn.downed === true && front.temporaryHealth === heirloom.temporaryAmount,
			String(front.temporaryHealth));

		// Falsified: a CHARACTER going down is not a piece, and pays nothing.
		const before = hc.livingEntityArray("ally", combat)[0].temporaryHealth;
		hc.fireRunHooks("onAllyDowned", { entity: ana, context: aimed(ana) });
		check("a character going down is not a piece falling",
			hc.livingEntityArray("ally", combat)[0].temporaryHealth === before);
	}

	// =============================================================== SHE ANSWERS FOR HER PIECES (session 47)
	// Noodle: "Give anastasia a status that redirects lust golems would gain to her."
	{
		startFight(41);
		const combat = hc.state.run.combat;
		const ana = hc.state.run.partyArray[0];
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: combat });
		const pawn = piecesOf()[0];

		// Falsified first: with the status off, the Pawn takes its own Lust.
		hc.removeStatus(ana, "commandersBurden", null, aimed(ana));
		hc.gainLust(pawn, 6, {}, aimed(pawn));
		check("without the status a piece takes its own Lust", pawn.lust > 0, String(pawn.lust));

		pawn.lust = 0;
		const hers = ana.lust;
		hc.applyStatus(ana, "commandersBurden", 1, aimed(ana));
		hc.gainLust(pawn, 6, {}, aimed(pawn));
		check("with it, the piece takes none", pawn.lust === 0, String(pawn.lust));
		check("and she takes it instead", ana.lust > hers, hers + " -> " + ana.lust);
		check("Lust aimed at HER is untouched by the redirect", hc.gainLust(ana, 3, {}, aimed(ana)) > 0);
		check("her outfit is what puts it on, so a later costume need not",
			hc.findDefinition(hc.characterArray, "anastasia").outfitArray[0].hooks.onCombatStart != null);
		check("and the engine reads the FIELD, not the index",
			hc.findDefinition(hc.statusArray, "commandersBurden").absorbsGolemLust === true);
	}

	// =============================================================== HER BROKEN FORMS (session 47)
	// Noodle: "Please add Broken cards to anastasia. Starter deals damage to a random friendly piece.
	// Common sacrifices a pawn to reduce lust. Rare sets her lust to 5 below her HP (unusable if she's
	// below 5 hp)."
	{
		const brokenOf = (index) => hc.findDefinition(hc.cardArray, hc.brokenFormIndexFor(hc.findDefinition(hc.cardArray, index)));
		for (const [rank, index] of [["starter", "anastasiaAdvance"], ["common", "anastasiaInterpose"], ["rare", "anastasiaCheck"]]) {
			const broken = brokenOf(index);
			check("her " + rank + " has a broken form", broken != null && broken.rarity === "broken",
				broken == null ? "missing" : broken.index);
		}
		// SESSION 47 ROUND THREE changed what this asserts. It used to read "hits a piece at random" --
		// Noodle's first spec. He then rewrote the card: "Blunder should have no effect, instead dealing
		// damage to an enemy piece if unplayed at the end of your turn."
		check("the starter's broken form does nothing when played",
			brokenOf("anastasiaAdvance").effectArray.length === 0);
		check("`randomPiece` is a registered mode that only picks golems",
			hc.targetModeDefinition("randomPiece") != null);
		check("the common's still spends a Pawn",
			JSON.stringify(brokenOf("anastasiaInterpose").effectArray).indexOf('"loseHealth"') >= 0);

		// THE RARE SETS, both ways. Falsify: it has to be able to come DOWN as well as up, or it is a
		// drawback card and not the way back it was asked to be.
		startFight(42);
		const combat = hc.state.run.combat;
		const ana = hc.state.run.partyArray[0];
		const rare = brokenOf("anastasiaCheck");
		ana.health = 40;
		ana.lust = 90;
		hc.resolveEffectArray(rare.effectArray, aimed(ana));
		check("the rare brings her Lust DOWN to five under her health", ana.lust === 35, String(ana.lust));
		ana.lust = 2;
		hc.resolveEffectArray(rare.effectArray, aimed(ana));
		check("and up to it from below", ana.lust === 35, String(ana.lust));
		ana.health = 4;
		check("it cannot be played below 5 HP",
			hc.testCondition(rare.playableCondition, aimed(ana)) === false);
		ana.health = 5;
		check("and can at exactly 5", hc.testCondition(rare.playableCondition, aimed(ana)) === true);

		// A set is a SET: no in-fight modifier and no between-run weakness may bend it.
		check("setLust is its own verb, not a soothe", hc.findDefinition(hc.effectArray, "setLust") != null);

		// The warning report's list of what she is still missing should no longer name a broken form.
		const report = hc.warnings.report == null ? null : hc.warnings.report();
		const line = report == null ? "" : JSON.stringify(report);
		check("the in-development warning no longer asks for her broken forms",
			line.indexOf("starter broken form") < 0 && line.indexOf("common broken form") < 0 &&
			line.indexOf("rare broken form") < 0,
			line.slice(0, 200));
	}

	// =============================================================== her tree
	{
		const fresh = newEngine();
		const tree = fresh.findDefinition(fresh.characterArray, "anastasia").progressionTree;
		const other = fresh.findDefinition(fresh.characterArray, "clemence").progressionTree;
		check("she has a progression tree the size of everyone's",
			tree != null && tree.nodeArray.length === other.nodeArray.length, tree == null ? "none" : String(tree.nodeArray.length));
		const indexArray = tree.nodeArray.map((n) => n.index);
		check("every node index is hers and unique",
			indexArray.every((index) => /^ana/.test(index)) && new Set(indexArray).size === indexArray.length);
		check("every requirement names a node in her tree",
			tree.nodeArray.every((n) => (n.requiresArray || []).every((r) => indexArray.indexOf(r) >= 0)));
		check("her abilities are bought on it, A1 and A2",
			tree.nodeArray.filter((n) => n.abilityAdditionArray != null).map((n) => n.abilityAdditionArray[0].index).sort().join() ===
			"anastasiaKingsInvocation,anastasiaTransposition");
		check("and she no longer carries them from the start",
			fresh.findDefinition(fresh.characterArray, "anastasia").startingAbilityArray == null);
		const cardNamed = [];
		for (const node of tree.nodeArray) {
			for (const upgrade of node.starterUpgradeArray || []) cardNamed.push(upgrade.card);
			for (const entry of (node.cardAdditionArray || []).concat(node.cardRemovalArray || [])) cardNamed.push(entry.index);
			for (const entry of node.randomReplaceArray || []) cardNamed.push(entry.from);
		}
		// SESSION 47: the attack starter is anastasiaAdvance, not anastasiaCheck -- Check became a rare.
		check("every card her nodes touch is one of her two starters",
			cardNamed.length > 0 && cardNamed.every((index) => index === "anastasiaAdvance" || index === "anastasiaDevelop"),
			cardNamed.filter((index) => index !== "anastasiaAdvance" && index !== "anastasiaDevelop").join(","));
		const verbArray = [];
		for (const node of tree.nodeArray) {
			for (const upgrade of (node.starterUpgradeArray || []).concat(node.abilityUpgradeArray || [])) {
				for (const entry of (upgrade.addEffectArray || []).concat(upgrade.replaceEffectArray || []).concat(upgrade.effectArray || [])) verbArray.push(entry.index);
			}
		}
		check("and every effect they add is a registered verb",
			verbArray.length > 0 && verbArray.every((index) => fresh.findDefinition(fresh.effectArray, index) != null),
			verbArray.filter((index) => fresh.findDefinition(fresh.effectArray, index) == null).join(","));
		check("no wheel of hers switches Gambit off -- Call the King is paid in it",
			tree.nodeArray.every((n) => (n.abilityUpgradeArray || []).every((u) => u.disableMechanic !== true)));
		check("her rest option exists", tree.nodeArray.filter((n) => n.restOption != null)
			.every((n) => fresh.findDefinition(fresh.restOptionArray, n.restOption) != null));
	}

	// =============================================================== Gambit, re-derived
	check("Call the King asks for no more Gambit than the bar can hold",
		hc.tuning.chessmaster.kingInvocation.pawnRequirement <= hc.tuning.chessmaster.gambit.maximum);
	check("and the mechanic's ceiling is the tuning entry, not a literal",
		hc.findDefinition(hc.mechanicArray, "gambit").maximum === hc.tuning.chessmaster.gambit.maximum);
	check("King's Invocation costs what tuning says",
		hc.findDefinition(hc.cardArray, "anastasiaKingsInvocation").costArray.energy === hc.tuning.chessmaster.kingInvocation.baseCost);
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[115] Session 47 -- hover carried across a repaint: the hand bounce and the fighter shrink-and-grow");
{
	// The scene file is not loaded by the suite, so the carry object is lifted out of the source and run
	// against a DOM small enough to read: elements that hold a class list and nothing else.
	const combat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
	const css = fs.readFileSync(path.join(ROOT, "..", "css", "honeycomb.css"), "utf8");
	const objectStart = combat.indexOf("honeycomb.combatScene.carriedHover = {");
	const objectEnd = combat.indexOf("\n};", objectStart);
	check("the scene declares carriedHover", objectStart >= 0 && objectEnd > objectStart);

	const makeElement = () => {
		const classSet = new Set();
		return { classSet, classList: { add: (name) => classSet.add(name), remove: (name) => classSet.delete(name), contains: (name) => classSet.has(name) } };
	};
	const elementArray = [];
	let queryCount = 0;
	const sandbox = { honeycomb: { combatScene: {}, rootElement: () => ({
		querySelectorAll: (selector) => { queryCount += 1; return elementArray.filter((element) => element.classSet.has(selector.slice(1))); },
	}) } };
	vm.runInNewContext(combat.slice(objectStart, objectEnd + 3), sandbox);
	const carried = sandbox.honeycomb.combatScene.carriedHover;

	// THE REGRESSION ITSELF. Two repaints inside one frame: the second finds a hand that is marked but
	// not yet `:hover`. Asking `:hover` alone carried nothing the second time and the hand sank.
	check("the hand counts as hovered when it is `:hover` OR already carrying the mark",
		/\.hcHand:hover/.test(carried.handSelector) && carried.handSelector.indexOf(".hcHand." + carried.handClass) >= 0, carried.handSelector);
	check("and so does a fighter",
		/\.hcFighter:hover/.test(carried.fighterSelector) && carried.fighterSelector.indexOf(".hcFighter." + carried.fighterClass) >= 0, carried.fighterSelector);

	const hand = makeElement(), fighter = makeElement();
	elementArray.push(hand, fighter);
	carried.release();
	check("a pointer move with nothing carried touches no DOM", queryCount === 0, String(queryCount));
	carried.mark(null, "handClass");
	check("marking an element that is not there arms nothing", carried.active === false);
	carried.mark(hand, "handClass");
	carried.mark(fighter, "fighterClass");
	check("mark puts the class on and arms the release",
		hand.classSet.has(carried.handClass) && fighter.classSet.has(carried.fighterClass) && carried.active === true);
	carried.release();
	check("the next pointer move hands the question back to `:hover`",
		hand.classSet.size === 0 && fighter.classSet.size === 0 && carried.active === false);

	// The wiring, read from source.
	const repaint = combat.slice(combat.indexOf("honeycomb.combatScene.repaint = function"), combat.indexOf("//Log replay"));
	check("repaint asks the OLD battlefield who was hovered before replacing it",
		repaint.indexOf("carriedHover.fighterSelector") >= 0 &&
		repaint.indexOf("carriedHover.fighterSelector") < repaint.indexOf("battlefield.innerHTML"));
	check("and marks the rebuilt fighter", /carriedHover\.mark\([^;]*"fighterClass"\)/.test(repaint));
	check("the hand is asked through the same selector, not `:hover` alone",
		repaint.indexOf("carriedHover.handSelector") >= 0 && /querySelector\("\.hcHand:hover"\)/.test(repaint) === false);
	check("the scene shell releases the mark on a pointer move",
		/onpointermove="honeycomb\.combatScene\.carriedHover\.release\(\)"/.test(combat));
	check("the stylesheet steps a carried fighter forward exactly as a hovered one",
		css.indexOf(".hcFighter." + carried.fighterClass + ":not(.hcFocusFull)") >= 0);
	// THE HAND NO LONGER SINKS AT ALL (2026-09-21), so there is nothing for a carried mark to hold up.
	// This used to check that the resting-drop rule excused a carried hand -- `:not(.hcHandRaised)`.
	// The resting drop is gone: the hand stays where it is played from, in full colour, whether or not
	// a pointer is over it, so a repaint under a still pointer has nothing to bounce. The hand is still
	// marked and released alongside the fighter, and the checks above hold that machinery in place.
	check("the hand has no resting drop left to carry it through",
		css.indexOf("transform: translateY(var(--hc-hand-resting-drop") < 0);
}

console.log("\n[116] Session 48 -- a profile from before the queue, carried across");
{
	const hc = newEngine();
	// A save written under the old system: the event a rank-up raised was FROZEN onto the record, how far
	// the story had come was a count, and which scenes had actually been played was lustEventSeenArray.
	// Only that last one survives the change, and it is the one that matters -- a player must not be handed
	// a scene twice. See the toVersion 10 step of honeycomb.save.migrationArray.
	const shippedQueue = hc.lustEventQueueArray.slice();
	hc.lustEventQueueArray.length = 0;
	[
		{ index: "nettleVenom1", character: "nettle", tag: "venom", rank: 1, event: "lustEventFirstStirring" },
		{ index: "nettleVenom2", character: "nettle", tag: "venom", rank: 2, event: "lustEventTrial" },
		{ index: "anyCharm1", character: "any", tag: "charm", rank: 1, event: "lustEventUndone" },
	].forEach((row) => hc.lustEventQueueArray.push(row));

	const legacy = {
		formatVersion: 9,
		profile: {
			unlockedCharacterArray: ["nettle", "severine"],
			lustExposureArray: { nettle: { venom: hc.tuning.lust.exposureRankArray[1].atOrAbove } },
			lustEventSeenArray: ["nettle/venom/1", "severine/charm/1"],
			lustEventTally: { completed: { total: 2, character: { nettle: 1 }, tag: {}, characterTag: {} } },
			lustMilestoneFiredArray: ["total, 1, lustEventFirstStirring"],
			lustRankUpArray: {
				nettle: [{ id: 1, tag: "venom", rank: 2, eventIndex: "lustEventTrial", source: "list", trigger: null, backfilled: true }],
			},
			lustRankUpCounter: 1,
		},
		run: { lustBattle: { subject: "nettle", lustEntryId: 1 }, partyArray: [] },
	};
	check("it migrates, and lands on the current format version",
		hc.save.migrate(legacy) === true && legacy.formatVersion === hc.tuning.save.formatVersion &&
		hc.tuning.save.formatVersion === 10);
	check("every scene the player actually played through becomes a completed ROW",
		JSON.stringify(legacy.profile.lustEventDoneArray) === JSON.stringify(["nettleVenom1", "anyCharm1/severine"]),
		"done: " + JSON.stringify(legacy.profile.lustEventDoneArray));
	check("the count, the fired milestones and the seen keys are gone",
		legacy.profile.lustEventTally === undefined && legacy.profile.lustMilestoneFiredArray === undefined &&
		legacy.profile.lustEventSeenArray === undefined);
	check("a rank-up record keeps its rank and loses the event frozen onto it", (() => {
		const record = legacy.profile.lustRankUpArray.nettle[0];
		return record.rank === 2 && record.tag === "venom" && record.eventIndex === undefined &&
			record.source === undefined && record.trigger === undefined && record.backfilled === undefined;
	})());
	check("a Lust Battle in flight is dropped: its continuation named a record id that no longer exists",
		legacy.run === null);

	// And now the point of all of it: the migrated profile is offered what it is still owed, and nothing else.
	hc.state = { profile: legacy.profile, run: null };
	check("the scene already played is not offered again",
		hc.lustEvents.isDone(hc.lustEvents.findEntry("nettleVenom1"), "nettle") === true &&
		hc.lustEvents.queueFor("nettle").map((entry) => entry.index).join() === "nettleVenom2");
	check("and a character who had seen the fanned-out row is not offered it a second time",
		hc.lustEvents.queueFor("severine").length === 0);
	check("while the rank-up notification it kept still reads as one",
		hc.lustEvents.characterState("nettle") === "eventReady" &&
		hc.lustEvents.tagState("nettle", "venom") === "rankUp");

	hc.lustEventQueueArray.length = 0;
	shippedQueue.forEach((row) => hc.lustEventQueueArray.push(row));
}

console.log("\n[117] Session 47 -- ui/ B29 the debug shortcuts, B32 the enemy title");
{
	// Neither file is loaded headlessly, so the shortcut renderer is lifted out of the source and run
	// against a two-entry table, and the wiring is read as text.
	const title = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-title.js"), "utf8");
	const ui = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-ui.js"), "utf8");
	const css = fs.readFileSync(path.join(ROOT, "..", "css", "honeycomb.css"), "utf8");

	const start = title.indexOf("honeycomb.debug.shortcutMarkup = function");
	const end = title.indexOf("\n};", start);
	check("the debug table has a shortcut renderer", start >= 0 && end > start);
	let inFight = true;
	const sandbox = { honeycomb: {
		debug: {}, tuning: { debug: { enabled: true } },
		escapeAttribute: (text) => String(text), escapeText: (text) => String(text),
		ui: { iconTag: () => "<i></i>" },
		debugActionArray: [
			{ index: "winFight", name: "Win", glyph: "star", color: "#fff", quick: true, topBar: true, available: () => inFight },
			{ index: "loseFight", name: "Lose", glyph: "skull", color: "#fff", quick: true, available: () => inFight },
			{ index: "wipeSaves", name: "Wipe", glyph: "skull", color: "#fff" },
		],
	} };
	vm.runInNewContext(title.slice(start, end + 3), sandbox);
	// Session 57: the renderer skips a `secret` action through honeycomb.debug.actionHidden, lifted the same way.
	const hiddenStart = title.indexOf("honeycomb.debug.actionHidden = function");
	vm.runInNewContext(title.slice(hiddenStart, title.indexOf("\n};", hiddenStart) + 3), sandbox);
	const shortcut = sandbox.honeycomb.debug.shortcutMarkup;
	const count = (markup, needle) => markup.split(needle).length - 1;

	check("in a fight the top bar draws exactly the actions that asked for it",
		count(shortcut("topBar"), "honeycomb.debug.run(") === 1 && shortcut("topBar").indexOf("'winFight'") >= 0, shortcut("topBar"));
	check("and the panel pins every quick action in one row",
		count(shortcut("quick"), "honeycomb.debug.run(") === 2 && count(shortcut("quick"), "hcDebugQuickRow") === 1);
	check("an action that asked for nothing is drawn in neither place",
		shortcut("topBar").indexOf("wipeSaves") < 0 && shortcut("quick").indexOf("wipeSaves") < 0);
	inFight = false;
	check("outside a fight nothing is drawn -- no empty row, no dead button",
		shortcut("topBar") === "" && shortcut("quick") === "");
	inFight = true;
	sandbox.honeycomb.tuning.debug.enabled = false;
	check("and a release build, with the debug switch off, draws none of it",
		shortcut("topBar") === "" && shortcut("quick") === "");

	const winEntry = title.slice(title.indexOf('index: "winFight"'), title.indexOf('index: "loseFight"'));
	check("Win the current battle is one press from the fight", /quick: true/.test(winEntry) && /topBar: true/.test(winEntry));
	check("the top bar asks the debug table rather than naming an action", /honeycomb\.debug\.shortcutMarkup\("topBar"\)/.test(ui));
	check("the panel draws the quick row ABOVE the pickers",
		title.indexOf('shortcutMarkup("quick")') > 0 && title.indexOf('shortcutMarkup("quick")') < title.indexOf("//Encounter picker for the test-battle button."));
	const runBody = title.slice(title.indexOf("honeycomb.debug.run = function"), title.indexOf("//SHORTCUTS TO DEBUG ACTIONS"));
	check("a press re-checks availability, since no panel stood between it and the action", /action\.available\(\) != true\) return/.test(runBody));
	check("and a top-bar press waits for a replay", /combatScene\.busy == true\) return/.test(runBody));

	// B32. The rule is sliced out so a neighbour's declarations cannot satisfy the checks.
	const feetStart = css.indexOf(".hcFighterFeetName {");
	const feetRule = css.slice(feetStart, css.indexOf("}", feetStart));
	check("the stylesheet defines a title shadow beside the text shadow", /--hc-title-shadow:/.test(css));
	const tokenStart = css.indexOf("--hc-title-shadow:");
	const token = css.slice(tokenStart, css.indexOf(";", tokenStart));
	check("with a rim on all four diagonals and two halos behind it",
		count(token, " 0 #000") === 5 && count(token, "rgba(0, 0, 0") === 2, token);
	check("the enemy's name wears it", /text-shadow: *var\(--hc-title-shadow\)/.test(feetRule), feetRule);
	check("and wraps instead of being cut with an ellipsis",
		/white-space: *normal/.test(feetRule) && /text-overflow/.test(feetRule) === false && /overflow: *hidden/.test(feetRule) === false, feetRule);
	check("the name keeps its size -- a bigger font only cut more of them", /font-size: *var\(--hc-fs-tiny\)/.test(feetRule));
}

