	check("the same boss summoned to the party takes a place in the row", anchorOf({ enemyIndex: "matriarch", side: "ally", placement: back }) === null);
	check("a character stood on the enemy line is not anchored either", anchorOf({ characterIndex: "brienne", side: "enemy", placement: back }) === null);
	check("and nobody without a placement is anchored", anchorOf({ enemyIndex: "sporeling", side: "enemy" }) === null && anchorOf(null) === null);

