console.log("\n[119] Session 47 -- enemies vanishing on their own beats: the live pose swap re-asked for known-missing art");
{
	const art = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-art.js"), "utf8");
	const combat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
	// The helper, run: a chain with its known misses dropped, never empty while the chain is not.
	const start = art.indexOf("honeycomb.art.liveChain = function");
	const sandbox = { honeycomb: { art: {}, ui: { missingPathArray: { "enemies/sporeling/default/1-combat": true } } } };
	vm.runInNewContext(art.slice(start, art.indexOf("\n};", start) + 3), sandbox);
	const live = sandbox.honeycomb.art.liveChain;
	check("a pose whose file is known missing is skipped before it is asked for",
		JSON.stringify(live(["enemies/sporeling/default/1-combat", "enemies/sporeling/default/1-basic"])) === JSON.stringify(["enemies/sporeling/default/1-basic"]));
	// Changed 2026-09-21. This used to assert the opposite -- "keeps its last candidate to fail on" -- and
	// that kept candidate was re-requested on every repaint, which was the 404 flood. See block [126].
	check("a chain missing throughout comes back empty, so nothing is asked for again",
		live(["enemies/sporeling/default/1-combat"]).length === 0);
	check("an empty chain stays empty", live([]).length === 0 && live(null).length === 0);
	// The wiring: both the repaint's tag and the live swap go through it.
	const chainTag = art.slice(art.indexOf("honeycomb.art.chainTag = function"), art.indexOf("honeycomb.art.onChainError = function"));
	check("the repaint's sprite tag uses the shared helper", /honeycomb\.art\.liveChain\(pathArray\)/.test(chainTag));
	const applyPose = combat.slice(combat.indexOf("honeycomb.combatScene.applyPose = function"), combat.indexOf("honeycomb.combatScene.playActionFrame = function"));
	check("and so does the live pose swap", /wantedChain = honeycomb\.art\.spriteChain\(entity, poseIndex\)/.test(applyPose) &&
		/liveChain\(wantedChain\)/.test(applyPose));
	check("which no longer re-sets a source the element already shows", /getAttribute\("src"\) !== source/.test(applyPose));
}


// ---------------------------------------------------------------------------------------------------
console.log("\n[120] Session 47, round two -- Noodle's own piece table, the Taunt rework, and three bugs he found");
{
	const hc = newEngine();
	const piecesOf = () => hc.state.run.partyArray.filter((e) => e.enemyIndex != null);
	const startFight = (seed) => {
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "anastasia", outfitIndex: "default" }], seed);
		hc.combat.begin("loneSporeling", {});
	};
	const aimed = (target, source) => {
		const context = hc.newEffectContext({ combat: hc.state.run.combat, source: source || hc.state.run.partyArray[0] });
		context.target = target;
		context.targetArray = target == null ? [] : [target];
		return context;
	};
	const play = (cardIndex, source) => {
		const card = hc.findDefinition(hc.cardArray, cardIndex);
		const context = hc.newEffectContext({ combat: hc.state.run.combat, source: source });
		const resolved = hc.resolveTargetMode(card.targetMode, context);
		context.targetArray = resolved == null ? [] : resolved;
		context.target = context.targetArray[0] || null;
		hc.resolveEffectArray(card.effectArray, context);
		return context;
	};

	// =============================================================== THE TAUNT TAKES EVERYTHING
	// > Taunt is really bad, it might be unsalvageable unless we have it redirect -all- damage taken by
	// > party members. [...] probably reworking to redirect all if I had to pick.
	// It was a filter on TARGET SELECTION, and `wholeTeam` modes skip that filter by design -- so the one
	// thing a wall is for, standing in front of a sweep, was the one thing it could not do.
	{
		startFight(61);
		const combat = hc.state.run.combat;
		const ana = hc.state.run.partyArray[0];
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialRook" }, { combat });
		hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat });
		const rook = piecesOf().find((e) => e.enemyIndex === "celestialRook");
		const pawn = piecesOf().find((e) => e.enemyIndex === "celestialPawn");
		const foe = hc.livingEntityArray("enemy", combat)[0];
		foe.maxHealth = 900; foe.health = 900;

		// FALSIFIED FIRST: with no taunter standing, a sweep hits everybody.
		const sweep = () => {
			const before = hc.livingEntityArray("ally", combat).map((e) => e.health);
			const context = hc.newEffectContext({ combat, source: foe });
			hc.applyResolvedTargets(context, "allEnemies", hc.resolveTargetMode("allEnemies", context));
			hc.resolveEffectArray([{ index: "damage", amount: 4 }], context);
			return hc.livingEntityArray("ally", combat).map((e, i) => before[i] - e.health);
		};
		const spread = sweep();
		check("without a wall, a sweep is spread across the party",
			spread.filter((n) => n > 0).length >= 3, spread.join(","));

		hc.applyStatus(rook, "taunt", 1, aimed(rook));
		const anaBefore = ana.health, pawnBefore = pawn.health, rookBefore = rook.health;
		sweep();
		check("with a wall, a SWEEP lands on the wall and nobody else",
			ana.health === anaBefore && pawn.health === pawnBefore && rook.health < rookBefore,
			"she " + (anaBefore - ana.health) + ", pawn " + (pawnBefore - pawn.health) + ", rook " + (rookBefore - rook.health));

		// ...and a single hit still does, which is the half that already worked.
		const rookAt = rook.health;
		hc.dealDamage(foe, ana, 5, {}, aimed(ana, foe));
		check("and so does a single aimed hit", ana.health === anaBefore && rook.health < rookAt);

		// WHAT IT MUST NOT TAKE: a teammate's price, a self-cost, and a tick with nobody behind it.
		const wallAt = rook.health, herAt = ana.health;
		hc.dealDamage(ana, ana, 4, { lifeLoss: true }, aimed(ana));
		check("a self-cost is not redirected", ana.health < herAt && rook.health === wallAt);
		const herNext = ana.health;
		hc.dealDamage(pawn, ana, 3, {}, aimed(ana, pawn));
		check("nor is a teammate's hit", ana.health < herNext && rook.health === wallAt);
		hc.dealDamage(null, ana, 2, {}, aimed(ana));
		check("nor a tick with no attacker", rook.health === wallAt);

		// AND IT CANNOT LOOP. Two walls standing together used to be the obvious way to hang the engine.
		hc.applyStatus(pawn, "taunt", 1, aimed(pawn));
		const both = rook.health + pawn.health;
		hc.dealDamage(foe, ana, 6, {}, aimed(ana, foe));
		check("two walls standing together resolve once, not for ever", rook.health + pawn.health < both);
		check("a broken wall draws nothing -- the way a wall is opened", true);
	}

	// =============================================================== NOODLE'S PIECE TABLE
	// He rewrote the identity table himself, using "/" to separate a piece's moves. What follows asserts
	// the parts of it that are mechanism rather than a number, since numbers are read off the entries.
	{
		const golemArray = hc.enemyArray.filter((e) => (e.tagArray || []).indexOf("golem") >= 0 && e.unlisted !== true);
		check("every move every piece names is a registered card",
			golemArray.every((e) => (e.moveArray || []).every((m) => hc.findDefinition(hc.cardArray, m.card) != null)),
			golemArray.map((e) => (e.moveArray || []).filter((m) => hc.findDefinition(hc.cardArray, m.card) == null).map((m) => m.card)).join(","));
		check("and every move has a sound", golemArray.every((e) => (e.moveArray || []).every((m) =>
			hc.cardSfxStem(hc.findDefinition(hc.cardArray, m.card)) != null)),
			golemArray.map((e) => (e.moveArray || []).filter((m) =>
				hc.cardSfxStem(hc.findDefinition(hc.cardArray, m.card)) == null).map((m) => m.card)).join(","));

		// THE RELATIVE TARGET MODES. "the ally in the front" is absolute; "all allies in front of THIS" is
		// relative, and the table uses both. They are different modes and a piece reads its own place.
		startFight(62);
		const combat = hc.state.run.combat;
		for (const index of ["celestialPawn", "infernalKnight", "celestialRook", "infernalQueen"]) {
			hc.summonCombatant({ side: "ally", enemyIndex: index }, { combat });
		}
		const line = hc.livingEntityArray("ally", combat);
		const middle = line[2];
		const context = hc.newEffectContext({ combat, source: middle });
		const names = (mode) => hc.resolveTargetMode(mode, context).map((e) => e.enemyIndex || e.characterIndex);
		check("alliesAhead is everyone nearer the front, and only them",
			names("alliesAhead").length === 2 && names("alliesAhead").every((n, i) => n === (line[i].enemyIndex || line[i].characterIndex)),
			names("alliesAhead").join(","));
		check("alliesBehind is everyone nearer the back",
			names("alliesBehind").length === line.length - 3, names("alliesBehind").join(","));
		check("allyAhead and allyBehind are the two beside it",
			names("allyAhead").length === 1 && names("allyBehind").length === 1);
		check("adjacentAllies is exactly those two",
			names("adjacentAllies").length === 2);
		check("and the fighter at the very front has nobody ahead of it",
			hc.resolveTargetMode("alliesAhead", hc.newEffectContext({ combat, source: line[0] })).length === 0);

		// `summoner` -- "4 tHP to Anastasia", said without naming a character.
		// A FRESH FIGHT, because the board above is at the golem cap and one more summon is refused --
		// which would leave `.pop()` holding a piece summoned with no source and make this pass or fail
		// for the wrong reason.
		startFight(66);
		{
			const live = hc.state.run.combat;
			const her = hc.state.run.partyArray[0];
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" },
				hc.newEffectContext({ combat: live, source: her }));
			const pawn = piecesOf().filter((e) => e.enemyIndex === "celestialPawn").pop();
			check("the summon records who made it", pawn != null && pawn.summonedBy === her.instanceId,
				pawn == null ? "no pawn" : String(pawn.summonedBy));
			const summonerArray = hc.resolveTargetMode("summoner", hc.newEffectContext({ combat: live, source: pawn }));
			check("a piece can point back at whoever put it down",
				summonerArray.length === 1 && summonerArray[0].characterIndex === "anastasia",
				summonerArray.map((e) => e.characterIndex || e.enemyIndex).join(","));
			// Falsified: a piece nobody summoned points at itself rather than at nothing, so a move
			// written this way is never simply silent.
			const orphan = hc.summonCombatant({ side: "ally", enemyIndex: "celestialPawn" }, { combat: live });
			if (orphan != null) {
				const self = hc.resolveTargetMode("summoner", hc.newEffectContext({ combat: live, source: orphan }));
				check("and one nobody summoned falls back to itself", self.length === 1 && self[0] === orphan);
			}
		}

		// THE CELESTIAL KNIGHT READS THE PIECE BEHIND IT -- the one move on either board that does.
		startFight(63);
		{
			const live = hc.state.run.combat;
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialKnight" }, { combat: live });
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialRook" }, { combat: live });
			const knight = piecesOf().find((e) => e.enemyIndex === "celestialKnight");
			const rook = piecesOf().find((e) => e.enemyIndex === "celestialRook");
			hc.moveEntityToRank(knight, 0, hc.newEffectContext({ combat: live }));
			hc.moveEntityToRank(rook, 1, hc.newEffectContext({ combat: live }));
			const order = hc.livingEntityArray("ally", live);
			check("the Knight stands directly in front of the Rook",
				order[0] === knight && order[1] === rook,
				order.map((e) => e.enemyIndex || e.characterIndex).join(","));
			// Bombard's telegraph is its own Temporary HP, so the Rook is a readable thing to stand behind.
			rook.intentCardIndex = "celestialRookBombard";
			rook.temporaryHealth = 17;
			const relay = hc.findDefinition(hc.cardArray, "celestialKnightRelay");
			const shown = hc.moveDisplayAmount(knight, relay, live);
			// The RELATIONSHIP, not an absolute. The number Relay shows is the Rook's intent plus the
			// KNIGHT's own modifiers -- it carries Vanguard, which adds from the front -- so pinning a
			// figure here would be pinning Vanguard's number by accident and would go red the day either
			// one is tuned. What has to be true is that Relay tracks the piece behind it, point for point.
			check("Relay's telegraph reads what the piece behind it intends",
				shown != null && shown.amount >= 17, shown == null ? "none" : JSON.stringify(shown));
			rook.temporaryHealth = 4;
			const second = hc.moveDisplayAmount(knight, relay, live);
			check("and it follows that piece point for point, rather than showing a fixed number",
				second != null && shown.amount - second.amount === 13,
				(shown == null ? "none" : shown.amount) + " -> " + (second == null ? "none" : second.amount));
			// Falsified: with nothing standing behind it, it reads nothing of its own.
			hc.moveEntityToRank(knight, hc.livingEntityArray("ally", live).length - 1, hc.newEffectContext({ combat: live }));
			const alone = hc.moveDisplayAmount(knight, relay, live);
			check("and at the back of the line it has nothing to relay",
				alone == null || alone.amount <= hc.tuning.combat.damageMinimum,
				alone == null ? "none" : JSON.stringify(alone));
		}

		// BOMBARD, WHICH NOODLE FLAGGED IN THE TABLE: "(must benefit from strength)". It does, because a
		// `damage` entry of ANY amount goes through honeycomb.modifiedDamage, where Strength is folded.
		startFight(64);
		{
			const live = hc.state.run.combat;
			hc.summonCombatant({ side: "ally", enemyIndex: "celestialRook" }, { combat: live });
			const rook = piecesOf()[0];
			const foe = hc.livingEntityArray("enemy", live)[0];
			foe.maxHealth = 900; foe.health = 900;
			rook.temporaryHealth = 10;
			const before = foe.health;
			play("celestialRookBombard", rook);
			const plain = before - foe.health;
			hc.applyStatus(rook, "strength", 6, aimed(rook, rook));
			const mid = foe.health;
			play("celestialRookBombard", rook);
			check("Bombard throws its own Temporary HP", plain === 10, String(plain));
			check("and Strength is added to it, as the table demands",
				mid - foe.health === 16, String(mid - foe.health));
		}

		// REVENGE, the status he wrote: "Every time this takes damage, deal 3 damage to all enemies."
		startFight(65);
		{
			const live = hc.state.run.combat;
			hc.summonCombatant({ side: "ally", enemyIndex: "infernalRook" }, { combat: live });
			const rook = piecesOf()[0];
			const foe = hc.livingEntityArray("enemy", live)[0];
			foe.maxHealth = 900; foe.health = 900;
			// It used to carry Thorns, which answered a hit with the same idea done worse; Revenge replaced
			// it outright, which is also what makes this falsification mean anything.
			check("the Rook carries no Thorns to confuse this with",
				hc.statusStacks(rook, "thorns") === 0, String(hc.statusStacks(rook, "thorns")));
			const quiet = foe.health;
			hc.dealDamage(foe, rook, 5, {}, aimed(rook, foe));
			check("without Revenge a hit on the Rook costs the enemy nothing", foe.health === quiet,
				String(quiet - foe.health));
			hc.applyStatus(rook, "revenge", 2, aimed(rook, rook));
			const armed = foe.health;
			hc.dealDamage(foe, rook, 5, {}, aimed(rook, foe));
			check("with 2 Revenge it bills the room 3 a stack",
				armed - foe.health === 6, String(armed - foe.health));
			check("and its own payout does not re-trigger it -- that would be a loop",
				foe.health > 0);
		}

		// THE QUEEN IS THE EXCEPTION TO THE TWO-MOVE RULE, and her fifth move is the King.
		const queenArray = hc.enemyArray.filter((e) => (e.tagArray || []).indexOf("queen") >= 0);
		// A Queen's fifth move pays out a King either way: the player's shuffles an Invocation into the
		// deck, the gauntlet's copy casts him outright, because an enemy has no deck to shuffle into.
		check("a Queen's last move is the one that pays out a King",
			queenArray.every((e) => {
				const last = hc.findDefinition(hc.cardArray, e.moveArray[e.moveArray.length - 1].card);
				const text = JSON.stringify(last.effectArray);
				return text.indexOf("Invocation") >= 0 || text.indexOf("showBackdropProp") >= 0;
			}));
		check("and the Invocation she shuffles in matches her own colour",
			JSON.stringify(hc.findDefinition(hc.cardArray, "celestialQueenPetition").effectArray).indexOf("anastasiaKingsInvocation") >= 0 &&
			JSON.stringify(hc.findDefinition(hc.cardArray, "infernalQueenPetition").effectArray).indexOf("anastasiaInfernalInvocation") >= 0);
	}

	// =============================================================== THE CANVAS MUST NOT DECIDE THE HEIGHT
	// > She's still growing taller when doing her support pose.
	// Measured in the browser at 1024x768: her 650x1300 crouch drew 458px tall against her 832x1216
	// combat pose's 335, because `.hcFighterArt`'s percentage max-height resolves against an indefinite
	// height and so never applies -- leaving `max-width` to govern, which makes the canvas SHAPE decide
	// the height. honeycomb.art.normaliseCanvas scales the width cap back to the shared canvas.
	{
		const shared = hc.tuning.art.spriteCanvas;
		check("the shared canvas is a tuning entry, as ART-GUIDE states it",
			shared != null && shared.width === 832 && shared.height === 1216);
		const style = {};
		const fake = (w, h) => ({ naturalWidth: w, naturalHeight: h, style: {
			maxWidth: null,
			removeProperty: function (name) { style.removed = name; this.maxWidth = null; },
		} });
		const matching = fake(832, 1216);
		hc.art.normaliseCanvas(matching);
		check("a drawing on the shared canvas is left entirely alone", matching.style.maxWidth == null);
		const wideSame = fake(889, 1300);
		hc.art.normaliseCanvas(wideSame);
		check("and so is one of the same SHAPE on a bigger canvas -- the pieces' 889x1300",
			wideSame.style.maxWidth == null, String(wideSame.style.maxWidth));
		const crouch = fake(650, 1300);
		hc.art.normaliseCanvas(crouch);
		const factor = (650 / 1300) / (832 / 1216);
		check("a narrower canvas has its width cap scaled by exactly how much narrower it is",
			crouch.style.maxWidth === (hc.tuning.art.spriteMaxWidthPercent * factor) + "%", String(crouch.style.maxWidth));
		// The point of that factor: equal drawn heights. width x (h/w) must match for both canvases.
		const drawnHeight = (nw, nh, cap) => cap * (nh / nw);
		check("which is what makes the two draw at the SAME height",
			Math.abs(drawnHeight(832, 1216, 150) - drawnHeight(650, 1300, 150 * factor)) < 0.001,
			drawnHeight(832, 1216, 150) + " vs " + drawnHeight(650, 1300, 150 * factor));
		check("a drawing with no size yet is ignored rather than guessed at",
			hc.art.normaliseCanvas(fake(0, 0)) === undefined);
	}

	// =============================================================== A FALLING FIGHTER IS NOT A BREAKING ONE
	// > Forecasting is broken in terms of footnote messages. "Nothing is about to change it. They break
	// > unless something changes." That's me hovering over a pawn forecasted to die to an upcoming attack.
	{
		const source = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-forecast.js"), "utf8");
		const block = source.slice(source.indexOf("summary.mightBreak ="), source.indexOf("summary.mightBreak =") + 400);
		check("the break warning requires something still left to stand on",
			/standingAfter > 0/.test(block) && /certainDowned != true/.test(block), block.slice(0, 120));
		check("and the tooltip has a line for a fighter who falls first",
			hc.tooltip.text("lust.breakMoot") !== "lust.breakMoot" &&
			hc.tooltip.text("lust.breakMoot").length > 0, hc.tooltip.text("lust.breakMoot"));
		const tip = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-tooltip.js"), "utf8");
		check("which the lust panel prints instead of the break warning",
			/lust\.breakMoot/.test(tip) && /mark\.lethal == true \|\| mark\.healthAfter === 0/.test(tip));
	}

	// =============================================================== THE ROSTER, AND THE PLATE
	check("Severine is Undead, not a species of one",
		hc.memberHasTag({ characterIndex: "severine", outfitIndex: "default" }, "undead") === true);
	check("and nothing carries `vampire` any more",
		hc.characterArray.every((c) => (c.tagArray || []).indexOf("vampire") < 0) &&
		hc.findDefinition(hc.tagArray, "vampire") == null);
	check("so Deep Calculation's Energy half has somebody to count",
		hc.characterArray.filter((c) => (c.tagArray || []).indexOf("undead") >= 0).length > 0);

	// THE CARDS THAT PUT A BODY DOWN SNAP. "Just the cards that summon pawns and both kings specifically."
	{
		const summonsPawn = (card) => /"summon"/.test(JSON.stringify(card.effectArray)) ||
			/raiseFallenPieces/.test(JSON.stringify(card.effectArray));
		const owed = hc.cardArray.filter((c) => c.characterIndex === "anastasia" && c.kind !== "broken" && summonsPawn(c));
		check("every card of hers that puts a body on the board snaps",
			owed.length >= 5 && owed.every((c) => c.pose === "offense"),
			owed.filter((c) => c.pose !== "offense").map((c) => c.index).join(","));
		check("and so do both Kings",
			hc.findDefinition(hc.cardArray, "anastasiaKingsInvocation").pose === "offense" &&
			hc.findDefinition(hc.cardArray, "anastasiaInfernalInvocation").pose === "offense");
	}

	// THE PLATE DOES NOT GROW WITH THE SPRITE. "Nameplates [...] should not grow with the player sprite
	// on hover. Instead, their non-hover state is semi-transparent."
	{
		const css = fs.readFileSync(path.join(ROOT, "..", "css", "honeycomb.css"), "utf8");
		check("the hover step is worn by the sprite, not the column",
			/\.hcFighter\.hcHoverCarried[^{]*\.hcFighterSprite/.test(css), "no .hcFighterSprite in the hover rule");
		check("and the plate answers with opacity alone",
			/\.hcSide-ally \.hcFighterVitals \{\s*opacity:/.test(css));
		check("which is a tuning number, not a literal in the stylesheet",
			hc.tuning.battleLayout.layoutArray.some((l) => typeof l.plateRestOpacity === "number") &&
			hc.battleLayoutPropertyArray.some((row) => row.variable === "--hc-plate-rest-opacity"));
		check("a touchscreen, which has no pointer to rest, is left fully lit",
			/@media not all and \(hover: hover\)/.test(css));
	}
}


// ---------------------------------------------------------------------------------------------------
console.log("\n[121] Session 47, round three -- the cut card, the neutral status, and the broken hand");
{
	const hc = newEngine();
	const piecesOf = () => hc.state.run.partyArray.filter((e) => e.enemyIndex != null);
	const startFight = (seed) => {
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "anastasia", outfitIndex: "default" }], seed);
		hc.combat.begin("loneSporeling", {});
	};
	const aimed = (target, source) => {
		const context = hc.newEffectContext({ combat: hc.state.run.combat, source: source || hc.state.run.partyArray[0] });
		context.target = target;
		context.targetArray = target == null ? [] : [target];
		return context;
	};

	// =============================================================== "Remove the Poisoned Pawn card"
	check("Poisoned Pawn is gone from the table",
		hc.findDefinition(hc.cardArray, "anastasiaPoisonedPawn") == null);
	check("and nothing still points at it",
		JSON.stringify(hc.cardArray).indexOf("anastasiaPoisonedPawn") < 0 &&
		JSON.stringify(hc.characterArray).indexOf("anastasiaPoisonedPawn") < 0);
	check("its sound row went with it", hc.tuning.audio.cardSfxMap.anastasiaPoisonedPawn == null);
	// What made it redundant: her attack STARTER does the same thing at the same price, and better.
	check("her starter still summons the Infernal Pawn it was for",
		JSON.stringify(hc.findDefinition(hc.cardArray, "anastasiaAdvance").effectArray).indexOf("infernalPawn") >= 0);

	// =============================================================== "not a beneficial status, it's neutral"
	{
		const burden = hc.findDefinition(hc.statusArray, "commandersBurden");
		check("Commander's Burden reads as neutral", hc.statusPolarity(burden) === 0, String(hc.statusPolarity(burden)));
		check("and is still not a debuff, which would be the other wrong answer", burden.isDebuff !== true);
		// A neutral status is not counted as a debuff and is not what a cleanse reaches for.
		startFight(71);
		const ana = hc.state.run.partyArray[0];
		const before = hc.debuffCount(ana);
		hc.applyStatus(ana, "commandersBurden", 1, aimed(ana));
		check("so it does not count toward a debuff tally", hc.debuffCount(ana) === before, String(hc.debuffCount(ana)));
		check("and it still does its job", hc.statusStacks(ana, "commandersBurden") === 1);
	}

	// =============================================================== THE BROKEN HAND, BY RARITY
	// > All of the broken cards are currently Blunder instead of the commons and rares being the ones I
	// > designed.
	// His original spec was per RARITY; it had been built as three cards naming their own forms, so
	// exactly three of her cards broke into what he designed and every other one broke into the starter's.
	{
		const formOf = (index) => hc.brokenFormIndexFor(hc.findDefinition(hc.cardArray, index));
		check("a starter of hers breaks into Blunder", formOf("anastasiaAdvance") === "anastasiaAdvanceBroken");
		check("a common breaks into the one he designed for commons",
			formOf("anastasiaInterpose") === "anastasiaInterposeBroken", String(formOf("anastasiaInterpose")));
		check("and so does a common he never named",
			formOf("anastasiaBattery") === "anastasiaInterposeBroken", String(formOf("anastasiaBattery")));
		check("a rare breaks into the one he designed for rares",
			formOf("anastasiaCheck") === "anastasiaCheckBroken", String(formOf("anastasiaCheck")));
		check("and so does a rare he never named",
			formOf("anastasiaSimul") === "anastasiaCheckBroken", String(formOf("anastasiaSimul")));
		// THE REGRESSION ITSELF, stated as a count: no rarity may collapse onto the starter's form.
		const commonArray = hc.cardArray.filter((c) => c.characterIndex === "anastasia" && c.rarity === "common");
		const rareArray = hc.cardArray.filter((c) => c.characterIndex === "anastasia" && c.rarity === "rare");
		check("EVERY common of hers breaks into the common form, not Blunder",
			commonArray.length > 3 && commonArray.every((c) => formOf(c.index) === "anastasiaInterposeBroken"),
			commonArray.filter((c) => formOf(c.index) !== "anastasiaInterposeBroken").map((c) => c.index).join(","));
		check("and EVERY rare into the rare form",
			rareArray.length > 1 && rareArray.every((c) => formOf(c.index) === "anastasiaCheckBroken"),
			rareArray.filter((c) => formOf(c.index) !== "anastasiaCheckBroken").map((c) => c.index).join(","));
		// The rule is general: a card naming its own form still overrides the rarity map.
		check("a card naming its own form still wins over the rarity map",
			hc.brokenFormIndexFor({ characterIndex: "anastasia", rarity: "common", brokenCard: "anastasiaCheckBroken" }) === "anastasiaCheckBroken");
		check("and a rarity the map does not name falls back to the character's",
			hc.brokenFormIndexFor({ characterIndex: "anastasia", rarity: "special" }) === "anastasiaAdvanceBroken");
		check("nobody else grew a rarity map by accident",
			hc.characterArray.filter((c) => c.brokenCardByRarity != null).map((c) => c.index).join() === "anastasia");
	}

	// =============================================================== BLUNDER IS A BLANK THAT BITES IF HELD
	// > Blunder should have no effect, instead dealing damage to an enemy piece if unplayed at the end of
	// > your turn.
	{
		const blunder = hc.findDefinition(hc.cardArray, "anastasiaAdvanceBroken");
		check("playing Blunder does nothing at all",
			Array.isArray(blunder.effectArray) && blunder.effectArray.length === 0);
		check("what it does is written on the unplayed list instead",
			Array.isArray(blunder.unplayedEffectArray) && blunder.unplayedEffectArray.length > 0);

		startFight(72);
		const combat = hc.state.run.combat;
		const ana = hc.state.run.partyArray[0];
		const foe = hc.livingEntityArray("enemy", combat)[0];
		foe.maxHealth = 900; foe.health = 900;

		// HELD: it bites as the turn closes.
		const held = hc.addCardToPile("anastasiaAdvanceBroken", "hand", hc.newEffectContext({ combat, source: ana }));
		held.ownerInstanceId = ana.instanceId;
		const before = foe.health;
		hc.combat.resolveUnplayedCards(hc.newEffectContext({ combat }));
		check("a Blunder still in hand at the end of the turn bites",
			foe.health < before, (before - foe.health) + " dealt");

		// FALSIFIED: an ordinary card sitting in hand does nothing at all.
		const quiet = foe.health;
		const ordinary = hc.addCardToPile("anastasiaDevelop", "hand", hc.newEffectContext({ combat, source: ana }));
		if (ordinary != null) ordinary.ownerInstanceId = ana.instanceId;
		const bodies = hc.state.run.partyArray.length;
		hc.combat.resolveUnplayedCards(hc.newEffectContext({ combat }));
		check("a card with no unplayed list is left alone by the same pass",
			hc.state.run.partyArray.length === bodies, "Develop summoned from the hand");
		check("though the Blunder beside it bit again", foe.health < quiet);

		// AND IT FIRES FROM THE REAL TURN END, not only when called directly.
		startFight(73);
		{
			const live = hc.state.run.combat;
			const her = hc.state.run.partyArray[0];
			const target = hc.livingEntityArray("enemy", live)[0];
			target.maxHealth = 900; target.health = 900;
			const copy = hc.addCardToPile("anastasiaAdvanceBroken", "hand", hc.newEffectContext({ combat: live, source: her }));
			copy.ownerInstanceId = her.instanceId;
			const at = target.health;
			hc.combat.endPlayerTurn();
			check("ending the turn is what triggers it", target.health < at, (at - target.health) + " dealt");
		}
		// The seam is general and fires whatever the discard rule is.
		const source = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-combat.js"), "utf8");
		const turnEnd = source.slice(source.indexOf("honeycomb.combat.endPlayerTurn = function"), source.indexOf("honeycomb.combat.resolveUnplayedCards = function"));
		// The CALL, not a mention of it: the comment above the call names the flag too, which is what made
		// a naive indexOf comparison read backwards.
		check("and it is resolved OUTSIDE the discard, so a rule set that keeps the hand still fires it",
			turnEnd.indexOf("honeycomb.combat.resolveUnplayedCards(context);") <
				turnEnd.indexOf("if (honeycomb.tuning.combat.discardHandOnTurnEnd"),
			turnEnd.indexOf("honeycomb.combat.resolveUnplayedCards(context);") + " vs " +
				turnEnd.indexOf("if (honeycomb.tuning.combat.discardHandOnTurnEnd"));
	}

	// =============================================================== THE RUN DECK IS THE PARTY'S
	// Found by re-simulating the gauntlet after the piece rework: a Queen's fifth move shuffles a King's
	// Invocation into the deck, and her pieces are ALSO the gauntlet's enemies -- so the enemy-side Queen
	// of the Queens' Guard was handing the PLAYER a King, twice a fight.
	{
		startFight(74);
		const combat = hc.state.run.combat;
		const before = hc.state.run.deckArray.length;
		const foeQueen = hc.summonCombatant({ side: "enemy", enemyIndex: "celestialQueen" }, { combat });
		hc.resolveEffectArray(hc.findDefinition(hc.cardArray, "celestialQueenPetition").effectArray,
			hc.newEffectContext({ combat, source: foeQueen }));
		check("an enemy cannot write to the party's run deck",
			hc.state.run.deckArray.length === before, before + " -> " + hc.state.run.deckArray.length);

		// ...and the party's own Queen still can, which is the whole point of the move.
		const ours = piecesOf().length === 0
			? hc.summonCombatant({ side: "ally", enemyIndex: "celestialQueen" }, { combat })
			: piecesOf()[0];
		hc.resolveEffectArray(hc.findDefinition(hc.cardArray, "celestialQueenPetition").effectArray,
			hc.newEffectContext({ combat, source: ours }));
		check("and the party's own Queen still pays out her King",
			hc.state.run.deckArray.length === before + 1, before + " -> " + hc.state.run.deckArray.length);

		// The old behaviour is still reachable, but only by asking for it.
		const forced = hc.state.run.deckArray.length;
		hc.resolveEffectArray([{ index: "addCardToDeck", card: "anastasiaCheck", evenFromOpponents: true }],
			hc.newEffectContext({ combat, source: foeQueen }));
		check("unless the card says so outright -- a curse forced on you is a real idea",
			hc.state.run.deckArray.length === forced + 1);
	}

	// =============================================================== the pool after the cut
	{
		const poolArray = hc.cardArray.filter((c) => c.characterIndex === "anastasia" && c.kind == null && c.rarity !== "broken");
		check("her pool survived the cut at a sane size", poolArray.length >= 12 && poolArray.length <= 24, String(poolArray.length));
		check("every card of hers still has a sound",
			hc.cardArray.filter((c) => c.characterIndex === "anastasia").every((c) => hc.cardSfxStem(c) != null),
			hc.cardArray.filter((c) => c.characterIndex === "anastasia" && hc.cardSfxStem(c) == null).map((c) => c.index).join(","));
	}
}

console.log("\n[122] Session 49 -- the Event Gallery: opt-in tiles, per-character pages, and a replay that changes nothing");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	hc.state.profile.unlockedCharacterArray = ["brienne", "nettle", "severine"];

	// ---------------------------------------------------------------- the source table
	{
		const source = hc.findDefinition(hc.gallerySourceArray, "lustEvent");
		check("Lust Events are a SOURCE row rather than engine code -- the seam another kind of scene joins at",
			source != null && typeof source.collect === "function" && typeof source.open === "function" &&
			source.available() === true);
	}

	// ---------------------------------------------------------------- membership is OPT-IN
	// > Opt-in, because ... We want to save the start points of events, and only the start points.
	{
		const entryArray = hc.gallery.entryArray();
		const named = entryArray.map((entry) => entry.entryIndex);
		check("a row with no `gallery` block is playable but never replayable",
			hc.findDefinition(hc.lustEventQueueArray, "retiredPartTwo") != null && named.indexOf("retiredPartTwo") < 0,
			"entries: " + named.join());
		check("and a row that opts in becomes a tile",
			named.indexOf("nettleVenomSpecimen") >= 0 && named.indexOf("afterThree") >= 0);
		check("`gallery: true` is the shorthand for every default",
			hc.gallery.readBlock({ gallery: true }) != null && hc.gallery.readBlock({ gallery: false }) === null &&
			hc.gallery.readBlock({}) === null);
	}

	// ---------------------------------------------------------------- one tile per character, per row
	{
		const fanArray = hc.gallery.entryArray().filter((entry) => entry.entryIndex === "anyUndone");
		check("a row that fans out across the roster is one tile on each of their pages, keyed per character",
			fanArray.length === 3 &&
			fanArray.map((entry) => entry.key).sort().join() ===
				["lustEvent:anyUndone/brienne", "lustEvent:anyUndone/nettle", "lustEvent:anyUndone/severine"].join(),
			fanArray.map((entry) => entry.key).join());
		check("and a character nobody has met has no tiles of it",
			hc.gallery.entryArray().every((entry) => entry.characterArray.indexOf("cinder") < 0));
	}

	// ---------------------------------------------------------------- every scene relevant to a character
	// Noodle: "need to have every scene relevant to each character appear in their gallery page." A scene
	// about two of them is written on one row and names the other, and shows up on BOTH pages.
	{
		const pair = hc.gallery.findEntry("lustEvent:afterThree");
		check("a two-hander names both characters, and the tile is on both of their pages",
			pair != null && pair.subject === "severine" &&
			pair.characterArray.indexOf("severine") >= 0 && pair.characterArray.indexOf("brienne") >= 0,
			pair == null ? "missing" : pair.characterArray.join());
		const briennePage = hc.gallery.pageFor("brienne");
		const brienneKeys = briennePage.reduce((all, group) => all.concat(group.entryArray.map((e) => e.key)), []);
		check("so Brienne's page carries Severine's scene even though no row of hers names it",
			brienneKeys.indexOf("lustEvent:afterThree") >= 0, brienneKeys.join());
	}

	// ---------------------------------------------------------------- the page: grouped and ordered
	{
		const page = hc.gallery.pageFor("nettle");
		check("a page is blocked out by weakness, one block per tag she has a scene for",
			page.map((group) => group.index).sort().join() === "charm,venom",
			page.map((group) => group.index).join());
		// The order is the CONTENT TABLE's, never the queue's: two characters' pages have to name their
		// weaknesses in the same order, and only the tag table can promise that.
		const tagOrder = (index) => hc.cardTagArray.findIndex((tag) => tag.index === index);
		check("and the blocks come out in content-table order, not in whatever order the queue mentioned them",
			page.every((group, position) => position === 0 || tagOrder(page[position - 1].index) < tagOrder(group.index)),
			page.map((group) => group.index + "@" + tagOrder(group.index)).join());
		const venom = page.filter((group) => group.index === "venom")[0];
		// SCENES, not their battle endings -- those are tested below and sit under the scene they belong to.
		const sceneArray = venom == null ? [] : venom.entryArray.filter((entry) => entry.outcomeIndex == null);
		check("while the scenes inside a block come out in the order the queue was written",
			sceneArray.map((entry) => entry.entryIndex).join() === "nettleVenomSpecimen,nettleVenomMethodology,nettleVenomSynthesis",
			sceneArray.map((entry) => entry.entryIndex).join());
	}

	// ---------------------------------------------------------------- locked, then unlocked
	{
		const before = hc.gallery.findEntry("lustEvent:nettleVenomSpecimen");
		check("a scene the profile has not played is LOCKED", before.unlocked === false);
		check("a locked tile says the mechanical half of what it wants and nothing else",
			before.lockedCaption === "Venom · " + hc.lust.rankDefinitionByRank(1).name,
			String(before.lockedCaption));
		check("a row whose requirement is not a rank says only the weakness",
			hc.gallery.findEntry("lustEvent:afterThree").lockedCaption === "Charm",
			String(hc.gallery.findEntry("lustEvent:afterThree").lockedCaption));
		check("and a locked tile cannot be played", hc.gallery.play("lustEvent:nettleVenomSpecimen") === false);

		// Nettle's page: her THREE venom scenes, the two battle endings under the third of them, and the
		// fanned-out charm scene. `retiredNoTile` is hers too but opts out, so it is not counted.
		check("the count reads found of total, endings included", (() => {
			const count = hc.gallery.countFor("nettle");
			return count.found === 0 && count.total === 6;
		})(), JSON.stringify(hc.gallery.countFor("nettle")));

		hc.lustEvents.markDone(hc.lustEvents.findEntry("nettleVenomSpecimen"), "nettle");
		const after = hc.gallery.findEntry("lustEvent:nettleVenomSpecimen");
		check("playing it through unlocks its tile, and nothing else's",
			after.unlocked === true && hc.gallery.findEntry("lustEvent:anyUndone/nettle").unlocked === false);
		check("playing one scene opens that scene and no other", 
			hc.gallery.countFor("nettle").found === 1, JSON.stringify(hc.gallery.countFor("nettle")));
		// The battle is in rank 3, so its two endings open with RANK 3 rather than with rank 1. They are
		// still one unlock between them: finishing the scene once opens both.
		hc.lustEvents.markDone(hc.lustEvents.findEntry("nettleVenomSynthesis"), "nettle");
		check("and the scene with the battle opens three: itself and both of its endings",
			hc.gallery.countFor("nettle").found === 4, JSON.stringify(hc.gallery.countFor("nettle")));
		hc.lustEvents.clearDone("nettleVenomSynthesis", "nettle");
		check("the tile's title is the block's, not the event's placeholder name",
			after.name === "A vial she can't identify", after.name);
	}

	// ---------------------------------------------------------------- a multi-part scene is ONE tile
	{
		// ON THE FIXTURE PAIR, because no shipped scene is multi-part any more. Nettle's three ranks are
		// three separate scenes and each is its own tile; writing them as parts of one made replaying
		// rank 1 walk straight on into ranks 2 and 3, which is what this shape is supposed to be FOR and
		// was wrong there.
		const first = hc.gallery.replayParams("lustEvent:retiredPartOne", 0);
		const second = hc.gallery.replayParams("lustEvent:retiredPartOne", 1);
		const third = hc.gallery.replayParams("lustEvent:retiredPartOne", 2);
		check("a replay starts at the start point, under the gallery host",
			first != null && first.eventIndex === "lustEventFirstStirring" && first.host === "gallery" &&
			first.subject === "severine");
		check("and walks on into the parts the start row names",
			second != null && second.eventIndex === "lustEventTrial" && second.subject === "severine",
			JSON.stringify(second));
		check("then stops", third === null);
		check("while a scene that names no parts is one tile and stops after itself",
			hc.gallery.replayParams("lustEvent:nettleVenomSpecimen", 1) === null);
	}

	// ---------------------------------------------------------------- Anastasia is not a page
	{
		const pageArray = hc.gallery.pageArray();
		check("the gallery offers one page per SHIPPED character -- no tile, no ??? slot for one in development",
			pageArray.every((page) => page.characterIndex !== "anastasia") &&
			pageArray.length === hc.shippedCharacterArray().length,
			pageArray.map((page) => page.characterIndex).join());
		check("an unlocked character is named and the rest are held as ??? slots",
			pageArray.filter((page) => page.known).map((page) => page.characterIndex).sort().join() ===
				"brienne,nettle,severine",
			pageArray.filter((page) => page.known).map((page) => page.characterIndex).join());
	}

	// ---------------------------------------------------------------- the replay host
	{
		const host = hc.findDefinition(hc.eventHostArray, "gallery");
		check("the gallery's host resolves nothing, records nothing, and saves no position",
			host != null && host.appliesEffects === false && host.savesPosition === false &&
			host.recordsSeen === false);
	}

	// ---------------------------------------------------------------- THE CLOBBER THAT WOULD HAVE BEEN
	// The gallery opens from the title screen, and the title screen has a Continue button: a run may be
	// paused inside a map event. Writing a replay's position to the run's one saved event slot would
	// throw that away.
	{
		hc.state.run = { eventState: { eventIndex: "mapEvent", pageIndex: "thePageTheyWereOn" }, partyArray: [] };

		hc.eventOverlay.host = "gallery";
		check("under the replay host the event position is not tracked", hc.eventState.tracked() === false);
		hc.eventState.begin("lustEventFirstStirring", { pageIndex: null });
		hc.eventState.update({ pageIndex: "zzz" });
		hc.eventState.clear();
		check("so a replay writes nothing to the run's saved event -- not through begin, update or clear",
			hc.state.run.eventState != null && hc.state.run.eventState.eventIndex === "mapEvent" &&
			hc.state.run.eventState.pageIndex === "thePageTheyWereOn",
			JSON.stringify(hc.state.run.eventState));
		check("and it reads nothing back either: a reread always starts at the scene's first page",
			hc.eventState.savedFor("mapEvent") === null);

		// Falsification: the same four calls under the map's own host do every one of those things.
		hc.eventOverlay.host = "map";
		check("while the map's host still tracks it, which is what the guard is guarding",
			hc.eventState.tracked() === true && hc.eventState.savedFor("mapEvent") != null);
		hc.eventState.clear();
		check("and still clears it", hc.state.run.eventState === null);
		hc.state.run = null;
	}

	// ---------------------------------------------------------------- a reread pays nothing
	// The placeholder scene's second choice grants 40 personal experience and 4 weakness. Taken in the
	// gallery it must grant neither, and taken for real it must grant both.
	{
		const choiceIndex = 1;
		const openScene = (host) => {
			hc.eventOverlay.host = host;
			hc.eventOverlay.eventIndex = "lustEventFirstStirring";
			hc.eventOverlay.subject = "nettle";
			hc.eventOverlay.lustEntryIndex = "nettleVenomSpecimen";
			hc.eventOverlay.pageIndex = null;
			hc.eventOverlay.resultText = null;
			hc.eventOverlay.leadText = null;
			hc.eventOverlay.answerArray = null;
			hc.eventOverlay.pendingChoiceIndex = null;
			hc.eventOverlay.discoveryRecorded = false;
			hc.eventOverlay.keepsEventReady = false;
		};
		const reading = () => ({
			experience: hc.state.profile.personalExperienceArray == null ? 0
				: (hc.state.profile.personalExperienceArray.nettle || 0),
			weakness: hc.lust.exposureFor("nettle", "venom"),
			eventKnown: hc.discovery.isKnown("event", "lustEventFirstStirring"),
		});

		openScene("gallery");
		const beforeReplay = reading();
		hc.eventOverlay.choose("lustEventFirstStirring", choiceIndex);
		const afterReplay = reading();
		check("a replayed choice grants no experience, no weakness and no discovery",
			afterReplay.experience === beforeReplay.experience &&
			afterReplay.weakness === beforeReplay.weakness &&
			afterReplay.eventKnown === false && beforeReplay.eventKnown === false,
			JSON.stringify(beforeReplay) + " -> " + JSON.stringify(afterReplay));
		check("and it still shows what the choice said happened",
			typeof hc.eventOverlay.resultText === "string" && hc.eventOverlay.resultText.length > 0);

		// Falsification: the same choice, under the host that means it.
		openScene("lustEvent");
		const beforeReal = reading();
		hc.eventOverlay.choose("lustEventFirstStirring", choiceIndex);
		const afterReal = reading();
		check("while the same choice played for real grants all three -- so the suppression is real",
			afterReal.experience > beforeReal.experience && afterReal.weakness > beforeReal.weakness &&
			afterReal.eventKnown === true,
			JSON.stringify(beforeReal) + " -> " + JSON.stringify(afterReal));
		hc.eventOverlay.host = "map";
	}

	// ---------------------------------------------------------------- win and loss as separate things
	// > I want to have win and loss events as separate things, which means if you win it you can't see
	// > the loss event.
	{
		// THE BUG THAT KILLED THE FEATURE. startCombat documents victoryEvent / defeatEvent, and both
		// battleContinuation and returnParams read them -- but resolve never copied them onto the request,
		// so an authored victoryEvent fell through to the "Lust Event Cleared!" stub. Fixed session 49.
		hc.state.run = null;
		hc.resolveEffectArray([{ index: "startCombat", encounter: "loneSporeling",
			victoryEvent: "lustEventUndone", defeatEvent: "lustEventCleared" }], hc.newEffectContext({}));
		const pending = hc.pendingCombatHolder().pendingCombat;
		check("a Lust Battle can name a separate event for each outcome, and the request carries them",
			pending != null && pending.victoryEvent === "lustEventUndone" && pending.defeatEvent === "lustEventCleared",
			JSON.stringify(pending));
		const continuation = hc.lustEvents.battleContinuation({ index: "lustEventTrial" }, pending);
		check("so the continuation carries them, and the winner is sent to the event that was written",
			hc.lustEvents.returnParams(continuation, true).eventIndex === "lustEventUndone" &&
			hc.lustEvents.returnParams(continuation, false).eventIndex === "lustEventCleared");
		check("and the gallery's replay comes back under its OWN host, so no row is completed",
			hc.lustEvents.returnParams(continuation, true, "gallery").host === "gallery" &&
			hc.lustEvents.returnParams(continuation, true).host === "lustEvent");
		hc.pendingCombatHolder().pendingCombat = null;
	}

	// ---------------------------------------------------------------- the outcome tiles
	{
		// nettleVenomSpecimen's part three is the synthesis, whose battle names a page per outcome. Both are tiles.
		const page = hc.gallery.pageFor("nettle");
		const venom = page.filter((group) => group.index === "venom")[0];
		const keyArray = venom.entryArray.map((entry) => entry.key);
		check("a scene with a battle in it lists its endings as tiles of their own, under the scene",
			keyArray.join() === ["lustEvent:nettleVenomSpecimen", "lustEvent:nettleVenomMethodology",
				"lustEvent:nettleVenomSynthesis", "lustEvent:nettleVenomSynthesis#victory:synthWon",
				"lustEvent:nettleVenomSynthesis#defeat:synthLost"].join(), keyArray.join());
		// AN ENDING IS KEYED BY WHAT IT PLAYS. A scene may hold two fights, and keying on the outcome
		// alone would hand both victories one key -- one tile where there are two, and one ledger entry
		// opening the wrong ending. The battle's own continuation rebuilds the same key, which is how
		// losing a replay opens the ending that was actually reached.
		check("an ending is keyed by the page or event it plays, so two fights in one scene cannot collide", (() => {
			const victory = hc.gallery.outcomeFor(true);
			const second = hc.gallery.outcomeKey("lustEvent:x", victory, hc.gallery.outcomeTarget(
				{ victoryPage: "anotherWin" }, victory));
			const first = hc.gallery.outcomeKey("lustEvent:x", victory, hc.gallery.outcomeTarget(
				{ victoryPage: "trialWon" }, victory));
			return first !== second && first === "lustEvent:x#victory:trialWon";
		})());
		check("and the fight that just ended rebuilds that key from its own continuation", (() => {
			const continuation = { replayKey: "lustEvent:nettleVenomSynthesis", victoryPage: "synthWon", defeatPage: "synthLost" };
			const outcome = hc.gallery.outcomeFor(false);
			return hc.gallery.outcomeKey(continuation.replayKey, outcome,
				hc.gallery.outcomeTarget(continuation, outcome)) === "lustEvent:nettleVenomSynthesis#defeat:synthLost";
		})());
		check("a separate EVENT per outcome keys the same way a page does", (() => {
			const outcome = hc.gallery.outcomeFor(true);
			return hc.gallery.outcomeKey("lustEvent:x", outcome, hc.gallery.outcomeTarget(
				{ victoryEvent: "lustEventUndone" }, outcome)) === "lustEvent:x#victory:lustEventUndone";
		})());
		check("and an outcome the battle names nothing for gets no tile at all",
			hc.gallery.outcomeTarget({}, hc.gallery.outcomeFor(true)) === null);
		check("and it finds them through the scene's later PARTS, not only its start point",
			hc.gallery.battleRequestArray("nettleMethodology").length === 0 &&
			hc.gallery.battleRequestArray("nettleSynthesis").length === 1);
		check("each ending is titled by the page that was written, not by the plain word",
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#victory:synthWon").name === "Extraction" &&
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#defeat:synthLost").name === "Marked");
		check("an ending plays the ending itself rather than replaying the scene that leads to it", (() => {
			const params = hc.gallery.replayParams("lustEvent:nettleVenomSynthesis#defeat:synthLost", 0);
			return params != null && params.eventIndex === "nettleSynthesis" && params.pageIndex === "synthLost" &&
				params.host === "gallery";
		})(), JSON.stringify(hc.gallery.replayParams("lustEvent:nettleVenomSynthesis#defeat:synthLost", 0)));

		// > which means if you win it you can't see the loss event
		// THE BATTLE IS IN RANK 3, so it is rank 3 that opens both endings -- not rank 1, which is now a
		// separate scene with a tile of its own and no fight in it.
		hc.lustEvents.markDone(hc.lustEvents.findEntry("nettleVenomSynthesis"), "nettle");
		check("finishing the scene once opens BOTH endings, so winning never costs the loss scene",
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#victory:synthWon").unlocked === true &&
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#defeat:synthLost").unlocked === true);
		// And the one thing a replay may change: an ending reached by replaying the battle.
		hc.lustEvents.clearDone("nettleVenomSynthesis", "nettle");
		check("with the scene un-played again, both endings shut with it",
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#victory:synthWon").unlocked === false &&
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#defeat:synthLost").unlocked === false);
		hc.gallery.record("lustEvent:nettleVenomSynthesis#defeat:synthLost");
		check("losing a REPLAYED battle opens that ending on its own -- the only thing a replay changes",
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#defeat:synthLost").unlocked === true &&
			hc.gallery.findEntry("lustEvent:nettleVenomSynthesis#victory:synthWon").unlocked === false &&
			hc.state.profile.lustEventDoneArray.indexOf("nettleVenomSynthesis") < 0,
			JSON.stringify(hc.state.profile.galleryUnlockedArray));
		hc.lustEvents.markDone(hc.lustEvents.findEntry("nettleVenomSynthesis"), "nettle");
	}

	// ---------------------------------------------------------------- the fight still happens
	{
		// The scene's SHAPE resolves in a replay even though its payout does not, which is what makes a
		// Lust Battle replayable at all.
		const battleChoice = [{ index: "gainPersonalExperience", amount: 999 },
			{ index: "startCombat", encounter: "loneSporeling", partyArray: ["subject"] },
			{ index: "gainWeakness", tag: "venom", amount: 99 }];
		const structural = hc.structuralEffectArray(battleChoice);
		check("only the scene's structure survives a replay -- the fight, not the experience beside it",
			structural.length === 1 && structural[0].index === "startCombat", JSON.stringify(structural));
		check("and `startCombat` is marked structural on its own table entry, not in a list over here",
			hc.findDefinition(hc.effectArray, "startCombat").sceneStructure === true &&
			hc.findDefinition(hc.effectArray, "gainPersonalExperience").sceneStructure !== true);
	}

	// ---------------------------------------------------------------- THE RUN THAT MUST SURVIVE IT
	// A replayed Lust Battle builds a run of its own, and the gallery opens from the title screen, which
	// has a Continue button. Losing the player's paused run to a scene reread would be unforgivable.
	{
		const pausedRun = { day: 7, partyArray: [], marker: "the player's own run" };
		hc.state.run = pausedRun;
		hc.gallery.stashedRun = null;
		hc.save.suspended = false;

		// Standing in for the fight: the stash, the flag and the suspension are what beginBattle does first.
		hc.gallery.stashedRun = hc.state.run;
		hc.gallery.stashHeld = true;
		hc.save.suspended = true;
		hc.state.run = { day: 1, partyArray: [], marker: "the throwaway battle run" };
		check("while a replayed battle is fought, NOTHING reaches storage",
			hc.save.autosave("lustBattleEnd") === false && hc.save.autosave() === false);

		hc.gallery.releaseStash();
		check("and the player's own run is handed back afterwards, saving with it",
			hc.state.run === pausedRun && hc.state.run.marker === "the player's own run" &&
			hc.save.suspended === false && hc.gallery.stashedRun === null);
		check("releasing a stash that was never taken leaves the run alone", (() => {
			hc.gallery.stashHeld = false;
			hc.state.run = pausedRun;
			hc.gallery.releaseStash();
			return hc.state.run === pausedRun;
		})());

		// RESTORING A STASH OF NULL IS THE COMMON CASE, and the one that bites. The gallery is usually
		// opened between runs, so the stash is null -- and putting that null back is what throws the
		// battle's own run away. Without it the player keeps a phantom run and the title screen offers to
		// Continue a fight that is over.
		hc.state.run = null;
		hc.gallery.stashedRun = hc.state.run;
		hc.gallery.stashHeld = true;
		hc.save.suspended = true;
		hc.state.run = { day: 1, partyArray: [], marker: "the throwaway battle run" };
		hc.gallery.releaseStash();
		check("a replay started with NO run leaves none behind -- the battle's own run is thrown away",
			hc.state.run === null && hc.gallery.stashHeld === false && hc.save.suspended === false,
			hc.state.run == null ? "null" : hc.state.run.marker);
	}

	// ---------------------------------------------------------------- a MAP event replays too
	// > It'll need to be able to display the same kind of events as when you're wandering around on the
	// > map after all. It won't break doing that, right?
	{
		const mapEventArray = hc.eventArray.filter((event) => event.weight > 0 && event.lustEvent !== true);
		check("there are map events to replay at all", mapEventArray.length >= 5, String(mapEventArray.length));

		// A map event's fight belongs to the party, not to one character, so it names no subject. The open
		// gallery page answers instead -- otherwise the choice resolves, no fight starts, and the player
		// is left on the page with nothing said. Found replaying the Sealed Door.
		hc.state.run = null;
		hc.gallery.characterIndex = "nettle";
        hc.eventOverlay.subject = null;
		check("a fight in a map event still has somebody to field: whoever's page is open",
			hc.gallery.battleSubject() === "nettle");
		hc.eventOverlay.subject = "severine";
		check("while an event that names its own character keeps her",
			hc.gallery.battleSubject() === "severine");
		hc.eventOverlay.subject = null;

		// A PRICED CHOICE IS FREE IN THE GALLERY, and must actually be takeable. The cost gate in `choose`
		// refused it even though the tile drew it as enabled, which made a clickable option do nothing --
		// found on the Quiet Shrine's 30-gold offering with no gold and no run.
		const priced = { costArray: { gold: 30 }, effectArray: [] };
		hc.eventOverlay.host = "gallery";
		check("a host that charges nothing does not gate on affording it",
			hc.eventHost().appliesEffects === false && hc.canAfford(priced.costArray) === false);
		hc.eventOverlay.host = "map";
	}

	// ---------------------------------------------------------------- the screens, read as source
	// The scene and UI files need a real DOM and are not loaded headless, so the wiring is asserted
	// against their source -- the same way [117] and [118] hold the top bar and the Battle Lab.
	{
		const read = (name) => fs.readFileSync(path.join(ROOT, "honeycomb", name), "utf8");
		const mapSource = read("honeycomb-map.js");
		const uiSource = read("honeycomb-ui.js");
		const teamSource = read("honeycomb-scene-teambuilding.js");
		const titleSource = read("honeycomb-scene-title.js");
		const gallerySource = read("honeycomb-gallery.js");

		check("the MAP no longer asks the top bar for a party button",
			/honeycomb\.ui\.topBar\(\{[^}]*\}\)/.test(mapSource) && mapSource.indexOf("showParty") < 0);
		check("its party rail opens the party window on the face that was pressed",
			mapSource.indexOf("honeycomb.partyWindow.open('") >= 0 &&
			mapSource.indexOf("member.characterIndex") >= 0);
		check("and the Broken alert came with it rather than being dropped -- session 21's fix, moved",
			mapSource.indexOf("alert: member.broken == true") >= 0 &&
			mapSource.indexOf('honeycomb.tooltip.attributes("partyAlert", "broken")') >= 0);
		check("a portrait can wear that alert, drawn inside the frame it clips",
			uiSource.indexOf("hcPortraitAlert") >= 0 && uiSource.indexOf("hcPortraitBadge") >= 0);
		check("BATTLE keeps its party button: there is no rail of faces to press there",
			read("honeycomb-scene-combat.js").indexOf("showParty: true") >= 0);

		check("the heart on the top bar is the gallery now",
			uiSource.indexOf("settings.showGallery == true") >= 0 &&
			uiSource.indexOf("honeycomb.gallery.open()") >= 0);
		check("teambuilding asks for it", teamSource.indexOf("showGallery: true") >= 0);
		check("and the title screen offers the same window as a named button",
			titleSource.indexOf("honeycomb.gallery.open()") >= 0 && titleSource.indexOf("Gallery</div>") >= 0);

		// Both screens open the ONE overlay, which is what Noodle asked for: "The gallery buttons on the
		// title and in the teambuilding should open the same window."
		check("both buttons open the same overlay, not two of them",
			(gallerySource.match(/honeycomb\.overlay\.register\(/g) || []).length === 1 &&
			gallerySource.indexOf('index: "gallery"') >= 0);

		// EVERY CLASS THE GALLERY DRAWS HAS A RULE. A tile whose class is a typo is invisible to the
		// engine tests above and looks like a styling accident in the browser.
		const cssSource = fs.readFileSync(path.join(ROOT, "..", "css", "honeycomb.css"), "utf8");
		const classSet = new Set((gallerySource.match(/hcGallery[A-Za-z]*/g) || []));
		const missingArray = [...classSet].filter((name) => cssSource.indexOf("." + name) < 0);
		check("every hcGallery class the window emits is styled",
			classSet.size >= 6 && missingArray.length === 0, "unstyled: " + missingArray.join());
		check("and the loader ships the file",
			fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-loader.js"), "utf8").indexOf("honeycomb-gallery.js") >= 0);
	}

	// ---------------------------------------------------------------- the words a tile is titled with
	{
		check("an event's words fill outside the overlay too, which is what a tile's default title reads",
			hc.eventWords("{name} and {tag}", "nettle", "nettleVenomSpecimen") === "Nettle and Venom",
			hc.eventWords("{name} and {tag}", "nettle", "nettleVenomSpecimen"));
	}
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[123] Session 50 -- looping music: three tracks, a gapless lap, and the host's music handed back intact");
{
	const metrics = JSON.parse(fs.readFileSync(path.resolve(__dirname, "music", "music-metrics.json"), "utf8"));
	const spec = JSON.parse(fs.readFileSync(path.resolve(__dirname, "music", "music-loops.json"), "utf8"));
	const repoRoot = path.resolve(ROOT, "..", "..");

	// A WHOLE BROWSER'S WORTH OF <audio>, FAKED. honeycomb-music.js takes its elements and its clock from
	// two seams, so a lap, a throttled tab and a frozen one can all be driven here in milliseconds.
	function musicBench(options) {
		const settings = options || {};
		const hc = newEngine();
		const music = hc.tuning.audio.music;
		const bench = { hc, music, clock: 1000, elementArray: [], blockPlay: false, startLagSeconds: settings.startLagSeconds || 0, dueArray: [], sinceTick: 0, farSeeks: 0 };
		hc.music.schedule = (callback, delayMs) => { bench.dueArray.push({ callback, at: bench.clock + delayMs }); };
		// The sandbox's own global object, reached through its Function constructor: the platform adapter
		// reads the HOST's names as bare globals, so that is where a fake host has to be written.
		bench.global = hc.platform.sound.constructor("return this")();
		hc.music.now = () => bench.clock;
		hc.music.probeVolumeControl = () => settings.noVolume !== true;
		hc.music.createElement = (filePath) => {
			const track = music.trackArray.find((entry) => filePath.indexOf("/" + entry.file + music.extension) >= 0);
			const element = {
				path: filePath, paused: true, seeking: false, muted: false, volume: 1, playCalls: 0, lag: 0,
				duration: track.loopSeconds + music.postRollSeconds, time: 0,
				get currentTime() { return this.time; },
				// A source that cannot seek (a server with no Range support) reports 0 to 0 and sends
				// every seek back to the top, which is exactly what Chrome was measured doing.
				seekable: { length: 1, end: () => (settings.noSeek === true ? 0 : track.loopSeconds + music.postRollSeconds) },
				// A seek lands a little off where it was aimed, as a real one does
				set currentTime(value) {
					if (value > 0) bench.farSeeks++;
					this.time = settings.noSeek === true ? 0 : value + (value > 0 ? (settings.seekErrorSeconds || 0) : 0);
				},
				play() {
					this.playCalls++;
					if (bench.blockPlay) return { catch: (handler) => handler({ name: "NotAllowedError" }) };
					if (this.paused) this.lag = bench.startLagSeconds;
					this.paused = false;
					return { catch() {} };
				},
				pause() { this.paused = true; },
				removeAttribute() { this.released = true; },
				load() {},
			};
			bench.elementArray.push(element);
			return element;
		};
		// Moves the clock and every playing element in 5ms steps, fires what the player scheduled when it
		// falls due, and runs the player's tick every `tickEveryMs` (its own pace unless told otherwise).
		bench.run = (totalMs, tickEveryMs) => {
			const step = 5;
			const tickGap = tickEveryMs || music.tickMs;
			for (let spent = 0; spent < totalMs; spent += step) {
				bench.clock += step;
				for (const element of bench.elementArray.slice()) {
					if (element.paused) continue;
					let advance = step / 1000;
					// play() takes a moment to produce sound: the clock of a fresh element starts late
					if (element.lag > 0) { const held = Math.min(element.lag, advance); element.lag -= held; advance -= held; }
					element.time += advance;
					if (element.time >= element.duration) { element.time = element.duration; element.paused = true; if (element.onended) element.onended(); }
				}
				const dueNow = bench.dueArray.filter((entry) => entry.at <= bench.clock);
				bench.dueArray = bench.dueArray.filter((entry) => entry.at > bench.clock);
				// A throttled tab delays timers exactly as it delays ticks
				for (const entry of dueNow) { if (tickGap > music.tickMs) bench.dueArray.push({ callback: entry.callback, at: Infinity, held: true }); else entry.callback(); }
				bench.sinceTick += step;
				if (bench.sinceTick >= tickGap) {
					bench.sinceTick = 0;
					for (const entry of bench.dueArray.filter((held) => held.held === true)) entry.callback();
					bench.dueArray = bench.dueArray.filter((held) => held.held !== true);
					hc.music.tick();
				}
				if (bench.onStep) bench.onStep();
			}
		};
		bench.live = (trackIndex) => { const player = hc.music.playerMap[trackIndex]; return player.elementArray[player.live]; };
		bench.master = () => hc.platform.musicVolume() * music.volume;
		return bench;
	}

	// ------------------------------------------------------------------ the files and the numbers agree
	{
		const hc = newEngine();
		const music = hc.tuning.audio.music;
		const wrongArray = [];
		for (const track of music.trackArray) {
			const built = metrics.trackMap[track.file];
			if (built == null) { wrongArray.push(track.index + " was never built"); continue; }
			if (Math.abs(built.loopSeconds - track.loopSeconds) > 0.0005) wrongArray.push(track.index + " tuning says " + track.loopSeconds + ", the build says " + built.loopSeconds);
			if (!fs.existsSync(path.join(repoRoot, music.folder, track.file + music.extension))) wrongArray.push(track.index + " has no file");
		}
		check("every track's loopSeconds is the length the build measured, and its file exists", wrongArray.length === 0, wrongArray.join("; "));
		check("the post-roll the runtime waits in is the post-roll the files were built with",
			Object.values(metrics.trackMap).every((built) => built.postRollSeconds === music.postRollSeconds && Math.abs(built.fileSeconds - built.loopSeconds - music.postRollSeconds) < 0.001));
		check("the build PROVED each file's post-roll repeats its opening (decoded back and correlated)",
			Object.values(metrics.trackMap).every((built) => built.postRollIdentity > 0.995),
			Object.values(metrics.trackMap).map((built) => built.index + " " + built.postRollIdentity).join());
		check("every track is mastered to the one loudness, under the peak ceiling",
			Object.values(metrics.trackMap).every((built) => Math.abs(built.lufs - spec.targetLufs) <= 0.5 && built.peakDb <= spec.peakCeilingDb),
			Object.values(metrics.trackMap).map((built) => built.index + " " + built.lufs + " LUFS " + built.peakDb + " dB").join());
		check("no seam is a click: the jump at each is within twice what the music does anyway",
			Object.values(metrics.trackMap).every((built) => built.seamClickRatioArray.every((ratio) => ratio < 2)),
			Object.values(metrics.trackMap).map((built) => built.index + " " + built.seamClickRatioArray.join("/")).join());
		check("a lap is a whole number of beats, so the pulse never stumbles at the seam",
			Object.values(metrics.trackMap).every((built) => Math.abs(built.beats - Math.round(built.beats)) < 0.01),
			Object.values(metrics.trackMap).map((built) => built.index + " " + built.beats).join());
		check("every cue names a real track", [music.defaultTrack].concat(Object.values(music.sceneCueMap), Object.values(music.afterSceneCueMap),
			Object.values(music.eventCueMap), Object.keys(music.transitionByTrackMap)).every((index) => music.trackArray.some((track) => track.index === index)));
		check("the loader ships the file",
			fs.readFileSync(path.join(repoRoot, "scripts", "misc", "honeycomb", "honeycomb-loader.js"), "utf8").indexOf("honeycomb-music.js") >= 0);
	}

	// ------------------------------------------------------------------ which track a moment asks for
	{
		const bench = musicBench();
		const hc = bench.hc;
		const heard = () => hc.music.currentTrack;
		hc.music.onScene("title", "");
		check("the title track plays on game start", heard() === "title");
		hc.music.onScene("teambuilding", "title"); hc.music.onScene("map", "teambuilding");
		check("and keeps playing through teambuilding and the first map, until combat is triggered", heard() === "title");
		hc.music.onScene("combat", "map");
		check("combat brings the combat track", heard() === "combat");
		hc.music.onEvent("combatEnded");
		check("which plays until victory or defeat -- the map track takes over under the victory screen", heard() === "map");
		hc.music.onScene("combat", "combat");
		check("the combat scene rebuilding itself under that screen does not bring the combat track back", heard() === "map");
		hc.music.onScene("map", "combat");
		check("the map track plays until another combat begins", heard() === "map");
		hc.music.onScene("combat", "map");
		check("and the next fight takes it back", heard() === "combat");
		hc.music.onScene("map", "combat");
		check("a fight left with no victory or defeat (abandoned) still cannot leave the combat track playing", heard() === "map");
		hc.music.onEvent("combatBegan");
		check("a fight chained straight onto another is a cue with no scene change", heard() === "combat");
		hc.music.onScene("title", "combat");
		check("the title screen has the title track", heard() === "title");

		const fresh = musicBench();
		fresh.hc.music.onScene("combat", "");
		check("a save resumed mid-fight boots straight into the combat track", fresh.hc.music.currentTrack === "combat");
		const onMap = musicBench();
		onMap.hc.music.onScene("map", "");
		check("and one resumed on the map starts with the default", onMap.hc.music.currentTrack === onMap.music.defaultTrack);
	}

	// ------------------------------------------------------------------ one lap, at an ordinary tick
	{
		const bench = musicBench({ startLagSeconds: 0.08, seekErrorSeconds: 0.006 });
		const hc = bench.hc;
		const lap = bench.music.trackArray.find((track) => track.index === "title").loopSeconds;
		hc.music.onScene("title", "");
		bench.run(bench.music.transition.fadeInMs + 500);
		const first = bench.live("title");
		check("the track fades in to the host's volume times its own", Math.abs(first.volume - bench.master()) < 1e-9 && first.paused === false, String(first.volume));

		let worstLevel = 0, bothAudible = 0, worstTrueOffset = 0;
		bench.onStep = () => {
			// The offset as the EARS would have it -- read off the fake elements' real positions, not
			// off what the player believes it measured.
			const audible = bench.elementArray.filter((element) => !element.paused && element.volume > 0);
			if (audible.length === 2) worstTrueOffset = Math.max(worstTrueOffset, Math.abs(Math.abs(audible[0].time - audible[1].time) - lap));
			const total = bench.elementArray.reduce((sum, element) => sum + (element.paused ? 0 : element.volume), 0);
			worstLevel = Math.max(worstLevel, Math.abs(total - bench.master()));
			if (bench.elementArray.filter((element) => !element.paused && element.volume > 0).length > 1) bothAudible++;
		};
		bench.run((lap + 4) * 1000 - bench.music.transition.fadeInMs - 500);
		bench.onStep = null;
		const second = bench.live("title");
		check("a lap is played by changing over to a SECOND element, never by looping the first", bench.elementArray.length === 2 && second !== first);
		check("the level never moved during the changeover: the two shares always sum to the whole", worstLevel < 1e-9 && bothAudible > 2, worstLevel + " over " + bothAudible + " steps");
		check("the incoming element was lined up inside the tolerance before it was heard, despite a slow start and an inexact seek",
			Math.abs(hc.music.playerMap.title.lastAlignmentError) <= bench.music.handoff.toleranceSeconds, String(hc.music.playerMap.title.lastAlignmentError));
		check("and they truly WERE lined up while both could be heard -- the player was not fooled by a clock that had not started running",
			worstTrueOffset <= bench.music.handoff.toleranceSeconds + 1e-9, String(worstTrueOffset));
		check("and is now exactly one lap behind where the outgoing one stopped", Math.abs((second.currentTime + lap) - (lap + 4 + 0)) < 0.2, String(second.currentTime));
		check("the outgoing element is parked at the top, paused, ready for the lap after", first.paused === true && first.currentTime === 0);
		check("nothing was ever asked to loop", bench.elementArray.every((element) => element.loop !== true));

		bench.run(lap * 1000);
		check("the lap after that changes back, and still only two elements exist", bench.live("title") === first && bench.elementArray.length === 2);
	}

	// ------------------------------------------------------------------ a source that cannot seek
	{
		const bench = musicBench({ startLagSeconds: 0.08, noSeek: true });
		const lap = bench.music.trackArray.find((track) => track.index === "title").loopSeconds;
		bench.hc.music.onScene("title", "");
		const offsetByLap = [0, 0, 0];
		let lapNumber = 0;
		bench.onStep = () => {
			const audible = bench.elementArray.filter((element) => !element.paused && element.volume > 0);
			if (audible.length === 2) offsetByLap[lapNumber] = Math.max(offsetByLap[lapNumber], Math.abs(Math.abs(audible[0].time - audible[1].time) - lap));
		};
		bench.run((lap + 3) * 1000); lapNumber = 1;
		bench.run(lap * 1000); lapNumber = 2;
		bench.run(lap * 1000);
		check("where the source cannot seek (python's http.server: Chrome reports `seekable` 0 to 0) the player never asks for one",
			bench.farSeeks === 0 && bench.elementArray.length === 2, bench.farSeeks + " seeks");
		check("so the first changeover is only as good as the latency guess", offsetByLap[0] > 0 && offsetByLap[0] < 0.05, String(offsetByLap[0]));
		check("and every one after it is lined up, because the player LEARNED the latency from the first",
			offsetByLap[1] <= bench.music.handoff.toleranceSeconds && offsetByLap[2] <= bench.music.handoff.toleranceSeconds, offsetByLap.join(" / "));
	}

	// ------------------------------------------------------------------ a hidden tab: one tick a second
	{
		const bench = musicBench({ startLagSeconds: 0.08 });
		const lap = bench.music.trackArray.find((track) => track.index === "title").loopSeconds;
		bench.hc.music.onScene("title", "");
		const first = bench.live("title") || null;
		let offsetAtSwap = null;
		bench.onStep = () => {
			const player = bench.hc.music.playerMap.title;
			if (player.handoff == null || player.handoff.stage !== "fading") return;
			offsetAtSwap = Math.abs((player.elementArray[player.live].time - lap) - player.elementArray[1 - player.live].time);
		};
		bench.run((lap + bench.music.postRollSeconds - 0.2) * 1000, 1000);
		const live = bench.live("title");
		check("throttled to one tick a second, the changeover still lands inside the post-roll", bench.elementArray.length === 2 && live !== bench.elementArray[0] && live.paused === false,
			"elements " + bench.elementArray.length);
		check("and the two were lined up when it happened, a late start having been aimed at where the music had got to",
			offsetAtSwap != null && offsetAtSwap <= bench.music.handoff.toleranceSeconds, String(offsetAtSwap));
	}

	// ------------------------------------------------------------------ a frozen tab: no ticks at all
	{
		const bench = musicBench();
		const lap = bench.music.trackArray.find((track) => track.index === "title").loopSeconds;
		bench.hc.music.onScene("title", "");
		bench.run(5000);
		bench.run((lap + bench.music.postRollSeconds) * 1000, Infinity);
		const live = bench.live("title");
		check("with no ticks at all the file ENDS -- and the other element picks the lap up where it stopped",
			bench.elementArray.length === 2 && live === bench.elementArray[1] && live.paused === false && live.currentTime >= bench.music.postRollSeconds, String(live.currentTime));
	}

	// ------------------------------------------------------------------ resume, restart, and the switch
	{
		const bench = musicBench();
		const hc = bench.hc;
		hc.music.onScene("combat", "");
		bench.run(20000);
		hc.music.onEvent("combatEnded");
		bench.run(15000);
		const map = bench.live("map"), combat = bench.live("combat");
		const mapTransition = bench.music.transitionByTrackMap.map;
		check("the map track waited out its delay before it sounded", Math.abs(map.currentTime - (15 - mapTransition.delayMs / 1000)) < 0.11, String(map.currentTime));
		check("the combat track faded out, was paused, and went back to the top", combat.paused === true && combat.currentTime === 0 && combat.volume === 0);
		hc.music.onScene("combat", "map");
		bench.run(10000);
		const mapHeldAt = map.currentTime;
		check("the map track is paused while the fight plays, holding its place", map.paused === true && mapHeldAt > 10);
		hc.music.onEvent("combatEnded");
		bench.run(5000);
		check("and carries on from there, so a short walk between fights is not the same opening bars every time", map.paused === false && map.currentTime > mapHeldAt);

		hc.platform.sound.constructor("musicDisabled = true")();
		hc.music.refresh();
		bench.run(bench.music.disabledFadeMs + 200);
		check("switching music off silences and pauses everything", bench.elementArray.every((element) => element.paused === true));
		check("and schedules nothing while it is off", hc.music.tick() === false);
		hc.platform.sound.constructor("musicDisabled = false")();
		hc.music.refresh();
		bench.run(4000);
		check("switching it back on brings back the track that was playing", bench.live("map").paused === false && Math.abs(bench.live("map").volume - bench.master()) < 1e-9);
	}

	// ------------------------------------------------------------------ autoplay
	{
		const bench = musicBench();
		const hc = bench.hc;
		bench.blockPlay = true;
		hc.music.onScene("title", "");
		bench.run(1000);
		const calls = bench.live("title").playCalls;
		check("a browser that refuses to play before a gesture is asked once, not every tick", hc.music.blocked === true && calls === 1, String(calls));
		bench.blockPlay = false;
		hc.platform.sound("uiClick");
		bench.run(500);
		check("and the first button pressed starts the music, with no listener anywhere", bench.live("title").paused === false && hc.music.blocked === false);
	}

	// ------------------------------------------------------------------ a browser with no volume control
	{
		const bench = musicBench({ noVolume: true });
		const lap = bench.music.trackArray.find((track) => track.index === "title").loopSeconds;
		bench.hc.music.onScene("title", "");
		let unmutedTogether = 0;
		bench.onStep = () => { if (bench.elementArray.filter((element) => !element.paused && !element.muted).length > 1) unmutedTogether++; };
		bench.run((lap + 3) * 1000);
		check("where `volume` is ignored (iOS) the changeover is a cut between `muted` flags, never both at full", unmutedTogether === 0 && bench.live("title") === bench.elementArray[1] && bench.live("title").muted === false);
	}

	// ------------------------------------------------------------------ the host's music
	{
		const bench = musicBench();
		const hc = bench.hc;
		const host = bench.global;
		const song = { muted: false, paused: false, volume: 0.4, duration: 300, currentTime: 100, pause() { this.paused = true; }, play() { this.paused = false; } };
		const callArray = [];
		host.musicDisabled = false;
		host.playlist = [{ muted: false, paused: true, volume: 0, pause() { this.paused = true; } }, song];
		host.currentAudio = song;
		host.timeoutID = setTimeout(() => callArray.push("TIMER FIRED"), 1e8);
		host.startMusic = () => callArray.push("startMusic");
		host.pauseAll = () => { callArray.push("pauseAll"); song.pause(); };
		host.unpauseAll = () => { callArray.push("unpauseAll"); song.play(); };
		host.data = { player: { musicVolume: 50 } };

		hc.music.onScene("title", "");
		check("the host's songs are MUTED while honeycomb plays -- never paused, which sound.js reads as an autoplay block and answers by switching off sound effects too",
			host.playlist.every((entry) => entry.muted === true) && song.paused === false && song.volume === 0.4 && callArray.length === 0, callArray.join());
		check("and its next-song timer is stopped, so no song can start unmuted underneath", host.timeoutID == null);
		bench.run(3000);
		check("honeycomb's music follows the host's volume slider", Math.abs(bench.live("title").volume - 0.5 * bench.music.volume) < 1e-9, String(bench.live("title").volume));

		hc.platform.setMusicEnabled(false);
		hc.platform.setMusicEnabled(true);
		check("the music switch inside honeycomb never wakes the host's song over honeycomb's", callArray.length === 0 && host.musicDisabled === false, callArray.join());

		hc.music.end();
		check("leaving unmutes the host's songs and restarts its next-song timer", host.playlist.every((entry) => entry.muted === false) && host.timeoutID != null && song.paused === false);
		check("and releases every element honeycomb made", bench.elementArray.every((element) => element.paused === true && element.released === true) && Object.keys(hc.music.playerMap).length === 0);
		clearTimeout(host.timeoutID);

		hc.music.onScene("title", "");
		hc.platform.setMusicEnabled(false);
		hc.music.end();
		check("music switched OFF inside honeycomb leaves the host paused by its own pauseAll", callArray.join() === "pauseAll" && song.paused === true, callArray.join());
		hc.music.onScene("title", "");
		hc.platform.setMusicEnabled(true);
		hc.music.end();
		check("and switched back ON inside, the host is woken by its own unpauseAll", callArray.join() === "pauseAll,unpauseAll" && song.paused === false, callArray.join());

		const bare = musicBench();
		bare.global.musicDisabled = true;
		bare.global.playlist = [];
		bare.global.unpauseAll = () => { throw new Error("unpauseAll reads playlist[0] and throws on an empty playlist"); };
		let threw = false;
		try { bare.hc.platform.setMusicEnabled(true); } catch (error) { threw = true; }
		check("a host that never started a song (every dev preview) survives the music switch", threw === false);
	}
}

console.log("\n[124] Session 50 -- E12: the Act1-1 clerk recast as The Shroud, a black mold colony");
{
	const hc = newEngine();
	const imageFolder = path.resolve(ROOT, "..", "..", "v13 spire images");
	const pall = hc.findDefinition(hc.enemyArray, "tallyman");

	check("the Act1-1 boss is The Shroud", pall.name === "The Shroud", pall.name);
	// The species tag moved because a mold colony is not a machine. Nothing in the card or relic tables
	// keys off either word, measured before the change, so this is a display and bestiary change only.
	check("and it is a plant rather than a construct",
		pall.tagArray.indexOf("plant") >= 0 && pall.tagArray.indexOf("construct") < 0, pall.tagArray.join());

	// RETOOL, DON'T RELOCATE. E7 measured this boss's numbers and the recast is forbidden to move them;
	// these are the values budget-audit.js and enemy-template.js were run against.
	check("its health is the E7 re-budget, untouched", pall.baseHealth === 205 && pall.healthVariance === 0);
	check("its role and boss flag are untouched", pall.role === "boss" && pall.isBoss === true);
	check("its five moves are the same five indices in the same order",
		pall.moveArray.map((move) => move.card).join() === "tallySlam,tallyCollect,tallyAudit,tallyInterest,tallyReckoning",
		pall.moveArray.map((move) => move.card).join());
	check("and it still opens carrying one stack of its own passive",
		pall.startingStatusArray.length === 1 && pall.startingStatusArray[0].status === "ledger" &&
		pall.startingStatusArray[0].stacks === 1);

	// The mechanic did not change, only what it is called: disturbance feeds the colony, and the feed
	// is spent all at once. The hook is what makes that true, so it is what gets asserted.
	const damp = hc.findDefinition(hc.statusArray, "ledger");
	const bloom = hc.findDefinition(hc.statusArray, "tally");
	check("The Damp still answers a card played by the other side",
		damp.name === "The Damp" && Object.keys(damp.hooks).join() === "onOpponentCardPlayed",
		Object.keys(damp.hooks).join());
	// `reactionHooks` compiles its reactions into closures, so the effect inside is not reachable from
	// the table -- the hook NAME is as far as a structural check can see. What is checkable, and is the
	// half that actually rots, is the two halves of the rename agreeing: the status's own name and the
	// line printed under it.
	check("and what it grants is Bloom, in both its name and the line the player reads",
		bloom.name === "Bloom" && damp.description.indexOf(bloom.name) >= 0, damp.description);

	// A status index and a VALUE registry index both spell `tally`, in different arrays. findDefinition
	// returns the first match of whichever array it is handed, so the two never shadow -- but a session
	// that "tidied" one into the other would break every ability reading an event amount.
	check("the tally VALUE registry entry is still separate from the Bloom status",
		hc.findDefinition(hc.valueArray, "tally") != null &&
		hc.findDefinition(hc.valueArray, "tally") !== bloom);

	// Fruiting declares its own text because a generated line for a scaling amount says neither whose
	// stacks nor how many. A declared line can drift from the status it names; this is the check that
	// it has not.
	const fruiting = hc.findDefinition(hc.cardArray, "tallyReckoning");
	check("Fruiting's declared text names Bloom and not the old Tally",
		fruiting.name === "Fruiting" && fruiting.text.indexOf("Bloom") >= 0 && fruiting.text.indexOf("Tally") < 0,
		fruiting.text);

	// Indices stay (they are save data); WORDS are what the recast moved. Anything a player can read
	// that still says clerk is a miss, and the four move renames are easy to leave half-done.
	const clerkWordArray = ["Tallyman", "Ledger Slam", "Collect Debt", "Compound Interest", "Reckoning", "Counting House"];
	const visibleArray = [];
	for (const card of hc.cardArray) visibleArray.push(card.name, card.text);
	for (const status of hc.statusArray) visibleArray.push(status.name, status.description);
	for (const enemy of hc.enemyArray) visibleArray.push(enemy.name);
	for (const encounter of hc.encounterArray) {
		visibleArray.push(encounter.name);
		for (const condition of encounter.victoryConditionArray || []) visibleArray.push(condition.text);
	}
	const survivorArray = clerkWordArray.filter((word) =>
		visibleArray.some((line) => typeof line === "string" && line.indexOf(word) >= 0));
	check("no player-visible string still calls it the clerk", survivorArray.length === 0, survivorArray.join());
	check("while the card indices are deliberately still the clerk's",
		hc.findDefinition(hc.cardArray, "tallySlam") != null && hc.findDefinition(hc.cardArray, "tallyCollect") != null);

	// Both statuses were pointed at new icons. An icon that does not exist renders as nothing at all and
	// no rule reports it, which is exactly the class of miss that survives a green suite.
	for (const status of [damp, bloom]) {
		check("the " + status.name + " icon exists on disk",
			fs.existsSync(path.join(imageFolder, status.iconPath + ".webp")), status.iconPath);
	}
}

console.log("\n[125] Session 50 -- `benched`: finished content held out of a build, and the Salvager on the bench");
{
	const hc = newEngine();
	const benchedArray = hc.encounterArray.filter((encounter) => encounter.benched === true);

	check("the two Scrap Salvager encounters are the benched ones",
		benchedArray.map((encounter) => encounter.index).sort().join() === "salvagerCrew,salvagerDeep",
		benchedArray.map((encounter) => encounter.index).join());
	// The bench has to be the ONLY thing holding them back, or deleting the field would not ship them.
	check("and nothing else is holding them out of the pool",
		benchedArray.every((encounter) => encounter.testFixture !== true && encounter.isElite === true &&
			encounter.regionIndexArray.indexOf(1) >= 0));

	// Behavioural, not declarative: the flag is worth nothing unless the roller honours it. Region 1's
	// elite pool at both tiers, rolled hard enough that a 1-in-4 miss cannot explain a clean run.
	// A run has to exist first, or every roll draws from the unseeded stream and says so 800 times.
	startRun(hc, 5011);
	const seen = {};
	let nullCount = 0;
	for (const tier of ["middle", "late"]) {
		for (let roll = 0; roll < 400; roll++) {
			const encounter = hc.rollEncounter(tier, { elite: true, regionIndex: 1 });
			if (encounter == null) { nullCount++; continue; }
			seen[encounter.index] = (seen[encounter.index] || 0) + 1;
		}
	}
	check("800 region-1 elite rolls never return a benched encounter",
		seen.salvagerCrew == null && seen.salvagerDeep == null, Object.keys(seen).join());
	// Benching the last entry of a pool would silently hand elite nodes an ordinary fight (E11's bug).
	check("and every one of those rolls still found an elite fight", nullCount === 0, "nulls: " + nullCount);
	check("region 1's elite pool still has entries left to roll", Object.keys(seen).length >= 2, Object.keys(seen).join());

	// The Salvager is BENCHED, not cut -- the workstream's law forbids cutting an enemy. He must still be
	// on the roster, still fielded by those two encounters, and simply unreachable from a map.
	check("the Scrap Salvager is still on the roster and still in those two encounters",
		hc.findDefinition(hc.enemyArray, "drownedSalvager") != null &&
		benchedArray.every((encounter) => encounter.enemyIndexArray.indexOf("drownedSalvager") >= 0));
	const reachableArray = hc.encounterArray.filter((encounter) =>
		encounter.benched !== true && encounter.testFixture !== true &&
		encounter.enemyIndexArray.indexOf("drownedSalvager") >= 0);
	check("and no rollable encounter fields him", reachableArray.length === 0,
		reachableArray.map((encounter) => encounter.index).join());
}

