console.log("\n[126] 2026-09-21 -- an ordinary enemy is `1-combat` and `1-offense`, and `-basic` is never an enemy file");
{
	// Noodle: "Basic combat sprites use -combat. Ordinary enemies should have -combat and -offense, that's
	// it. Players, bosses, special specific peeps get other sprites. -basic is used for the standing
	// sprites in the teambuilding scene."
	//
	// The enemy folder was tidied four times and put back four times, because three places in the engine
	// asked an enemy for `-basic` (the sprite chain's floor, the portrait chain, the boot warm) and a chain
	// with no file left re-requested its last path on every repaint. This block holds all four shut, and
	// then holds the FOLDER to the rule, so the next tidy cannot be quietly undone either.
	const hc = newEngine();
	hc.ui = hc.ui || { missingPathArray: {} };
	const imageFolder = path.resolve(ROOT, "..", "..", "v13 spire images");
	const fighter = (enemy, health) => ({ side: "enemy", enemyIndex: enemy.index, health: health, maxHealth: 10, statusArray: [] });
	const isSpecial = (enemy) => enemy.artPoseArray != null;

	// 1. No enemy is ever asked for a `-basic` file, in any pose, healthy or hurt.
	const basicAskArray = [];
	for (const enemy of hc.enemyArray) {
		for (const pose of hc.art.poseArray) {
			for (const health of [10, 1]) {
				for (const one of hc.art.spriteChain(fighter(enemy, health), pose.index, { state: null })) {
					if (/-basic$/.test(one)) basicAskArray.push(enemy.index + ":" + one);
				}
			}
		}
		for (const one of hc.art.enemyPortraitChain(enemy.index)) if (/-basic$/.test(one)) basicAskArray.push(enemy.index + ":" + one);
	}
	check("no enemy sprite or portrait request names a -basic file", basicAskArray.length === 0, basicAskArray.slice(0, 5).join("; "));

	// 2. An ordinary enemy is asked for exactly two files, whatever the fight does to it.
	const ordinary = hc.enemyArray.find((enemy) => !isSpecial(enemy));
	const base = hc.art.baseFolder({ enemyIndex: ordinary.index });
	check("a hit reaction on an ordinary enemy asks for 1-combat and nothing else",
		JSON.stringify(hc.art.spriteChain(fighter(ordinary, 10), "damaged", { state: null })) === JSON.stringify([base + "/1-combat"]));
	check("a hurt ordinary enemy is still asked for tier 1 only",
		JSON.stringify(hc.art.spriteChain(fighter(ordinary, 1), "combat", { state: null })) === JSON.stringify([base + "/1-combat"]));
	check("its attack asks for 1-offense, then 1-combat",
		JSON.stringify(hc.art.spriteChain(fighter(ordinary, 10), "offense", { state: null })) === JSON.stringify([base + "/1-offense", base + "/1-combat"]));
	check("its face is its 1-combat drawing, with no portrait file asked for",
		JSON.stringify(hc.art.enemyPortraitChain(ordinary.index)) === JSON.stringify([base + "/1-combat"]));

	// 3. A special case declares what it has, and is asked for it.
	const anastasia = hc.findDefinition(hc.enemyArray, "gauntletAnastasia");
	const anastasiaBase = hc.art.baseFolder({ enemyIndex: "gauntletAnastasia" });
	check("a declared hurt pose is asked for first",
		hc.art.spriteChain(fighter(anastasia, 1), "damaged", { state: null })[0] === anastasiaBase + "/2-damaged");
	check("a declared portrait is asked for first", hc.art.enemyPortraitChain("gauntletAnastasia")[0] === anastasiaBase + "/0-portrait");

	// 4. The boot warm takes its enemy paths from the same place.
	const warmArray = [];
	const realWarm = hc.preload.warm;
	hc.preload.warm = (pathArray) => { for (const one of pathArray) warmArray.push(one); };
	hc.preload.warmCommon();
	hc.preload.warm = realWarm;
	const warmBasicArray = warmArray.filter((one) => one.indexOf(hc.art.rootArray.enemy + "/") === 0 && /-basic$/.test(one));
	check("the boot warm asks no enemy for a -basic file", warmBasicArray.length === 0, warmBasicArray.slice(0, 5).join("; "));

	// 5. A chain with nothing left draws the placeholder and requests nothing.
	const artSource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-art.js"), "utf8");
	const chainTagSource = artSource.slice(artSource.indexOf("honeycomb.art.chainTag = function"), artSource.indexOf("honeycomb.art.normaliseCanvas = function"));
	check("the sprite tag draws the placeholder outright for an all-missing chain",
		/if \(liveArray\.length === 0\) \{\s*return '<img src="' \+ honeycomb\.placeholderArt\(pathArray\[0\]\)/.test(chainTagSource));

	// 5b. THE WALK FINISHES. The tag's attribute is lowercased by the HTML parser, and the scripts used to
	// write a differently-named one, so the error handler read position 0 for ever: a chain with two
	// missing files re-requested the same file without end, and after a pose swap a missing `1-offense`
	// was recorded as a missing `1-combat`. Run here on an element that behaves as the DOM does.
	{
		const attributeMap = {};
		const element = {
			getAttribute: (name) => (attributeMap[name.toLowerCase()] == null ? null : attributeMap[name.toLowerCase()]),
			setAttribute: (name, value) => { attributeMap[name.toLowerCase()] = String(value); },
			src: "", onerror: () => {},
		};
		const realPlaceholder = hc.placeholderArt;
		hc.placeholderArt = (label) => "placeholder:" + label;
		hc.ui.missingPathArray = {};
		// The tag as the parser leaves it, then a live pose swap onto a different chain.
		element.setAttribute("data-honeycombchain", "enemies/x/default/1-combat");
		element.setAttribute("data-honeycombchainat", "0");
		hc.art.writeChain(element, ["enemies/x/default/1-offense", "enemies/x/default/1-combat"], 0);
		hc.art.onChainError(element);
		check("a missing attack pose is recorded as the attack pose, not as the enemy's good 1-combat",
			hc.ui.missingPathArray["enemies/x/default/1-offense"] === true && hc.ui.missingPathArray["enemies/x/default/1-combat"] !== true);
		check("and the walk moves on to 1-combat", /1-combat/.test(element.src));
		hc.art.writeChain(element, ["a", "b", "c"], 0);
		const sourceArray = [];
		for (let step = 0; step < 6 && element.onerror != null; step++) { hc.art.onChainError(element); sourceArray.push(element.src); }
		check("a chain of three missing files is walked once and ends on the placeholder",
			element.onerror === null && sourceArray.length === 3 && sourceArray[2] === "placeholder:a", sourceArray.join(" > "));
		hc.placeholderArt = realPlaceholder;
		hc.ui.missingPathArray = {};
		const combatSource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
		check("no script writes the chain through `dataset` any more",
			!/dataset\.honeycombChain/i.test(combatSource.replace(/\/\/.*$/gm, "")) && !/dataset\.honeycombChain/i.test(artSource.replace(/\/\/.*$/gm, "")));
	}

	// 6. THE FOLDER. Every file the game will ask for is there, and an ordinary enemy's folder holds
	// nothing else. `node tools/enemy-art-tidy.js` reports and fixes a failure here.
	const missingArray = [];
	const extraArray = [];
	const allowedArray = ["1-combat.webp", "1-offense.webp", ".generated.txt"];
	// Real drawings outside the rule that are waiting on Noodle's decision. An entry here is a question
	// that is still open, not a file the game needs; nothing in the engine asks for any of them.
	// Empty since 2026-09-22: the celestialQueen `2-offense` it held was generator output (Noodle), and
	// is archived in `_source/_archive-enemy-poses/`.
	const undecidedArray = [];
	const specialFolderMap = {};
	for (const enemy of hc.enemyArray) if (isSpecial(enemy)) specialFolderMap[hc.art.baseFolder({ enemyIndex: enemy.index })] = true;
	const seenFolderMap = {};
	for (const enemy of hc.enemyArray) {
		const folder = hc.art.baseFolder({ enemyIndex: enemy.index });
		for (const warmPath of hc.art.enemyWarmPaths(enemy)) {
			if (enemy.artOwed !== true && !fs.existsSync(path.join(imageFolder, warmPath + ".webp"))) missingArray.push(warmPath);
		}
		if (seenFolderMap[folder] === true || specialFolderMap[folder] === true) continue;
		seenFolderMap[folder] = true;
		const folderPath = path.join(imageFolder, folder);
		if (!fs.existsSync(folderPath)) continue;
		for (const name of fs.readdirSync(folderPath)) {
			if (allowedArray.indexOf(name) < 0 && undecidedArray.indexOf(folder + "/" + name) < 0) extraArray.push(folder + "/" + name);
		}
	}
	check("every enemy's resting drawing exists", missingArray.length === 0, missingArray.slice(0, 8).join("; "));
	check("an ordinary enemy's folder holds 1-combat, 1-offense and nothing else (run tools/enemy-art-tidy.js)",
		extraArray.length === 0, extraArray.length + " extra: " + extraArray.slice(0, 8).join("; "));
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[127] 2026-09-21 -- the remembered tree lookup (`selectedNodeArray`) always equals a fresh one");
{
	// balance_tests/BRIEF.md Step 1. `selectedNodeArray` runs on every card resolved, so its answer is
	// kept per character. The key is the CONTENT (outfit + selection list), and this block holds it to
	// that: after every kind of change, the remembered answer must equal a computation that never
	// remembers anything. The reference below is the pre-cache algorithm, kept here on purpose.
	const hc = newEngine();
	hc.state = hc.newProfile();
	hc.setResource("experience", 100000);
	const fresh = (selection) => {
		const tree = hc.progression.treeFor(selection);
		if (tree == null) return "";
		const result = [];
		for (const node of tree.nodeArray) {
			const rank = Math.min(hc.progression.rankOf(selection.characterIndex, node.index), hc.progression.rankMaximum(node));
			for (let copy = 0; copy < rank; copy++) result.push(node.index);
		}
		return result.join(",");
	};
	const remembered = (selection) => hc.progression.selectedNodeArray(selection).map((node) => node.index).join(",");
	const same = (label, selection) => check(label, remembered(selection) === fresh(selection),
		"remembered: " + remembered(selection) + " | fresh: " + fresh(selection));
	const loadout = { characterIndex: "brienne", outfitIndex: "default", equipmentArray: [] };

	same("an empty selection", loadout);
	hc.progression.select(loadout, "briStart");
	same("after buying a node", loadout);
	check("and the answer really did change", remembered(loadout) === "briStart");
	hc.progression.select(loadout, "briAbility1");
	hc.progression.select(loadout, "briExtraAttack");
	same("after buying more nodes", loadout);
	let rankedNode = null;
	for (const node of hc.progression.treeFor(loadout).nodeArray) {
		if (hc.progression.rankMaximum(node) > 1 && hc.progression.refuseReason(loadout, node.index) === null) { rankedNode = node; break; }
	}
	if (rankedNode != null) {
		hc.progression.select(loadout, rankedNode.index);
		hc.progression.select(loadout, rankedNode.index);
		const count = remembered(loadout).split(",").filter((name) => name === rankedNode.index).length;
		same("after buying a second rank", loadout);
		check("a second rank is a second copy", count >= 2, "copies of " + rankedNode.index + ": " + count);
	} else check("the brienne tree has a node with more than one rank to test", false);
	hc.progression.unselect(loadout, "briAbility1");
	same("after refunding a node and everything hanging off it", loadout);

	// A snapshot / restore round trip, which is what every forecast and bot lookahead does. The restore
	// replaces the whole state object, so a cache keyed on anything but content would answer wrongly here.
	const snapshot = hc.snapshotState();
	const beforeBuy = remembered(loadout);
	hc.progression.select(loadout, "briAbility1");
	same("after a buy following a snapshot", loadout);
	check("and that buy changed the answer", remembered(loadout) !== beforeBuy);
	hc.restoreState(snapshot);
	same("after restoring the snapshot that undoes the buy", loadout);
	check("and the restored answer is the snapshot's", remembered(loadout) === beforeBuy);

	// Outfit change: the bloodied fixture locks three nodes, so the tree differs and a held locked node
	// contributes nothing.
	const bloodied = { characterIndex: "brienne", outfitIndex: "bloodied", equipmentArray: [] };
	hc.progression.select(loadout, "briAbility1");
	hc.progression.select(loadout, "briExtraAttack");
	same("the default outfit before the change", loadout);
	check("the extra-attack node is held in the default outfit", remembered(loadout).indexOf("briExtraAttack") >= 0);
	same("in an outfit that locks nodes", bloodied);
	check("a locked node contributes nothing", remembered(bloodied).indexOf("briExtraAttack") < 0);
	same("and back to the default outfit", loadout);
	check("the outfit change did not leak into the default outfit's answer", remembered(loadout).indexOf("briExtraAttack") >= 0);

	hc.progression.reset(loadout);
	same("after a reset", loadout);
	check("and a reset leaves nothing", remembered(loadout) === "");

	// Two characters keep separate answers.
	const nettle = { characterIndex: "nettle", outfitIndex: "default", equipmentArray: [] };
	hc.progression.select(loadout, "briStart");
	hc.progression.select(nettle, "netStart");
	same("brienne beside nettle", loadout);
	same("nettle beside brienne", nettle);
	check("neither character reads the other's answer", remembered(loadout) === "briStart" && remembered(nettle) === "netStart",
		remembered(loadout) + " / " + remembered(nettle));

	check("an unchanged selection returns the stored answer without rebuilding it",
		hc.progression.selectedNodeArray(loadout) === hc.progression.selectedNodeArray(loadout));
	check("a member that is null or has no character gets an empty answer",
		hc.progression.selectedNodeArray(null).length === 0 && hc.progression.selectedNodeArray({}).length === 0);
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[128] 2026-09-21 -- the balance tests' run player pays what the game pays, and plays the same run twice");
{
	// balance_tests/BRIEF.md Step 4. The victory screen's payout moved into `honeycomb.combat.settleVictory`
	// so a headless run pays exactly what the screen pays. The run player then drives the game's own
	// overlays. This block holds the moved function, the repeatability of a run, damage carrying from one
	// fight to the next, and the route rule, each against the game's own numbers.
	const balanceLib = path.join(__dirname, "balance", "lib");
	const { loadEngine } = require(path.join(balanceLib, "engine.js"));
	const combatPlayer = require(path.join(balanceLib, "combat-player.js"));
	const runPlayer = require(path.join(balanceLib, "run-player.js"));
	const policies = require(path.join(balanceLib, "policies.js"));
	const party = ["brienne", "nettle", "severine"].map((characterIndex) => ({ characterIndex, outfitIndex: "default" }));

	// 1. THE MOVED PAYOUT.
	const overlaySource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-overlays-combat.js"), "utf8");
	check("the victory screen asks the engine for its payout",
		overlaySource.indexOf("honeycomb.combat.settleVictory()") >= 0);
	check("and no longer pays gold, relics or experience itself",
		overlaySource.indexOf("honeycomb.combat.finishVictory()") < 0 && overlaySource.indexOf("honeycomb.addResource(\"gold\", reward.gold)") < 0);
	{
		const hc = loadEngine();
		hc.state = hc.newProfile();
		hc.newRun(party, 11);
		let settled = null;
		for (let attempt = 0; attempt < 6 && settled == null; attempt++) {
			hc.state = hc.newProfile();
			hc.newRun(party, 11 + attempt);
			hc.combat.begin("wispCluster", {});
			if (combatPlayer.playCombat(hc, false).won !== true) continue;
			const goldBefore = hc.getResource("gold");
			const experienceBefore = hc.progression.personalExperience("brienne") + hc.progression.personalExperience("nettle") + hc.progression.personalExperience("severine");
			const reward = hc.combat.settleVictory();
			const experienceAfter = hc.progression.personalExperience("brienne") + hc.progression.personalExperience("nettle") + hc.progression.personalExperience("severine");
			settled = { reward, goldBefore, goldAfter: hc.getResource("gold"), experienceBefore, experienceAfter, hc };
		}
		check("a won fight settles", settled != null);
		if (settled != null) {
			check("its gold is paid", settled.goldAfter === settled.goldBefore + settled.reward.gold, settled.goldBefore + " + " + settled.reward.gold + " -> " + settled.goldAfter);
			check("its experience is paid to the party", settled.experienceAfter > settled.experienceBefore && settled.reward.experience != null,
				settled.experienceBefore + " -> " + settled.experienceAfter);
			check("its relic, when it rolls one, is held", settled.reward.relicIndex == null || settled.hc.hasRelic(settled.reward.relicIndex));
		}
	}

	// 2. THE SAME SEED PLAYS THE SAME RUN, on a second engine as well.
	const recordOf = (hc, seed) => { hc.state = hc.newProfile(); return runPlayer.playRun({ hc, party, seed, policy: policies.thinDeckPolicy }); };
	const engineA = loadEngine({ drivenOverlays: true }), engineB = loadEngine({ drivenOverlays: true });
	const first = recordOf(engineA, 7);
	const again = recordOf(engineA, 7);
	const other = recordOf(engineB, 7);
	const different = recordOf(engineB, 8);
	check("a run ends, and is either won or lost", first.outcome === "victory" || first.outcome === "defeat", String(first.outcome));
	check("the same seed on the same engine gives the same record", JSON.stringify(first) === JSON.stringify(again));
	check("and on a fresh engine", JSON.stringify(first) === JSON.stringify(other));
	check("a different seed gives a different record", JSON.stringify(first) !== JSON.stringify(different));

	// 3. DAMAGE CARRIES. Two fights on consecutive stops with nothing between them start where the last ended.
	const fightTypes = ["combat", "elite", "boss"];
	const countCarried = (record) => {
		const fightAt = {};
		for (const fight of record.fightArray) fightAt[fight.nodeId] = fight;
		let pairs = 0, carried = 0;
		for (let index = 0; index + 1 < record.nodeArray.length; index++) {
			const a = record.nodeArray[index], b = record.nodeArray[index + 1];
			if (fightTypes.indexOf(a.type) < 0 || fightTypes.indexOf(b.type) < 0 || fightAt[a.id] == null || fightAt[b.id] == null || fightAt[a.id].won !== true) continue;
			pairs++;
			if (JSON.stringify(fightAt[a.id].healthAfter) === JSON.stringify(fightAt[b.id].healthBefore)) carried++;
		}
		return { pairs, carried };
	};
	const measured = countCarried(first);
	check("this run has back-to-back fights to compare", measured.pairs > 0, "pairs: " + measured.pairs);
	check("each fight starts with the health the last one ended with", measured.pairs > 0 && measured.carried === measured.pairs, measured.carried + " of " + measured.pairs);
	// The check has to be able to fail: hand the second fight of a pair a fresh party and it must be noticed.
	const tampered = JSON.parse(JSON.stringify(first));
	for (let index = 0; index + 1 < tampered.nodeArray.length; index++) {
		const a = tampered.nodeArray[index], b = tampered.nodeArray[index + 1];
		const second = tampered.fightArray.find((fight) => fight.nodeId === b.id);
		if (fightTypes.indexOf(a.type) >= 0 && fightTypes.indexOf(b.type) >= 0 && second != null) { second.healthBefore = second.healthBefore.map(() => 9999); break; }
	}
	check("and the comparison notices a fight that did not carry it over", countCarried(tampered).carried < measured.carried);

	// 3b. A WON RUN IS RECORDED AS WON. Found the hard way: a profile reference kept from before the run went stale
	// when a dry run replaced the state, and every won run was recorded as a loss. A party made very hard to
	// kill wins the run, and the profile's own win counter and the record must agree.
	{
		const hc = loadEngine({ drivenOverlays: true });
		hc.state = hc.newProfile();
		const winsBefore = hc.state.profile.runsWon;
		const won = runPlayer.playRun({
			hc, party, seed: 2, policy: policies.thinDeckPolicy,
			afterNewRun: (engine) => { for (const member of engine.state.run.partyArray) { member.maxHealth = 4000; member.health = 4000; } },
		});
		check("a party that cannot be killed wins the run, and the record says so", won.outcome === "victory", String(won.outcome));
		check("the profile's own win counter went up by one", hc.state.profile.runsWon === winsBefore + 1, winsBefore + " -> " + hc.state.profile.runsWon);
		check("a won run paid experience to the party", Object.keys(won.experience).every((name) => won.experience[name] > 0), JSON.stringify(won.experience));
	}

	// 4. THE ROUTE. A run that leaves the first region goes where the boss it just beat says.
	const route = hc_routeCheck();
	function hc_routeCheck() {
		const hc = loadEngine({ drivenOverlays: true });
		let found = null;
		// SESSION 55 WIDENED AND REORDERED THIS LIST. Whether a seed's run reaches and beats a boss under
		// the random policy depends on the map it generates, and session 55 changed map generation in three
		// ways at once (the first row is a rest, treasure is capped, the edge fan no longer leans one way).
		// None of the old six descended afterwards. The list is longer now so one changed number cannot
		// empty it again, and the ones known to descend are first so the loop stops on the first try.
		// The list is re-found whenever content changes enough to reshape a run: session 55b rebuilt every
		// ordinary encounter on all three Act1-2 routes, and none of the previous seeds descended after it.
		// Known to descend first, so the loop stops on its first try.
		for (const seed of [7, 13, 14, 18, 25, 26, 15, 16, 19, 20, 3, 4, 5, 6, 9, 10]) {
			hc.state = hc.newProfile();
			const record = runPlayer.playRun({ hc, party, seed, policy: policies.randomPolicy });
			if (record.route != null) { found = record; break; }
		}
		return { hc, record: found };
	}
	check("a run that descended was found to check", route.record != null);
	if (route.record != null) {
		const bossFight = route.record.fightArray.find((fight) => fight.boss && fight.won);
		const table = route.hc.tuning.map.route;
		const entry = table.byBossArray.find((row) => row.bossEncounterIndex === bossFight.encounter);
		const expected = entry == null ? table.defaultSecondRegion : entry.regionIndex;
		check("it descended into the region the boss it beat names", route.record.route === expected, route.record.route + " vs " + expected + " after " + bossFight.encounter);
	}
}

// ---------------------------------------------------------------------------------------------------
console.log("\n[129] 2026-09-21 -- session 55's playtest fixes: the preview does not spend, the gate holds, the words are filled in");
{
	// Five reports from Noodle's last two playtest sessions, each with the thing that was actually wrong
	// under it. Root FEEDBACK.md's inbox, filed into the workstreams in session 55.

	// 1. "Whetstone relic does nothing". honeycomb.modifiedDamage is shared by the real hit and by the
	// live number printed on a card in hand, and the hand is re-described every beat -- so the
	// once-a-turn charge was spent by a PREVIEW before the player could play anything. A preview asks;
	// it does not spend.
	{
		const hc = newEngine();
		startRun(hc, 1234, [{ characterIndex: "brienne", outfitIndex: "default", equipmentArray: ["whetstone"] }]);
		const combat = hc.combat.begin("loneSporeling", {});
		const ally = hc.state.run.partyArray[0];
		const enemy = combat.enemyArray[0];
		hc.combat.startPlayerTurn();
		check("the Whetstone's charge is up at the start of the turn", ally.whetstoneReady === true);

		const describeContext = { live: { source: ally, target: enemy, combat: combat } };
		const describedArray = [];
		for (let repeat = 0; repeat < 5; repeat++) describedArray.push(hc.describeAmount(10, {}, describeContext, null));
		check("a card in hand prints the bonus every time it is described",
			describedArray.every((printed) => String(printed) === "12"), describedArray.join(","));
		check("and describing it five times does not spend the charge", ally.whetstoneReady === true);

		const realContext = hc.newEffectContext({ source: ally, target: enemy, combat: combat });
		check("the play itself gets the bonus", hc.modifiedDamage(ally, enemy, 10, {}, realContext) === 12);
		check("which spends the charge", ally.whetstoneReady === false);
		check("so the second attack this turn does not get it",
			hc.modifiedDamage(ally, enemy, 10, {}, hc.newEffectContext({ source: ally, target: enemy, combat: combat })) === 10);
		hc.combat.startPlayerTurn();
		check("and the next turn hands it back", ally.whetstoneReady === true);
	}

	// 2. "Cracked Ampoule shouldn't appear if you don't have a poison character". It already carried the
	// offerCondition. The TREASURE roll built its own candidate list and never asked, so a chest handed
	// out all twelve character-gated relics. It draws from honeycomb.uncarriedRelicArray now, which is
	// the list the fight reward already used.
	{
		const hc = newEngine();
		startRun(hc, 7, [{ characterIndex: "brienne", outfitIndex: "default" }, { characterIndex: "cinder", outfitIndex: "default" }]);
		const offeredArray = [];
		for (let repeat = 0; repeat < 600; repeat++) {
			const relic = hc.rollRelicOffer();
			if (relic != null && offeredArray.indexOf(relic.index) < 0) offeredArray.push(relic.index);
		}
		check("the chest offers something at all", offeredArray.length > 0);
		const allowedArray = hc.uncarriedRelicArray(null, "common").map((relic) => relic.index);
		const leakArray = offeredArray.filter((index) => allowedArray.indexOf(index) < 0);
		check("and nothing it offers is barred by its own offerCondition", leakArray.length === 0, leakArray.join(","));
		check("Nettle's relic is not on the table for a party without Nettle",
			offeredArray.indexOf("crackedAmpoule") < 0 && hc.relicOfferable(hc.findDefinition(hc.relicArray, "crackedAmpoule")) === false);
	}

	// 3. "Mulligan stone should not appear if max rerolls is 0". It refills the reroll pool, so it is a
	// dead rare in a run that has no pool. `resource` values read a maximum now.
	{
		const hc = newEngine();
		startRun(hc, 11);
		const stone = hc.findDefinition(hc.relicArray, "mulliganStone");
		check("a run with no reroll pool is not offered the Mulligan Stone",
			hc.resourceMaximum("reroll") === 0 && hc.relicOfferable(stone) === false);
		hc.state.run.resourceMaximumArray.reroll = 2;
		check("a run that has earned rerolls is", hc.relicOfferable(stone) === true);
		check("the value reads the maximum rather than what is left",
			hc.resolveValue({ index: "resource", resource: "reroll", maximum: true }, hc.newEffectContext({})) === 2);
	}

	// 4. "Ransom took my tHP but gave nothing else". It spent up to 8 Temporary HP and drew one card per
	// 4 spent, so 1 to 3 Temporary HP was taken and paid for with nothing. `step` rounds the spend down
	// to what the card will actually pay for.
	{
		const hc = newEngine();
		startRun(hc, 3, [{ characterIndex: "brienne", outfitIndex: "default" }]);
		const combat = hc.combat.begin("loneSporeling", {});
		const ally = hc.state.run.partyArray[0];
		const card = hc.findDefinition(hc.cardArray, "brienneRansom");
		const spendEntry = card.effectArray[0];
		const drawEntry = card.effectArray[1];
		function ransomAt(startingTemporary) {
			ally.temporaryHealth = startingTemporary;
			const context = hc.newEffectContext({ source: ally, target: ally, targetArray: [ally], combat: combat });
			hc.resolveEffectArray([spendEntry], context);
			return { spent: context.tally.temporarySpent == null ? 0 : context.tally.temporarySpent,
				kept: ally.temporaryHealth, draws: hc.resolveValue(drawEntry.amount, context) };
		}
		const belowABlock = [1, 2, 3].map(ransomAt);
		check("under a full block Ransom takes nothing at all",
			belowABlock.every((result) => result.spent === 0 && result.draws === 0),
			JSON.stringify(belowABlock));
		check("and leaves the Temporary HP where it was",
			belowABlock[0].kept === 1 && belowABlock[1].kept === 2 && belowABlock[2].kept === 3);
		const sevenHeld = ransomAt(7);
		check("at 7 it spends one block and keeps the remainder",
			sevenHeld.spent === 4 && sevenHeld.kept === 3 && sevenHeld.draws === 1, JSON.stringify(sevenHeld));
		const eightHeld = ransomAt(8);
		check("at 8 it spends both blocks", eightHeld.spent === 8 && eightHeld.draws === 2, JSON.stringify(eightHeld));
		check("its printed text says so", card.text.indexOf("4 at a time") >= 0, card.text);
	}

	// 5. "Sundered reads, 'Takes {damageincreasePercent}% more damage per stack.'" -- he was quoting what
	// the KEYWORD PANEL on a card showed. honeycomb.keywordDefinition handed back a status's raw
	// `description` while the status icon's own tooltip called honeycomb.statusDescription, so the two
	// disagreed and six statuses printed a token at the player.
	{
		const hc = newEngine();
		const tokenArray = [];
		for (const status of hc.statusArray) {
			const keyword = hc.keywordDefinition(status.index);
			if (keyword != null && /\{\w+\}/.test(String(keyword.description))) tokenArray.push(status.index);
		}
		check("no keyword panel prints an unfilled {token}", tokenArray.length === 0, tokenArray.join(","));
		check("Weak's panel names its real number",
			hc.keywordDefinition("weak").description.indexOf("25%") >= 0, hc.keywordDefinition("weak").description);
		check("and it agrees with the status tooltip",
			hc.keywordDefinition("weak").description === hc.statusDescription(hc.findDefinition(hc.statusArray, "weak")));
	}

	// 6. "Winning 'The Sealed Door' traps you in a loop". The choice that starts a fight returns before
	// the line that records where the event is, so the saved position was still the page the fight was
	// chosen FROM -- and the overlay's "a saved position wins" rule made that page beat the `victoryPage`
	// the win came back with. The player was handed the same choice again, forever.
	{
		const balanceLib = path.join(__dirname, "balance", "lib");
		const { loadEngine } = require(path.join(balanceLib, "engine.js"));
		const hc = loadEngine({ drivenOverlays: true });
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "brienne", outfitIndex: "default" }], 42);

		hc.overlay.open("event", { eventIndex: "theSealedDoor", nodeId: null });
		check("the Sealed Door opens on its first page", hc.eventOverlay.pageIndex == null);
		check("and the run records that it is there",
			hc.state.run.eventState != null && hc.state.run.eventState.eventIndex === "theSealedDoor" &&
			hc.state.run.eventState.pageIndex == null);

		// The win comes back naming the page past the door.
		hc.overlay.open("event", { eventIndex: "theSealedDoor", pageIndex: "beyond", nodeId: null, fromCombat: true });
		check("winning the fight shows the page past the door", hc.eventOverlay.pageIndex === "beyond", String(hc.eventOverlay.pageIndex));
		check("and not the choice that started the fight again",
			hc.state.run.eventState.pageIndex === "beyond", String(hc.state.run.eventState.pageIndex));

		const sealedDoor = hc.findDefinition(hc.eventArray, "theSealedDoor");
		const shownPage = (sealedDoor.pageArray || []).find((page) => page.index === hc.eventOverlay.pageIndex);
		const shownArray = shownPage == null ? [] : shownPage.choiceArray.map((choice) => choice.index);
		check("so the choices on show are the reliquary and the drop, not the bolts",
			shownArray.join(",") === "reliquary,drop", shownArray.join(","));

		// The saved position still wins for an ordinary reopen, which is what it is for: a refresh
		// mid-event, and the map's unfinished-node button.
		hc.overlay.open("event", { eventIndex: "theSealedDoor", nodeId: null });
		check("an ordinary reopen still resumes where the event was left", hc.eventOverlay.pageIndex === "beyond");
	}

	// 7. THE HAND EDITS THE TREE GENERATOR REVERTS. Session 55 ran generate-progression-trees.js to
	// reprice one field and it replaced each character's whole nodeArray, undoing four pieces of content
	// that had been edited into the file by hand since the generator last ran. Only ONE of the four had a
	// check, which is why the other three were nearly shipped. They have checks now. See the banner at
	// the top of that tool.
	{
		const hc = newEngine();
		const nodeOf = (characterIndex, nodeIndex) => hc.findDefinition(hc.characterArray, characterIndex)
			.progressionTree.nodeArray.find((entry) => entry.index === nodeIndex);

		const counterguard = nodeOf("brienne", "briCex3");
		check("briCex3 is Counterguard, not the Taunt it replaced in session 31",
			counterguard.name === "Counterguard" && counterguard.retortStacks === 1 &&
			counterguard.firstHitTaunt == null && counterguard.hooks != null &&
			typeof counterguard.hooks.onCombatStart === "function", counterguard.name);

		const aegis = nodeOf("brienne", "briAbility2");
		check("Aegis's description is the session-47 wording, where each ally gains HALF",
			aegis.description.indexOf("each ally gains half") >= 0, aegis.description);

		const glimpse = nodeOf("cassadora", "casAbility1");
		check("Cassadora's mechanic is called the Orb, not Foresight",
			glimpse.description.indexOf("Orb") >= 0 && glimpse.description.indexOf("Foresight") < 0, glimpse.description);

		const oneWithNothing = nodeOf("clemence", "clmAbility2");
		check("One with Nothing costs HALF the Devotion spent in life",
			oneWithNothing.description.indexOf("half that much life") >= 0, oneWithNothing.description);

		// And the reprice that started it, on every character rather than only Brienne's.
		const vigourArray = ["brienne", "nettle", "severine", "cassadora", "cinder", "clemence", "anastasia"]
			.map((characterIndex) => hc.findDefinition(hc.characterArray, characterIndex).progressionTree.nodeArray
				.find((entry) => /Start$/.test(entry.index)));
		check("every Vigour node prices its whole self at about 25, however many ranks it splits into",
			vigourArray.every((node) => {
				const ranks = node.rankMaximum == null ? 1 : node.rankMaximum;
				return node.cost === Math.max(1, Math.round(25 / ranks));
			}), vigourArray.map((node) => node.index + ":" + (node.rankMaximum || 1) + "r@" + node.cost).join(" "));
	}

	// 8. "Boss nodes list the boss if encountered before" / "Boss node tooltip should give rundown of
	// boss, again if encountered before". Every boss node read "Boss -- 1 foe. The thing this place
	// belongs to." whichever of the three it was, which is what map/FEEDBACK.md B41 found under "I don't
	// know how to trigger the three routes": the Act1-1 boss decides the route and the node never said so.
	{
		const hc = newEngine();
		startRun(hc, 5, [{ characterIndex: "brienne", outfitIndex: "default" }]);
		hc.map.generateRegion();
		const map = hc.state.run.map;
		const bossNode = map.rowArray[map.rowArray.length - 1].find((node) => node.typeIndex === "boss");
		const encounter = hc.findDefinition(hc.encounterArray, bossNode.encounterIndex);
		const bossIndex = encounter.enemyIndexArray[0];
		const boss = hc.findDefinition(hc.enemyArray, bossIndex);
		const text = () => hc.map.previewContents(bossNode.id).replace(/<[^>]*>/g, " ");

		check("a boss never met keeps its name to itself", text().indexOf(boss.name) < 0, text());
		check("and says nothing about where it leads", text().indexOf("leads to") < 0);

		hc.discovery.record("enemy", bossIndex, null);
		check("a boss met before is named on the node", text().indexOf(boss.name) >= 0, text());
		check("with its health", text().indexOf(boss.baseHealth + " HP") >= 0, text());
		const routeEntry = hc.tuning.map.route.byBossArray
			.find((row) => row.bossEncounterIndex === bossNode.encounterIndex);
		const destination = hc.findDefinition(hc.regionArray, routeEntry.regionIndex);
		check("and the route it decides", text().indexOf("Beating it leads to " + destination.name) >= 0, text());
	}

	// 9. "Have three boss nodes at the end instead of one, each leads to a different Act1-2 route, letting
	// players choose their boss and 1-2 route." The final row was one node with a rolled boss, so which
	// route a run took was a dice roll it never saw.
	{
		const hc = newEngine();
		const region = hc.findDefinition(hc.regionArray, "upperCatacombs");
		const expectedArray = region.bossEncounterIndexArray;
		check("act1-1 has three bosses to put on the row", expectedArray.length === 3, expectedArray.join(","));

		const reachArray = [];
		for (const seed of [5, 11, 23, 37, 44]) {
			startRun(hc, seed, [{ characterIndex: "brienne", outfitIndex: "default" }]);
			hc.map.generateRegion();
			const rowArray = hc.state.run.map.rowArray;
			const bossRow = rowArray[rowArray.length - 1];
			const beforeRow = rowArray[rowArray.length - 2];
			check("seed " + seed + ": the final row is every boss, each one once",
				bossRow.length === expectedArray.length &&
				bossRow.every((node) => node.typeIndex === "boss") &&
				expectedArray.every((index) => bossRow.filter((node) => node.encounterIndex === index).length === 1),
				bossRow.map((node) => node.encounterIndex).join(","));
			for (const node of beforeRow) {
				reachArray.push(bossRow.filter((boss) => node.edgeArray.indexOf(boss.id) >= 0).length);
			}
		}
		check("and every node on the row before them reaches all three, so the choice is always there",
			reachArray.length > 0 && reachArray.every((count) => count === expectedArray.length),
			reachArray.join(","));

		// A region naming ONE boss is untouched: it still ends in a single node.
		const vault = hc.findDefinition(hc.regionArray, "floodedVault");
		check("a region with one boss is left alone", (vault.bossEncounterIndexArray || []).length === 1);
	}

	// 10. "Mushroom Frontier is still called The Flooded Vault". The region's five enemies were recast as
	// dry frontier myconids in session 34; only the title was left behind. The INDEX is unchanged, since
	// it is written into saves and into every encounter that belongs here.
	{
		const hc = newEngine();
		const region = hc.findDefinition(hc.regionArray, "floodedVault");
		check("region 1 is named for the frontier", region.name === "The Mushroom Frontier", region.name);
		check("and its blurb is not about water",
			region.description.indexOf("colder") < 0 && region.description.indexOf("Deeper") < 0, region.description);
		check("its index is left alone, because saves carry it", region.index === "floodedVault");
	}
}

