console.log("\n[132] 2026-09-22 -- an enemy's `artOwed` agrees with its folder (art_pipeline/ART-RESTRUCTURE.md)");
{
	// 23 enemies carried `artOwed: true` for days after their drawings landed, with a comment saying
	// "no drawing yet" above each. The flag only changes behaviour for cards, so nothing failed and the
	// comments went on being wrong. A resting drawing the generator did not write (absent from the
	// folder's `.generated.txt`) is a real drawing, and an enemy standing on one owes no art.
	const hc = newEngine();
	const imageFolder = path.resolve(ROOT, "..", "..", "v13 spire images");
	const owedButDrawnArray = [];
	for (const enemy of hc.enemyArray) {
		const folderPath = path.join(imageFolder, hc.art.baseFolder({ enemyIndex: enemy.index }));
		const restingName = "1-" + hc.art.restingPose() + ".webp";
		if (!fs.existsSync(path.join(folderPath, restingName))) continue;
		const manifestPath = path.join(folderPath, ".generated.txt");
		const manifest = fs.existsSync(manifestPath) ? fs.readFileSync(manifestPath, "utf8").split(/\r?\n/) : [];
		const drawn = manifest.indexOf(restingName) < 0;
		if (drawn && enemy.artOwed === true) owedButDrawnArray.push(enemy.index);
	}
	check("no enemy standing on a real drawing says its art is owed",
		owedButDrawnArray.length === 0, owedButDrawnArray.join(", "));
	check("the three still on generator stand-ins say so (moldLeech, drownedSalvager, hollowChampion)",
		["moldLeech", "drownedSalvager", "hollowChampion"].every((index) =>
			hc.findDefinition(hc.enemyArray, index).artOwed === true));
}

