console.log("\n[135] 2026-09-22 -- session 57: the invitation reaches a shop that was stocked before the switch went on");
// A player walked all three routes and never saw the invitation. Their save stood in a shop whose stock
// was rolled while the switch was off, and stock is rolled once and saved on its map node.
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	hc.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 5);
	const settings = hc.tuning.chessmaster.gauntlet;
	for (const row of hc.tuning.map.route.byBossArray) hc.discovery.record("region", row.regionIndex, null);

	settings.enabled = false;
	const staleStock = hc.shop.rollStock();
	check("a shop stocked with the switch off has no invitation", staleStock.relicArray.every((r) => r.index !== settings.relicIndex));
	const callsOff = hc.state.rng.shop.calls;
	check("and topping it up while the switch is still off adds nothing and rolls nothing",
		hc.shop.stockGuaranteedRelics(staleStock) === 0 && hc.state.rng.shop.calls === callsOff);

	settings.enabled = true;
	const rolledBefore = staleStock.relicArray.map((r) => r.index);
	check("switched on, the same saved shelf gains the invitation", hc.shop.stockGuaranteedRelics(staleStock) === 1);
	check("at the front of the shelf, with the relics it already had kept behind it",
		staleStock.relicArray[0].index === settings.relicIndex &&
		staleStock.relicArray.slice(1).map((r) => r.index).join() === rolledBefore.join());
	const price = staleStock.relicArray[0].price;
	const rarePrice = hc.shopTuning.relicPriceArray.rare;
	const variance = hc.shopTuning.priceVariance;
	check("priced as any rare relic is", price >= Math.floor(rarePrice * (1 - variance)) && price <= Math.ceil(rarePrice * (1 + variance)), String(price));
	const callsOn = hc.state.rng.shop.calls;
	check("reopening the shop never adds a second one or rolls again",
		hc.shop.stockGuaranteedRelics(staleStock) === 0 && hc.state.rng.shop.calls === callsOn &&
		staleStock.relicArray.filter((r) => r.index === settings.relicIndex).length === 1);
	staleStock.relicArray[0].sold = true;
	check("nor once it is sold", hc.shop.stockGuaranteedRelics(staleStock) === 0);

	const overlay = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-overlays-map.js"), "utf8");
	check("the shop tops up its shelf every time it opens, for node and Mail Order stock alike",
		/stock = honeycomb\.shop\.standaloneStock;\s*\}\s*\/\/[^\n]*\n\s*honeycomb\.shop\.stockGuaranteedRelics\(stock\);/.test(overlay));

	// The unlock's other half: a region is recorded when its boss falls, whatever the switch said then,
	// so a profile that cleared the routes before session 57 already qualifies.
	const fresh = newEngine();
	fresh.state = fresh.newProfile();
	fresh.newRun([{ characterIndex: "severine", outfitIndex: "default" }], 5);
	check("a profile that has walked no route does not qualify",
		fresh.testCondition({ index: "gauntletOpen" }, fresh.newEffectContext({})) === false);
	for (const row of fresh.tuning.map.route.byBossArray) fresh.discovery.record("region", row.regionIndex, null);
	check("and once all three are on its ledger the invitation is offerable",
		fresh.testCondition({ index: "gauntletOpen" }, fresh.newEffectContext({})) === true);
}

