console.log("\n[136] 2026-09-22 -- session 57: the debug tools keep Anastasia secret");
// Noodle: "I want her to stay completely secret until unlocked through gameplay." The debug panel ships
// to testers, and its "unlock all", its gauntlet button, its pickers and the Battle Lab all named her.
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	check("the debug secret switch ships off", hc.tuning.debug.showsSecrets === false);
	check("she is hidden from debug screens", hc.discovery.hiddenFromDebug("character", "anastasia") === true);
	check("a shipped character is not", hc.discovery.hiddenFromDebug("character", "brienne") === false);
	check("her pieces, cards, relic and fights are hidden",
		hc.discovery.hiddenFromDebug("enemy", "celestialKnight") === true &&
		hc.discovery.hiddenFromDebug("card", hc.cardArray.find((c) => c.characterIndex === "anastasia").index) === true &&
		hc.discovery.hiddenFromDebug("relic", "gauntletInvitation") === true &&
		hc.discovery.hiddenFromDebug("encounter", "gauntletGrandmaster") === true);
	check("ordinary content is not", hc.discovery.hiddenFromDebug("enemy", "sporeling") === false &&
		hc.discovery.hiddenFromDebug("encounter", "tallyLedger") === false);
	hc.tuning.debug.showsSecrets = true;
	check("the switch lifts it for a developer", hc.discovery.hiddenFromDebug("character", "anastasia") === false &&
		hc.discovery.hiddenFromDebug("enemy", "celestialKnight") === false);
	hc.tuning.debug.showsSecrets = false;
	hc.state.profile.unlockedCharacterArray.push("anastasia");
	check("once she is earned, nothing of hers is hidden", hc.discovery.hiddenFromDebug("character", "anastasia") === false &&
		hc.discovery.hiddenFromDebug("enemy", "celestialKnight") === false);

	// The screens are not loaded headlessly, so the wiring is read off the source.
	const title = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-title.js"), "utf8");
	const lab = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-overlays-lab.js"), "utf8");
	check("the gauntlet button is marked secret", /index: "toGauntlet",[\s\S]{0,200}secret: true/.test(title));
	check("a secret action is skipped when drawn, pressed or promoted",
		(title.match(/honeycomb\.debug\.actionHidden\(action\) == true/g) || []).length === 3);
	check("unlock all grants an in-development character only with the switch on",
		/if \(honeycomb\.tuning\.debug\.showsSecrets != true\) break;\s*if \(honeycomb\.characterArray\[developmentIndex\]\.inDevelopment != true\) continue;/.test(title));
	check("the fight, enemy and character pickers each ask hiddenFromDebug",
		["encounter", "enemy", "character"].every((kind) => title.indexOf('hiddenFromDebug("' + kind + '"') >= 0));
	check("the Battle Lab asks it for enemies, characters (twice) and cards",
		(lab.match(/hiddenFromDebug\("character"/g) || []).length === 2 && lab.indexOf('hiddenFromDebug("enemy"') >= 0 &&
		lab.indexOf('hiddenFromDebug("card"') >= 0);

	// Noodle's chess hall (session 57): every fight in the gallery stands in front of it.
	const gallery = hc.findDefinition(hc.regionArray, hc.tuning.chessmaster.gauntlet.regionIndex);
	check("the gauntlet's fights use the chess hall background", gallery.battleBackdropPath === "backgrounds/chess");
	check("and the file is there", fs.existsSync(path.resolve(ROOT, "..", "..", "v13 spire images", "backgrounds", "chess.webp")));
	// The combat scene is not loaded headlessly; its resolver is read off the source.
	const sceneCombat = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
	check("and the fight asks the map's region for it",
		/if \(region != null && region\.battleBackdropPath != null\) return region\.battleBackdropPath;/.test(sceneCombat));
	check("while no gauntlet encounter overrides it with its own",
		hc.encounterArray.filter((e) => /^gauntlet/.test(e.index)).every((e) => e.battleBackdropPath == null));
}

