console.log("\n[137] 2026-09-22 -- session 57: Heavy Swing, Whetted Edge, the intent card, the campfire's Lust, the footsteps");
{
	// A fresh fight with Brienne holding the given Temporary HP and a card of the given index in hand.
	const setUp = (outfitIndex, temporaryHealth) => {
		const hc = newEngine();
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "brienne", outfitIndex: outfitIndex }], 7);
		hc.combat.begin("loneSporeling", {});
		const combat = hc.state.run.combat;
		const brienne = hc.state.run.partyArray[0];
		brienne.temporaryHealth = temporaryHealth;
		const enemy = combat.enemyArray[0];
		enemy.health = 999;
		return { hc, combat, brienne, enemy };
	};
	const swing = (world) => {
		world.hc.addCardToPile("brienneHeavySwing", "hand", world.hc.newEffectContext({ combat: world.combat, source: world.brienne }));
		const result = world.hc.combat.playCard(world.combat.handArray[world.combat.handArray.length - 1], world.enemy.instanceId);
		return result.context.log.filter((entry) => entry.type === "damage" && entry.targetId === world.enemy.instanceId).length;
	};

	// HEAVY SWING. A player: "I had 16 temp hp but he didn't do the bonus damage." Thorns on the target
	// took 7 Temporary HP off Brienne after the first hit, and the second hit asked afterwards.
	{
		const world = setUp("default", 16);
		world.hc.applyStatus(world.enemy, "thorns", 7, world.hc.newEffectContext({ combat: world.combat, source: world.enemy }));
		check("Heavy Swing into Thorns 7 at 16 Temporary HP still swings twice", swing(world) === 2);
		check("though Thorns did take Brienne under 10 on the way", world.brienne.temporaryHealth < 10, String(world.brienne.temporaryHealth));
	}
	check("at 10 Temporary HP it swings twice", swing(setUp("default", 10)) === 2);
	check("at 9 it swings once", swing(setUp("default", 9)) === 1);
	{
		const hc = newEngine();
		const card = hc.findDefinition(hc.cardArray, "brienneHeavySwing");
		check("both of its forms ask when played",
			card.effectArray[1].condition.checkedAtStart === true && card.upgradeArray[0].effectArray[1].condition.checkedAtStart === true);
		// The same shape without the flag reads the state as its own entry comes up -- what "if the target
		// is now downed" cards rely on.
		const world = setUp("default", 12);
		const context = world.hc.newEffectContext({ combat: world.combat, source: world.brienne });
		context.targetArray = [world.enemy];
		const condition = { index: "compare", operation: "greaterOrEqual", left: { index: "stat", stat: "temporaryHealth", of: "source" }, right: 10 };
		const effects = (flag) => [
			// A hit on Brienne herself: her default outfit soaks it with Temporary HP, 12 -> 7.
			{ index: "damage", amount: 5, targetOverride: "owner" },
			{ index: "damage", amount: 1, condition: Object.assign({}, condition, flag ? { checkedAtStart: true } : {}) },
		];
		const hitsFor = (flag) => {
			world.brienne.temporaryHealth = 12;
			const before = world.enemy.health;
			world.hc.resolveEffectArray(effects(flag), context);
			return before - world.enemy.health;
		};
		check("an unflagged condition still reads the state when its entry runs", hitsFor(false) === 0);
		check("a flagged one reads it when the list starts", hitsFor(true) === 1);
	}

	// WHETTED EDGE. "upgrade it and reduce its cost by 1 this combat" -- both halves outlived the fight.
	{
		const world = setUp("default", 0);
		const { hc, combat, brienne } = world;
		const target = hc.addCardToRunDeck("brienneHeavySwing", brienne.instanceId);
		combat.handArray.push(target.instanceId);
		hc.addCardToPile("neutralWhettedEdge", "hand", hc.newEffectContext({ combat: combat, source: brienne }));
		const played = hc.combat.playCard(combat.handArray[combat.handArray.length - 1], target.instanceId);
		const during = hc.resolveCard(target);
		check("Whetted Edge upgrades the card for the fight", played.played === true && during.name === "Heavy Swing+");
		const costNow = (card) => hc.combat.playCost(card, hc.newEffectContext({ combat: hc.state.run.combat, card: card, source: brienne })).energy;
		check("and makes it cost 1 less", costNow(during) === 0, String(costNow(during)));
		check("without touching the card's own level", (target.upgradeLevel || 0) === 0 && target.combatUpgradeLevel === 1);
		hc.combat.clear();
		check("the fight over, the card is plain again", hc.resolveCard(target).name === "Heavy Swing" &&
			target.combatUpgradeLevel === undefined && target.costModifierArray === undefined);
		// A save written before session 57 may carry an old fight's discount; the next fight drops it.
		target.costModifierArray = { energy: -1 };
		hc.combat.begin("loneSporeling", {});
		check("a leftover discount from an older save is gone when the next fight begins", target.costModifierArray === undefined);
		check("every fight-only field is on the cleared list",
			["costModifierArray", "costOverrideArray", "combatUpgradeLevel", "combatUpgradePath"].every((field) => hc.combat.fightOnlyCardFieldArray.indexOf(field) >= 0));
		check("Whetted Edge asks for the one-fight upgrade",
			hc.findDefinition(hc.cardArray, "neutralWhettedEdge").effectArray[0].forThisCombat === true);
		check("while the campfire's Sharpen still upgrades for good",
			JSON.stringify(hc.findDefinition(hc.restOptionArray, "sharpen").effectArray).indexOf("forThisCombat") < 0);
		check("the level a copy plays at adds the fight's extra to its own",
			hc.cardUpgradeLevelNow({ upgradeLevel: 1, combatUpgradeLevel: 1 }) === 2 && hc.cardUpgradeLevelNow({}) === 0);
	}

	// THE INTENT CARD. "the ennemy card position masks their first debuff" -- it now sits under its own
	// plate (z-index 2) and comes to the front only when hovered.
	{
		const css = fs.readFileSync(path.resolve(ROOT, "..", "css", "honeycomb.css"), "utf8");
		// Anchored to a line start: the boss's `.hcAnchor-back .hcIntentCardSlot {` rule comes earlier in the file.
		const ruleAt = (selector) => { const at = css.indexOf("\n" + selector + " {"); return css.slice(at, css.indexOf("}", at)); };
		const slotRule = ruleAt(".hcIntentCardSlot");
		const plateRule = ruleAt(".hcFighterVitals");
		const z = (rule) => Number((rule.match(/z-index:\s*(\d+)/) || [])[1]);
		check("the resting intent card sits below its own nameplate", z(slotRule) < z(plateRule), z(slotRule) + " vs " + z(plateRule));
		check("a hovered one comes to the front", /\.hcIntentCardSlot:hover \{[^}]*z-index: 6/.test(css));
		check("a charged move's card no longer lifts itself over the plate",
			/\.hcIntentCardSlot\.hcIntentRare \{[^}]*z-index/.test(css) === false);
		check("a back-anchored boss's card stays under her plate",
			/\.hcAnchor-back \.hcIntentCardSlot \{ z-index: 4; \}/.test(css) && /\.hcAnchor-back \.hcFighterVitals \{ z-index: 5; \}/.test(css));
	}

	// THE CAMPFIRE. "Please make the campfire reduce lust as well as health, equal amounts."
	{
		const hc = newEngine();
		hc.state = hc.newProfile();
		hc.newRun([{ characterIndex: "brienne", outfitIndex: "default" }, { characterIndex: "severine", outfitIndex: "default" }], 7);
		const party = hc.state.run.partyArray;
		const reset = () => party.forEach((member) => { member.health = 10; member.lust = 40; });
		const sleep = hc.findDefinition(hc.restOptionArray, "sleep");
		reset();
		hc.resolveEffectArray(sleep.effectArray, hc.newEffectContext({ source: party[0] }));
		check("Sleep removes as much Lust as it heals, on everyone",
			party.every((member) => member.health - 10 === 40 - member.lust && member.health > 10),
			party.map((member) => (member.health - 10) + "/" + (40 - member.lust)).join(","));
		const treatment = hc.findDefinition(hc.restOptionArray, "treatment");
		reset();
		const context = hc.newEffectContext({ source: party[0] });
		context.target = party[1];
		context.targetArray = [party[1]];
		hc.resolveEffectArray(treatment.effectArray[0].effectArray, context);
		check("Treatment removes as much Lust as it heals, on the one treated",
			party[1].health - 10 === 40 - party[1].lust && party[1].health > 10 && party[0].lust === 40);
		check("the previews say so", /removes as much Lust/.test(sleep.previewText()) && /remove as much Lust/.test(treatment.previewText()));
		hc.tuning.rest.lustPerHealth = 0;
		reset();
		hc.resolveEffectArray(sleep.effectArray, hc.newEffectContext({ source: party[0] }));
		check("tuning.rest.lustPerHealth at 0 turns it off, words and all",
			party.every((member) => member.lust === 40) && /Lust/.test(sleep.previewText()) === false);
	}

	// THE FOOTSTEPS. "never meant to be played moving between nodes, it's far too long, it was for
	// descending floors".
	{
		const hc = newEngine();
		const audio = hc.tuning.audio;
		check("walking to a node plays no library file", audio.fileMap.nodeEnter === undefined);
		check("so it falls back to the host's short move", audio.eventMap.nodeEnter === "move");
		check("the footsteps play on the way down a floor", audio.fileMap.regionDescend === "miscWalkingWood");
		check("and the descent is a screen-length moment", audio.eventMomentMap.regionDescend === "screen");
		const overlay = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-overlays-map.js"), "utf8");
		const descend = overlay.slice(overlay.indexOf("honeycomb.descendRegion = function"), overlay.indexOf("\n};", overlay.indexOf("honeycomb.descendRegion = function")));
		check("Descend plays it", descend.indexOf('honeycomb.platform.sound("regionDescend")') >= 0);
	}

	// THE ROUTES' BATTLE BACKGROUNDS (Noodle, session 57: "I just added backgrounds for each of them").
	{
		const hc = newEngine();
		const imageFolder = path.resolve(ROOT, "..", "..", "v13 spire images");
		const wanted = { floodedVault: "backgrounds/frontier", flora: "backgrounds/arbor", pollenRoad: "backgrounds/road", gauntletGallery: "backgrounds/chess" };
		for (const regionIndex of Object.keys(wanted)) {
			const region = hc.findDefinition(hc.regionArray, regionIndex);
			check(region.name + " fights stand in front of " + wanted[regionIndex],
				region.battleBackdropPath === wanted[regionIndex] && fs.existsSync(path.join(imageFolder, wanted[regionIndex] + ".webp")));
		}
	}
}

console.log("\n[138] 2026-09-23 -- the Honeycomb play button on Syrup Town's title screen");
{
	// Noodle: "Make proper honeycomb play button on menu [...] needs to work on mobile portrait and
	// landscape, button spacing hard". The layout is worked out by layoutTitleHoneycomb() in
	// scripts/gameplay/title.js, so this runs that function on a spread of screens and measures the
	// boxes it produces, the same way they were measured live in the browser on 2026-09-23.
	const titleSource = fs.readFileSync(path.join(ROOT, "..", "gameplay", "title.js"), "utf8");
	const grab = (name) => {
		const start = titleSource.indexOf("function " + name + "(");
		let depth = 0, index = titleSource.indexOf("{", start);
		for (; index < titleSource.length; index++) {
			if (titleSource[index] === "{") depth++;
			if (titleSource[index] === "}" && --depth === 0) break;
		}
		return titleSource.slice(start, index + 1);
	};
	const pillAspect = 408 / 1024;
	// norwester runs 10.7 times its font size wide for "HONEYCOMB CATACOMBS" (measured live), and the
	// frame's ornaments leave about 76% of the button's width for text.
	const labelWidthPerPixel = 10.7;
	const screens = [[375, 812], [375, 667], [360, 640], [390, 844], [412, 915], [768, 1024], [812, 375],
		[915, 412], [960, 400], [800, 600], [1024, 768], [1280, 720], [1366, 768], [1920, 1080], [2560, 1080], [3440, 1440]];
	const problems = [];
	for (const [width, height] of screens) {
		const portrait = height > width;
		const sandbox = {
			window: { innerWidth: width, innerHeight: height, matchMedia: () => ({ matches: portrait }) },
			titleButtons: portrait ? [[29, 52], [29, 64], [29, 76], [29, 88]] : [[31, 70], [8, 70], [75, 70], [54, 70]],
			Math,
		};
		vm.createContext(sandbox);
		vm.runInContext(grab("titleHoneycombFontSize") + "\n" + grab("layoutTitleHoneycomb") + "\nvar box = layoutTitleHoneycomb();", sandbox);
		const box = sandbox.box;
		const pillShare = (box.pillWidth != null ? box.pillWidth : (portrait ? 50 : 20)) / 100;
		const rects = sandbox.titleButtons.map(([left, top]) => ({ left: left / 100 * width, top: top / 100 * height,
			right: left / 100 * width + pillShare * width, bottom: top / 100 * height + pillShare * width * pillAspect }));
		const honeycomb = { left: box.left / 100 * width, top: box.top / 100 * height, right: (box.left + box.width) / 100 * width, bottom: box.top / 100 * height + box.height };
		const all = rects.concat([honeycomb]);
		const label = width + "x" + height;
		for (let first = 0; first < all.length; first++) {
			for (let second = first + 1; second < all.length; second++) {
				const a = all[first], b = all[second];
				if (a.left < b.right && b.left < a.right && a.top < b.bottom && b.top < a.bottom) problems.push(label + " buttons " + first + " and " + second + " overlap");
			}
		}
		if (all.some((rect) => rect.left < 0 || rect.right > width || rect.bottom > height)) problems.push(label + " a button leaves the screen");
		if (portrait && Math.min(...all.map((rect) => rect.top)) < 0.47 * height) problems.push(label + " the column reaches up into the title letters");
		if (box.height < 24) problems.push(label + " the Honeycomb button is only " + Math.round(box.height) + "px tall");
		if (box.fontSize * labelWidthPerPixel > 0.76 * (honeycomb.right - honeycomb.left)) problems.push(label + " the label runs into the frame");
	}
	check("on " + screens.length + " screens, phone to ultrawide, the five title buttons never overlap, leave the screen or cover the title",
		problems.length === 0, problems.join("; "));
	check("one line turns it off: titleHoneycombButton = true sits on its own line",
		/\nvar titleHoneycombButton = true;/.test(titleSource.replace(/\r/g, "")));
	check("and the flag guards both the layout and the button, so off means the old title exactly",
		/if \(titleHoneycombButton == true && typeof honeycombBoot === "function"\) \{\s*titleHoneycombBox = layoutTitleHoneycomb\(\);/.test(titleSource)
		&& /if \(titleHoneycombBox != null\) \{/.test(titleSource));
	check("the button's art goes through honeycomb.image, the one path to Honeycomb's image folder",
		/honeycomb\.image\("ui\/buttonFrontGold"\)/.test(titleSource) && titleSource.indexOf("v13 spire images") < 0);
}

console.log("\n[139] 2026-09-23 -- event art: the campfire shows the party leader, and every event picture exists");
{
	const imageFolder = path.resolve(ROOT, "..", "..", "v13 spire images");
	const hc = newEngine();
	const tokenArray = hc.tuning.ui.eventPartyTokenArray;
	const token = tokenArray[0];
	const campfire = hc.findDefinition(hc.eventArray, "theCampfire");
	check("the campfire's picture names the leader token", typeof campfire.imagePath === "string" && campfire.imagePath.indexOf(token) >= 0, campfire.imagePath);

	hc.state = hc.newProfile();
	check("with no run, the token resolves to the fallback character's folder",
		hc.eventOverlay.artPathFor("events/campfire/" + token) === "events/campfire/" +
		hc.findDefinition(hc.characterArray, hc.tuning.ui.eventLeaderFallbackCharacter).artFolder);
	hc.newRun([{ characterIndex: "nettle", outfitIndex: "default" }, { characterIndex: "brienne", outfitIndex: "default" }], 7);
	check("with Nettle at the front, the campfire is Nettle's", hc.eventOverlay.artPathFor(campfire.imagePath) === "events/campfire/necro",
		hc.eventOverlay.artPathFor(campfire.imagePath));
	check("a path without the token is returned untouched, and so is null",
		hc.eventOverlay.artPathFor("events/well") === "events/well" && hc.eventOverlay.artPathFor(null) === null);
	check("the second place resolves to the second member: {leader}-{second} is necro-knight",
		hc.eventOverlay.artPathFor("events/x-" + tokenArray[0] + "-" + tokenArray[1]) === "events/x-necro-knight");
	check("a place the party does not fill reads as the leader: {third} in a party of two is necro",
		hc.eventOverlay.artPathFor("events/x-" + tokenArray[2]) === "events/x-necro");
	// The event screen needs the UI layer to draw, which the suite does not load, so the wiring is read
	// off the source: all three art fields and the gallery tile go through the resolver.
	const overlaySource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-overlays-map.js"), "utf8");
	const gallerySource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-gallery.js"), "utf8");
	check("the event screen resolves its picture, backdrop and speaker through artPathFor",
		["backgroundPath", "imagePath", "speakerPath"].every((field) =>
			new RegExp("var " + field + " = honeycomb\\.eventOverlay\\.artPathFor\\(").test(overlaySource)));
	check("and so does the gallery tile", /honeycomb\.imageTag\(honeycomb\.eventOverlay\.artPathFor\(entry\.imagePath\)/.test(gallerySource));

	// Every event picture is a real file. A missing one draws a labelled placeholder on the event a run
	// opens most often (map/ B42: the campfire and the Sealed Door were both missing for weeks).
	const missing = [];
	const artFolders = hc.characterArray.filter((character) => character.artFolder != null).map((character) => character.artFolder);
	for (const event of hc.eventArray) {
		for (const field of ["imagePath", "backgroundPath", "speakerPath"]) {
			const value = event[field];
			if (typeof value !== "string") continue;
			// Every combination of folders for the tokens the path uses.
			let pathArray = [value];
			for (const one of tokenArray) {
				if (value.indexOf(one) < 0) continue;
				pathArray = [].concat(...pathArray.map((partial) => artFolders.map((folder) => partial.split(one).join(folder))));
			}
			for (const one of pathArray) {
				if (!fs.existsSync(path.join(imageFolder, one + ".webp"))) missing.push(event.index + " " + field + " " + one);
			}
		}
	}
	check("every event's picture, backdrop and speaker is on disk, the campfire once per character (" + artFolders.length + ")",
		missing.length === 0, missing.join("; "));
}

console.log("\n[140] 2026-09-23 -- the packed save and the .noodle file");
{
	// Noodle: "the savedata's way too long. Gotta find a way to scale it down safely, and add option to
	// save to .noodle file as syrup town does". Packing only runs asynchronously and this suite does not,
	// so the round trip runs in tools/save-text.js, which loads the same engine files; this block builds
	// a save mid-fight, hands it over, and reads the verdict.
	const hc = newEngine();
	hc.state = hc.newProfile();
	hc.newRun([{ characterIndex: "brienne", outfitIndex: "default" }, { characterIndex: "nettle", outfitIndex: "default" },
		{ characterIndex: "severine", outfitIndex: "default" }], 11);
	const encounter = hc.encounterArray.find((entry) => entry.elite !== true && entry.boss !== true);
	hc.combat.begin(encounter.index, {});
	const reportPath = path.join(require("os").tmpdir(), "honeycomb-suite-report-" + process.pid + ".txt");
	fs.writeFileSync(reportPath, hc.save.toReportText());
	const run = require("child_process").spawnSync(process.execPath, [path.join(__dirname, "save-text.js"), "check", reportPath], { encoding: "utf8" });
	fs.unlinkSync(reportPath);
	let verdict = null;
	try { verdict = JSON.parse(run.stdout.trim()); } catch (parseError) { verdict = null; }
	check("save-text.js ran and reported", verdict != null, run.stdout + run.stderr);
	if (verdict != null) {
		check("a save taken mid-fight packs behind the HC1~ marker", verdict.prefixOk === true);
		check("and unpacks to exactly the text that went in, character for character", verdict.roundTripIdentical === true);
		check("the packed text is under a third of the plain length (" + verdict.packedLength + " of " + verdict.plainLength + ")",
			verdict.packedLength * 3 < verdict.plainLength);
		check("Load reads the packed text and the plain text into the same state", verdict.loadedPacked === true &&
			verdict.loadedPlain === true && verdict.sameStateEitherWay === true);
		check("a packed save cut short is refused and leaves the state untouched", verdict.damagedRefused === true);
		check("the file name matches Syrup Town's shape: Honeycomb 2026-09-03 07-05.noodle",
			verdict.fileName === "Honeycomb 2026-09-03 07-05.noodle", verdict.fileName);
	}
	check("the exit code agrees with the verdict", run.status === 0, "exit " + run.status);

	// The panel's wiring, read off the source: the UI layer is not loaded here.
	const titleSource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-title.js"), "utf8");
	check("Copy / Load Save offers Save to .noodle file and Load from .noodle file",
		titleSource.indexOf('onclick="honeycomb.saveTransfer.download()">Save to .noodle file') >= 0 &&
		/<input type="file"[^>]*onchange="honeycomb\.saveTransfer\.loadFile\(this\)"/.test(titleSource));
	check("both load buttons go through fromAnyText, which reads packed and plain alike",
		/honeycomb\.saveTransfer\.loadText = function[\s\S]{0,120}honeycomb\.save\.fromAnyText\(text\)/.test(titleSource) &&
		/honeycomb\.saveTransfer\.loadText\(box\.value/.test(titleSource) && /honeycomb\.saveTransfer\.loadText\(String\(reader\.result\)/.test(titleSource));
	check("the copy box and the file hold the same packed text",
		/honeycomb\.save\.pack\(honeycomb\.save\.toReportText\(\)\)/.test(titleSource) &&
		/var text = honeycomb\.saveTransfer\.packedText;[\s\S]{0,400}new Blob\(\[text\]/.test(titleSource));
	// Stored slots are deliberately left as plain JSON: autosave is synchronous and runs every turn.
	// save.read only JSON.parses, so a slot that reads back is a plain JSON slot.
	const beforeWrite = JSON.stringify(hc.state);
	check("a stored slot is still plain JSON, and reads back to the same state",
		hc.save.write(1, true) === true && hc.save.read(1) === true && JSON.stringify(hc.state) === beforeWrite);
}

console.log("\n[141] 2026-09-23 -- alt outfit art, outfit bullets, free Fortitude, the Weeping Bloom");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	const ART_ROOT = path.resolve(ROOT, "..", "..", "v13 spire images", "characters");
	const readList = (folder, name) => {
		const file = path.join(folder, name);
		return fs.existsSync(file) ? fs.readFileSync(file, "utf8").split(/\r?\n/).filter((line) => line !== "" && line[0] !== "#") : [];
	};

	// Read off the disk: an alt outfit with no drawing of its own holds a copy of every default picture.
	const copyProblemArray = [];
	let copyOutfitCount = 0;
	for (const character of hc.characterArray) {
		if (character.artFolder == null) continue;
		const defaultFolder = path.join(ART_ROOT, character.artFolder, character.defaultOutfit);
		if (!fs.existsSync(defaultFolder)) continue;
		const defaultSet = fs.readdirSync(defaultFolder).filter((name) => name.endsWith(".webp")).sort();
		for (const outfit of character.outfitArray) {
			if (outfit.index === character.defaultOutfit) continue;
			const folder = path.join(ART_ROOT, character.artFolder, outfit.index);
			if (!fs.existsSync(folder)) continue;
			const claimed = readList(folder, ".generated.txt");
			const webpArray = fs.readdirSync(folder).filter((name) => name.endsWith(".webp"));
			if (webpArray.some((name) => claimed.indexOf(name) < 0)) continue;
			copyOutfitCount++;
			const missing = defaultSet.filter((name) => webpArray.indexOf(name) < 0);
			if (missing.length > 0) copyProblemArray.push(character.artFolder + "/" + outfit.index + " lacks " + missing.join(", "));
		}
	}
	check("every alt outfit with no drawing of its own holds a copy of every default picture (" + copyOutfitCount + " outfits)",
		copyOutfitCount > 0 && copyProblemArray.length === 0, copyProblemArray.join("; "));

	const readyChain = hc.art.spriteChain({ side: "ally", characterIndex: "nettle", outfitIndex: "sporemother",
		health: 1, maxHealth: 1, statusArray: [] }, "basic", { state: null, tier: 2 });
	const firstOnDisk = readyChain.find((candidate) => hc.art.canvasSize(candidate) != null);
	check("Sporemother Nettle's Lust-Event-ready picture is her own 2-basic, not 1-basic",
		firstOnDisk === "characters/necro/sporemother/2-basic", firstOnDisk);
	check("a recoloured copy of a drawing is not marked as a stand-in; the generated portrait still is",
		hc.art.isPlaceholderArt("characters/necro/sporemother/3-combat") === false &&
		hc.art.isPlaceholderArt("characters/necro/sporemother/2-broken") === false &&
		hc.art.isPlaceholderArt("characters/necro/sporemother/0-portrait") === true);

	const siegeplate = hc.findOutfit(hc.findDefinition(hc.characterArray, "brienne"), "siegeplate");
	const siegeLines = hc.outfitDescriptionLines(siegeplate);
	check("a string description splits into one bullet per sentence", siegeLines.length === 5 &&
		siegeLines[0] === "+6 Max HP." && siegeLines[3].indexOf("Aegis becomes Battering Ram: spend all Resolve, deal that much") === 0, JSON.stringify(siegeLines));
	check("an array description is used line for line",
		JSON.stringify(hc.outfitDescriptionLines({ description: ["One", "Two. Still two."] })) === JSON.stringify(["One", "Two. Still two."]));
	check("the markup is a list, and every outfit in the game makes at least one bullet",
		/^<ul class="hcOutfitBullets"><li>/.test(hc.outfitDescriptionMarkup(siegeplate)) &&
		hc.characterArray.every((character) => character.outfitArray.every((outfit) => outfit.description == null || hc.outfitDescriptionLines(outfit).length > 0)));

	const fortArray = [];
	for (const character of hc.characterArray) {
		const tree = character.progressionTree;
		for (const node of (tree == null ? [] : tree.nodeArray || [])) if (node.fortitude === true) fortArray.push(node);
	}
	check("every character's Fortitude is free, open from the start, and says Lust Events are missed (" + fortArray.length + ")",
		fortArray.length === hc.characterArray.length && fortArray.every((node) => hc.progression.nodeCost(node, 1) === 0 &&
			node.free === true && (node.requiresArray || []).length === 0 && /never build, and \w+ misses every Lust Event\./.test(node.description)),
		fortArray.map((node) => node.index + ":" + hc.progression.nodeCost(node, 1)).join(", "));

	const selection = (index) => ({ characterIndex: index, outfitIndex: hc.findDefinition(hc.characterArray, index).defaultOutfit });
	const inPool = () => hc.eligibleEventArray().some((event) => event.index === "theWeepingBloom");
	const bloom = hc.findDefinition(hc.eventArray, "theWeepingBloom");
	const study = bloom.choiceArray[0].effectArray;
	hc.newRun([selection("brienne"), selection("severine")], 1);
	check("without Nettle the Weeping Bloom is not in the pool", inPool() === false);
	hc.state.run.seenEventArray = hc.eventArray.map((event) => event.index);
	check("nor in the pool that reopens once every event has been seen", inPool() === false);
	check("and the reopened pool keeps Broken-only events out when nobody is Broken",
		hc.eligibleEventArray().every((event) => event.appearsWhenBroken !== true));
	hc.newRun([selection("nettle"), selection("brienne")], 2);
	check("with Nettle at venom rank 0 it is in the pool", inPool() === true);
	check("Study it previews two rerolls and one venom rank",
		hc.describeEffectArray(study, hc.newEffectContext({})) === "Gain 2 Reroll. Nettle's Venom weakness rises 1 rank.",
		hc.describeEffectArray(study, hc.newEffectContext({})));
	const studyContext = hc.newEffectContext({});
	hc.resolveEffectArray(study, studyContext);
	check("Study it raises venom to exactly the rank 1 threshold and pays 2 rerolls",
		hc.lust.rankFor("nettle", "venom") === 1 && hc.lust.exposureFor("nettle", "venom") === hc.tuning.lust.exposureRankArray[0].atOrAbove &&
		hc.state.run.resourceArray.reroll === 2);
	const rankedEntry = studyContext.log.find((entry) => entry.type === "weaknessRanked");
	check("it logs the rank reached, for the result panel", rankedEntry != null && rankedEntry.rank === 1 && rankedEntry.ranks === 1);
	check("the rank-up popup's log entry is written too", studyContext.log.some((entry) => entry.type === "lustRank"));
	// The UI layer is not loaded here; the tile's icon is stubbed so its words can be read.
	hc.ui = hc.ui || {};
	if (typeof hc.ui.iconTag !== "function") hc.ui.iconTag = () => "";
	check("the result panel has a row that draws it",
		hc.eventOverlay.gainKindArray.some((kind) => kind.index === "weaknessRanked" && /Now rank 1, Sensitised/.test(kind.draw(rankedEntry))));
	// The one-rank-per-run ceiling does not stop it.
	check("the run ceiling does not take it out of the pool", inPool() === true &&
		hc.lust.rankGainThisRun("nettle", "venom") >= hc.tuning.lust.maximumRankGainPerRun);
	hc.resolveEffectArray(study, hc.newEffectContext({}));
	check("and a second Study in the same run goes one rank past the ceiling, to rank 2",
		hc.lust.rankFor("nettle", "venom") === 2 && hc.lust.exposureFor("nettle", "venom") === hc.tuning.lust.exposureRankArray[1].atOrAbove);
	hc.newRun([selection("nettle")], 3);
	hc.state.profile.lustExposureArray.nettle.venom = 30.5;
	hc.resolveEffectArray(study, hc.newEffectContext({}));
	check("from inside rank 2 it lands on rank 3's threshold exactly",
		hc.lust.exposureFor("nettle", "venom") === hc.tuning.lust.exposureRankArray[2].atOrAbove && hc.lust.rankFor("nettle", "venom") === 3);
	hc.newRun([selection("nettle")], 4);
	check("at the top rank it leaves the pool", inPool() === false);
	// Fortitude stubbed on for Nettle.
	const realFlag = hc.characterFieldFlag;
	hc.characterFieldFlag = (characterIndex, field) => (characterIndex === "nettle" && field === "fortitude") ? true : realFlag(characterIndex, field);
	hc.state.profile.lustExposureArray.nettle.venom = 20;
	const fortRank = hc.lust.rankFor("nettle", "venom");
	const fortPool = inPool();
	hc.lust.recordExposure({ characterIndex: "nettle", instanceId: null }, ["venom"], 30, hc.newEffectContext({}));
	const fortGrew = hc.lust.exposureFor("nettle", "venom") !== 20;
	const fortAdded = hc.lust.addExposure("nettle", "venom", 30, hc.newEffectContext({}));
	const fortMultiplier = hc.lust.vulnerabilityMultiplier({ characterIndex: "nettle" }, ["venom"]);
	const fortReady = hc.lustEvents.queueFor("nettle").length;
	hc.characterFieldFlag = realFlag;
	check("under Fortitude her weakness reads rank 0, whatever the ledger holds", fortRank === 0);
	check("under Fortitude nothing builds: not a fight's Lust, not an event's", fortGrew === false && fortAdded === 0);
	check("under Fortitude Lust hits her at the plain rate", fortMultiplier === 1);
	check("under Fortitude no Lust Event is owed, and the Weeping Bloom never appears", fortReady === 0 && fortPool === false);
	check("and giving Fortitude back restores the rank she had", hc.lust.rankFor("nettle", "venom") === 1 &&
		hc.lustEvents.queueFor("nettle").length > 0);
}

console.log("\n[142] 2026-09-23 -- the pages load Honeycomb through one loader");
{
	// The loader runs for real against a fake document, so this reads what it would append.
	const loaderPath = path.join(ROOT, "honeycomb", "honeycomb-loader.js");
	const appendedArray = [];
	const fakeHead = { appendChild: (element) => appendedArray.push(element) };
	const loaderSandbox = {
		document: { createElement: (tag) => ({ tag }), getElementsByTagName: () => [fakeHead] },
		Date, Math, String,
	};
	vm.createContext(loaderSandbox);
	vm.runInContext(fs.readFileSync(loaderPath, "utf8") + "\nthis.honeycombLoader = honeycombLoader;", loaderSandbox);
	const loader = loaderSandbox.honeycombLoader;
	const scriptElementArray = appendedArray.filter((element) => element.tag === "script");
	const styleElementArray = appendedArray.filter((element) => element.tag === "link");

	const onDisk = ["honeycomb.js"].concat(fs.readdirSync(path.join(ROOT, "honeycomb"))
		.filter((name) => name.endsWith(".js") && name !== "honeycomb-loader.js").map((name) => "honeycomb/" + name));
	const listed = loader.scriptArray.map((file) => file.replace("scripts/misc/", ""));
	check("the loader lists every Honeycomb script on disk once, and nothing that is not there (" + onDisk.length + ")",
		listed.length === onDisk.length && onDisk.every((file) => listed.filter((entry) => entry === file).length === 1),
		"missing: " + onDisk.filter((file) => listed.indexOf(file) < 0).join(", ") + "; extra: " + listed.filter((file) => onDisk.indexOf(file) < 0).join(", "));
	check("honeycomb.js loads first and the warnings last", listed[0] === "honeycomb.js" && listed[listed.length - 1] === "honeycomb/honeycomb-warnings.js");
	check("it appends one script per file, in list order, with async off and the ?v= number",
		scriptElementArray.length === loader.scriptArray.length && scriptElementArray.every((element, index) =>
			element.src === loader.scriptArray[index] + "?v=" + loader.version() && element.async === false));
	check("and the stylesheet, before the scripts, with the same number", styleElementArray.length === 1 &&
		styleElementArray[0].href === "scripts/css/honeycomb.css?v=" + loader.version() && appendedArray[0] === styleElementArray[0]);
	check("opened from a file, no ?v= is added", (() => {
		loaderSandbox.location = { protocol: "file:" };
		const fromFile = loader.query();
		loaderSandbox.location = { protocol: "https:" };
		const fromServer = loader.query();
		delete loaderSandbox.location;
		return fromFile === "" && fromServer === "?v=" + loader.version();
	})());
	check("the number changes once every refreshMinutes and not in between", (() => {
		const bucket = loader.refreshMinutes * 60000;
		const start = Math.floor(Date.now() / bucket) * bucket;
		loaderSandbox.Date = { now: () => start };
		const first = loader.version();
		loaderSandbox.Date = { now: () => start + bucket - 1 };
		const same = loader.version();
		loaderSandbox.Date = { now: () => start + bucket };
		const next = loader.version();
		loaderSandbox.Date = Date;
		return first === same && next !== first;
	})());
	check("with no page (a tool reading the list) it appends nothing", (() => {
		const bare = { Date, Math, String };
		vm.createContext(bare);
		vm.runInContext(fs.readFileSync(loaderPath, "utf8") + "\nthis.honeycombLoader = honeycombLoader;", bare);
		return bare.honeycombLoader.scriptArray.length === loader.scriptArray.length;
	})());

	for (const page of ["index.html", "mobile.html"]) {
		const html = fs.readFileSync(path.join(ROOT, "..", "..", page), "utf8");
		check(page + " appends the loader and carries no Honeycomb tag or stylesheet of its own",
			html.indexOf("<script>(function () { var loader = document.createElement(\"script\"); loader.src = \"scripts/misc/honeycomb/honeycomb-loader.js\" + (location.protocol === \"file:\" ? \"\" : \"?v=\" + Math.floor(Date.now() / 600000)); loader.async = false; document.head.appendChild(loader); })();</script>") >= 0 &&
			!/<script src="scripts\/misc\/honeycomb[^"']*\.js"><\/script>/.test(html) && html.indexOf("honeycomb.css") < 0 &&
			html.indexOf("writeStyles") < 0);
	}
}

console.log("\n[143] 2026-09-23 -- Noodle's sound swaps, by-ear trims and the outfit sound's start");
{
	const hc = newEngine();
	const audio = hc.tuning.audio;
	const playedArray = [], hostArray = [];
	const realPlayFile = hc.platform.playFile;
	hc.platform.playFile = (filePath, scale) => playedArray.push({ filePath, scale });
	const sandboxGlobal = hc.platform.sound.constructor("return this")();
	const realHost = sandboxGlobal.soundEffectStart;
	sandboxGlobal.soundEffectStart = (stem) => hostArray.push(stem);

	check("lustGained and partyShift are left out of fileMap, so they reach Syrup Town's sounds",
		audio.fileMap.lustGained == null && audio.fileMap.partyShift == null &&
		audio.eventMap.lustGained === "sell" && audio.eventMap.partyShift === "move");
	hc.platform.sound("lustGained");
	hc.platform.sound("partyShift");
	check("and playing them calls Syrup Town's own sound with sell and move", JSON.stringify(hostArray) === JSON.stringify(["sell", "move"]) &&
		playedArray.length === 0, JSON.stringify(hostArray));

	hc.platform.playStem("lewdSquish");
	check("a trim chosen by ear wins over the measured one", playedArray.length === 1 && playedArray[0].scale === audio.fileVolumeByEarMap.lewdSquish &&
		audio.fileVolumeByEarMap.lewdSquish !== audio.fileVolumeScaleMap.lewdSquish);
	hc.platform.sound("outfitChange");
	const outfitPlay = playedArray[playedArray.length - 1];
	check("the outfit sound starts 380ms in, past its silence, through a #t= fragment",
		outfitPlay != null && /!outfitChange\.mp3#t=0\.38$/.test(outfitPlay.filePath), outfitPlay && outfitPlay.filePath);
	hc.platform.playStem("weaponSlash");
	check("a file not in startAtMsMap plays from the start", /weaponSlash\.mp3$/.test(playedArray[playedArray.length - 1].filePath));

	hc.platform.playFile = realPlayFile;
	sandboxGlobal.soundEffectStart = realHost;
}

console.log("\n[144] 2026-09-23 -- a cleared button sentence hands back to the game's own; the campfire has no button list of its own");
{
	const hc = newEngine();
	const effectArray = [{ index: "gainResource", resource: "gold", amount: 40 }];
	const generated = hc.describeEffectArray(effectArray);
	check("a button with no sentence shows the generated description", hc.eventOverlay.previewText({ effectArray }) === generated && generated !== "", generated);
	check("an empty sentence counts as none written", hc.eventOverlay.previewText({ previewText: "", effectArray }) === generated);
	check("a typed sentence still wins", hc.eventOverlay.previewText({ previewText: "Coins.", effectArray }) === "Coins.");
	const campfire = hc.findDefinition(hc.eventArray, "theCampfire");
	check("the campfire event carries no buttons of its own, since its menu is built", campfire.isRest === true && campfire.choiceArray == null);
	check("and the built menu still offers the three base rows and a way out", hc.rest.choiceArray().length === hc.restOptionArray.filter((option) => option.base === true).length + 1);
}

console.log("\n[145] 2026-09-24 -- A quiet pool: leader lines, the leader's picture, the bath's effects");
{
	const hc = newEngine();
	const pool = hc.findDefinition(hc.eventArray, "aQuietPool");
	check("A quiet pool is in the event table and The Quiet Spring it replaces is gone",
		pool != null && hc.findDefinition(hc.eventArray, "theQuietSpring") == null);
	hc.state = hc.newProfile();
	const heard = (lead) => {
		hc.newRun([{ characterIndex: lead, outfitIndex: "default" }, { characterIndex: "clemence", outfitIndex: "default" }], 7);
		return pool.lineArray.filter((line) => line.condition == null || hc.testCondition(line.condition, hc.newEffectContext({}))).map((line) => line.characterIndex);
	};
	check("only the leader's line plays: Nettle leading hears Nettle alone", JSON.stringify(heard("nettle")) === '["nettle"]', JSON.stringify(heard("nettle")));
	check("and Clemence, standing second, never speaks from behind", JSON.stringify(heard("cinder")) === '["cinder"]', JSON.stringify(heard("cinder")));
	check("a leader with no line hears nothing, rather than someone else's", heard("anastasia").length === 0, JSON.stringify(heard("anastasia")));
	heard("nettle");
	check("the bath page shows the leader's own picture", hc.eventOverlay.artPathFor(pool.pageArray[0].imagePath) === "events/pool/necro",
		hc.eventOverlay.artPathFor(pool.pageArray[0].imagePath));

	// The bath: each member heals a tenth of HER OWN maximum health and keeps half HER OWN Lust.
	hc.newRun([{ characterIndex: "nettle", outfitIndex: "default" }, { characterIndex: "brienne", outfitIndex: "default" }], 7);
	const [first, second] = hc.state.run.partyArray;
	first.health = 10; first.lust = 30;
	second.health = 20; second.lust = 11; second.maxHealth = 100;
	hc.resolveEffectArray(pool.choiceArray[0].effectArray, hc.newEffectContext({}));
	check("each member heals a tenth of her own maximum health", first.health === 10 + Math.floor(first.maxHealth / 10) && second.health === 30,
		first.health + " / " + second.health);
	check("and each member's Lust is halved, rounding down", first.lust === 15 && second.lust === 5, first.lust + " / " + second.lust);
	check("the bath button turns to the page with the picture", pool.choiceArray[0].goToPage === pool.pageArray[0].index);
}

console.log("\n[146] 2026-09-23 -- only weakness tags build, and nothing builds past the top rank");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	const weaknessArray = hc.cardTagArray.filter((tag) => hc.lust.isWeaknessTag(tag.index)).map((tag) => tag.index).sort();
	check("the weaknesses are exactly the tags marked lustTag", JSON.stringify(weaknessArray) ===
		JSON.stringify(hc.cardTagArray.filter((tag) => tag.lustTag === true).map((tag) => tag.index).sort()) &&
		hc.lust.isWeaknessTag("human") === false && hc.lust.isWeaknessTag("support") === false, weaknessArray.join(", "));

	hc.lust.recordExposure({ characterIndex: "nettle", instanceId: null }, ["human", "woman", "support", "venom"], 20, hc.newEffectContext({}));
	const ledger = hc.state.profile.lustExposureArray.nettle;
	check("a hit carrying a character's own traits records only its weakness tag",
		ledger.venom > 0 && ledger.human == null && ledger.woman == null && ledger.support == null, JSON.stringify(ledger));
	check("and a trait tag never multiplies Lust", hc.lust.vulnerabilityMultiplier({ characterIndex: "nettle" }, ["human"]) === 1 &&
		hc.lust.rankFor("nettle", "human") === 0);

	const top = hc.lust.topThreshold();
	for (let hit = 0; hit < 40; hit++) {
		hc.state.profile.lustRankGainArray = {};
		hc.lust.recordExposure({ characterIndex: "nettle", instanceId: null }, ["venom"], 50, hc.newEffectContext({}));
	}
	check("exposure stops at the top rank's threshold (" + top + ")", ledger.venom === top, String(ledger.venom));
	check("so a weakness at the top rank costs nothing to reset", hc.lust.floorResetCost("nettle") === 0 &&
		hc.lust.characterBenchDaysToFloor("nettle") === 0);

	const old = hc.newProfile();
	old.lustExposureArray = { clemence: { penance: 105.3, human: 27, woman: 27, support: 27 } };
	old.lustRankGainArray = { clemence: { human: 1, penance: 1 } };
	old.lustRankUpArray = { clemence: [{ id: 1, tag: "human", rank: 2 }, { id: 2, tag: "penance", rank: 3 }] };
	hc.save.reconcileWeaknessLedger(old);
	check("loading an old save drops trait entries and caps the rest",
		JSON.stringify(old.lustExposureArray.clemence) === JSON.stringify({ penance: top }) &&
		JSON.stringify(old.lustRankGainArray.clemence) === JSON.stringify({ penance: 1 }) &&
		old.lustRankUpArray.clemence.length === 1 && old.lustRankUpArray.clemence[0].tag === "penance",
		JSON.stringify(old.lustExposureArray.clemence));

	const realFlag = hc.characterFieldFlag;
	hc.characterFieldFlag = (characterIndex, field) => (characterIndex === "nettle" && field === "fortitude") ? true : realFlag(characterIndex, field);
	hc.state.profile.lustExposureArray.nettle.charm = 20;
	const fortShown = hc.lust.exposureSummaryArray("nettle").length, fortCost = hc.lust.floorResetCost("nettle");
	hc.characterFieldFlag = realFlag;
	check("under Fortitude no weakness is shown and the reset costs nothing", fortShown === 0 && fortCost === 0);
}

console.log("\n[147] 2026-09-23 -- Revenge answers a hit Temporary HP soaks up");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	hc.newRun([{ characterIndex: "anastasia", outfitIndex: "default" }, { characterIndex: "brienne", outfitIndex: "default" }], 5);
	const encounter = hc.encounterArray.find((entry) => entry.elite !== true && entry.boss !== true && entry.unlisted !== true);
	hc.combat.begin(encounter.index, {});
	const combat = hc.state.run.combat;
	const allyArray = () => hc.livingEntityArray("ally", combat);
	const enemyHealth = () => hc.livingEntityArray("enemy", combat).reduce((total, entity) => total + entity.health, 0);
	const anastasia = allyArray().find((entity) => entity.characterIndex === "anastasia");
	hc.resolveEffectArray([{ index: "summon", enemy: "infernalRook" }, { index: "summon", enemy: "infernalPawn" }],
		hc.newEffectContext({ source: anastasia, combat: combat, log: [] }));
	const rook = allyArray().find((entity) => entity.enemyIndex === "infernalRook");
	const pawn = allyArray().find((entity) => entity.enemyIndex === "infernalPawn");
	// The steps honeycomb.combat.playMove takes, for a named move.
	const play = (entity, cardIndex) => {
		const card = hc.moveCard(entity, cardIndex);
		const log = [];
		const actionContext = hc.newEffectContext({ source: entity, card: card, combat: combat, log: log });
		if (hc.targetModeRequiresPick(card.targetMode) === true && hc.targetModeKind(card.targetMode) === "entity") {
			actionContext.target = hc.aiPickTarget(entity, card, combat, null);
		}
		hc.applyResolvedTargets(actionContext, card.targetMode, hc.resolveTargetMode(card.targetMode, actionContext));
		hc.resolveEffectArray(card.effectArray, actionContext);
		return log;
	};
	play(rook, "infernalRookGrudge");
	check("Grudge gives the Rook Revenge and puts it at the front", hc.statusStacks(rook, "revenge") === 1 && allyArray()[0] === rook);
	rook.temporaryHealth = 5;
	let log = play(pawn, "infernalPawnGnash");
	const soakedRevenge = log.filter((entry) => entry.type === "damage" && entry.damageType === "revenge");
	check("the Pawn's Gnash on a Rook whose Temporary HP soaks it all still sets off Revenge",
		rook.health === rook.maxHealth && soakedRevenge.length === hc.livingEntityArray("enemy", combat).length &&
		soakedRevenge.every((entry) => entry.amount + (entry.absorbed || 0) === 3), JSON.stringify(soakedRevenge));
	rook.temporaryHealth = 1;
	log = play(pawn, "infernalPawnGnash");
	check("a hit split between Temporary HP and health pays Revenge once, not twice",
		log.filter((entry) => entry.type === "damage" && entry.damageType === "revenge").length === hc.livingEntityArray("enemy", combat).length);
	const healthBefore = enemyHealth();
	hc.dealDamage(pawn, rook, 0, {}, hc.newEffectContext({ source: pawn, combat: combat, log: [] }));
	check("a hit of nothing sets off nothing", enemyHealth() === healthBefore);
}

console.log("\n[148] 2026-09-23 -- the Queen's Petition reaches this fight, once; a replay shows a shape change when it plays");
{
	const hc = newEngine();
	hc.state = hc.newProfile();
	hc.newRun([{ characterIndex: "anastasia", outfitIndex: "default" }, { characterIndex: "brienne", outfitIndex: "default" }], 5);
	hc.combat.begin(hc.encounterArray[0].index, {});
	const live = () => hc.state.run.combat;
	for (const enemy of hc.livingEntityArray("enemy", live())) { enemy.maxHealth = 9999; enemy.health = 9999; }
	const anastasia = hc.livingEntityArray("ally", live()).find((entity) => entity.characterIndex === "anastasia");
	hc.resolveEffectArray([{ index: "summon", enemy: "celestialQueen" }], hc.newEffectContext({ source: anastasia, combat: live(), log: [] }));
	const deckStart = hc.state.run.deckArray.length;
	const playedArray = [];
	let invocationInDrawPile = false;
	for (let turn = 1; turn <= 11 && !/victory|defeat/.test(live().phase); turn++) {
		const historyStart = live().historyArray.length;
		hc.combat.endPlayerTurn();
		if (!/victory|defeat/.test(live().phase)) hc.combat.runEnemyTurn();
		const played = live().historyArray.slice(historyStart).filter((entry) => entry.type === "moveUsed" && /^celestialQueen/.test(entry.card));
		for (const entry of played) playedArray.push(entry.card);
		if (played.some((entry) => entry.card === "celestialQueenPetition")) {
			const added = hc.state.run.deckArray[hc.state.run.deckArray.length - 1];
			invocationInDrawPile = added.cardIndex === "anastasiaKingsInvocation" && live().drawPileArray.indexOf(added.instanceId) >= 0;
		}
		if (live().phase === "enemyTurn") hc.combat.startPlayerTurn(hc.newEffectContext({ combat: live() }));
	}
	check("Petition puts the King's Invocation in the run deck and in this fight's draw pile", invocationInDrawPile === true);
	check("a Queen petitions once a fight: the second walk through her moves steps over it",
		playedArray.filter((card) => card === "celestialQueenPetition").length === 1 &&
		playedArray.filter((card) => card === "celestialQueenConversion").length === 2 &&
		hc.state.run.deckArray.length === deckStart + 1, playedArray.join(", "));
	check("both Queens mark Petition once per fight", ["celestialQueen", "infernalQueen"].every((index) =>
		hc.findDefinition(hc.enemyArray, index).moveArray.some((move) => /Petition$/.test(move.card) && move.oncePerCombat === true)));

	// The combat screen is not loaded here; its wiring is read off the source.
	const sceneSource = fs.readFileSync(path.join(ROOT, "honeycomb", "honeycomb-scene-combat.js"), "utf8");
	check("a replay reads its shape changes ahead and draws each piece's earlier shape until its beat",
		/honeycomb\.combatScene\.playLog = function[^{]*\{\s*honeycomb\.combatScene\.busy = true;\s*honeycomb\.combatScene\.readShapeChanges\(logArray\);/.test(sceneSource) &&
		/renderFighter = function \(entity, side\) \{\s*entity = honeycomb\.combatScene\.shownEntity\(entity\);/.test(sceneSource) &&
		/applyPose = function \(art, entity, poseIndex\) \{\s*entity = honeycomb\.combatScene\.shownEntity\(entity\);/.test(sceneSource) &&
		(sceneSource.match(/honeycomb\.combatScene\.revealShape\(entry\);\s*honeycomb\.combatScene\.repaint\(\);/g) || []).length === 2);
}

